insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:site.seo','{"titre":"Ouidah Heritage Tour · Travel to Ouidah, Benin","description":"Discover Ouidah, its heritage and places of remembrance with Ouidah Heritage Tour. Tours, events and trips planned with our local team.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.hero','{"kicker":["Memorial and cultural tourism agency","Ouidah, Benin"],"title":{"lead":"Ouidah,","accent":"city of Vodun and memory"},"sub":"Walk the Slave Route, from Chacha Square to the Door of No Return, facing the Atlantic.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Aerial view of Ouidah beach: Atlantic waves, golden sand and palm trees"},{"src":"/hero/hero-2-porte.jpg","alt":"The new Door of No Return in Ouidah, side view"}],"search":{"action":"/#chemins","label":"Search for a tour","submit":"Search","fields":[{"name":"lieu","label":"Destination","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Travel type","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Duration","objet":"calendrier","options":[{"value":"","label":"All durations"},{"value":"demi-journee","label":"Half-day"},{"value":"journee","label":"One day"},{"value":"plusieurs-jours","label":"Multiple days"}]}]},"primary":{"label":"View our tours","href":"/#chemins"},"secondary":{"label":"Design my custom trip","href":"/devis"},"facts":[{"value":"1721","label":"Portuguese fort, now a history museum"},{"value":"4 km","label":"From Chacha Square to the beach, via the Slave Route"},{"value":"2025","label":"New Door of No Return"},{"value":"23 August","label":"Day of remembrance of the slave trade"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.welcome','{"label":"Who we are","title":["Welcome home,","at the heart of your History."],"paragraphs":["Ouidah Heritage Tour is more than an agency: it is a commitment to responsible and deeply human tourism.","We invite you to experience Ouidah at the heart of its soul, a destination where history, spirituality, culture, art and nature meet to offer you an authentic experience.","Each journey is unique: our team cares for your interests, expectations and needs. We support you before, during and after the trip."],"link":{"label":"The history of Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"A young woman arranges colourful wax fabrics at the market"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Who we are","segments":[{"text":"Welcome home,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"The illuminated Door of No Return at night"},"ring":"sun"},{"text":"at the heart of your History,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"The painted entrance of the Temple of Pythons"},"ring":"abyss"},{"text":"from the Slave Route"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Ouidah beach at sunset"},"ring":"sun"},{"text":"to the ocean."}],"columns":[{"title":"Memory and culture","text":"Memorial and cultural tourism agency, we take you on foot along the Slave Route with a guide who narrates each stage."},{"title":"The places you choose","text":"The Temple of the Pythons opposite the basilica, the sacred forest of Kpassè, the Zobè market, the lagoon by canoe. We design your stay with the places that speak to you."},{"title":"From the airport to Ouidah","text":"Shuttle from Cotonou airport, accommodation, meals, vehicle: we organise with you everything surrounding the visit, before, during and after the trip."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.placesIntro','{"kicker":"The map · From the city to the sea","title":"Ouidah in four sites","titleParts":{"before":"Ouidah in","number":"4","spoken":"four","after":"sites."},"intro":"Scroll down: the route is drawn on the map, from the Portuguese fort to the Door of No Return, through the town streets.","link":"View the site","walked":"km covered","mapLabel":"Map of Ouidah showing the four sites and the walking route that links them"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Our commitments","title":"Seven commitments, delivered on the ground.","intro":"What you can expect from us, from the first question to the return.","of":"on"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.reasons','[{"title":"The territory, known up close","text":"From the Portuguese fort to the beach, our guides lead you on foot.","couleur":"sun"},{"title":"Verified facts","text":"The tour narratives are based on documented history of the slave trade.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"Entrance to the Ouidah History Museum, in the Portuguese fort"}},{"title":"Your story first","text":"Your itinerary is built around your story and your questions.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"The painted entrance of the Temple of Pythons"}},{"title":"Local partners","text":"Accommodation, meals, guides and artisans from the country: we choose the addresses for your stay together with you.","couleur":"abyss"},{"title":"For the diaspora","text":"Our \"Return to the Roots\" circuit takes Afro‑descendants from the fort to the Door of No Return.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"The Door of No Return facing the sea, in broad daylight"}},{"title":"Before, during, after","text":"Response within 24 hours, welcome on arrival, follow‑up until return.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"The Fish Route, lined with coconut palms, in Ouidah"}},{"title":"For local actors","text":"We help train local tourism operators and promote them.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.tenIntro','{"title":["What the city has in store for you,","from memory to the sea."],"link":{"label":"Discover them","href":"/#raisons"},"place":"Ouidah","discover":"Discover the site","circle":"Surround","circled":"Surrounded","path":{"label":"See my route","href":"#chemins"},"stripLabel":"The views, from memory to the ocean","filmEdge":"OUIDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.tenReasons','[{"slug":"route-des-esclaves","title":"The Slave Route","short":"Slave Route","category":"Memory","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"The Return Tree, final station of the Slave Route before the beach"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"From Place Chacha, where auctions were held, to the beach: about 4 km, the path that captives walked to the ships. You pass the Tree of Forgetting, around which they were made to turn to erase their name and origin, the Zomaï Huts, where they were locked in darkness, the Zoungbodji memorial, then the Return Tree, so that their spirit may return. It is walked on foot, with a guide who narrates each stage."},{"slug":"porte-du-non-retour","title":"The Gate of No Return","short":"Gate of No Return","category":"Memory","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"The Door of No Return facing the sea, in broad daylight"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"At the end of the Slave Route, on the beach, facing the Atlantic. It marks the site of the forced embarkation of millions of Africans. The first arch, inaugurated on 30 November 1995 on UNESCO’s initiative, was replaced in December 2025 by a taller gate. You reach it on foot, after the route’s stations, and stand there, facing the sea."},{"slug":"temple-des-pythons","title":"The Python Temple","short":"Python Temple","category":"Faith","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"The painted entrance of the Temple of Pythons"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Vodun sanctuary of the Dangbé serpent cult, documented since the late 17th century, where sacred pythons live. The temple faces the Basilica of the Immaculate Conception: two institutions existing side by side, on opposite sides of the same square. Visits are conducted respecting the site’s rules."},{"slug":"basilique","title":"The basilica, opposite the temple","short":"Basilica","category":"Faith","image":{"src":"/ouidah/visite-basilique.jpg","alt":"The Basilica of the Immaculate Conception in Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"The main Catholic place of worship in Ouidah, the Basilica of the Immaculate Conception was built between 1903 and 1909, and was elevated to the status of minor basilica in 1989. It stands opposite the Python Temple: in Ouidah you move from one to the other by crossing a square."},{"slug":"musee-histoire","title":"The Portuguese Fort Museum","short":"History Museum","category":"History","image":{"src":"/ouidah/lieu-musee.jpg","alt":"The Portuguese fort in Ouidah, which houses the history museum"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"The Portuguese fort São João Baptista de Ajudá, built in 1721, has housed the city’s history museum since 6 September 1967: the slave trade, the kingdoms, links with Brazil and the Americas, displayed through around 700 objects. The site is under renovation to host the future International Museum of Memory and Slavery: we inform you in advance of what is open."},{"slug":"foret-sacree-kpasse","title":"The sacred forest of Kpassè","short":"Kpassè forest","category":"Nature","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"Under the tall trees of the sacred forest of Kpassè, a vodun sculpture"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"A 4‑hectare forest island in the heart of the town, linked to King Kpassè. The forest houses vodun deities and sculptures, and provides a setting for ceremonies, notably during the Vodun Days. You enter through a painted gateway, then walk beneath the tall trees."},{"slug":"vodun-days","title":"Vodun Days","short":"Vodun Days","category":"Festival","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"An Egungun in the arena of Ouidah during the Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"Each early January, Ouidah hosts the major annual Vodun cultures gathering: ceremonies, ritual dances, exhibitions and meetings, respecting the rules set by the communities. The main ceremony and concerts take place on the beach, other events in the Kpassè forest. We do not organise the event: we organise your stay around it."},{"slug":"memorial-zoungbodji","title":"Zoungbodji Memorial","short":"Zoungbodji","category":"Memory","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"The Zoungbodji Memorial, on the Slave Route"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"The memorial of the village of Zoungbodji marks the final place where captives stayed before boarding, near the communal pit where the dead were thrown. It is the gravest stage of the Slave Route, about 2 km from the beach and the Gate of No Return. We pause there before heading to the sea."},{"slug":"marches","title":"Artisans, markets, cuisine","short":"Markets","category":"Flavours","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Female vendors carrying their goods in a street of Ouidah"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"The Zobè market, near the Portuguese fort, and the one in the Kpassè neighbourhood give rhythm to city life. Our guides take you there, as well as to artisans and the best eateries of Ouidah, from local eateries to restaurants. This is today’s city, living between two visits."},{"slug":"plage-et-lagune","title":"The beach and the lagoon","short":"Beach and lagoon","category":"Ocean","image":{"src":"/hero/hero-4-plage.jpg","alt":"The beach of Ouidah seen from the air, Atlantic waves and coconut palms"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"At the end of the Slave Route, a long, undeveloped beach where the main ceremony and the Vodun Days concerts are held. Behind it, the lagoon separates the town from the ocean: one of Benin’s most important coastal ecosystems, explored by canoe from the small landing stage. The Fishing Road, lined with coconut palms, runs between the two. Swimming is not recommended in strong winds."}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.toursIntro','{"label":"Our itineraries","all":{"label":"All itineraries","href":"/#chemins"},"onRequest":"Price on request","durationPending":"Duration to be confirmed","filtersLabel":"Filter itineraries"}'::jsonb,1,now()) on conflict(cle) do nothing;
