insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.prepare','{"title":["Prepare your trip,","map in hand."],"lead":"Ouidah is on the coast, 41 km from the airport. The essentials are covered in a few tips.","carte":{"ouidah":[2.0851,6.3622],"aeroport":[2.3844,6.3573],"porte":[2.0896,6.3243],"ville":"Ouidah","villeSous":"Atlantic coast","ocean":"Atlantic Ocean","pays":[{"nom":"Togo","lieu":[1.12,8.2]},{"nom":"Nigeria","lieu":[3.38,8.4]}],"cotonou":"Cotonou","aeroportNom":"international airport","porteNom":"Gate of No Return","km":"41 km","kmSous":"by road, by shuttle","ariaBenin":"Map of Benin: Ouidah, on the Atlantic coast, 41 km from Cotonou airport","ariaCote":"Benin’s coast: the road from Cotonou airport to Ouidah, 41 km"},"fiche":{"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"The Door of No Return facing the ocean, in Ouidah"},"titre":"Ouidah","texte":"Historic town, facing the Atlantic.","heureTexte":"Same time as Paris in winter.","fuseau":"Africa/Porto-Novo"},"accueil":{"titre":"We are waiting for you.","texte":"On arrival, the team can meet you at the airport if you wish."},"ongletsLabel":"Prepare your trip, by theme","numeros":"Useful numbers","question":"A question before you leave? We reply within 24 hours.","whatsapp":"Write on WhatsApp","ecrire":{"label":"Ask a question","href":"/devis?demande=question"},"verifie":"2026-10-22"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.preparer','[{"id":"sur-place","court":"On site","objet":"accueil","vue":"benin","titre":"Ouidah can be visited with peace of mind.","cle":{"valeur":"Accompanied","texte":"by our team, before, during and after the trip."},"mot":true,"points":["At the airport, we can wait for you if you wish: the shuttle will take you to Ouidah.","Accommodation and dining: we choose with you from the venues listed in Ouidah.","Before a ceremony photo or a portrait, a word is enough: just ask, it’s customary.","At the beach, enjoy the sand and the sunset; for swimming, ask for local advice, the Atlantic surf is strong."],"source":"OHT commitments · France Diplomatie (15 Sep 2026) · FCDO"},{"id":"arriver","court":"Arrive","objet":"navette","vue":"cote","titre":"Arrive, simply.","cle":{"valeur":"41 km","texte":"from Cotonou airport to Ouidah. The OHT shuttle takes you there."},"points":["Your e‑Visa is applied for online at evisa.bj: 30 or 90 days, response in 1 to 96 hours.","Apply at least 7 days before arrival, then keep it handy.","African nationals: no visa, up to 90 days.","French travellers: passport valid 6 months after return, return ticket in your bag."],"source":"evisa.bj · France Diplomatie · OSRM (41 km)"},{"id":"sante","court":"Health","objet":"sante","vue":"benin","titre":"Your health, prepared.","cle":{"valeur":"1 visit","texte":"to your doctor or an international vaccination centre, before departure."},"points":["Vaccinations up to date, hepatitis A and typhoid: your doctor will review them with you.","Yellow fever: vaccine recommended from 9 months. Slip your vaccination card into your bag.","Against mosquitoes: repellent and long‑sleeved clothing in the evening. Your doctor will tell you if anti‑malaria treatment is needed."],"source":"Benin Ministry of Health (16 Sep 2026) · Institut Pasteur · WHO — yellow fever: sources disagree, to be confirmed"},{"id":"argent","court":"Money","objet":"type-voyage","vue":"benin","titre":"Money, no calculations needed.","cle":{"valeur":"15,24 €","texte":"for 10 000 FCFA. The rate is fixed all year round."},"points":["The CFA franc is pegged to the euro: €1 = 655.957 FCFA, no variation.","Quick reference: 1 000 FCFA is about €1.50.","To withdraw, use ATMs located inside banks."],"source":"BCEAO · France Diplomatie"},{"id":"pratique","court":"Practical","objet":"prise","vue":"benin","fiche":"heure","titre":"Good to know.","cle":{"valeur":"0 h","texte":"time difference with Paris in winter, 1 h in summer."},"points":["220 V, plugs C and E: chargers from France and Belgium plug in without an adaptor.","French is the official language; in Ouidah Fon is also spoken.","A local SIM from MTN, Moov Africa or Celtiis, and you stay reachable.","Dry season from November to March, then mid‑July to mid‑September."],"source":"gouv.bj · ARCEP Benin · IEC · IANA"}]'::jsonb,1,now()) on conflict(cle) do nothing;
