insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.newsletter','{"nom":"The Ouidah newsletter","phraseSansHeure":"Tonight, the sun sets over Ouidah beach.","maintenant":"In Ouidah","photo":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Ouidah beach, its palm trees and the sand track at dusk"},"choisir":"Choose what Ouidah writes to you","sujets":[{"id":"departs","nom":"Our departure dates","texte":"Upcoming trips and tours, with their dates.","objet":"calendrier"},{"id":"agenda","nom":"Ouidah''s agenda","texte":"Vodun Days, Remembrance Day, Ouidah Blue: the city''s events.","objet":"fete"}],"langue":"The newsletter in","field":"Your email address","exemple":"vous@exemple.com","submit":"Receive the newsletter","consent":"I agree to receive the Ouidah Heritage Tour newsletter. Unsubscribe with one click.","envoi":"Signing up…","thanks":"Noted: the newsletter will arrive in your inbox.","echec":"Registration failed. Please try again in a moment.","limite":"Multiple sign‑ups have already been made from this connection. Please try again in an hour.","aucun":"Select at least one theme.","error":"Enter a valid email address and tick the box."}'::jsonb,1,now()) on conflict(cle) do nothing;
