insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.places','[{"n":"01","name":"Ouidah History Museum","kicker":"Portuguese Fort, 1721","text":"The Portuguese fort has housed the city history museum since 6 September 1967: the slave trade, the kingdoms, links with Brazil and the Americas.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"The red wall of the Portuguese fort of Ouidah"},"next":"680 m on foot to the Python Temple"},{"n":"02","name":"Python Temple","kicker":"Opposite the basilica","text":"The Dangbé python temple faces the Basilica of the Immaculate Conception, built from 1903 to 1909: two sides living side by side.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"The painted entrance of the Temple of Pythons"},"next":"2.5 km to the Zoungbodji memorial, via Chacha Square"},{"n":"03","name":"The Slave Route","kicker":"Approximately 4 km, six stops","text":"From Chacha Square to the beach, the route taken by captives to the ships: the Tree of Forgetting, the Zomaï Huts, the Zoungbodji Memorial, the Tree of Return.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"The Zoungbodji Memorial, on the Slave Route"},"next":"2 km to the beach and the Door of No Return"},{"n":"04","name":"Gate of No Return","kicker":"Erected in 1995, rebuilt in 2025","text":"On the beach, facing the Atlantic, it marks the place where millions of Africans were forcibly embarked.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"The illuminated Door of No Return at night"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.destinations','[{"slug":"musee-histoire","name":"Ouidah History Museum","subtitle":"Portuguese Fort, 1721","theme":"Memory","text":"The Portuguese fort houses the city history museum: the slave trade, the kingdoms, links with Brazil and the Americas.","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"The red wall of the Portuguese fort of Ouidah"},"href":"/ouidah/lieux/musee-histoire"},{"slug":"temple-des-pythons","name":"Python Temple","subtitle":"Opposite the basilica","theme":"Spirituality","text":"The Dangbé python temple faces the Basilica of the Immaculate Conception: two sides living side by side.","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"The painted entrance of the Temple of Pythons"},"href":"/ouidah/lieux/temple-des-pythons"},{"slug":"basilique","name":"Basilica of the Immaculate Conception","subtitle":"Built from 1903 to 1909","theme":"Spirituality","text":"Opposite the Python Temple, the Basilica of the Immaculate Conception.","coords":[6.3605968,2.0848595],"image":{"src":"/ouidah/visite-basilique.jpg","alt":"The Basilica of the Immaculate Conception in Ouidah"},"href":"/ouidah/lieux/basilique"},{"slug":"foret-sacree-kpasse","name":"Sacred forest of Kpassè","subtitle":null,"theme":"Spirituality","text":null,"coords":[6.3648371,2.0963694],"image":null,"href":"/ouidah/lieux/foret-sacree-kpasse"},{"slug":"place-chacha","name":"Chacha Square","subtitle":"Start of the Slave Route","theme":"Memory","text":null,"coords":[6.3564897,2.0850349],"image":null,"href":"/ouidah/lieux/place-chacha"},{"slug":"arbre-de-l-oubli","name":"Tree of Forgetting","subtitle":"On the Slave Route","theme":"Memory","text":null,"coords":[6.3480979,2.0868848],"image":null,"href":"/ouidah/lieux/arbre-de-l-oubli"},{"slug":"memorial-zoungbodji","name":"Zoungbodji Memorial","subtitle":"On the Slave Route","theme":"Memory","text":"On the Slave Route, the Zoungbodji memorial.","coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"The Zoungbodji Memorial, on the Slave Route"},"href":"/ouidah/lieux/memorial-zoungbodji"},{"slug":"arbre-du-retour","name":"Tree of Return","subtitle":"On the Slave Route","theme":"Memory","text":null,"coords":[6.3401724,2.0889473],"image":null,"href":"/ouidah/lieux/arbre-du-retour"},{"slug":"porte-du-non-retour","name":"Gate of No Return","subtitle":"Erected in 1995, rebuilt in 2025","theme":"Memory","text":"On the beach, facing the Atlantic, it marks the place where millions of Africans were forcibly embarked.","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"The Door of No Return facing the sea, in broad daylight"},"href":"/ouidah/lieux/porte-du-non-retour"},{"slug":"route-des-peches","name":"Fishing Route","subtitle":"Along the coast","theme":"Nature","text":"The coastal road between the ocean and the lagoon, lined with coconut palms.","coords":[6.339296,2.2101943],"image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"The Fish Route, lined with coconut palms, in Ouidah"},"href":null},{"slug":"ganvie","name":"Ganvié","subtitle":"Lake Nokoué","theme":"Nature","text":"The stilt village on Lake Nokoué, reached by canoe.","coords":[6.4681116,2.3899667],"image":{"src":"https://images.pexels.com/photos/6729840/pexels-photo-6729840.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Fisherman casting his net from a canoe in Ganvié"},"href":"/ouidah/lieux/ganvie"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.FICHES_LIEU','{"musee-histoire":{},"temple-des-pythons":{"recit":{"chapitre":"basilique","paragraphes":[0]}},"basilique":{},"foret-sacree-kpasse":{"photo":{"src":"/histoire/raison-foret-kpasse.webp","alt":"The sacred forest of Kpassè, in Ouidah"}},"place-chacha":{"photo":{"src":"/histoire/place-chacha-2025.webp","alt":"The redeveloped Chacha Square, 2025"}},"arbre-de-l-oubli":{"photo":{"src":"/histoire/arbre-oubli-2015.webp","alt":"The sculpture of the Tree of Forgetting"}},"memorial-zoungbodji":{},"arbre-du-retour":{"photo":{"src":"/histoire/raison-arbre-du-retour.webp","alt":"The Tree of Return and its statue"}},"porte-du-non-retour":{},"ganvie":{}}'::jsonb,1,now()) on conflict(cle) do nothing;
