insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.evenements','[{"slug":"vodun-days","title":"Vodun Days","short":"Vodun Days","theme":"Spirituality","place":"Ouidah","text":"The major annual gathering of Vodun cultures: ceremonies, ritual dances, exhibitions and meetings, respecting the rules set by the communities.","image":{"src":"https://images.pexels.com/photos/38242758/pexels-photo-38242758.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Egungun costume and mask embroidered in bright colours"},"quand":{"type":"editions","dates":[["2027-01-02","2027-01-09"]]},"organisateur":{"type":"externe","nom":"National event"},"offre":{"type":"sejour","nom":"Vodun Days stay","inclus":"accommodation, transfers, guide, escorted access","nuits":null,"prix":null,"places":null}},{"slug":"ouidah-blue","title":"Ouidah Blue","short":"Ouidah Blue","theme":"Culture","place":"Ouidah","text":"Festive gathering around the local and international artistic scene: music, visual arts and meetings.","image":null,"quand":{"type":"paques","debut":-1,"fin":1},"organisateur":{"type":"oht"},"offre":{"type":"billet","categories":[{"nom":"Place","detail":"event access","prix":null},{"nom":"Place and stay","detail":"your place, accommodation included","prix":null,"logement":true}],"places":null,"jauge":null}},{"slug":"souvenir-23-aout","title":"International Day of Remembrance of the Slave Trade and its Abolition","short":"Day of Remembrance of the Trade","theme":"Memory","place":"Slave Route, Ouidah","text":"UNESCO‑recognised date, marked in Ouidah by remembrance ceremonies on the Slave Route.","image":{"src":"https://images.pexels.com/photos/20231862/pexels-photo-20231862.jpeg?auto=compress&cs=tinysrgb&w=2400","alt":"A traveller facing the waves, on Ouidah beach at sunset"},"quand":{"type":"annuel","mois":8,"jour":23,"jours":1},"organisateur":{"type":"externe","nom":"Public commemoration"},"offre":{"type":"sejour","nom":"Memory stay","inclus":"accommodation, transfers, guide, accompanied ceremony","nuits":null,"prix":null,"places":null}}]'::jsonb,1,now()) on conflict(cle) do nothing;
