insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:fr.conciergerie','[{"id":"navette","court":"Shuttle","nom":"Shuttle.","question":"One‑way or return trip?","moment":"On arrival","lead":"From Cardinal Bernardin Gantin International Airport: about 41 km by road.","leadReleve":null,"objet":"navette","photo":{"src":"/ouidah/aeroport-fresque.jpg","alt":"The “Welcome to Benin” mural at Cotonou airport"},"credit":"Houss 2020, Wikimedia Commons, CC0","options":[{"label":"Go","detail":"Airport → Ouidah","releve":null,"phrase":"the shuttle on arrival"},{"label":"Return","detail":"And on the day of departure","releve":null,"phrase":"the return shuttle"},{"label":"No need","detail":null,"releve":null,"passe":true}]},{"id":"accueil","court":"Welcome","nom":"Welcome.","question":"Where would you like us to meet you?","moment":"Upon your arrival","lead":null,"leadReleve":null,"objet":"accueil","photo":{"src":"/ouidah/aeroport-facade.jpg","alt":"The façade of Cotonou International Airport"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"At the airport","detail":"As soon as you exit","releve":null,"phrase":"the airport welcome"},{"label":"In Ouidah","detail":"At your address","releve":null,"phrase":"the welcome in Ouidah"},{"label":"No need","detail":null,"releve":null,"passe":true}]},{"id":"telephone","court":"Phone","nom":"Telephone.","question":"A SIM card on arrival?","moment":"Day one","lead":null,"leadReleve":null,"objet":"telephone","photo":{"src":"/ouidah/eng-1-rue-basilique.jpg","alt":"A street in Ouidah, towards the basilica"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"SIM card","detail":"Call, write","releve":null,"phrase":"a SIM card"},{"label":"SIM card + data","detail":"And mobile internet","releve":null,"phrase":"a SIM card with internet"},{"label":"No need","detail":null,"releve":null,"passe":true}]},{"id":"hebergement","court":"Accommodation","nom":"Accommodation.","question":"What type of address?","moment":"The first evening","lead":"{n} addresses recorded in Ouidah. We choose with you the one that suits you.","leadReleve":"hebergement","objet":"hebergement","photo":{"src":"/ouidah/eng-3-case-plage.jpg","alt":"A round hut with a thatched roof, facing the beach"},"cadre":"50% 85%","credit":null,"options":[{"label":"Hotel","detail":null,"releve":"hebergement/Hôtel","phrase":"a hotel"},{"label":"Inn","detail":null,"releve":"hebergement/Auberge","phrase":"a hostel"},{"label":"Guesthouse","detail":null,"releve":"hebergement/Maison d''hôtes","phrase":"a B&B"},{"label":"Camp","detail":null,"releve":"hebergement/Campement","phrase":"a campsite"},{"label":"I have already booked","detail":null,"releve":null,"passe":true}]},{"id":"tables","court":"Tables","nom":"Tables.","question":"Where do you like to eat?","moment":"At the table","lead":"{n} tables recorded in Ouidah. Multiple choices possible.","leadReleve":"restauration","multi":true,"objet":"tables","photo":{"src":"/ouidah/eng-4-paillote.jpg","alt":"A thatched bar on Ouidah beach"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Restaurants","detail":null,"releve":"restauration/Restaurant","phrase":"restaurants"},{"label":"Bars","detail":null,"releve":"restauration/Bar","phrase":"bars"},{"label":"Cafés","detail":null,"releve":"restauration/Café","phrase":"cafés"},{"label":"No need","detail":null,"releve":null,"passe":true}]},{"id":"vehicule","court":"Vehicle","nom":"Vehicle.","question":"With or without driver?","moment":"The following days","lead":"To reach the beach via the Road of Peaches, Ganvié or Abomey at your own pace.","leadReleve":null,"objet":"vehicule","photo":{"src":"/ouidah/route-des-peches.jpg","alt":"The Road of Peaches, lined with streetlights, between lagoon and ocean"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"With driver","detail":null,"releve":null,"phrase":"a vehicle with driver"},{"label":"Without driver","detail":null,"releve":null,"phrase":"a vehicle without driver"},{"label":"No need","detail":null,"releve":null,"passe":true}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:histoire.histoireOuverture','{"titre":"From Glexwé to Ouidah","texte":"In Fon, the town is called Glexwé, often translated as “the house of fields”. Europeans recorded the name of the Houéda kingdom it belonged to in various ways: Whydah in English, Juda in French, Fida in Dutch, Ajudá in Portuguese. Ouidah derives from this. As early as 1681, an English source dates a letter “Agriffie in Whidaw”: Glexwé, in the Houéda country.","noms":["Glexwé","Whydah","Juda","Fida","Ajudá","Ouidah"]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:histoire.histoireChapitres','[{"id":"avant","repere":"17th century","court":"17th","titre":"Before the forts","ville":false,"temps":[["In the 17th century, Glexwé was the low town of the Houéda kingdom, north of a lagoon. The king lived at Savi, about ten kilometres further north. Long dominated by its neighbour Allada, the small kingdom freed itself in the second half of the century.","When Europeans settled, at the end of the century, most business was conducted at Savi, near the palace. Excavations on the site since 1991 have found only Dutch bricks and Chinese porcelain within the royal enclosure, indicating that the king controlled trade."],["According to tradition, the Houéda came from Tado, and their first king, Haholo, founded Savi. Tradition gives Glexwé another founder, Kpassè. It tells that he did not die like a man: he turned into an iroko tree. This tree is venerated in the sacred forest of Kpassè, in the Tové quarter, where the pre‑European village is located.","Another name appears in the accounts: Kpate, who is said to have welcomed the first Europeans. He still has a cult in Ouidah."]],"pieces":[{"hier":{"src":"/histoire/plan-palais-savi-1747.webp","largeur":1173,"hauteur":1313,"legende":"The king’s palace at Savi and the European trading posts, plan engraved in 1747"},"auj":null},{"hier":{"src":"/histoire/couronnement-roi-juida-1723.webp","largeur":1100,"hauteur":847,"legende":"The coronation of the Houéda king, 18th‑century engraving"},"auj":null},{"hier":null,"auj":{"src":"/histoire/raison-foret-kpasse.webp","largeur":1200,"hauteur":674,"legende":"The sacred forest of Kpassè, in the Tové quarter"}}]},{"id":"forts","repere":"1671 – 1721","court":"1671","titre":"The forts","ville":true,"temps":[["In 1671 the French West India Company opened a trading post in the Houéda kingdom. It was the first permanent European establishment. The English arrived in the 1680s. The French post was destroyed during the 1692 war. It returned in 1704 as a fort, built by the corsair Jean Doublet in a few weeks, of earth and thatch.","José de Torres, a merchant from Bahia, founded the Portuguese fort São João Baptista de Ajudá in 1721."],["In the 18th century, English, French and Portuguese forts stood side by side, a few kilometres from the beach. The Dutch never had a fort at Ouidah, nor did the Danes.","The English abandoned theirs in 1812. The French fort was demolished in 1908. In its place an esplanade stretches where, during Vodun Days, the Zangbéto – night guardians – dance. Today, only the Portuguese fort remains standing."]],"pieces":[{"hier":{"src":"/histoire/fort-anglais-1727.webp","largeur":1226,"hauteur":410,"legende":"The English fort, called William’s Fort, engraved in 1727"},"auj":null},{"hier":{"src":"/histoire/fort-francais-plan-1747.webp","largeur":1330,"hauteur":1400,"legende":"Plan of the French fort, engraved in 1747"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-gravure-1886.webp","largeur":960,"hauteur":628,"legende":"The Portuguese fort, engraving of 1886"},"auj":{"src":"/histoire/eng-2-musee.webp","largeur":1200,"hauteur":900,"legende":"The entrance to the Portuguese fort, now a history museum"}}]},{"id":"dahomey","repere":"1727","court":"1727","titre":"Dahomey","ville":false,"temps":[["In 1724, Agaja, king of Dahomey, seized Allada. In early March 1727, his army took Savi and destroyed it, along with the European trading posts there. Hufon, the last Houéda king, fled west with part of his people, first to an island near Grand-Popo. Other Houéda settled in Porto‑Novo and Badagry."],["Glexwé changes master and role. Trade with the Europeans concentrates there, and the town becomes the main trading hub of Dahomey. A governor settles there in 1733. The Europeans call him the vice‑king.","Later he will bear the title fon de yovogan, “chief of the Whites”, which the Houéda kingdom already used. The post always returns to a man from the country. The forts come under Dahomey authority: in July 1743, his army attacks the Portuguese fort."]],"pieces":[{"hier":{"src":"/histoire/comptoirs-savi-1747.webp","largeur":1400,"hauteur":948,"legende":"The European trading posts of Savi, engraved from surveys of 1725, two years before the town’s fall"},"auj":null}]},{"id":"chacha","repere":"1800 – 1849","court":"1800","titre":"The Chacha","ville":true,"temps":[["Francisco Félix de Souza, a slave trader from Brazil, first came to the coast in the early 1790s and settled there around 1800. He starts as a clerk‑accountant at the Portuguese fort, commands it temporarily around 1806, then trades on his own account.","At odds with King Adandozan, he is imprisoned at Abomey and escapes to Petit‑Popo. From there he supports the coup that puts Ghézo on the throne of Dahomey, probably in 1818. The new king makes him his commercial agent in Ouidah, where he returns around 1820."],["He is nicknamed Chacha. The origin of the word remains unknown: a tradition links it to the Portuguese “já, já”, “right away”, which he would often say. He establishes in the south‑west of the town a quarter that will later be called Brazil, Blézin in fon. His family, his slaves and his clients live there.","A novel made him the “vice‑king of Ouidah”. He never was: the yovogan charge belonged to a Dahomean."],["He dies in Ouidah on 8 May 1849, heavily in debt: he owed 80 000 dollars to King Ghézo. The king chooses his eldest son, Isidoro, to succeed him. The nickname then becomes a hereditary title, since borne by the head of the Souza family.","His tomb is in the family concession of Singbomey, behind Chacha Square. Since 1999, a plaque gives this name to the square. Recent official texts also call it Auction Square."]],"pieces":[{"hier":{"src":"/histoire/portrait-de-souza.webp","largeur":1164,"hauteur":1400,"legende":"Portrait attributed to Francisco Félix de Souza, painted before 1849"},"auj":null},{"hier":{"src":"/histoire/place-chacha-stele-2017.webp","largeur":1400,"hauteur":933,"legende":"The “Chacha Square” stele, in 2017"},"auj":null,"temps":2}]},{"id":"agudas","repere":"1835 – 1922","court":"1835","titre":"The Agudas","ville":true,"temps":[["From 1835, after the Malê revolt in Bahia, freed African slaves are expelled from Brazil or forced to leave. Many are Yoruba. In Ouidah they settle especially in the Maro quarter, west of the Brazil quarter, under the protection of De Souza.","Together with Portuguese and Brazilian merchant families, and African families linked to them, they form the Agudas. In the 19th century the word referred to the Portuguese, including Brazilians; it would come from Ajudá. Some Agudas, such as the Souza family, lived from the slave trade."],["Their descendants bear names such as de Souza, da Silva, d’Almeida, Martins, Olympio or Paraïso. In Benin they celebrate Nosso Senhor do Bonfim in January and dance the bourian, a masquerade from Bahia."],["Along the whole coast, their multi‑storey houses, with galleries, balustrades, shutters and ornate pediments, recall the sobrados of Salvador. At the start of the 20th century this style becomes a sign of success. Notables who are not Agudas also adopt it.","The Ajavon villa is an example. Its pediment bears the inscription “VILLA AJAVON 1922”. It was built for Ajavon, a wealthy merchant from neighbouring Togo. Since 11 November 2013, it houses the contemporary art museum of the Zinsou Foundation."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/maison-du-bresil.webp","largeur":1120,"hauteur":1400,"legende":"The House of Brazil, in 2024"},"temps":2},{"hier":null,"auj":{"src":"/histoire/villa-ajavon-1922.webp","largeur":1400,"hauteur":1050,"legende":"The Ajavon villa, dated 1922, now a museum of the Zinsou Foundation"},"temps":2}]},{"id":"mer","repere":"End of the 17th century – 1863","court":"1863","titre":"Up to the sea","ville":false,"temps":[["According to historians’ estimates, more than one million people were deported from Ouidah from the end of the 17th century to the 1860s."],["The town is about four kilometres from the sea, behind a lagoon. Captives were led on foot to the beach. Canoes took them across the bar, those sandbanks that close the coast, to ships anchored offshore."],["They mainly went to Brazil, especially Bahia, and to the Caribbean, notably Saint‑Domingue, now Haiti. At the end of the trade they went to Cuba.","In the 1840s, the palm‑oil trade took off, but the slave trade continued. In January 1852, under a British blockade, King Ghézo signed a treaty that abolished it. It had no lasting effect."],["In May 1860, the schooner Clotilda left Ouidah with 110 captives aboard. In July she secretly landed near Mobile, Alabama. It is the last known slave ship to have reached the United States.","On 10 October 1863, at Godomey, the steamship Cicerón embarked for Cuba about 960 people, marched on foot from Ouidah. It is the last known trans‑Atlantic embarkation linked to Ouidah."]],"chiffre":{"valeur":"More than one million","legende":"people deported from Ouidah, from the end of the 17th century to the 1860s, according to historians’ estimates"},"legende":[{"lettre":"A","nom":"European tents"},{"lettre":"B","nom":"The shoreline"},{"lettre":"C","nom":"Ships at anchor"}],"pieces":[{"hier":null,"auj":{"src":"/histoire/bienvenue-3-plage-cocotiers.webp","largeur":1200,"hauteur":795,"legende":"Ouidah beach"}}]},{"id":"basilique","repere":"1903 – 2011","court":"1903","titre":"The python and the basilica","ville":true,"temps":[["Dangbé, the royal python, is the deity of the Houéda kingdom. It incarnates in living snakes kept in its sanctuaries. Around 1700, a Dutch trader noted that the snakes were the kingdom''s primary deities."],["In Ouidah, its temple faces the Basilica of the Immaculate Conception. The church occupies the ground of the former yovogan residence, handed over to the Catholic mission in 1901, which arrived in Ouidah in 1861.","The first stone was laid on 30 August 1903. To build it, all city districts carried sand from the beach, including vodun practitioners. The cathedral was consecrated on 9 May 1909, before about 4,000 people."],["It became a basilica in 1989. On 19 November 2011, Benedict XVI signed Africae munus there, his exhortation on the Church in Africa."]],"pieces":[{"hier":{"src":"/histoire/procession-serpent-1725.webp","largeur":1400,"hauteur":674,"legende":"Procession to the great serpent for the king''s coronation, engraving published in 1730"},"auj":null},{"hier":{"src":"/histoire/temple-serpent-1930.webp","largeur":1400,"hauteur":666,"legende":"The snake temple, circa 1930"},"auj":{"src":"/histoire/bienvenue-2-temple-pythons.webp","largeur":1200,"hauteur":900,"legende":"The entrance to the Temple of the Pythons"}},{"hier":{"src":"/histoire/basilique-1930.webp","largeur":1003,"hauteur":1400,"legende":"The cathedral, circa 1930"},"auj":{"src":"/histoire/visite-basilique.webp","largeur":800,"hauteur":1200,"legende":"The Basilica of the Immaculate Conception"}}]},{"id":"fort","repere":"1892 – 1990","court":"1961","titre":"The burning fort","ville":true,"temps":[["In 1892, Ouidah came under French occupation. The French set the capital at Porto‑Novo, and trade moved to the Cotonou wharf. The town gradually declined. The Portuguese fort, however, remained in Lisbon''s hands."],["Dahomey became independent on 1 August 1960. Exactly one year later it took possession of the fort, which had remained a Portuguese enclave. Before leaving, the two last Portuguese officials set it alight.","In 1967 the fort housed the Ouidah History Museum. In 1975 Dahomey adopted the name Benin. Restored with help from the Portuguese Gulbenkian Foundation, the fort reopened in August 1990. Its refurbishment, started in 2020, aims to turn it into the future International Museum of Memory and Slavery."]],"pieces":[{"hier":{"src":"/histoire/rue-1892.webp","largeur":1216,"hauteur":665,"legende":"A street in Ouidah, engraving from 1892"},"auj":null},{"hier":{"src":"/histoire/marche-1930.webp","largeur":1400,"hauteur":1290,"legende":"The Ouidah market, circa 1930"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-entree-1917.webp","largeur":600,"hauteur":440,"legende":"The entrance to the Portuguese fort, in 1917"},"auj":{"src":"/histoire/lieu-musee.webp","largeur":1200,"hauteur":675,"legende":"The walls of the Portuguese fort"}}]},{"id":"souvenir","repere":"1993 – 1998","court":"1993","titre":"Remember","ville":true,"temps":[["From 8 to 18 February 1993, the city hosted the Ouidah 92 festival, dedicated to vodun arts and cultures. Planned for 1992, it retained that name. President Nicéphore Soglo insisted on it. Priests and visitors came especially from Brazil, Haiti and Trinidad and Tobago.","For the occasion, the Kpassè forest received statues of vodun deities and opened to non‑initiated visitors."],["The Slave Route trail was created during this festival. Six stages, mostly marked by sculptures by Cyprien Tokoudagba, run from Chacha Square to the beach over about three to four kilometres. In September 1994 UNESCO launched its \"Slave Route\" programme in Ouidah, proposed by Haiti and African countries. On 30 November 1995 the Door of No Return was inaugurated on the beach at the end of the path.","In 1998 a repentance march was founded by sociologist Honorat Aguessy. On the third Sunday of January it runs from Chacha Square to the Zomachi memorial, asking forgiveness from the descendants of those deported."]],"pieces":[{"hier":{"src":"/histoire/plaque-ouidah92.webp","largeur":933,"hauteur":1400,"legende":"The plaque placed for Ouidah 92 on the Auction Square, in 2017"},"auj":null},{"hier":{"src":"/histoire/memorial-zomachi-2017.webp","largeur":1400,"hauteur":933,"legende":"The Zomachi memorial, in 2017"},"auj":null}]},{"id":"fete","repere":"1996 – 2026","court":"2024","titre":"January festival","ville":true,"temps":[["In fon, vodun means \"deity, spirit\". The word gave rise to vodou in Haiti. On 10 January 1996, Nicéphore Soglo''s government made this day a paid public holiday, in tribute to vodun and traditional religions. An August 1997 law made it an annual celebration.","For years, the official ceremony on 10 January has been held on Ouidah beach, near the Door of No Return."],["In October 2023 the government created the Vodun Days, opening the festival to a worldwide audience. The first edition took place in Ouidah on 9 and 10 January 2024, across five sites: Maro Square, the French Fort esplanade, the Temple of the Pythons square, a temporary Mami convent and the Kpassè forest. Nearly 100,000 people attended the two main evenings.","Since the law of 2 September 2024 the festival falls on the second Friday of January. The 2025 and 2026 editions last three days."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-vodun-days-2024.webp","largeur":1200,"hauteur":675,"legende":"Dancers performing for the public at Vodun Days 2024, in Ouidah"},"temps":1},{"hier":null,"auj":{"src":"/histoire/collage-zangbeto-meko.webp","largeur":1200,"hauteur":801,"legende":"From Zangbéto to Vodun Days 2026, in the village of Mèkô, Ouidah commune"},"temps":1}]},{"id":"route","repere":"1993 – 2025","court":"2025","titre":"The Route, step by step","ville":true,"temps":[["The stories told at the stops belong to tradition. The captives'' journey to the sea, however, is a documented fact.","The Route starts at Chacha Square, also known as the Auction Square. A plaque placed in 1993 states that captives were sold at auction there, under a large tree. Contemporary testimonies describe something different: the price of captives was set by the king, and sales were carried out by his agents and by merchants'' houses, such as the de Souza house that lines the square. Recently redeveloped, the square is now a paved esplanade."],["Next comes the Tree of Forgetting. According to the tradition told to visitors, men had to walk round it nine times, women seven times, to forget their homeland. This story does not appear in any written source before the 1990s. Older texts refer to the site as the Captains'' Tree: the chiefs of Ouidah received Europeans there and walked round it three times. The original tree has disappeared."],["The Zomaï house bears a name that would mean \"where fire or light does not enter\". Tradition places captives locked in darkness there. Earlier writings link this name to the De Souza powder magazines."],["At Zoungbodji stands a memorial. Tradition says that captives who died before departure were buried at this spot."],["Further on is the Tree of Return. Tradition holds that captives walked round it three times so that their souls would return to Africa after death. No contemporary source mentions this rite. Its statue is by Cyprien Tokoudagba."],["The path ends on the beach at the Door of No Return. It is a monument: captives did not depart from a precise point but from the beach, in canoes. The 1995 arch was replaced. Unveiled in December 2025, the new Door rises over sixteen metres and bears more than two hundred sculptures.","Since 2021 the square, the Portuguese fort, the Zoungbodji sites and the Door beach have been on Benin''s indicative UNESCO list, a prerequisite for possible World Heritage inscription."]],"etapes":["Chacha Square","Tree of Forgetting","Zomaï House","Zoungbodji","Tree of Return","Gate of No Return"],"pieces":[{"hier":{"src":"/histoire/place-chacha-2017.webp","largeur":1400,"hauteur":933,"legende":"The square in 2017, with its large tree and the \"Place Chacha\" stele"},"auj":{"src":"/histoire/place-chacha-2025.webp","largeur":1400,"hauteur":787,"legende":"The redeveloped square, January 2025"}},{"hier":{"src":"/histoire/arbre-oubli-2015.webp","largeur":768,"hauteur":1024,"legende":"The Tree of Forgetting sculpture, installed for Ouidah 92, in 2015"},"auj":null},{"hier":null,"auj":{"src":"/histoire/case-zomai-2019.webp","largeur":809,"hauteur":1400,"legende":"The Zomaï house stele, inaugurated February 1993 (photo 2019)"}},{"hier":null,"auj":{"src":"/histoire/visite-zoungbodji.webp","largeur":1200,"hauteur":1200,"legende":"Zoungbodji Memorial"}},{"hier":null,"auj":{"src":"/histoire/raison-arbre-du-retour.webp","largeur":800,"hauteur":1200,"legende":"The Tree of Return and its statue (photo 2017)"}},{"hier":{"src":"/histoire/porte-1995.webp","largeur":1280,"hauteur":866,"legende":"The 1995 arch, photographed 2019"},"auj":{"src":"/histoire/eng-5-porte-jour.webp","largeur":675,"hauteur":1200,"legende":"The new Door of No Return, unveiled December 2025"}}]},{"id":"aujourdhui","repere":"Today","court":"2027","titre":"Return","ville":true,"temps":[["Since the law of 2 September 2024, a person of African descent whose ancestor was deported during the slave trade may apply for Beninese nationality. Proof may be provided through civil records, official documents, testimonies or a DNA test, which is not mandatory. Nationality is granted by decree, subject to conditions, and passes to descendants."],["In 2027 the Vodun Days will be held from 2 to 9 January. The traditional religions festival falls on Friday 8."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-egungun-vodun-days.webp","largeur":800,"hauteur":1200,"legende":"An Egungun during the Vodun Days"},"temps":1},{"hier":null,"auj":{"src":"/histoire/visite-cite-historique.webp","largeur":1200,"hauteur":675,"legende":"The entrance to the historic city of Ouidah"},"temps":0}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:histoire.histoireFinale','{"titre":"The Slave Route is walked, from Chacha Square to the beach.","texte":"Six stages, over roughly three to four kilometres."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:histoire.histoirePage','{"metaTitre":"The history of Ouidah — Ouidah Heritage Tour","metaDescription":"From Glexwé to Ouidah: the forts, Dahomey, the Chacha and the Agudas, the trade to the sea, the basilica, the Slave Route step by step, the new Door of No Return and the Vodun Days.","defiler":"Scroll down","hier":"Yesterday","avant":"Previous","aujourdhui":"Today","chapitres":"Chapters","cartes":{"royaume":{"src":"/histoire/carte-lune.webp","largeur":3146,"hauteur":2421},"ville":{"src":"/histoire/ville-1926-lune.webp","largeur":2400,"hauteur":2118}},"photoFin":"/histoire/fin-porte-nuit.webp","son":{"sources":["/son/histoire-bohicon.webm","/son/histoire-bohicon.m4a"],"volume":0.3,"fondu":4},"carteRoyaume":"Map of the kingdom of Whidah, engraved in the 18th century","carteVille":"Plan of Ouidah 1926","appel":{"principal":{"label":"Follow the Slave Route on foot","href":"/devis?circuit=route-des-esclaves"},"secondaire":{"label":"Create my trip","href":"/devis"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
