insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:credits-photos.creditsPhotos','[{"fichier":"/hero/hero-2-porte.jpg","oeuvre":"New Gate of No Return, side view","auteur":"MIA20102","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Nouvelle_Porte_du_Non-Retour_de_Ouidah_-_Vue_lat%C3%A9rale.jpg","modifiee":true},{"fichier":"/ouidah/aeroport-facade.jpg","oeuvre":"Facade of Cotonou Airport","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Fa%C3%A7ade_principale_de_l%27a%C3%A9roport_international_de_Cotonou.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-2-temple-pythons.jpg","oeuvre":"Entrance to the Temple of the Pythons","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_Temple_des_Pythons_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-3-plage-cocotiers.jpg","oeuvre":"Ouidah Beach (Benin, 2013)","auteur":"jbdodane","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Ouidah_(Benin,_2013).jpg","modifiee":true},{"fichier":"/ouidah/collage-danse-atchinan-kpasse.jpg","oeuvre":"Vodoun Atchinan, sacred forest of Kpassè (15)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._15.jpg","modifiee":true},{"fichier":"/ouidah/collage-danseur-kpasse.jpg","oeuvre":"Vodoun Atchinan, sacred forest of Kpassè (01)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._01.jpg","modifiee":true},{"fichier":"/ouidah/collage-egungun-vodun-days.jpg","oeuvre":"Egungun, Vodun Days","auteur":"Romario Coffi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Egungun_Allada_au_B%C3%A9nin_06.png","modifiee":true},{"fichier":"/ouidah/collage-fete-vodoun-2023.jpg","oeuvre":"Vodoun festival, 10 January 2023","auteur":"Dieu229","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:10_Janvier_2023,_F%C3%AAte_de_vodoun_%C3%A0_Ouidah_33.jpg","modifiee":true},{"fichier":"/ouidah/collage-marche-zobe.jpg","oeuvre":"Zobè Market","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-March%C3%A9_Zob%C3%A9.jpg","modifiee":true},{"fichier":"/ouidah/collage-vodun-days-2024.jpg","oeuvre":"Vodun Days 2024 in Ouidah","auteur":"Fermi12","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_Edition_2024_%C3%A0_Ouidah_au_B%C3%A9nin_18.jpg","modifiee":true},{"fichier":"/ouidah/collage-zangbeto-meko.jpg","oeuvre":"Zangbéto, Vodun Days 2026, Mèkô","auteur":"Gildas Lissassi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:VODUN_DAYS_2026_au_village_M%C3%A8k%C3%B4,_arrondissement_de_Dj%C3%AAgbadji_et_Commune_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-1-rue-basilique.jpg","oeuvre":"Vodun Square and Basilica","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_Vodun_place_and_Cathedral.jpg","modifiee":true},{"fichier":"/ouidah/eng-2-musee.jpg","oeuvre":"Ouidah History Museum","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_mus%C3%A9e_d%E2%80%99histoire_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-4-paillote.jpg","oeuvre":"Accommodation on Ouidah beach","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Habitation_sur_la_plage_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-7-vendeuses.jpg","oeuvre":"Female vendors, Ouidah beach","auteur":"GARNI RAFIK","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vendeuses-_plage_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/raison-arbre-du-retour.jpg","oeuvre":"Tree of Return","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Arbre_du_Retour_(1).jpg","modifiee":true},{"fichier":"/ouidah/raison-foret-kpasse.jpg","oeuvre":"Sacred forest of Kpassè","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Sacred_Forest_Ouidah_Benin_Jan_2018.jpg","modifiee":true},{"fichier":"/ouidah/raison-vodun-days.jpg","oeuvre":"Vodun Days, Ouidah arena","auteur":"Eureka9090","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_-_Ar%C3%A8ne_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/route-des-peches.jpg","oeuvre":"Fishing Route","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Route_des_p%C3%AAches_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/ouidah/visite-basilique.jpg","oeuvre":"Basilica of the Immaculate Conception","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Basilique_de_l%27Immacul%C3%A9e_Conception.jpg","modifiee":true},{"fichier":"/ouidah/visite-zoungbodji.jpg","oeuvre":"Zoungbodji Memorial","auteur":"Gbehlon","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_m%C3%A9morial_de_Zungboji.jpg","modifiee":true},{"fichier":"/histoire/place-chacha-stele-2017.webp","oeuvre":"Place Chacha, stele and gate (8)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(8).jpg","modifiee":true},{"fichier":"/histoire/maison-du-bresil.webp","oeuvre":"Brazil House, Ouidah (Ouidah 05)","auteur":"Satovgrad","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_05.jpg","modifiee":true},{"fichier":"/histoire/villa-ajavon-1922.webp","oeuvre":"Villa Ajavon","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_Villa_Ajavon_%C3%A0_Ouidah_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/histoire/plaque-ouidah92.webp","oeuvre":"Place Chacha, Ouidah 92 plaque (5)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(5).jpg","modifiee":true},{"fichier":"/histoire/memorial-zomachi-2017.webp","oeuvre":"Zomachi Memorial (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Memorial_Zomachi_(1).jpg","modifiee":true},{"fichier":"/histoire/place-chacha-2017.webp","oeuvre":"Place Chacha, fig tree and statue (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(1).jpg","modifiee":true},{"fichier":"/histoire/arbre-oubli-2015.webp","oeuvre":"Tree of Forgetting","auteur":"David Stanley","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Tree_of_Forgetting_(21136368019).jpg","modifiee":false},{"fichier":"/histoire/case-zomai-2019.webp","oeuvre":"Zomaï''s cage, Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_cage_de_Zoma%C3%AF_Ouidah.jpg","modifiee":true},{"fichier":"/histoire/porte-1995.webp","oeuvre":"Door of no return","auteur":"Francisco Anzola","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Door_of_no_return.jpg","modifiee":true},{"fichier":"/son/histoire-bohicon.webm","oeuvre":"Song, underground house of Agongointo, Bohicon (background audio for the History page)","auteur":"algoryn, radio aporee ::: maps","licence":"Public domain (PDM 1.0)","licenceUrl":"https://creativecommons.org/publicdomain/mark/1.0/","source":"https://archive.org/details/aporee_34624_39796","modifiee":true},{"fichier":"cartes","oeuvre":"Map background","auteur":"© les contributeurs d''OpenStreetMap, OpenMapTiles, OpenFreeMap","licence":"ODbL","licenceUrl":"https://opendatacommons.org/licenses/odbl/","source":"https://www.openstreetmap.org/copyright","modifiee":false}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:legal','{"_note":"Pages légales (mentions, confidentialité et cookies, CGV), en français, éditables depuis l''admin (à venir) : chaque information de la société a une valeur et un interrupteur « visible » ; une information masquée ou vide disparaît de toutes les pages (ligne de fiche, phrase qui la cite). Sources : RCCM, carte professionnelle APIEx, annonce légale (11-12/06/2026) ; Code du numérique du Bénin (loi 2017-20), art. 328 : capital social et adresse du siège sont des mentions obligatoires ; décret 2023-493 art. 38 : référence de la licence obligatoire. Références : Assets OHT/Pages-legales/recherches/REFERENCES.md. Blocs : p (texte, liens [texte](adresse), {clé} de la société), liste, fiche, tableau, composant.","miseAJour":"6 November 2026","societe":{"denomination":{"libelle":"Company name","valeur":"OUIDAH HERITAGE TOUR","visible":true},"forme":{"libelle":"Legal form","valeur":"Simplified joint‑stock company (SAS)","visible":true},"capital":{"libelle":"Share capital","valeur":"1 000 000 FCFA","visible":true},"siege":{"libelle":"Registered office","valeur":"Îlot 1158, plot F, house Sikiratou Moustapha Lawani, Haie Vive‑Cocotiers district, 12th arrondissement, Cotonou (Littoral), Benin","visible":true},"quartier":{"libelle":"Headquarters district (public)","valeur":"Haie Vive‑Cocotiers","visible":true},"ville":{"libelle":"Headquarters city (public)","valeur":"Cotonou","visible":true},"agence":{"libelle":"Agency in Ouidah","valeur":null,"visible":true},"rccm":{"libelle":"RCCM","valeur":"RB/COT/26 B 43278 of 11 June 2026, Commercial Court of Cotonou","visible":true},"ifu":{"libelle":"IFU","valeur":"3202629321372","visible":true},"carte":{"libelle":"Professional card","valeur":"Professional trader card No 1310CPC26, issued by APIEx, valid until 12 June 2028","visible":true},"licence":{"libelle":"Travel agency licence","valeur":null,"visible":true},"activite":{"libelle":"Activity","valeur":"Tourism and events, artistic and cultural activities","visible":true},"presidente":{"libelle":"Publication management","valeur":"Ms Nathalie Rosine RIFFERT, President","visible":true},"telephones":{"libelle":"Phone","valeur":["+229 01 98 87 36 36","+229 01 94 35 50 50"],"visible":true},"email":{"libelle":"E‑mail","valeur":"contact@ouidahheritagetour.bj","visible":true}},"pages":{"/mentions-legales":{"titre":"Legal notice","metaTitre":"Legal notice — Ouidah Heritage Tour","metaDescription":"Publisher, hosting, content ownership, photo credits and site accessibility for Ouidah Heritage Tour.","intro":"Who publishes this site, who hosts it and who to contact.","sections":[{"id":"editeur","titre":"The publisher","blocs":[{"fiche":["denomination","forme","capital","siege","agence","rccm","ifu","carte","licence","activite","telephones","email"]}]},{"id":"publication","titre":"Publication management","blocs":[{"p":"{presidente}."}]},{"id":"hebergement","titre":"Accommodation","blocs":[{"fiche":[["Website","Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, United States · [vercel.com](https://vercel.com)"],["Database","Supabase Pte. Ltd., 65 Chulia Street #38-02/03, OCBC Centre, Singapore 049513 · [supabase.com](https://supabase.com)"]]}]},{"id":"propriete","titre":"Texts, photos and logo","blocs":[{"p":"The logo, texts, illustrations and layout of this site belong to OUIDAH HERITAGE TOUR or their authors. To reuse them, even partially, ask us first for written permission at {email}."},{"p":"Photos published under a free licence are used according to their terms and their authors are credited below. Map tiles are © OpenStreetMap contributors, under ODbL licence."}]},{"id":"credits","titre":"Photo credits","blocs":[{"composant":"credits"}]},{"id":"accessibilite","titre":"Accessibility","blocs":[{"p":"We want everyone to be able to read this site and plan their trip. It can be navigated with a keyboard, images have descriptions, texts have sufficient contrast and animations are removed when your device requests reduced motion."},{"p":"A passage difficult to read or a button that does not respond? Write to us at {email} indicating the page: we will reply and fix it."}]},{"id":"liens","titre":"Links to other sites","blocs":[{"p":"The site sometimes links to official sites or partners, for example for visas or an event. Their content is the responsibility of their publishers."}]},{"id":"droit","titre":"Applicable law","blocs":[{"p":"This site is subject to Beninese law. For a reservation or order, the [terms and conditions of sale](/conditions-generales-de-vente#litiges) specify how to resolve a dispute."}]}]},"/politique-de-confidentialite":{"titre":"Privacy and cookies","metaTitre":"Privacy and cookies — Ouidah Heritage Tour","metaDescription":"The data Ouidah Heritage Tour collects, why, how long, what the site stores in your browser and how to exercise your rights.","intro":"What we collect, why, for how long, and how to exercise your rights. We do not sell any data and the site displays no advertising. Visits are counted only with your consent.","sections":[{"id":"responsable","titre":"Who is responsible for your data","blocs":[{"p":"{denomination}, {forme}, whose registered office is {siege}."},{"p":"For any question about your data, write to {email} with the subject “Personal data”, or by post to the registered office."}]},{"id":"donnees","titre":"What we collect and why","blocs":[{"p":"Only what you provide us in a form, and only for the stated reason."},{"tableau":{"colonnes":["When","Data","Why","How long"],"lignes":[["You request a quote (“Create my trip”)","Name, email, WhatsApp if you provide it, country, guide language, your trip (dates, locations, chosen services), your message","Respond to your request and prepare your quote, upon your request","3 years after our last exchange if no booking follows"],["You keep your request to resume it later","Your trip and your answers, without your contact details","We send you the retrieval link and retrieve your request","The link is valid for 30 days; an unsent draft is deleted 90 days after its creation"],["You book a ticket or a stay","Name, email, phone, country, language, package, number of places, amount, payment method and transaction reference","Create your booking, your ticket and your invoice","10 years, retention period for accounting records"],["You place an order in the shop","First name, last name, email, phone, country, delivery address if you choose delivery, items and options, your message","Confirm, prepare and deliver your order","10 years, retention period for accounting records"],["You subscribe to the Ouidah Newsletter","Email, language, chosen topics, date of your consent","We send you the newsletter, with your consent","Until you unsubscribe, which can be done at any time from each newsletter or by email"],["You submit a form","A hashed fingerprint of your IP address, never the address itself","Limit automated submissions and protect the service","The same duration as the request to which it is attached"]]}},{"p":"The appointment and partner application forms collect your contact details and the information you enter so our team can arrange the appointment or review your application. Incoming emails may be linked to your enquiry to help the team follow it up."}]},{"id":"paiement","titre":"Payment","blocs":[{"p":"You pay via the payment gateway you choose from those offered: Kkiapay, FedaPay, Stripe, Flutterwave or Paystack. We do not see or store your card numbers or Mobile Money codes: we receive the amount, the payment status and its reference."}]},{"id":"destinataires","titre":"Who receives your data","blocs":[{"liste":["The Ouidah Heritage Tour team who prepares your trip or your order.","Our technical providers, for this service only: Vercel (website hosting and, if you consent, audience measurement, United States), Supabase (database), our messaging {email}, hosted by AfriRegister (sending confirmation emails, quotes and tickets), the payment gateway you choose and Groq, Inc. (site AI assistant, United States).","Your stay partners (accommodation, transport, guide), for what they need only: your name, dates and number of travellers."]},{"p":"We do not sell or rent your data, and we do not use it for advertising."}]},{"id":"transferts","titre":"Data outside Benin","blocs":[{"p":"Some of our providers are based outside Benin, notably in the United States and Singapore. We only entrust them with what is necessary for the service, within the framework of their contractual data‑protection commitments."}]},{"id":"navigateur","titre":"What the site stores in your browser","blocs":[{"p":"To ensure you do not lose anything between pages, the site keeps some information in your browser. It remains on your device and only reaches us if you submit a form. It is required for the site to function."},{"liste":["Your travel file: destinations, itinerary, dates, services and selected tickets.","Your ongoing quote request, including the name and email you have already entered, so you do not have to re‑type them.","The chosen currency and the shop basket.","The return of a pending payment, cleared when the tab is closed.","The site opening already viewed, cleared when the tab is closed.","Your choices on the optional services below."]},{"p":"The site does not place any advertising or audience‑measurement cookies. To clear everything, delete this site’s data in your browser settings."}]},{"id":"assistant","titre":"Site assistant and chat with the team","blocs":[{"p":"OHT’s AI assistant answers your questions based on the sole content published on this site. To generate each response, your message and the latest conversation exchanges are sent to our subcontractor Groq, Inc., in the United States; we do not send them for any other purpose. The conversation is deleted when you leave the page, or after 30 minutes of inactivity. If you give the assistant information that our team must act on (travel project, quote request, contact details, complaint, unanswered question), it forwards a summary to the team: only this summary is retained, for 90 days. If you choose to write to a team member, the conversation and the email or WhatsApp number left for a callback remain with us for 90 days, then are deleted; a conversation turned into a request follows the request retention period. Questions the assistant could not answer are kept without your IP address or any identifier, after removing the emails, numbers and names they contain, so our team can respond and supplement the assistant’s knowledge. Your IP address is kept only as a fingerprint, to enforce usage limits (number of messages). You can request access, rectification or deletion of your data at {email}."}]},{"id":"cookies","titre":"Optional services, at your choice","blocs":[{"p":"Three services transmit data to a third party or count your visits. They only start with your consent, and refusing does not deprive you of any page."},{"fiche":[["Interactive maps","The map data comes from OpenFreeMap, which receives your IP address. Refused: the map is displayed as an image."],["Approximate city","Your city is derived from your IP address by our host, Vercel; otherwise from your time zone, via the Open-Meteo service. It is used to locate Ouidah relative to you and remains in your browser. Refused: you enter it yourself."],["Audience measurement","Page views, counted without cookies or identifiers by the OHT counter and by Vercel Web Analytics (United States), to know what interests our visitors. Refused: nothing is counted."]]},{"p":"You can change your mind at any time here or via the “Cookies” link at the bottom of each page."},{"composant":"choixCookies"}]},{"id":"securite","titre":"Security","blocs":[{"p":"The site is served over HTTPS. Our databases are only accessible to people who need them. Request‑resume links and tickets are signed; we keep only their hash, never the link itself."}]},{"id":"droits","titre":"Your rights","blocs":[{"p":"You can at any time access your data, have it corrected or erased, object to its use, request a copy in a readable format, and withdraw your consent for the Newsletter or optional services."},{"p":"Write to {email} with the subject “Personal data”. We may ask you to confirm your identity, then we will reply within 30 days."},{"p":"If our response does not satisfy you, you may contact the Personal Data Protection Authority (APDP): Rue 6.076, Aïdjèdo, El Marzouk Joël building, 01 BP 04837 Cotonou, Benin · +229 21 32 57 88 · contact@apdp.bj · [apdp.bj](https://apdp.bj)."},{"p":"You can also use [My data](/mes-donnees) to receive a personal link at your email address. This link lets you download your data or submit a deletion request to the team. Records needed to track payments and for accounting are retained."}]},{"id":"mineurs","titre":"Minors","blocs":[{"p":"Our bookings are for adults. A minor under 16 years only provides us with data with a parent’s consent."}]},{"id":"modifications","titre":"Updates","blocs":[{"p":"The date of the last update is shown at the top of this page. If a change affects an ongoing booking, we will write to you."}]}]},"/conditions-generales-de-vente":{"titre":"Terms and conditions of sale","metaTitre":"General terms and conditions of sale — Ouidah Heritage Tour","metaDescription":"Event tickets, quoted stays and Ouidah Heritage Tour shop: prices, payment, withdrawal, cancellation, delivery, returns and disputes.","intro":"The rules that apply when you book a ticket, a stay or order from the shop. Something unclear? Write to us before booking.","sections":[{"id":"champ","titre":"What these terms apply to","blocs":[{"p":"They apply to the sale of {denomination}, {forme} (see the [legal notice](/mentions-legales)) :"},{"liste":["tickets for events we organise;","stays, tours and accompaniment established on quotation, including around an event organised by others;","shop items;"]},{"p":"You accept them by confirming your booking or order. The version in force on that day remains yours."}]},{"id":"prix","titre":"Price and payment","blocs":[{"liste":["Prices are shown inclusive of all taxes, in CFA francs (XOF). The display in euros follows the fixed rate 1 € = 655.957 XOF.","For the shop, delivery charges are added to the item price and are shown before any payment.","You pay in full, without deposit, using one of the payment gateways offered at checkout. We never receive your card details."]}]},{"id":"retractation","titre":"Your right of withdrawal","blocs":[{"p":"You have 15 working days to change your mind without having to justify yourself: from the date of your payment for a ticket or a stay, or receipt for an item. Write to us at {email}; we will refund the full amount within 14 days using the payment method you used."},{"p":"This right no longer applies to a ticket or stay that has already been fully taken, nor to items made to order or personalised at your request."}]},{"id":"billets","titre":"Event tickets","blocs":[{"liste":["You book via the site’s calendar: select the package, number of places and contact details, then pay.","Your ticket, in your name and with a QR code, is sent to you by e‑mail as soon as the payment gateway confirms the payment. Show it on your phone or printed; each QR code grants entry once.","Unable to attend? After the withdrawal period, we refund the full amount up to 30 days before the event and half between 30 and 8 days before. After that, you can give your place to someone else: we transfer the ticket to the person you choose, free of charge, up to 48 hours before the event.","If we cancel or postpone the event, you can choose between a full refund or keeping your place for the new date."]}]},{"id":"sejours","titre":"Stays and accompaniment on quotation","blocs":[{"liste":["Your quotation request is free and non‑binding. The quotation details the services, dates, what is included and the total price. It is valid for 15 days.","Your reservation becomes firm when you accept the quotation and pay the full amount at once. We will then send you written confirmation of your trip.","For a stay linked to an event organised by others, such as the Vodun Days, we sell the stay, not the event. Its programme depends on the organisers; if it changes, we will adapt your stay with you.","Do you wish to change your dates or services? Let us know: we will adjust according to availability, and any price difference will be added or refunded to you.","After the withdrawal period, if you cancel, we refund the full amount up to 45 days before arrival, less any non-refundable costs already incurred with our partners, for which we provide details; half between 45 and 15 days before arrival; and less than 15 days before arrival, we offer to reschedule your stay, subject to availability.","If we have to cancel, we will refund the full amount or offer you another stay, whichever you prefer.","Passport, visa and yellow‑fever vaccination certificate are your responsibility: the \"Prepare your trip\" section guides you. Travel insurance, including repatriation, is strongly recommended.","We are responsible for the proper delivery of the services we sell. Flights you book yourself remain outside our scope."]}]},{"id":"boutique","titre":"Shop","blocs":[{"liste":["Your order is first a request. Within 2 working days we will confirm by e‑mail the availability, delivery method and total amount, fees included.","You pay in full after this confirmation; the sale is concluded upon receipt of payment.","Made‑to‑order or personalised items are produced after payment, within the timeframe indicated in the confirmation."]}]},{"id":"livraison","titre":"Delivery and returns","blocs":[{"liste":["Pick‑up in Ouidah, free of charge: the location and opening hours are listed in the confirmation.","Delivery to Benin and to the countries offered at checkout. Fees depend on the country and parcel; they are shown to you before payment.","Indicative times from dispatch: 2‑5 working days in Benin, 5‑10 in West Africa, 7‑21 elsewhere. We will provide you with the parcel tracking information.","Outside Benin, any import duties and taxes are the responsibility of the recipient.","Return of an item: within 15 working days of receipt, in its original condition. We will refund the item and the original delivery costs within 14 days after receiving it; return shipping costs are yours. An exchange of size or colour is possible within the same period, subject to stock.","Item damaged or different from your order: report it to us within 7 days of receipt, with photos. We will exchange, repair or refund it, at our expense.","Made‑to‑order or personalised items are neither returned nor exchanged, except for defects."]}]},{"id":"donnees","titre":"Your data","blocs":[{"p":"What we do with your details is described on the [Privacy and cookies](/politique-de-confidentialite) page."}]},{"id":"litiges","titre":"Claims and disputes","blocs":[{"p":"For any claim, contact us: {telephones} · {email}. We will reply within 7 working days and will first seek an amicable solution with you."},{"p":"You can also lodge a complaint with the Beninese tourism authority."},{"p":"These terms are governed by Beninese law; in the absence of agreement, the Commercial Court of Cotonou has jurisdiction. If you reside outside Benin, you retain the protections afforded by your own country''s law, including the right to bring a claim before your local court where applicable."}]}]}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:legal-ui.legalUi','{"miseAJour":"Last updated:","sommaire":"Summary","revoirChoix":"Review my choices"}'::jsonb,1,now()) on conflict(cle) do nothing;
