insert into public.contenu_site(cle,valeur,version,publie_le) values('EN:site.messages','{"fr.nav.sousLabel.m0":"Open the menu {label}","fr.nav.voyage.m0":"Your trip · {n}","fr.placesIntro.of.m0":"over {km} km of tours","fr.toursIntro.count.m0":"{n} itineraries","fr.toursIntro.count.m1":"{n} itinerary","fr.toursIntro.from.m0":"From {v0} FCFA","fr.cheminsIntro.ready.desc.m0":"itinerary designed","fr.cheminsIntro.ready.desc.m1":"itineraries designed","fr.cheminsIntro.ready.desc.m2":"{v0} by our guides","fr.cheminsIntro.ready.steps.m0":"step","fr.cheminsIntro.ready.steps.m1":"steps","fr.cheminsIntro.compose.desc.m0":"place","fr.cheminsIntro.compose.desc.m1":"places","fr.cheminsIntro.compose.desc.m2":"{v0} to see, where to stay, where to eat: keep what speaks to you","fr.cheminsIntro.compose.views.list.m0":"All places · {n}","fr.cheminsIntro.compose.position.m0":"Place {i} of {n}","fr.cheminsIntro.trip.count.m0":"saved place","fr.cheminsIntro.trip.count.m1":"saved places","fr.cheminsIntro.trip.count.m2":"No saved places","fr.cheminsIntro.trip.remove.m0":"Remove {nom}","fr.cheminsIntro.location.youAre.m0":"You are in {ville} · {km} km","fr.cheminsIntro.time.at.m0":"{h} in Ouidah","fr.cheminsIntro.time.night.m0":"nighttime · sunset at {h}","fr.cheminsIntro.time.day.m0":"daytime · sunrise at {h}","fr.cheminsIntro.globe.ouidah.m0":"place","fr.cheminsIntro.globe.ouidah.m1":"places","fr.cheminsIntro.globe.ouidah.m2":"Ouidah · {v0} to discover","fr.datesSection.titleStay.m0":"You will be in Ouidah","fr.datesSection.titleStay.m1":"day","fr.datesSection.titleStay.m2":"days","fr.datesSection.titleStay.m3":"in {v0}.","fr.datesSection.intro.m0":"{nom}, {date}: the next big event. Set your dates for the year, we’ll tell you what’s happening during your stay.","fr.datesSection.during.m0":"{nom} takes place during your stay.","fr.datesSection.after.m0":"{nom}, an Ouidah Heritage Tour event, starts just after your departure.","fr.datesSection.after.m1":"{nom} starts just after your dep