insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:site.seo','{"titre":"Ouidah Heritage Tour · Viajes a Ouidah, Benín","description":"Descubre Ouidah, su patrimonio y sus lugares de memoria con Ouidah Heritage Tour. Circuitos, eventos y viajes preparados con el equipo local.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.hero','{"kicker":["Agencia de turismo memorial y cultural","Ouidah, Benín"],"title":{"lead":"Ouidah,","accent":"ciudad del Vudú y de la memoria"},"sub":"Sigue a pie la Ruta de los Esclavos, desde la plaza Chacha hasta la Puerta del No-Volver, frente al Atlántico.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Vista aérea de la playa de Ouidah: olas del Atlántico, arena dorada y cocoteros"},{"src":"/hero/hero-2-porte.jpg","alt":"La nueva Puerta del No-Volver de Ouidah, vista de lado"}],"search":{"action":"/#chemins","label":"Buscar un circuito","submit":"Buscar","fields":[{"name":"lieu","label":"Destino","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Tipo de viaje","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Duración","objet":"calendrier","options":[{"value":"","label":"Todas las duraciones"},{"value":"demi-journee","label":"Media jornada"},{"value":"journee","label":"Un día"},{"value":"plusieurs-jours","label":"Varios días"}]}]},"primary":{"label":"Ver nuestros circuitos","href":"/#chemins"},"secondary":{"label":"Diseñar mi viaje a medida","href":"/devis"},"facts":[{"value":"1721","label":"Fuerte portugués, convertido en museo de historia"},{"value":"4 km","label":"Desde la plaza Chacha a la playa, por la Ruta de los Esclavos"},{"value":"2025","label":"Nueva Puerta del No-Volver"},{"value":"23 de agosto","label":"Día de recuerdo de la trata de esclavos"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.welcome','{"label":"Quiénes somos","title":["Bienvenido a casa,","en el corazón de tu Historia."],"paragraphs":["Ouidah Heritage Tour es mucho más que una agencia: es un compromiso con un turismo responsable y profundamente humano.","Te invitamos a vivir Ouidah al máximo de su esencia, un destino donde la historia, la espiritualidad, la cultura, el arte y la naturaleza se encuentran para ofrecerte una experiencia auténtica.","Cada viaje es único: nuestro equipo cuida tus intereses, tus expectativas y tus necesidades. Te acompañamos antes, durante y después del viaje."],"link":{"label":"La historia de Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Una joven guarda telas wax coloridas en el mercado"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Quiénes somos","segments":[{"text":"Bienvenido a casa,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"La Puerta del No-Volver iluminada, de noche"},"ring":"sun"},{"text":"en el corazón de tu Historia,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"La entrada pintada del Templo de los Pythons"},"ring":"abyss"},{"text":"desde la Ruta de los Esclavos"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"La playa de Ouidah al atardecer"},"ring":"sun"},{"text":"hasta el océano."}],"columns":[{"title":"Memoria y cultura","text":"Agencia de turismo memorial y cultural, le llevamos a pie por la Ruta de los Esclavos, con un guía que narra cada etapa."},{"title":"Los lugares que elige","text":"El Templo de los Pitones frente a la basílica, el bosque sagrado de Kpassè, el mercado de Zobè, la laguna en piragua. Componemos su estancia con los lugares que le hablan."},{"title":"Del aeropuerto a Ouidah","text":"Transporte desde el aeropuerto de Cotonou, alojamiento, comidas, vehículo: organizamos con usted todo lo que rodea la visita, antes, durante y después del viaje."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.placesIntro','{"kicker":"El mapa · De la ciudad al océano","title":"Ouidah en cuatro lugares","titleParts":{"before":"Ouidah en","number":"4","spoken":"cuatro","after":"lugares."},"intro":"Desplácese: el recorrido se dibuja en el mapa, del fuerte portugués hasta la Puerta del No-Volver, por las calles de la ciudad.","link":"Ver el lugar","walked":"km recorridos","mapLabel":"Mapa de Ouidah con los cuatro lugares y el recorrido a pie que los une"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Nuestros compromisos","title":"Siete compromisos, cumplidos en el terreno.","intro":"Lo que puede esperar de nosotros, desde la primera pregunta hasta el regreso.","of":"sobre"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.reasons','[{"title":"El territorio, conocido de cerca","text":"Del fuerte portugués a la playa, nuestros guías le llevan a pie.","couleur":"sun"},{"title":"Hechos verificados","text":"Los relatos de la visita se basan en la historia documentada del comercio.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"La entrada del museo de historia de Ouidah, en el fuerte portugués"}},{"title":"Su historia primero","text":"Su circuito se construye alrededor de su historia y sus preguntas.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"La entrada pintada del Templo de los Pythons"}},{"title":"Socios del país","text":"Alojamientos, comidas, guías y artesanos del país: elegimos con usted las direcciones de la estancia.","couleur":"abyss"},{"title":"Para la diáspora","text":"Nuestro circuito Regreso a las fuentes lleva a los afrodescendientes del fuerte a la Puerta del No-Volver.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"La Puerta del No-Volver frente al océano, a plena luz del día"}},{"title":"Antes, durante, después","text":"Respuesta en menos de 24 horas, bienvenida a la llegada, seguimiento hasta el regreso.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"La ruta de los Pesqueros, bordeada de cocoteros, en Ouidah"}},{"title":"Para los actores locales","text":"Participamos en la formación de los actores del turismo local y los damos a conocer.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.tenIntro','{"title":["Lo que la ciudad le reserva,","de la memoria al océano."],"link":{"label":"Descubrirlos","href":"/#raisons"},"place":"Ouidah","discover":"Descubrir el lugar","circle":"Rodear","circled":"Rodeada","path":{"label":"Ver mi camino","href":"#chemins"},"stripLabel":"Las vistas, de la memoria al océano","filmEdge":"OUDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.tenReasons','[{"slug":"route-des-esclaves","title":"La Ruta de los Esclavos","short":"Ruta de los Esclavos","category":"Memoria","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"El Árbol del Regreso, última estación de la Ruta de los Esclavos antes de la playa"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"Desde la plaza Chacha, donde se realizaban las subastas, hasta la playa: aproximadamente 4 km, el camino que recorrían los cautivos hasta los barcos. Se pasa por el Árbol del Olvido, alrededor del cual los hacían girar para borrar su nombre y origen, las Casillas Zomaï, donde los encerraban en la oscuridad, el memorial de Zoungbodji, y luego el Árbol del Regreso, para que su alma vuelva. Se recorre a pie, con un guía que narra cada etapa."},{"slug":"porte-du-non-retour","title":"La Puerta del No-Volver","short":"Puerta del No-Volver","category":"Memoria","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"La Puerta del No-Volver frente al océano, a plena luz del día"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"Al final de la Ruta de los Esclavos, en la playa, frente al Atlántico. Marca el lugar del embarque forzado de millones de africanos. El primer arco, inaugurado el 30 de noviembre de 1995 por iniciativa de la UNESCO, dio paso en diciembre de 2025 a una puerta más alta. Se llega a pie, tras las estaciones de la ruta, y se está allí, frente al mar."},{"slug":"temple-des-pythons","title":"El Templo de los Pitones","short":"Templo de los Pitones","category":"Fe","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"La entrada pintada del Templo de los Pythons"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Santuario vodún del culto a la serpiente Dangbé, atestiguado desde finales del siglo XVII, donde viven pitones sagrados. El templo está frente a la basílica de la Inmaculada Concepción: dos lugares que conviven lado a lado, a ambos lados de una misma plaza. La visita se realiza respetando las normas del sitio."},{"slug":"basilique","title":"La basílica, frente al templo","short":"Basílica","category":"Fe","image":{"src":"/ouidah/visite-basilique.jpg","alt":"La basílica de la Inmaculada Concepción de Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"Principal lugar de culto católico de Ouidah, la basílica de la Inmaculada Concepción fue construida entre 1903 y 1909, y elevada al rango de basílica menor en 1989. Se alza frente al Templo de los Pitones: en Ouidah se pasa de uno a otro cruzando una plaza."},{"slug":"musee-histoire","title":"El museo del fuerte portugués","short":"Museo de historia","category":"Historia","image":{"src":"/ouidah/lieu-musee.jpg","alt":"El fuerte portugués de Ouidah, que alberga el museo de historia"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"El fuerte portugués São João Baptista de Ajudá, construido en 1721, alberga desde el 6 de septiembre de 1967 el museo de historia de la ciudad: la trata, los reinos, los vínculos con Brasil y las Américas, a través de unas 700 piezas. El sitio está en obras para acoger el futuro Museo internacional de la memoria y de la esclavitud: le informamos antes de su visita lo que está abierto."},{"slug":"foret-sacree-kpasse","title":"El bosque sagrado de Kpassè","short":"Bosque de Kpassè","category":"Naturaleza","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"Bajo los grandes árboles del bosque sagrado de Kpassè, una escultura vodún"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"Una isla forestal de 4 hectáreas en pleno centro de la ciudad, vinculada al rey Kpassè. El bosque alberga deidades vodún y esculturas, y sirve de escenario para ceremonias, especialmente durante los Vodun Days. Se accede por una puerta pintada y luego se camina bajo los grandes árboles."},{"slug":"vodun-days","title":"Los Vodun Days","short":"Vodun Days","category":"Fiesta","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"Un Egungun en la arena de Ouidah durante los Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"Cada comienzo de enero, Ouidah acoge el gran encuentro anual de las culturas vodún: ceremonias, danzas rituales, exposiciones y encuentros, respetando las normas establecidas por las comunidades. La gran ceremonia y los conciertos se celebran en la playa, y otros momentos en el bosque de Kpassè. No organizamos el evento: organizamos su estancia alrededor."},{"slug":"memorial-zoungbodji","title":"El memorial de Zoungbodji","short":"Zoungbodji","category":"Memoria","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"El memorial de Zoungbodji, en la Ruta de los Esclavos"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"El memorial del pueblo de Zoungbodji marca el último lugar donde se alojaban los cautivos antes del embarque, cerca de la fosa común donde se arrojaban los muertos. Es la etapa más grave de la Ruta de los Esclavos, a unos 2 km de la playa y de la Puerta del No‑Retorno. Se hace una parada allí antes de volver al mar."},{"slug":"marches","title":"Artesanos, mercados, cocina","short":"Mercados","category":"Sabores","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Vendedoras llevando sus mercancías en una calle de Ouidah"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"El mercado de Zobè, cerca del fuerte portugués, y el del barrio de Kpassè marcan el ritmo de la vida de la ciudad. Nuestros guías los llevan, así como a los artesanos y a los buenos restaurantes de Ouidah, desde los puestos callejeros hasta los restaurantes. Es la ciudad de hoy, la que vive entre dos visitas."},{"slug":"plage-et-lagune","title":"La playa y la laguna","short":"Playa y laguna","category":"Océano","image":{"src":"/hero/hero-4-plage.jpg","alt":"La playa de Ouidah vista desde el aire, olas del Atlántico y cocoteros"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"Al final de la Ruta de los Esclavos, una larga playa poco acondicionada, donde se celebran la gran ceremonia y los conciertos de los Vodun Days. Detrás, la laguna separa la ciudad del océano: uno de los ecosistemas costeros más importantes de Benín, que se descubre en piragua desde el pequeño embarcadero. La ruta de la Pesca, bordeada de cocoteros, corre entre ambos. No se recomienda bañarse en caso de viento fuerte."}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.toursIntro','{"label":"Nuestros circuitos","all":{"label":"Todos los circuitos","href":"/#chemins"},"onRequest":"Precio a solicitud","durationPending":"Duración por confirmar","filtersLabel":"Filtrar los circuitos"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.cheminsIntro','{"origin":[2.0901,6.3589],"timeZone":"Africa/Porto-Novo","kicker":"Nuestros circuitos · Partiendo de Ouidah","title":{"lead":"Tu camino","accent":"hacia Ouidah."},"intro":"Elija un circuito ya preparado por nuestros guías, o seleccione sus lugares uno a uno: lo convertimos en su viaje.","ready":{"label":"Circuitos listos","heading":"Circuitos elaborados por nuestros guías.","book":"Reservar este circuito","customize":"Personalizarlo"},"compose":{"label":"Crear mi camino","heading":"Guarda los lugares que te hablan.","views":{"deck":"Un lugar a la vez"},"viewsLabel":"Forma de recorrer los lugares","skip":"Pasar","keep":"Guardar este lugar","kept":"Guardado","see":"Ver","noPhoto":"Foto próximamente","done":"Has recorrido todos los lugares.","restart":"Rever los lugares","far":"Más lejos"},"filters":[{"key":"a-voir","label":"Para ver","ids":["a-voir"],"color":"#ac3215","group":"voir","on":true},{"key":"plage","label":"Playas","ids":["plage"],"color":"#2a7ab8","group":"voir","on":true},{"key":"nature","label":"Naturaleza","ids":["nature"],"color":"#3f8a4e","group":"voir","on":true},{"key":"hebergement","label":"Dónde dormir","ids":["hebergement"],"color":"#0f162d","group":"dormir","on":true},{"key":"restauration","label":"Dónde comer","ids":["restauration"],"color":"#c98a00","group":"manger","on":true},{"key":"artisanat","label":"Artesanía","ids":["artisanat"],"color":"#8a4fb3","group":"voir","on":true},{"key":"marche","label":"Mercados","ids":["marche"],"color":"#d9661f","group":"voir","on":true},{"key":"pratique","label":"Práctico","ids":["sante","argent","transport","services"],"color":"#5b6478","group":"pratique","on":false},{"key":"culte","label":"Lugares de culto","ids":["culte"],"color":"#8a8f9c","group":"voir","on":false}],"filtersLabel":"Lugares mostrados en el mapa","groups":{"voir":"Para ver y vivir","dormir":"Dónde dormir","manger":"Dónde comer","pratique":"Práctico"},"place":{"add":"Añadir a mi viaje","remove":"Quitar de mi viaje","close":"Cerrar la ficha","call":"Llamar","website":"Sitio web","outside":"Fuera de Ouidah","verification":{"osm":"Registrado en OpenStreetMap, por confirmar","web":"Registrado en fuentes públicas, por confirmar","osm+web":"Confirmado por varias fuentes"}},"mapLocale":{"CooperativeGesturesHandler.WindowsHelpText":"Ctrl + rueda para acercar el mapa","CooperativeGesturesHandler.MacHelpText":"⌘ + rueda para acercar el mapa","CooperativeGesturesHandler.MobileHelpText":"Dos dedos para mover el mapa","NavigationControl.ZoomIn":"Acercar","NavigationControl.ZoomOut":"Alejar","AttributionControl.ToggleAttribution":"Fuentes del mapa"},"trip":{"label":"Tu camino","empty":"Guarda un lugar: se añade aquí.","note":"Orden, duración y tarifa ajustados contigo.","cta":"Solicitar este viaje","href":"/devis","back":"Buen regreso: tus lugares te esperaban.","saved":"Guardado en este dispositivo, sin cuenta."},"location":{"ask":"¿De dónde partes?","change":"Modificar","field":"Tu ciudad de salida","placeholder":"Ej.: Montreal, París, Abiyán","submit":"Validar","notFound":"Ciudad no encontrada, prueba otra ortografía.","you":"tú"},"time":{},"globe":{"label":"La Tierra en este momento, girando hacia Ouidah"},"mapLabel":"Mapa de los lugares de Ouidah y sus alrededores","mapFallback":"El mapa interactivo no puede mostrarse en este navegador. Los lugares deben elegirse uno a uno.","tabs":"Elige cómo componer tu viaje"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.datesSection','{"title":{"lead":"Venir a","accent":"buen momento."},"none":"No hay grandes citas en esas fechas: Ouidah se visita todo el año.","units":{"days":"días","hours":"h","minutes":"min","seconds":"s"},"live":{"arrival":"Llegada","departure":"Salida","end":"Fin"},"pass":{"oht":"Evento OHT","date":"Fecha","place":"Lugar","in":"En","arrival":"Llegada","departure":"Salida","nights":"Noches","during":"Durante tu estancia","after":"Justo después de tu salida","onRequest":"Tarifa a petición","extendCta":"Prolongar","bookStay":"Reservar la estancia","bookPlace":"Reservar mi plaza","byOht":"Organizado por Ouidah Heritage Tour · tus billetes aparecen tras el pago confirmado.","formulas":"Fórmula"},"talon":{"titre":"Sus datos de contacto","ouvrir":"Reservar mi plaza","fermer":"Cerrar la reserva","places":"Plazas","moins":"Una plaza menos","plus":"Una plaza más","accompagnement":"Tu acompañamiento","accompagnementNote":"según presupuesto, respuesta en 24 h","deja":"ya elegido en la Conserjería","unique":{"titre":"Un solo envío, una sola referencia."},"nom":"Nombre y apellidos","email":"Correo electrónico","repris":"recuperado de tu solicitud","payerAvec":"Pagar con","passerelles":{"kkiapay":{"nom":"Kkiapay","moyens":"Mobile Money, tarjeta"},"fedapay":{"nom":"FedaPay","moyens":"Mobile Money, tarjeta"},"stripe":{"nom":"Stripe","moyens":"Tarjeta bancaria"},"flutterwave":{"nom":"Flutterwave","moyens":"Tarjeta bancaria"},"paystack":{"nom":"Paystack","moyens":"Tarjeta, Mobile Money"}},"accord":"Acepto que Ouidah Heritage Tour use esta información para mi reserva.","confidentialite":{"label":"Privacidad","href":"/politique-de-confidentialite"},"envoi":"Preparando el pago…","attente":{"devis":"Tu solicitud de acompañamiento ya está anotada.","autre":"Pagar de otra forma"},"verification":"Verificando tu pago…","nonConfirme":{"titre":"Pago aún no confirmado","texte":"Si ya pagaste, la confirmación suele llegar en unos segundos.","reessayer":"Verificar de nuevo"},"paye":{"titreSans":"Está reservado.","entree":"A presentar en la entrada","precedent":"Billete anterior","suivant":"Billete siguiente","telecharger":"Descargar los billetes","reference":"Referencia de tu viaje","suivi":"Ver mi ticket y mi recibo","recap":{"formule":"Fórmula","paye":"Pagado","devis":"Según presupuesto"},"tampon":"PAGADO"},"erreurs":{"champs":"Falta su nombre, su correo electrónico o su consentimiento.","limite":"Se han realizado varias reservas desde esta conexión. Inténtelo de nuevo en una hora.","surDemande":"El precio de esta fórmula está disponible bajo petición: lo añadimos a su viaje.","passerelle":"Este método de pago no está disponible. Elija otro.","indisponible":"El pago en línea no responde en este momento. Inténtelo de nuevo en un instante."},"surDemande":"Añadir a mi viaje"},"scrub":{"ask":"¿Cuándo viene?","hint":"Deslice la cápsula sobre el año","place":"Reserve su estancia","today":"Hoy","legendOht":"Evento OHT","legendOther":"Gran cita","lengths":[{"label":"Fin de semana","nuits":2},{"label":"Semana","nuits":7},{"label":"10 noches","nuits":10},{"label":"2 semanas","nuits":14}],"lengthsLabel":"Duración de la estancia","reset":"Borrar mis fechas"},"timeZone":"Africa/Porto-Novo","fallbackImage":{"src":"/hero/hero-4-plage.jpg","alt":"La playa de Ouidah vista desde el aire, olas del Atlántico y cocoteros"}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.prepare','{"title":["Prepare su viaje,","con el mapa en mano."],"lead":"Ouidah está en la costa, a 41 km del aeropuerto. Lo esencial cabe en unos pocos consejos.","carte":{"ouidah":[2.0851,6.3622],"aeroport":[2.3844,6.3573],"porte":[2.0896,6.3243],"ville":"Ouidah","villeSous":"Costa atlántica","ocean":"Océano Atlántico","pays":[{"nom":"Togo","lieu":[1.12,8.2]},{"nom":"Nigeria","lieu":[3.38,8.4]}],"cotonou":"Cotonou","aeroportNom":"aeropuerto internacional","porteNom":"Puerta del No-Volver","km":"41 km","kmSous":"por carretera, en lanzadera","ariaBenin":"Mapa de Benín: Ouidah, en la costa atlántica, a 41 km del aeropuerto de Cotonou","ariaCote":"La costa de Benín: la carretera del aeropuerto de Cotonou a Ouidah, 41 km"},"fiche":{"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"La Puerta del No-Volver frente al océano, en Ouidah"},"titre":"Ouidah","texte":"Ciudad histórica, frente al Atlántico.","heureTexte":"Misma hora que París en invierno.","fuseau":"Africa/Porto-Novo"},"accueil":{"titre":"Le esperamos.","texte":"A su llegada, el equipo le recibe en el aeropuerto, si lo desea."},"ongletsLabel":"Prepare su viaje, por tema","numeros":"Números útiles","question":"¿Una pregunta antes de partir? Respondemos en 24 horas.","whatsapp":"Escribir en WhatsApp","ecrire":{"label":"Hacer una pregunta","href":"/devis?demande=question"},"verifie":"2026-10-22"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.preparer','[{"id":"sur-place","court":"En el sitio","objet":"accueil","vue":"benin","titre":"Ouidah se visite con tranquilidad.","cle":{"valeur":"Acompañado","texte":"por nuestro equipo, antes, durante y después del viaje."},"mot":true,"points":["En el aeropuerto, le esperamos si lo desea: el shuttle le lleva hasta Ouidah.","Alojamiento y comidas: elegimos con usted entre las direcciones seleccionadas en Ouidah.","Antes de una foto de ceremonia o un retrato, basta una palabra: pregunte, es costumbre.","En la playa, disfrute de la arena y la puesta de sol; para nadar, pida consejo en el lugar, la corriente del Atlántico es fuerte."],"source":"Engagements OHT · France Diplomatie (15 sept. 2026) · FCDO"},{"id":"arriver","court":"Llegar","objet":"navette","vue":"cote","titre":"Llegar, simplemente.","cle":{"valeur":"41 km","texte":"del aeropuerto de Cotonou a Ouidah. El shuttle OHT le lleva allí."},"points":["Su e-Visa se solicita en línea, en evisa.bj: 30 o 90 días, respuesta en 1 a 96 horas.","Solicite al menos 7 días antes de la llegada, y manténgalo a mano.","Ciudadanos africanos: sin visa, hasta 90 días.","Viajeros franceses: pasaporte válido 6 meses después del regreso, billete de regreso en la mochila."],"source":"evisa.bj · France Diplomatie · OSRM (41 km)"},{"id":"sante","court":"Salud","objet":"sante","vue":"benin","titre":"Su salud, preparada.","cle":{"valeur":"1 visita","texte":"con su médico o en un centro de vacunación internacional, antes de la salida."},"points":["Vacunas al día, hepatitis A y tifus: su médico revisa con usted.","Fiebre amarilla: vacuna recomendada desde los 9 meses. Guarde su libreta en la mochila.","Contra los mosquitos: repelente y mangas largas por la noche. Su médico le dirá si es útil un tratamiento contra la malaria."],"source":"Ministerio de Salud de Benín (16 sept. 2026) · Institut Pasteur · OMS — fiebre amarilla: fuentes en desacuerdo, por confirmar"},{"id":"argent","court":"Dinero","objet":"type-voyage","vue":"benin","titre":"El dinero, sin cálculos.","cle":{"valeur":"15,24 €","texte":"por 10 000 FCFA. El tipo es fijo, todo el año."},"points":["El franco CFA está vinculado al euro: 1 € = 655,957 FCFA, sin variación.","Referencia rápida: 1 000 FCFA son aproximadamente 1,50 €.","Para retirar, elija los cajeros ubicados dentro de las agencias."],"source":"BCEAO · France Diplomatie"},{"id":"pratique","court":"Práctico","objet":"prise","vue":"benin","fiche":"heure","titre":"Bueno saber.","cle":{"valeur":"0 h","texte":"de diferencia con París en invierno, 1 h en verano."},"points":["220 V, enchufes C y E: los cargadores de Francia y Bélgica se conectan sin adaptador.","El francés es el idioma oficial; en Ouidah también se habla fon.","Una tarjeta SIM local MTN, Moov Africa o Celtiis, y usted sigue siendo localizable.","Temporada seca de noviembre a marzo, luego de mediados de julio a mediados de septiembre."],"source":"gouv.bj · ARCEP Bénin · IEC · IANA"}]'::jsonb,1,now()) on conflict(cle) do nothing;
