insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.newsletter','{"nom":"La carta de Ouidah","phraseSansHeure":"Esta noche, el sol se pone sobre la playa de Ouidah.","maintenant":"En Ouidah","photo":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"La playa de Ouidah, sus cocoteros y la pista de arena al final del día"},"choisir":"Elige lo que Ouidah te escribe","sujets":[{"id":"departs","nom":"Nuestras fechas de salida","texte":"Los próximos viajes y circuitos, con sus fechas.","objet":"calendrier"},{"id":"agenda","nom":"La agenda de Ouidah","texte":"Vodun Days, Jornada del recuerdo, Ouidah Blue: los eventos de la ciudad.","objet":"fete"}],"langue":"La carta en","field":"Tu dirección de correo electrónico","exemple":"vous@exemple.com","submit":"Recibir la carta","consent":"Acepto recibir la carta de Ouidah Heritage Tour. Cancelación con un clic.","envoi":"Registro en curso…","thanks":"Está anotado: la carta llegará a tu buzón.","echec":"El registro no se completó. Inténtalo de nuevo en un momento.","limite":"Varias inscripciones ya se han realizado desde esta conexión. Inténtalo de nuevo en una hora.","aucun":"Elige al menos un tema.","error":"Indica una dirección de correo válida y marca la casilla."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.collage','{"label":"Ouidah en imágenes","title":["Una ciudad","que se vive."],"images":[{"src":"/ouidah/collage-danse-atchinan-kpasse.jpg","alt":"Una bailarina adornada con collares de perlas, durante una ceremonia vodun en el bosque sagrado de Kpassè","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-egungun-vodun-days.jpg","alt":"Un Egungun con traje bordado, entre el público de los Vodun Days en Ouidah","credit":"Romario Coffi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-marche-zobe.jpg","alt":"La entrada del mercado Zobè, a la sombra de los grandes árboles","credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-danseur-kpasse.jpg","alt":"Un bailarín con pagna azul, en el suelo, durante una ceremonia vodun en el bosque sagrado de Kpassè","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-fete-vodoun-2023.jpg","alt":"Bailarines con trajes festivos y tocados rojos, en la fiesta del vodun del 10 de enero en Ouidah","credit":"Dieu229, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-zangbeto-meko.jpg","alt":"Dos Zangbéto con flecos coloridos durante los Vodun Days, en el pueblo de Mèkô (municipio de Ouidah)","credit":"Gildas Lissassi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-vodun-days-2024.jpg","alt":"Bailarinas con pagnas coloridos frente al público de los Vodun Days 2024 en Ouidah","credit":"Fermi12, Wikimedia Commons, CC BY-SA 4.0"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
