insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.places','[{"n":"01","name":"Museo de historia de Ouidah","kicker":"Fuerte portugués, 1721","text":"El fuerte portugués alberga desde el 6 de septiembre de 1967 el museo de historia de la ciudad: la trata, los reinos, los vínculos con Brasil y las Américas.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"El muro rojo del fuerte portugués de Ouidah"},"next":"680 m a pie hasta el Templo de los Pitones"},{"n":"02","name":"Templo de los Pitones","kicker":"Frente a la basílica","text":"El templo del pitón Dangbé está frente a la basílica de la Inmaculada Concepción, construida entre 1903 y 1909: dos estructuras que conviven lado a lado.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"La entrada pintada del Templo de los Pythons"},"next":"2,5 km hasta el memorial de Zoungbodji, por la plaza Chacha"},{"n":"03","name":"La Ruta de los Esclavos","kicker":"Aproximadamente 4 km, seis estaciones","text":"Desde la plaza Chacha hasta la playa, el camino que recorrían los cautivos hacia los barcos: el Árbol del Olvido, las Cabañas Zomaï, el Memorial de Zoungbodji, el Árbol del Regreso.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"El memorial de Zoungbodji, en la Ruta de los Esclavos"},"next":"2 km hasta la playa y la Puerta del No‑Regreso"},{"n":"04","name":"Puerta del No-Volver","kicker":"Erigida en 1995, reconstruida en 2025","text":"En la playa, frente al Atlántico, marca el lugar del embarque forzado de millones de africanos.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"La Puerta del No-Volver iluminada, de noche"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
