insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.evenements','[{"slug":"vodun-days","title":"Vodun Days","short":"Vodun Days","theme":"Espiritualidad","place":"Ouidah","text":"El gran encuentro anual de las culturas Vodun: ceremonias, danzas rituales, exposiciones y encuentros, respetando las normas establecidas por las comunidades.","image":{"src":"https://images.pexels.com/photos/38242758/pexels-photo-38242758.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Disfraz y máscara Egungun bordados con colores vivos"},"quand":{"type":"editions","dates":[["2027-01-02","2027-01-09"]]},"organisateur":{"type":"externe","nom":"Evento nacional"},"offre":{"type":"sejour","nom":"Estancia Vodun Days","inclus":"alojamiento, traslados, guía, acceso acompañado","nuits":null,"prix":null,"places":null}},{"slug":"ouidah-blue","title":"Ouidah Blue","short":"Ouidah Blue","theme":"Cultura","place":"Ouidah","text":"Encuentro festivo alrededor de la escena artística local e internacional: música, artes visuales y encuentros.","image":null,"quand":{"type":"paques","debut":-1,"fin":1},"organisateur":{"type":"oht"},"offre":{"type":"billet","categories":[{"nom":"Plaza","detail":"acceso al evento","prix":null},{"nom":"Plaza y estancia","detail":"tu plaza, alojamiento incluido","prix":null,"logement":true}],"places":null,"jauge":null}},{"slug":"souvenir-23-aout","title":"Día internacional de la memoria de la trata de esclavos y su abolición","short":"Día de la memoria de la trata","theme":"Memoria","place":"Ruta de los Esclavos, Ouidah","text":"Fecha reconocida por la UNESCO, marcada en Ouidah con ceremonias de recogimiento en la Ruta de los Esclavos.","image":{"src":"https://images.pexels.com/photos/20231862/pexels-photo-20231862.jpeg?auto=compress&cs=tinysrgb&w=2400","alt":"Una viajera frente a las olas, en la playa de Ouidah al atardecer"},"quand":{"type":"annuel","mois":8,"jour":23,"jours":1},"organisateur":{"type":"externe","nom":"Conmemoración pública"},"offre":{"type":"sejour","nom":"Estancia de la memoria","inclus":"alojamiento, traslados, guía, ceremonia acompañada","nuits":null,"prix":null,"places":null}}]'::jsonb,1,now()) on conflict(cle) do nothing;
