insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.conciergerie','[{"id":"navette","court":"Transporte","nom":"Transporte.","question":"¿Un trayecto o ida y vuelta?","moment":"A la llegada","lead":"Desde el aeropuerto internacional Cardinal Bernardin Gantin: aproximadamente 41 km por carretera.","leadReleve":null,"objet":"navette","photo":{"src":"/ouidah/aeroport-fresque.jpg","alt":"El fresco «Bienvenido a Benín» en el aeropuerto de Cotonou"},"credit":"Houss 2020, Wikimedia Commons, CC0","options":[{"label":"Ida","detail":"Aeropuerto → Ouidah","releve":null,"phrase":"el transporte a la llegada"},{"label":"Ida y vuelta","detail":"Y el día de la salida","releve":null,"phrase":"el transporte ida y vuelta"},{"label":"No es necesario","detail":null,"releve":null,"passe":true}]},{"id":"accueil","court":"Recepción","nom":"Recepción.","question":"¿Dónde quiere que lo esperemos?","moment":"A su llegada","lead":null,"leadReleve":null,"objet":"accueil","photo":{"src":"/ouidah/aeroport-facade.jpg","alt":"La fachada del aeropuerto internacional de Cotonou"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"En el aeropuerto","detail":"Al salir","releve":null,"phrase":"la recepción en el aeropuerto"},{"label":"En Ouidah","detail":"En su dirección","releve":null,"phrase":"la recepción en Ouidah"},{"label":"No es necesario","detail":null,"releve":null,"passe":true}]},{"id":"telephone","court":"Teléfono","nom":"Teléfono.","question":"¿Una tarjeta SIM al llegar?","moment":"El primer día","lead":null,"leadReleve":null,"objet":"telephone","photo":{"src":"/ouidah/eng-1-rue-basilique.jpg","alt":"Una calle de Ouidah, hacia la basílica"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Tarjeta SIM","detail":"Llamar, escribir","releve":null,"phrase":"una tarjeta SIM"},{"label":"Tarjeta SIM + datos","detail":"Y internet móvil","releve":null,"phrase":"una tarjeta SIM con internet"},{"label":"No es necesario","detail":null,"releve":null,"passe":true}]},{"id":"hebergement","court":"Alojamiento","nom":"Alojamiento.","question":"¿Qué tipo de dirección?","moment":"La primera noche","lead":"{n} direcciones registradas en Ouidah. Elegimos contigo la que te represente.","leadReleve":"hebergement","objet":"hebergement","photo":{"src":"/ouidah/eng-3-case-plage.jpg","alt":"Una casita redonda con techo de paja, frente a la playa"},"cadre":"50% 85%","credit":null,"options":[{"label":"Hotel","detail":null,"releve":"hebergement/Hôtel","phrase":"un hotel"},{"label":"Albergue","detail":null,"releve":"hebergement/Auberge","phrase":"una posada"},{"label":"Casa de huéspedes","detail":null,"releve":"hebergement/Maison d''hôtes","phrase":"una casa de huéspedes"},{"label":"Campement","detail":null,"releve":"hebergement/Campement","phrase":"un campamento"},{"label":"Ya he reservado","detail":null,"releve":null,"passe":true}]},{"id":"tables","court":"Mesas","nom":"Mesas.","question":"¿Dónde te gusta comer?","moment":"En la mesa","lead":"{n} mesas registradas en Ouidah. Se pueden elegir varias opciones.","leadReleve":"restauration","multi":true,"objet":"tables","photo":{"src":"/ouidah/eng-4-paillote.jpg","alt":"Una palapa al borde de la playa de Ouidah"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Restaurantes","detail":null,"releve":"restauration/Restaurant","phrase":"restaurantes"},{"label":"Bares","detail":null,"releve":"restauration/Bar","phrase":"bares"},{"label":"Cafés","detail":null,"releve":"restauration/Café","phrase":"cafés"},{"label":"No es necesario","detail":null,"releve":null,"passe":true}]},{"id":"vehicule","court":"Vehículo","nom":"Vehículo.","question":"¿Con o sin conductor?","moment":"Los días siguientes","lead":"Para llegar a la playa por la ruta de los Pescados, Ganvié o Abomey a su ritmo.","leadReleve":null,"objet":"vehicule","photo":{"src":"/ouidah/route-des-peches.jpg","alt":"La ruta de la Pesca, bordeada de farolas, entre laguna y océano"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Con conductor","detail":null,"releve":null,"phrase":"un vehículo con conductor"},{"label":"Sin conductor","detail":null,"releve":null,"phrase":"un vehículo sin conductor"},{"label":"No es necesario","detail":null,"releve":null,"passe":true}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:histoire.histoireOuverture','{"titre":"De Glexwé a Ouidah","texte":"En fon, la ciudad se llama Glexwé, que a menudo se traduce como «la casa de los campos». Los europeos anotaron de varias maneras el nombre del reino houéda al que pertenecía: Whydah en inglés, Juda en francés, Fida en neerlandés, Ajudá en portugués. De ahí Ouidah. Ya en 1681, un inglés fechó una carta «Agriffie in Whidaw»: Glexwé, en la tierra houéda.","noms":["Glexwé","Whydah","Juda","Fida","Ajudá","Ouidah"]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:histoire.histoireChapitres','[{"id":"avant","repere":"siglo XVII","court":"XVII","titre":"Antes de los fuertes","ville":false,"temps":[["En el siglo XVII, Glexwé es la ciudad baja del reino houéda, al norte de una laguna. El rey vive en Savi, a unas diez kilómetros más al norte. Durante mucho tiempo dominado por su vecino Allada, el pequeño reino se emancipa en la segunda mitad del siglo.","Cuando los europeos se instalan, a finales del siglo, la mayor parte de los asuntos se tratan en Savi, cerca del palacio. Las excavaciones realizadas en el sitio desde 1991 solo han encontrado ladrillos holandeses y porcelana china dentro del recinto real, señal de que el rey controlaba el comercio."],["Según la tradición, los Houéda habrían venido de Tado, y su primer rey, Haholo, habría fundado Savi. La tradición da a Glexwé otro fundador, Kpassè. Cuenta que no murió como un hombre: se habría convertido en iroko. Ese árbol se venera en el bosque sagrado de Kpassè, en el barrio Tové, donde se ubica el pueblo anterior a la llegada de los europeos.","Otro nombre aparece en los relatos: Kpate, que habría recibido a los primeros europeos. Siempre tiene un culto en Ouidah."]],"pieces":[{"hier":{"src":"/histoire/plan-palais-savi-1747.webp","largeur":1173,"hauteur":1313,"legende":"El palacio del rey en Savi y los comercios europeos, plano grabado en 1747"},"auj":null},{"hier":{"src":"/histoire/couronnement-roi-juida-1723.webp","largeur":1100,"hauteur":847,"legende":"La coronación del rey houéda, grabado del siglo XVIII"},"auj":null},{"hier":null,"auj":{"src":"/histoire/raison-foret-kpasse.webp","largeur":1200,"hauteur":674,"legende":"El bosque sagrado de Kpassè, en el barrio Tové"}}]},{"id":"forts","repere":"1671 – 1721","court":"1671","titre":"Los fuertes","ville":true,"temps":[["En 1671, la Compañía Francesa de Indias Occidentales abre un comercio en el reino houéda. Es el primer establecimiento europeo permanente. Los ingleses llegan en la década de 1680. El comercio francés es destruido durante la guerra de 1692. Regresa en 1704 como un fuerte, que el corsario Jean Doublet construye en unas semanas, de tierra y paja.","José de Torres, comerciante venido de Bahía, funda en 1721 el fuerte portugués São João Baptista de Ajudá."],["En el siglo XVIII, los fuertes inglés, francés y portugués coexisten, a varios kilómetros de la playa. Los holandeses nunca tuvieron fuerte en Ouidah, ni los daneses.","Los ingleses abandonan el suyo en 1812. El fuerte francés es demolido en 1908. En su lugar se extiende una explanada donde, durante los Vodun Days, bailan los Zangbéto, guardianes de la noche. Hoy, solo el fuerte portugués sigue en pie."]],"pieces":[{"hier":{"src":"/histoire/fort-anglais-1727.webp","largeur":1226,"hauteur":410,"legende":"El fuerte inglés, llamado William''s Fort, grabado en 1727"},"auj":null},{"hier":{"src":"/histoire/fort-francais-plan-1747.webp","largeur":1330,"hauteur":1400,"legende":"Plano del fuerte francés, grabado en 1747"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-gravure-1886.webp","largeur":960,"hauteur":628,"legende":"El fuerte portugués, grabado de 1886"},"auj":{"src":"/histoire/eng-2-musee.webp","largeur":1200,"hauteur":900,"legende":"La entrada del fuerte portugués, convertido en museo de historia"}}]},{"id":"dahomey","repere":"1727","court":"1727","titre":"Le Dahomey","ville":false,"temps":[["En 1724, Agaja, rey de Dahomey, se apodera de Allada. A principios de marzo de 1727, su ejército toma Savi y la destruye, junto con los puestos europeos que allí se encontraban. Hufon, último rey houéda, huye hacia el oeste con parte de su pueblo, primero a una isla cerca de Grand-Popo. Otros houéda se establecen en Porto-Novo y en Badagry."],["Glexwé cambia de amo y de papel. El comercio con los europeos se concentra allí, y la ciudad se convierte en la principal plaza de comercio del Dahomey. Un gobernador se instala en 1733. Los europeos la llaman el vice-rey.","Más tarde, llevará el título fon de yovogan, «jefe de los Blancos», que el reino houéda ya utilizaba. El puesto siempre vuelve a un hombre del país. Los fuertes pasan bajo la autoridad del Dahomey: en julio de 1743, su ejército ataca el fuerte portugués."]],"pieces":[{"hier":{"src":"/histoire/comptoirs-savi-1747.webp","largeur":1400,"hauteur":948,"legende":"Los puestos europeos de Savi, grabados a partir de registros de 1725, dos años antes de la caída de la ciudad"},"auj":null}]},{"id":"chacha","repere":"1800 – 1849","court":"1800","titre":"El Chacha","ville":true,"temps":[["Francisco Félix de Souza, traficante de esclavos venido de Brasil, llega por primera vez a la costa a principios de la década de 1790 y se establece allí alrededor de 1800. Comienza como escribano‑contable en el fuerte portugués, lo dirige interinamente alrededor de 1806, y luego comercia por cuenta propia.","En conflicto con el rey Adandozan, es encarcelado en Abomey y escapa a Petit-Popo. Desde allí apoya el golpe de Estado que lleva a Ghézo al trono de Dahomey, probablemente en 1818. El nuevo rey lo nombra su agente comercial en Ouidah, donde regresa alrededor de 1820."],["Le apodan Chacha. El origen de la palabra es desconocido: una tradición la vincula al portugués «já, já», «¡ya, ya!», que él solía decir. Fundó al suroeste de la ciudad un barrio que más tarde recibirá el nombre de Brasil, Blézin en fon. Su familia, sus esclavos y sus clientes viven allí.","Una novela lo ha llamado «vice‑rey de Ouidah». Nunca lo fue: el cargo de yovogan correspondía a un dahomeyano."],["Muere en Ouidah el 8 de mayo de 1849, muy endeudado: debía 80 000 dólares al rey Ghézo. El rey elige para sucederle a su hijo mayor, Isidoro. El apodo se convierte entonces en un título hereditario, llevado desde entonces por el jefe de la familia Souza.","Su tumba se encuentra en la concesión familiar de Singbomey, detrás de la plaza Chacha. Desde 1999, una placa da ese nombre a la plaza. Los textos oficiales recientes también la llaman plaza de las Subastas."]],"pieces":[{"hier":{"src":"/histoire/portrait-de-souza.webp","largeur":1164,"hauteur":1400,"legende":"Retrato atribuido a Francisco Félix de Souza, pintado antes de 1849"},"auj":null},{"hier":{"src":"/histoire/place-chacha-stele-2017.webp","largeur":1400,"hauteur":933,"legende":"La estela «Plaza Chacha», en 2017"},"auj":null,"temps":2}]},{"id":"agudas","repere":"1835 – 1922","court":"1835","titre":"Los Agudas","ville":true,"temps":[["A partir de 1835, tras la revuelta de los Malês en Bahía, afrodescendientes liberados son expulsados de Brasil o empujados a partir. Muchos son yoruba. En Ouidah se instalan, entre otros, en el barrio Maro, al oeste del barrio Brasil, bajo la protección de De Souza.","Con las familias de comerciantes portugueses y brasileños, y las familias africanas vinculadas a ellos, forman los Agudas. En el siglo XIX, la palabra designa a los portugueses, incluidos los brasileños; proviene de Ajudá. Algunos Agudas, como la familia Souza, vivían del tráfico de esclavos."],["Sus descendientes llevan nombres como de Souza, da Silva, d''Almeida, Martins, Olympio o Paraïso. En Benín celebran Nosso Senhor do Bonfim en enero y bailan la bourian, una mascarada proveniente de Bahía."],["A lo largo de la costa, sus casas de varios pisos, con galerías, balaustradas, persianas y frontones ornamentados, recuerdan los sobrados de Salvador. A principios del siglo XX, este estilo se convierte en signo de éxito. También lo adoptan notables que no son agudas.","La villa Ajavon es un ejemplo. Su frontón lleva la inscripción «VILLA AJAVON 1922». Fue construida para Ajavon, un rico comerciante venido del vecino Togo. Desde el 11 de noviembre de 2013, alberga el museo de arte contemporáneo de la Fundación Zinsou."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/maison-du-bresil.webp","largeur":1120,"hauteur":1400,"legende":"La Casa de Brasil, en 2024"},"temps":2},{"hier":null,"auj":{"src":"/histoire/villa-ajavon-1922.webp","largeur":1400,"hauteur":1050,"legende":"La villa Ajavon, datada de 1922, convertida en museo de la Fundación Zinsou"},"temps":2}]},{"id":"mer","repere":"Final del siglo XVII – 1863","court":"1863","titre":"Hasta el mar","ville":false,"temps":[["Según estimaciones de historiadores, más de un millón de personas fueron deportadas desde Ouidah, desde finales del siglo XVII hasta los años 1860."],["La ciudad está a unos cuatro kilómetros del mar, detrás de una laguna. Los cautivos eran llevados a pie hasta la playa. Piraguas los hacían cruzar la barra, esos bancos de arena que cierran la costa, hasta los barcos anclados en alta mar."],["Partían principalmente hacia Brasil, especialmente Bahía, y hacia las Antillas, sobre todo Saint‑Domingue, la actual Haití. Al final del comercio, se dirigían a Cuba.","En la década de 1840, el comercio de aceite de palma despega, pero la trata continúa. En enero de 1852, bajo bloqueo británico, el rey Ghézo firma un tratado que la abolía. No tiene efecto duradero."],["En mayo de 1860, la goleta Clotilda parte de Ouidah con 110 cautivos a bordo. En julio, desembarca en secreto cerca de Mobile, Alabama. Es el último barco negrero conocido que llegó a los Estados Unidos.","El 10 de octubre de 1863, en Godomey, el vapor Cicerón embarca para Cuba a unas 960 personas, llevadas a pie desde Ouidah. Es el último embarque transatlántico conocido vinculado a Ouidah."]],"chiffre":{"valeur":"Más de un millón","legende":"de personas deportadas desde Ouidah, desde finales del siglo XVII hasta los años 1860, según estimaciones de historiadores"},"legende":[{"lettre":"A","nom":"Tiendas de los europeos"},{"lettre":"B","nom":"La ribera"},{"lettre":"C","nom":"Barcos en reparación"}],"pieces":[{"hier":null,"auj":{"src":"/histoire/bienvenue-3-plage-cocotiers.webp","largeur":1200,"hauteur":795,"legende":"La playa de Ouidah"}}]},{"id":"basilique","repere":"1903 – 2011","court":"1903","titre":"La pitón y la basílica","ville":true,"temps":[["Dangbé, la pitón real, es la deidad del reino houéda. Se encarna en serpientes vivas, guardadas en sus santuarios. Alrededor de 1700, un comerciante holandés anotó que las serpientes son las primeras deidades del reino."],["En Ouidah, su templo está frente a la basílica de la Inmaculada Concepción. La iglesia ocupa el terreno de la antigua residencia del yovogan, cedida en 1901 a la misión católica, llegada a Ouidah en 1861.","La primera piedra se colocó el 30 de agosto de 1903. Para construirla, todos los barrios de la ciudad trajeron arena desde la playa, incluidos los adeptos del vodún. La catedral se consagró el 9 de mayo de 1909, ante unas 4 000 personas."],["Se convirtió en basílica en 1989. El 19 de noviembre de 2011, Benedicto XVI firmó allí Africae munus, su exhortación sobre la Iglesia en África."]],"pieces":[{"hier":{"src":"/histoire/procession-serpent-1725.webp","largeur":1400,"hauteur":674,"legende":"Procesión al gran serpiente para la coronación del rey, grabado publicado en 1730"},"auj":null},{"hier":{"src":"/histoire/temple-serpent-1930.webp","largeur":1400,"hauteur":666,"legende":"El templo de la serpiente, alrededor de 1930"},"auj":{"src":"/histoire/bienvenue-2-temple-pythons.webp","largeur":1200,"hauteur":900,"legende":"La entrada del templo de los Pitones"}},{"hier":{"src":"/histoire/basilique-1930.webp","largeur":1003,"hauteur":1400,"legende":"La catedral, alrededor de 1930"},"auj":{"src":"/histoire/visite-basilique.webp","largeur":800,"hauteur":1200,"legende":"La basílica de la Inmaculada Concepción"}}]},{"id":"fort","repere":"1892 – 1990","court":"1961","titre":"El fuerte que arde","ville":true,"temps":[["En 1892, Ouidah pasa bajo ocupación francesa. Los franceses establecen la capital administrativa en Porto-Novo, y el comercio se traslada al muelle de Cotonou. La ciudad declina poco a poco. El fuerte portugués, por su parte, sigue en manos de Lisboa."],["El Dahomey se vuelve independiente el 1 de agosto de 1960. Un año día por día después, toma posesión del fuerte, que había sido una enclave portuguesa. Antes de irse, los dos últimos funcionarios portugueses lo incendiaron.","En 1967, el fuerte acoge el Museo de Historia de Ouidah. En 1975, el Dahomey adopta el nombre de Benín. Restaurado con la ayuda de la fundación portuguesa Gulbenkian, el fuerte reabre en agosto de 1990. Su rehabilitación, iniciada en 2020, debe convertirlo en el futuro Museo internacional de la memoria y de la esclavitud."]],"pieces":[{"hier":{"src":"/histoire/rue-1892.webp","largeur":1216,"hauteur":665,"legende":"Una calle de Ouidah, grabado de 1892"},"auj":null},{"hier":{"src":"/histoire/marche-1930.webp","largeur":1400,"hauteur":1290,"legende":"El mercado de Ouidah, alrededor de 1930"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-entree-1917.webp","largeur":600,"hauteur":440,"legende":"La entrada del fuerte portugués, en 1917"},"auj":{"src":"/histoire/lieu-musee.webp","largeur":1200,"hauteur":675,"legende":"Los muros del fuerte portugués"}}]},{"id":"souvenir","repere":"1993 – 1998","court":"1993","titre":"Recordar","ville":true,"temps":[["Del 8 al 18 de febrero de 1993, la ciudad acogió el festival Ouidah 92, dedicado a las artes y culturas vodún. Previsto para 1992, mantuvo ese nombre. Lo quiso el presidente Nicéphore Soglo. Sacerdotes y visitantes llegaron, entre otros, de Brasil, Haití y Trinidad y Tobago.","Para la ocasión, el bosque de Kpassè recibe estatuas de deidades vodún y se abre a visitantes no iniciados."],["El recorrido de la Ruta de los Esclavos nace durante este festival. Seis etapas, mayormente con esculturas de Cyprien Tokoudagba, llevan de la plaza Chacha a la playa, en unos tres o cuatro kilómetros. En septiembre de 1994, la UNESCO lanzó en Ouidah su programa « La Ruta del esclavo », propuesto por Haití y países africanos. El 30 de noviembre de 1995, la Puerta del No Retorno se inauguró en la playa, al final del camino.","En 1998 nace una marcha del arrepentimiento, a iniciativa del sociólogo Honorat Aguessy. El tercer domingo de enero, va de la plaza Chacha al memorial Zomachi, para pedir perdón a los descendientes de los deportados."]],"pieces":[{"hier":{"src":"/histoire/plaque-ouidah92.webp","largeur":933,"hauteur":1400,"legende":"La placa colocada para Ouidah 92 en la plaza de Subastas, en 2017"},"auj":null},{"hier":{"src":"/histoire/memorial-zomachi-2017.webp","largeur":1400,"hauteur":933,"legende":"El memorial Zomachi, en 2017"},"auj":null}]},{"id":"fete","repere":"1996 – 2026","court":"2024","titre":"La fiesta de enero","ville":true,"temps":[["En fon, vodun significa «deidad, espíritu». La palabra dio origen al vodou, en Haití. El 10 de enero de 1996, el gobierno de Nicéphore Soglo declaró este día como festivo y remunerado, en homenaje al vodun y a las religiones tradicionales. Una ley de agosto de 1997 lo convierte en una fiesta anual.","Durante años, la ceremonia oficial del 10 de enero se celebró en la playa de Ouidah, cerca de la Puerta del No‑Regreso."],["En octubre de 2023, el gobierno creó los Vodun Days, para abrir la fiesta a un público de todo el mundo. La primera edición tuvo lugar en Ouidah los 9 y 10 de enero de 2024, en cinco sitios: la plaza Maro, la explanada del Fuerte francés, la plaza del templo de los Pitones, un convento efímero de Mami y el bosque de Kpassè. Se contabilizaron cerca de 100 000 personas en las dos grandes noches.","Desde la ley del 2 de septiembre de 2024, la fiesta cae el segundo viernes de enero. Las ediciones 2025 y 2026 duran tres días."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-vodun-days-2024.webp","largeur":1200,"hauteur":675,"legende":"Bailarinas frente al público de los Vodun Days 2024, en Ouidah"},"temps":1},{"hier":null,"auj":{"src":"/histoire/collage-zangbeto-meko.webp","largeur":1200,"hauteur":801,"legende":"De Zangbéto a los Vodun Days 2026, en el pueblo de Mèkô, comuna de Ouidah"},"temps":1}]},{"id":"route","repere":"1993 – 2025","court":"2025","titre":"La Ruta, paso a paso","ville":true,"temps":[["Los relatos contados en las etapas forman parte de la tradición. El trayecto de los cautivos hasta el mar, por su parte, es un hecho establecido.","La Ruta parte de la plaza Chacha, también llamada plaza de las Subastas. Una placa colocada en 1993 afirma que allí se vendían los cautivos en subasta, bajo un gran árbol. Los testimonios de la época describen otra cosa: el precio de los cautivos lo fijaba el rey, y las ventas pasaban por sus agentes y por las casas de los comerciantes, como la de los de Souza, que bordean la plaza. Reurbanizada recientemente, la plaza es hoy una explanada pavimentada."],["A continuación aparece el Árbol del Olvido. Según la tradición contada a los visitantes, los hombres debían darle nueve vueltas, las mujeres siete, para olvidar su país. Este relato no aparece en ningún escrito antes de los años 1990. Los textos antiguos llaman a este lugar el Árbol de los capitanes: los jefes de Ouidah recibían allí a los europeos y les daban tres vueltas. El árbol original ha desaparecido."],["La casilla Zomaï lleva un nombre que significaría «donde el fuego, o la luz, no entra». La tradición sitúa allí a cautivos encerrados en la oscuridad. Escritos más antiguos asocian este nombre a las reservas de pólvora de De Souza."],["En Zoungbodji se erige un memorial. Según la tradición, los cautivos muertos antes de la partida fueron enterrados en ese lugar."],["Más adelante, el Árbol del Regreso. La tradición dice que los cautivos le daban tres vueltas, para que su alma volviera a África después de su muerte. Ninguna fuente de la época menciona este rito. Su estatua es de Cyprien Tokoudagba."],["El camino termina en la playa, en la Puerta del No‑Regreso. Es un monumento: los cautivos no partían de un punto preciso, sino de la playa, en piragua. El arco de 1995 fue reemplazado. Revelada en diciembre de 2025, la nueva Puerta se eleva más de dieciséis metros y lleva más de doscientas esculturas.","Desde 2021, la plaza, el fuerte portugués, los sitios de Zoungbodji y la playa de la Puerta figuran en la lista indicativa de Benín en la UNESCO, paso previo a una posible inscripción en el Patrimonio Mundial."]],"etapes":["Plaza Chacha","Árbol del Olvido","Casa Zomaï","Zoungbodji","Árbol del Regreso","Puerta del No-Volver"],"pieces":[{"hier":{"src":"/histoire/place-chacha-2017.webp","largeur":1400,"hauteur":933,"legende":"La plaza en 2017, con su gran árbol y la estela «Plaza Chacha»"},"auj":{"src":"/histoire/place-chacha-2025.webp","largeur":1400,"hauteur":787,"legende":"La plaza reurbanizada, en enero de 2025"}},{"hier":{"src":"/histoire/arbre-oubli-2015.webp","largeur":768,"hauteur":1024,"legende":"La escultura del Árbol del Olvido, colocada para Ouidah 92, en 2015"},"auj":null},{"hier":null,"auj":{"src":"/histoire/case-zomai-2019.webp","largeur":809,"hauteur":1400,"legende":"La estela de la casilla Zomaï, inaugurada en febrero de 1993 (foto de 2019)"}},{"hier":null,"auj":{"src":"/histoire/visite-zoungbodji.webp","largeur":1200,"hauteur":1200,"legende":"El memorial de Zoungbodji"}},{"hier":null,"auj":{"src":"/histoire/raison-arbre-du-retour.webp","largeur":800,"hauteur":1200,"legende":"El Árbol del Regreso y su estatua (foto de 2017)"}},{"hier":{"src":"/histoire/porte-1995.webp","largeur":1280,"hauteur":866,"legende":"El arco de 1995, fotografiado en 2019"},"auj":{"src":"/histoire/eng-5-porte-jour.webp","largeur":675,"hauteur":1200,"legende":"La nueva Puerta del No‑Regreso, revelada en diciembre de 2025"}}]},{"id":"aujourdhui","repere":"Hoy","court":"2027","titre":"Regresar","ville":true,"temps":[["Desde la ley del 2 de septiembre de 2024, una persona afrodescendiente con un ancestro deportado durante la trata puede solicitar la nacionalidad beninesa. La prueba puede presentarse mediante el registro civil, documentos oficiales, testimonios o una prueba de ADN, que no es obligatoria. La nacionalidad se concede por decreto, bajo condiciones, y se transmite a los descendientes."],["En 2027, los Vodun Days se celebran del 2 al 9 de enero. La fiesta de las religiones tradicionales cae el viernes 8."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-egungun-vodun-days.webp","largeur":800,"hauteur":1200,"legende":"Un Egungun durante los Vodun Days"},"temps":1},{"hier":null,"auj":{"src":"/histoire/visite-cite-historique.webp","largeur":1200,"hauteur":675,"legende":"La entrada de la ciudad histórica de Ouidah"},"temps":0}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:histoire.histoireFinale','{"titre":"La Ruta de los Esclavos se recorre a pie, desde la plaza Chacha hasta la playa.","texte":"Seis etapas, aproximadamente de tres a cuatro kilómetros."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:histoire.histoirePage','{"metaTitre":"La historia de Ouidah — Ouidah Heritage Tour","metaDescription":"De Glexwé a Ouidah: los fuertes, el Dahomey, el Chacha y los Agudas, la trata hasta el mar, la basílica, la Ruta de los Esclavos paso a paso, la nueva Puerta del No‑Regreso y los Vodun Days.","defiler":"Desplazar hacia abajo","hier":"Ayer","avant":"Anterior","aujourdhui":"Hoy","chapitres":"Capítulos","cartes":{"royaume":{"src":"/histoire/carte-lune.webp","largeur":3146,"hauteur":2421},"ville":{"src":"/histoire/ville-1926-lune.webp","largeur":2400,"hauteur":2118}},"photoFin":"/histoire/fin-porte-nuit.webp","son":{"sources":["/son/histoire-bohicon.webm","/son/histoire-bohicon.m4a"],"volume":0.3,"fondu":4},"carteRoyaume":"Mapa del reino de Whidah, grabado en el siglo XVIII","carteVille":"Plan de Ouidah en 1926","appel":{"principal":{"label":"Seguir la Ruta de los Esclavos, a pie","href":"/devis?circuit=route-des-esclaves"},"secondaire":{"label":"Crear mi viaje","href":"/devis"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:fr.creditsPage','{"intro":"Algunas fotos del sitio y la banda sonora de la página Historia están publicadas bajo licencia libre. Gracias a sus autores.","modifiee":"adaptada","carteSource":"© los colaboradores de OpenStreetMap"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:credits-photos.creditsPhotos','[{"fichier":"/hero/hero-2-porte.jpg","oeuvre":"Nueva Puerta del No-Volver, vista lateral","auteur":"MIA20102","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Nouvelle_Porte_du_Non-Retour_de_Ouidah_-_Vue_lat%C3%A9rale.jpg","modifiee":true},{"fichier":"/ouidah/aeroport-facade.jpg","oeuvre":"Fachada del aeropuerto de Cotonou","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Fa%C3%A7ade_principale_de_l%27a%C3%A9roport_international_de_Cotonou.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-2-temple-pythons.jpg","oeuvre":"Entrada del Templo de los Pitones","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_Temple_des_Pythons_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-3-plage-cocotiers.jpg","oeuvre":"Playa de Ouidah (Benín, 2013)","auteur":"jbdodane","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Ouidah_(Benin,_2013).jpg","modifiee":true},{"fichier":"/ouidah/collage-danse-atchinan-kpasse.jpg","oeuvre":"Vodoun Atchinan, bosque sagrado de Kpassè (15)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._15.jpg","modifiee":true},{"fichier":"/ouidah/collage-danseur-kpasse.jpg","oeuvre":"Vodoun Atchinan, bosque sagrado de Kpassè (01)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._01.jpg","modifiee":true},{"fichier":"/ouidah/collage-egungun-vodun-days.jpg","oeuvre":"Egungun, Vodun Days","auteur":"Romario Coffi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Egungun_Allada_au_B%C3%A9nin_06.png","modifiee":true},{"fichier":"/ouidah/collage-fete-vodoun-2023.jpg","oeuvre":"Fiesta del vodún, 10 de enero de 2023","auteur":"Dieu229","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:10_Janvier_2023,_F%C3%AAte_de_vodoun_%C3%A0_Ouidah_33.jpg","modifiee":true},{"fichier":"/ouidah/collage-marche-zobe.jpg","oeuvre":"Mercado Zobè","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-March%C3%A9_Zob%C3%A9.jpg","modifiee":true},{"fichier":"/ouidah/collage-vodun-days-2024.jpg","oeuvre":"Vodun Days 2024 en Ouidah","auteur":"Fermi12","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_Edition_2024_%C3%A0_Ouidah_au_B%C3%A9nin_18.jpg","modifiee":true},{"fichier":"/ouidah/collage-zangbeto-meko.jpg","oeuvre":"Zangbéto, Vodun Days 2026, Mèkô","auteur":"Gildas Lissassi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:VODUN_DAYS_2026_au_village_M%C3%A8k%C3%B4,_arrondissement_de_Dj%C3%AAgbadji_et_Commune_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-1-rue-basilique.jpg","oeuvre":"Plaza del vodún y basílica","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_Vodun_place_and_Cathedral.jpg","modifiee":true},{"fichier":"/ouidah/eng-2-musee.jpg","oeuvre":"Museo de historia de Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_mus%C3%A9e_d%E2%80%99histoire_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-4-paillote.jpg","oeuvre":"Vivienda en la playa de Ouidah","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Habitation_sur_la_plage_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-7-vendeuses.jpg","oeuvre":"Vendedoras, playa de Ouidah","auteur":"GARNI RAFIK","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vendeuses-_plage_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/raison-arbre-du-retour.jpg","oeuvre":"Árbol del Regreso","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Arbre_du_Retour_(1).jpg","modifiee":true},{"fichier":"/ouidah/raison-foret-kpasse.jpg","oeuvre":"Bosque sagrado de Kpassè","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Sacred_Forest_Ouidah_Benin_Jan_2018.jpg","modifiee":true},{"fichier":"/ouidah/raison-vodun-days.jpg","oeuvre":"Vodun Days, arena de Ouidah","auteur":"Eureka9090","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_-_Ar%C3%A8ne_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/route-des-peches.jpg","oeuvre":"Ruta de la Pesca","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Route_des_p%C3%AAches_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/ouidah/visite-basilique.jpg","oeuvre":"Basílica de la Inmaculada Concepción","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Basilique_de_l%27Immacul%C3%A9e_Conception.jpg","modifiee":true},{"fichier":"/ouidah/visite-zoungbodji.jpg","oeuvre":"Memorial de Zoungbodji","auteur":"Gbehlon","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_m%C3%A9morial_de_Zungboji.jpg","modifiee":true},{"fichier":"/histoire/place-chacha-stele-2017.webp","oeuvre":"Plaza Chacha, estela y portal (8)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(8).jpg","modifiee":true},{"fichier":"/histoire/maison-du-bresil.webp","oeuvre":"Casa de Brasil, Ouidah (Ouidah 05)","auteur":"Satovgrad","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_05.jpg","modifiee":true},{"fichier":"/histoire/villa-ajavon-1922.webp","oeuvre":"Villa Ajavon","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_Villa_Ajavon_%C3%A0_Ouidah_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/histoire/plaque-ouidah92.webp","oeuvre":"Plaza Chacha, placa Ouidah 92 (5)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(5).jpg","modifiee":true},{"fichier":"/histoire/memorial-zomachi-2017.webp","oeuvre":"Memorial Zomachi (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Memorial_Zomachi_(1).jpg","modifiee":true},{"fichier":"/histoire/place-chacha-2017.webp","oeuvre":"Plaza Chacha, higuera y estatua (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(1).jpg","modifiee":true},{"fichier":"/histoire/arbre-oubli-2015.webp","oeuvre":"Árbol del Olvido","auteur":"David Stanley","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Tree_of_Forgetting_(21136368019).jpg","modifiee":false},{"fichier":"/histoire/case-zomai-2019.webp","oeuvre":"La jaula de Zomaï, Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_cage_de_Zoma%C3%AF_Ouidah.jpg","modifiee":true},{"fichier":"/histoire/porte-1995.webp","oeuvre":"Puerta del No Retorno","auteur":"Francisco Anzola","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Door_of_no_return.jpg","modifiee":true},{"fichier":"/son/histoire-bohicon.webm","oeuvre":"Canto, casa subterránea de Agongointo, Bohicon (sonido de fondo de la página Historia)","auteur":"algoryn, radio aporee ::: maps","licence":"Dominio público (PDM 1.0)","licenceUrl":"https://creativecommons.org/publicdomain/mark/1.0/","source":"https://archive.org/details/aporee_34624_39796","modifiee":true},{"fichier":"cartes","oeuvre":"Fondos de mapa","auteur":"© les contributeurs d''OpenStreetMap, OpenMapTiles, OpenFreeMap","licence":"ODbL","licenceUrl":"https://opendatacommons.org/licenses/odbl/","source":"https://www.openstreetmap.org/copyright","modifiee":false}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:legal','{"_note":"Pages légales (mentions, confidentialité et cookies, CGV), en français, éditables depuis l''admin (à venir) : chaque information de la société a une valeur et un interrupteur « visible » ; une information masquée ou vide disparaît de toutes les pages (ligne de fiche, phrase qui la cite). Sources : RCCM, carte professionnelle APIEx, annonce légale (11-12/06/2026) ; Code du numérique du Bénin (loi 2017-20), art. 328 : capital social et adresse du siège sont des mentions obligatoires ; décret 2023-493 art. 38 : référence de la licence obligatoire. Références : Assets OHT/Pages-legales/recherches/REFERENCES.md. Blocs : p (texte, liens [texte](adresse), {clé} de la société), liste, fiche, tableau, composant.","miseAJour":"6 de noviembre de 2026","societe":{"denomination":{"libelle":"Denominación","valeur":"OUIDAH HERITAGE TOUR","visible":true},"forme":{"libelle":"Forma","valeur":"Sociedad por acciones simplificada (SAS)","visible":true},"capital":{"libelle":"Capital social","valeur":"1 000 000 FCFA","visible":true},"siege":{"libelle":"Sede social","valeur":"Isla 1158, parcela F, casa Sikiratou Moustapha Lawani, barrio Haie Vive-Cocotiers, 12.º distrito, Cotonou (Litoral), Benín","visible":true},"quartier":{"libelle":"Barrio de la sede (público)","valeur":"Haie Vive-Cocotiers","visible":true},"ville":{"libelle":"Ciudad de la sede (público)","valeur":"Cotonou","visible":true},"agence":{"libelle":"Agencia en Ouidah","valeur":null,"visible":true},"rccm":{"libelle":"RCCM","valeur":"RB/COT/26 B 43278 del 11 de junio de 2026, Tribunal de comercio de Cotonou","visible":true},"ifu":{"libelle":"IFU","valeur":"3202629321372","visible":true},"carte":{"libelle":"Tarjeta profesional","valeur":"Tarjeta profesional de comerciante n.º 1310CPC26, emitida por la APIEx, válida hasta el 12 de junio de 2028","visible":true},"licence":{"libelle":"Licencia de agencia de viajes","valeur":null,"visible":true},"activite":{"libelle":"Actividad","valeur":"Turismo y eventos, actividades artísticas y culturales","visible":true},"presidente":{"libelle":"Dirección de la publicación","valeur":"Sra. Nathalie Rosine RIFFERT, Presidenta","visible":true},"telephones":{"libelle":"Teléfono","valeur":["+229 01 98 87 36 36","+229 01 94 35 50 50"],"visible":true},"email":{"libelle":"Correo electrónico","valeur":"contact@ouidahheritagetour.bj","visible":true}},"pages":{"/mentions-legales":{"titre":"Avisos legales","metaTitre":"Avisos legales — Ouidah Heritage Tour","metaDescription":"Editor, alojamiento, propiedad de los contenidos, créditos fotográficos y accesibilidad del sitio Ouidah Heritage Tour.","intro":"Quién edita este sitio, quién lo aloja y a quién escribir.","sections":[{"id":"editeur","titre":"El editor","blocs":[{"fiche":["denomination","forme","capital","siege","agence","rccm","ifu","carte","licence","activite","telephones","email"]}]},{"id":"publication","titre":"Dirección de la publicación","blocs":[{"p":"{presidente}."}]},{"id":"hebergement","titre":"Alojamiento","blocs":[{"fiche":[["Sitio","Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, Estados Unidos · [vercel.com](https://vercel.com)"],["Base de datos","Supabase Pte. Ltd., 65 Chulia Street #38-02/03, OCBC Centre, Singapur 049513 · [supabase.com](https://supabase.com)"]]}]},{"id":"propriete","titre":"Textos, fotos y logotipo","blocs":[{"p":"El logotipo, los textos, las ilustraciones y el diseño de este sitio pertenecen a OUIDAH HERITAGE TOUR o a sus autores. Para reutilizarlos, incluso parcialmente, solicítenos primero un acuerdo por escrito a {email}."},{"p":"Las fotos publicadas bajo licencia libre se usan según sus condiciones y sus autores se citan en los créditos a continuación. Los fondos de mapa son © los colaboradores de OpenStreetMap, bajo licencia ODbL."}]},{"id":"credits","titre":"Créditos de fotos","blocs":[{"composant":"credits"}]},{"id":"accessibilite","titre":"Accesibilidad","blocs":[{"p":"Queremos que todos puedan leer este sitio y planificar su viaje. Se navega con el teclado, las imágenes tienen descripción, los textos tienen contraste y las animaciones se desactivan cuando su dispositivo solicita menos movimiento."},{"p":"¿Un pasaje difícil de leer o un botón que no responde? Escríbanos a {email} indicando la página: le responderemos y corregiremos."}]},{"id":"liens","titre":"Enlaces a otros sitios","blocs":[{"p":"El sitio a veces enlaza a sitios oficiales o socios, por ejemplo para el visado o un evento. Su contenido depende de sus editores."}]},{"id":"droit","titre":"Derecho aplicable","blocs":[{"p":"Este sitio está sujeto al derecho beninés. Para una reserva o un pedido, los [términos y condiciones de venta](/conditions-generales-de-vente#litiges) especifican cómo resolver un desacuerdo."}]}]},"/politique-de-confidentialite":{"titre":"Privacidad y cookies","metaTitre":"Privacidad y cookies — Ouidah Heritage Tour","metaDescription":"Los datos que recopila Ouidah Heritage Tour, por qué, cuánto tiempo, lo que el sitio guarda en su navegador y cómo ejercer sus derechos.","intro":"Qué recogemos, por qué, durante cuánto tiempo y cómo ejercer sus derechos. No vendemos datos y el sitio no muestra publicidad. Las visitas solo se cuentan con su consentimiento.","sections":[{"id":"responsable","titre":"Quién es responsable de sus datos","blocs":[{"p":"{denomination}, {forme}, con sede social en {siege}."},{"p":"Para cualquier consulta sobre sus datos, escriba a {email} con el asunto «Datos personales», o por correo a la sede."}]},{"id":"donnees","titre":"Lo que recopilamos y por qué","blocs":[{"p":"Solo lo que nos confía en un formulario, y solo por la razón indicada."},{"tableau":{"colonnes":["Cuándo","Datos","Por qué","Cuánto tiempo"],"lignes":[["Solicita un presupuesto («Crear mi viaje»)","Nombre, correo electrónico, WhatsApp si lo proporciona, país, idioma del guía, su viaje (fechas, lugares, servicios elegidos), su mensaje","Responder a su solicitud y preparar su presupuesto, a su petición","3 años después de nuestro último intercambio si no hay ninguna reserva"],["Mantienes tu solicitud para retomarla más tarde","Tu viaje y tus respuestas, sin tus datos de contacto","Te enviamos el enlace para reanudar y recuperar tu solicitud","El enlace es válido 30 días; un borrador nunca enviado se elimina 90 días después de su creación"],["Reservas un billete o una estancia","Nombre, correo electrónico, teléfono, país, idioma, fórmula, número de plazas, importe, método de pago y referencia de la transacción","Emitir tu reserva, tu billete y tu factura","10 años, período de conservación de los documentos contables"],["Realizas un pedido en la tienda","Nombre, apellidos, correo electrónico, teléfono, país, dirección de envío si eliges entrega, artículos y opciones, tu mensaje","Confirmar, preparar y entregar tu pedido","10 años, período de conservación de los documentos contables"],["Te suscribes al Boletín de Ouidah","Correo electrónico, idioma, temas elegidos, fecha de tu consentimiento","Te enviamos el boletín, con tu consentimiento","Hasta que te des suscribas, posible en cualquier momento desde cada boletín o por correo electrónico"],["Envías un formulario","Una huella cifrada de tu dirección IP, nunca la dirección en sí","Limitar los envíos automatizados y proteger el servicio","El mismo período que la solicitud a la que está vinculada"]]}},{"p":"Los formularios de citas y de candidatura de colaboradores recogen sus datos de contacto y la información que introduce para que nuestro equipo organice la cita o estudie su candidatura. Los correos recibidos pueden vincularse a su solicitud para facilitar su seguimiento."}]},{"id":"paiement","titre":"Pago","blocs":[{"p":"Pagas en la pasarela de pago que elijas entre las ofrecidas: Kkiapay, FedaPay, Stripe, Flutterwave o Paystack. No vemos ni guardamos tus números de tarjeta ni tus códigos Mobile Money: recibimos el importe, el estado del pago y su referencia."}]},{"id":"destinataires","titre":"Quién recibe tus datos","blocs":[{"liste":["El equipo de Ouidah Heritage Tour que prepara tu viaje o tu pedido.","Nuestros proveedores técnicos, solo para este servicio: Vercel (alojamiento del sitio y, si lo aceptas, medición de audiencia, EE. UU.), Supabase (base de datos), nuestro correo {email}, alojado por AfriRegister (envío de correos de confirmación, presupuestos y billetes), la pasarela de pago que elijas y Groq, Inc. (asistente IA del sitio, EE. UU.).","Los socios de tu estancia (alojamiento, transporte, guía), solo lo que necesitan: tu nombre, tus fechas y el número de viajeros."]},{"p":"No vendemos ni alquilamos tus datos, y no los usamos para publicidad."}]},{"id":"transferts","titre":"Datos fuera de Benín","blocs":[{"p":"Algunos de nuestros proveedores están ubicados fuera de Benín, especialmente en EE. UU. y Singapur. Solo les confiamos lo necesario para el servicio, dentro de sus compromisos contractuales de protección de datos."}]},{"id":"navigateur","titre":"Lo que el sitio guarda en tu navegador","blocs":[{"p":"Para que no pierdas nada de una página a otra, el sitio guarda cierta información en tu navegador. Permanece en tu dispositivo y solo nos llega si envías un formulario. Es necesaria para el funcionamiento del sitio."},{"liste":["Tu expediente de viaje: lugares, itinerario, fechas, servicios y billetes elegidos.","Tu solicitud de presupuesto en curso, incluido el nombre y el correo que ya ingresaste, para no volver a escribirlos.","La moneda elegida y el carrito de la tienda.","El retorno de un pago en curso, borrado al cerrar la pestaña.","La apertura del sitio ya vista, borrada al cerrar la pestaña.","Tus elecciones sobre los servicios opcionales a continuación."]},{"p":"El sitio no deposita ninguna cookie publicitaria ni de medición de audiencia. Para borrar todo, elimina los datos de este sitio en la configuración de tu navegador."}]},{"id":"assistant","titre":"Asistente del sitio y conversación con el equipo","blocs":[{"p":"El asistente IA de OHT responde a sus preguntas basándose únicamente en el contenido publicado en este sitio. Para generar cada respuesta, su mensaje y los últimos intercambios de la conversación se envían a nuestro subcontratista Groq, Inc., en Estados Unidos; no los enviamos a nadie más. La conversación se elimina cuando abandona la página, o después de 30 minutos sin actividad. Si le proporciona al asistente información que nuestro equipo debe actuar (proyecto de viaje, solicitud de presupuesto, datos de contacto, reclamación, pregunta sin respuesta), se envía un resumen al equipo: solo ese resumen se conserva durante 90 días. Si elige escribir a una persona del equipo, la conversación y el correo electrónico o número de WhatsApp dejados para ser contactado permanecen con nosotros 90 días, luego se eliminan; una conversación convertida en solicitud sigue la duración de las solicitudes. Las preguntas que el asistente no pudo responder se guardan sin su dirección IP ni ningún identificador, después de retirar los correos, números y nombres que contengan, para que nuestro equipo pueda responder y completar lo que el asistente sabe. Su dirección IP solo se conserva como huella, para aplicar los límites de uso (número de mensajes). Puede solicitar acceso, rectificación o eliminación de sus datos a {email}."}]},{"id":"cookies","titre":"Servicios opcionales, a su elección","blocs":[{"p":"Tres servicios transmiten datos a un tercero o contabilizan sus visitas. Solo se activan con su consentimiento, y rechazarlos no le priva de ninguna página."},{"fiche":[["Mapas interactivos","Los fondos de mapa provienen de OpenFreeMap, que recibe su dirección IP. Rechazado: el mapa se muestra como imagen."],["Ciudad aproximada","Su ciudad se deduce de su dirección IP por nuestro hospedador, Vercel; en su defecto, de su zona horaria, por el servicio Open-Meteo. Sirve para situar Ouidah respecto a su ubicación y permanece en su navegador. Rechazado: la ingresa usted mismo."],["Medida de audiencia","Las páginas vistas, contadas sin cookies ni identificadores por el contador de OHT y por Vercel Web Analytics (Estados Unidos), para saber qué interesa a nuestros visitantes. Rechazado: no se cuenta nada."]]},{"p":"Puede cambiar de opinión en cualquier momento aquí o con el enlace « Cookies » al pie de cada página."},{"composant":"choixCookies"}]},{"id":"securite","titre":"Seguridad","blocs":[{"p":"El sitio se sirve en HTTPS. Nuestras bases solo son accesibles para las personas que las necesitan. Los enlaces de reanudación de una solicitud y los boletos están firmados; solo conservamos la huella del enlace, nunca el enlace mismo."}]},{"id":"droits","titre":"Sus derechos","blocs":[{"p":"Puede en cualquier momento acceder a sus datos, corregirlos o eliminarlos, oponerse a su uso, solicitar una copia en formato legible y retirar su consentimiento para la Carta o los servicios opcionales."},{"p":"Escriba a {email} con el asunto « Datos personales ». Podemos pedirle que confirme su identidad y le responderemos en 30 días."},{"p":"Si nuestra respuesta no le satisface, puede acudir a la Autoridad de Protección de Datos Personales (APDP): Rue 6.076, Aïdjèdo, edificio El Marzouk Joël, 01 BP 04837 Cotonou, Benín · +229 21 32 57 88 · contact@apdp.bj · [apdp.bj](https://apdp.bj)."},{"p":"También puede utilizar [Mis datos](/mes-donnees) para recibir un enlace personal en su correo electrónico. El enlace permite descargar sus datos o enviar una solicitud de eliminación al equipo. Se conservan los justificantes necesarios para el seguimiento de los pagos y la contabilidad."}]},{"id":"mineurs","titre":"Menores","blocs":[{"p":"Nuestras reservas están dirigidas a adultos. Un menor de menos de 16 años solo nos transmite sus datos con el consentimiento de un padre o tutor."}]},{"id":"modifications","titre":"Actualizaciones","blocs":[{"p":"La fecha de la última actualización aparece en la parte superior de esta página. Si un cambio afecta una reserva en curso, le escribiremos."}]}]},"/conditions-generales-de-vente":{"titre":"Condiciones generales de venta","metaTitre":"Condiciones generales de venta — Ouidah Heritage Tour","metaDescription":"Boletos de eventos, estancias bajo presupuesto y tienda de Ouidah Heritage Tour: precios, pago, desistimiento, cancelación, entrega, devoluciones y disputas.","intro":"Las normas que se aplican cuando reserva un boleto, una estancia o compra en la tienda. ¿Algún punto no está claro? Escríbanos antes de reservar.","sections":[{"id":"champ","titre":"A qué se aplican estas condiciones","blocs":[{"p":"Se aplican a las ventas de {denomination}, {forme} (ver los [avisos legales](/mentions-legales)) :"},{"liste":["los boletos de los eventos que organizamos;","las estancias, circuitos y acompañamientos establecidos bajo presupuesto, incluidos los relacionados con un evento organizado por terceros;","los artículos de la tienda."]},{"p":"Las acepta al confirmar su reserva o pedido. La versión vigente ese día será la que le corresponda."}]},{"id":"prix","titre":"Precio y pago","blocs":[{"liste":["Los precios se indican con todos los impuestos incluidos, en francos CFA (XOF). La visualización en euros sigue el tipo fijo 1 € = 655,957 FCFA.","Para la tienda, los gastos de envío se añaden al precio de los artículos y se le indican antes de cualquier pago.","Paga de una sola vez, sin anticipo, a través de una de las pasarelas ofrecidas al momento del pago. Nunca recibimos los datos de su tarjeta."]}]},{"id":"retractation","titre":"Su derecho de retractación","blocs":[{"p":"Dispone de 15 días hábiles para cambiar de opinión, sin necesidad de justificarlo: a partir de su pago de un billete o una estancia, o de la recepción de un artículo. Escríbanos a {email}; le reembolsamos el total en 14 días, mediante el medio de pago utilizado."},{"p":"Este derecho ya no se aplica a un billete o una estancia ya totalmente realizados, ni a los artículos hechos a medida o personalizados a su solicitud."}]},{"id":"billets","titre":"Billetes de eventos","blocs":[{"liste":["Reserva en la agenda del sitio: fórmula, número de plazas y datos de contacto, luego pago.","Su billete, a su nombre y con un código QR, le es enviado por correo electrónico tan pronto como la pasarela nos confirma el pago. Preséntelo en su teléfono o impreso; cada código QR abre la entrada una vez.","¿No puede venir? Después del plazo de retractación, le reembolsamos el total hasta 30 días antes del evento y la mitad entre 30 y 8 días antes. Más tarde, regale su plaza: cambiamos el billete al nombre de la persona que elija, sin coste, hasta 48 horas antes.","Si cancelamos o posponemos el evento, usted elige entre el reembolso total o su plaza en la nueva fecha."]}]},{"id":"sejours","titre":"Estancias y acompañamientos bajo presupuesto","blocs":[{"liste":["Su solicitud de presupuesto es gratuita y no le obliga. El presupuesto detalla los servicios, las fechas, lo que está incluido y el precio total. Es válido 15 días.","Su reserva es firme cuando acepta el presupuesto y paga su importe de una sola vez. Entonces le enviamos la confirmación escrita de su viaje.","Para una estancia alrededor de un evento organizado por terceros, como los Vodun Days, vendemos la estancia, no el evento. Su programa depende de sus organizadores; si cambia, adaptamos su estancia con usted.","¿Desea modificar sus fechas o servicios? Díganoslo: ajustamos según la disponibilidad, y la diferencia de precio se suma o se le reembolsa.","Después del plazo de retractación, si cancela, le reembolsamos el total hasta 45 días antes de la llegada, deduciendo los gastos ya incurridos con nuestros socios y no reembolsables, que le justificaremos; la mitad entre 45 y 15 días antes; menos de 15 días antes, le proponemos reprogramar su estancia según la disponibilidad.","Si debemos cancelar, le reembolsamos el total o le proponemos otra estancia, a su elección.","El pasaporte, el visado y el certificado de vacunación contra la fiebre amarilla corren por su cuenta: la sección «Preparar su viaje» le guía. Se recomienda encarecidamente un seguro de viaje, con repatriación incluida.","Nos hacemos responsables de la correcta ejecución de los servicios que vendemos. Los vuelos que reserve usted mismo quedan fuera de nuestro ámbito."]}]},{"id":"boutique","titre":"Tienda","blocs":[{"liste":["Su pedido es primero una solicitud. En 2 días hábiles le confirmamos por correo electrónico la disponibilidad, el modo de entrega y el importe total, gastos incluidos.","Paga de una sola vez después de esta confirmación; la venta se concluye al recibir el pago.","Los artículos a medida o personalizados se realizan después del pago, dentro del plazo indicado en la confirmación."]}]},{"id":"livraison","titre":"Envío y devoluciones","blocs":[{"liste":["Retiro en Ouidah, sin coste: el lugar y los horarios aparecen en la confirmación.","Envío a Benín y a los países ofrecidos al hacer el pedido. Los gastos dependen del país y del paquete; se le indican antes del pago.","Plazos indicativos a partir del envío: de 2 a 5 días hábiles en Benín, de 5 a 10 en África Occidental, de 7 a 21 en otros lugares. Le proporcionamos el seguimiento del paquete.","Fuera de Benín, los derechos e impuestos de importación que puedan existir corren a cargo del destinatario.","Devolución de un artículo: dentro de los 15 días hábiles siguientes a su recepción, en su estado original. Le reembolsamos el artículo y los gastos de envío originales en 14 días después de recibirlo; los gastos de devolución son por su cuenta. Un cambio de talla o color es posible en el mismo plazo, según el stock.","Artículo dañado o diferente de su pedido: notifíquenos en los 7 días siguientes a la recepción, con fotos adjuntas. Lo cambiamos, lo repararemos o le reembolsamos, los gastos corren a nuestro cargo.","Los artículos a medida o personalizados no se aceptan para devolución ni cambio, salvo defectos."]}]},{"id":"donnees","titre":"Sus datos","blocs":[{"p":"El uso que hacemos de sus datos de contacto se describe en la página [Privacidad y cookies](/politique-de-confidentialite)."}]},{"id":"litiges","titre":"Reclamaciones y litigios","blocs":[{"p":"Para cualquier reclamación, contáctenos: {telephones} · {email}. Le respondemos en 7 días hábiles y buscamos primero una solución amistosa con usted."},{"p":"También puede presentar una reclamación a la administración beninesa encargada del turismo."},{"p":"Estas condiciones se rigen por la legislación beninesa; en ausencia de acuerdo, el Tribunal de Comercio de Cotonou es competente. Si reside fuera de Benín, mantiene las protecciones que le otorga la ley de su país, incluido el derecho a acudir al juez de su domicilio cuando la legislación lo prevea."}]}]}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:legal-ui.legalUi','{"miseAJour":"Actualización:","sommaire":"Resumen","revoirChoix":"Revisar mis elecciones"}'::jsonb,1,now()) on conflict(cle) do nothing;
