insert into public.contenu_site(cle,valeur,version,publie_le) values('ES:site.messages','{"fr.nav.sousLabel.m0":"Abrir el menú {label}","fr.nav.voyage.m0":"Tu viaje · {n}","fr.placesIntro.of.m0":"sobre {km} km de visita","fr.toursIntro.count.m0":"{n} circuitos","fr.toursIntro.count.m1":"{n} circuito","fr.toursIntro.from.m0":"Desde {v0} FCFA","fr.cheminsIntro.ready.desc.m0":"itinerario compuesto","fr.cheminsIntro.ready.desc.m1":"itinerarios compuestos","fr.cheminsIntro.ready.desc.m2":"{v0} por nuestros guías","fr.cheminsIntro.ready.steps.m0":"etapa","fr.cheminsIntro.ready.steps.m1":"etapas","fr.cheminsIntro.compose.desc.m0":"lugar","fr.cheminsIntro.compose.desc.m1":"lugares","fr.cheminsIntro.compose.desc.m2":"{v0} para ver, dónde dormir, dónde comer: conserva lo que te llama","fr.cheminsIntro.compose.views.list.m0":"Todos los lugares · {n}","fr.cheminsIntro.compose.position.m0":"Lugar {i} de {n}","fr.cheminsIntro.trip.count.m0":"lugar guardado","fr.cheminsIntro.trip.count.m1":"lugares guardados","fr.cheminsIntro.trip.count.m2":"Ningún lugar guardado","fr.cheminsIntro.trip.remove.m0":"Eliminar {nom}","fr.cheminsIntro.location.youAre.m0":"Estás en {ville} · {km} km","fr.cheminsIntro.time.at.m0":"{h} en Ouidah","fr.cheminsIntro.time.night.m0":"es de noche · puesta a las {h}","fr.cheminsIntro.time.day.m0":"es de día · salida a las {h}","fr.cheminsIntro.globe.ouidah.m0":"lugar","fr.cheminsIntro.globe.ouidah.m1":"lugares","fr.cheminsIntro.globe.ouidah.m2":"Ouidah · {v0} por descubrir","fr.datesSection.titleStay.m0":"Estarás en Ouidah","fr.datesSection.titleStay.m1":"día","fr.datesSection.titleStay.m2":"días","fr.datesSection.titleStay.m3":"en {v0}.","fr.datesSection.intro.m0":"{nom}, {date}: el próximo gran evento. Indica tus fechas del año, te decimos qué ocurre durante tu estancia.","fr.datesSection.during.m0":"{nom} ocurre durante tu estancia.","fr.datesSection.after.m0":"{nom}, un evento Ouidah Heritage Tour, comienza justo después de tu salida.","fr.datesSection.after