insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:site.seo','{"titre":"Ouidah Heritage Tour · Reisen nach Ouidah, Benin","description":"Entdecken Sie Ouidah, sein Erbe und seine Gedenkstätten mit Ouidah Heritage Tour. Rundreisen, Veranstaltungen und Reisen, die mit dem lokalen Team vorbereitet wurden.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.hero','{"kicker":["Erinnerungs- und Kulturreiseagentur","Ouidah, Benin"],"title":{"lead":"Ouidah,","accent":"Stadt des Vodun und der Erinnerung"},"sub":"Folgen Sie der Route des Esclaves zu Fuß von der Place Chacha bis zur Porte du Non-Retour am Atlantik.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Luftaufnahme des Strandes von Ouidah: Atlantikwellen, goldener Sand und Kokospalmen"},{"src":"/hero/hero-2-porte.jpg","alt":"Die neue Porte du Non-Retour in Ouidah, von der Seite gesehen"}],"search":{"action":"/#chemins","label":"Eine Tour suchen","submit":"Suchen","fields":[{"name":"lieu","label":"Zielort","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Reiseart","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Dauer","objet":"calendrier","options":[{"value":"","label":"Jede Dauer"},{"value":"demi-journee","label":"Halber Tag"},{"value":"journee","label":"Ein Tag"},{"value":"plusieurs-jours","label":"Mehrere Tage"}]}]},"primary":{"label":"Unsere Touren ansehen","href":"/#chemins"},"secondary":{"label":"Meine maßgeschneiderte Reise planen","href":"/devis"},"facts":[{"value":"1721","label":"Portugiesische Festung, heute ein Geschichtsmuseum"},{"value":"4 km","label":"Von der Place Chacha über die Route des Esclaves zum Strand"},{"value":"2025","label":"Neue Porte du Non-Retour"},{"value":"23. August","label":"Tag des Gedenkens an den Sklavenhandel"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.welcome','{"label":"Wer wir sind","title":["Willkommen zu Hause,","im Herzen Ihrer Geschichte."],"paragraphs":["Ouidah Heritage Tour ist mehr als eine Agentur: Es ist ein Engagement für verantwortungsbewussten und zutiefst menschlichen Tourismus.","Wir laden Sie ein, Ouidah ganz nah an seiner Seele zu erleben, ein Ziel, wo Geschichte, Spiritualität, Kultur, Kunst und Natur zusammenkommen, um Ihnen ein authentisches Erlebnis zu bieten.","Jede Reise ist einzigartig: Unser Team kümmert sich um Ihre Interessen, Erwartungen und Bedürfnisse. Wir begleiten Sie vor, während und nach der Reise."],"link":{"label":"Die Geschichte von Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Eine junge Frau sortiert bunte Wax‑Stoffe auf dem Markt"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Wer wir sind","segments":[{"text":"Willkommen zu Hause,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Die beleuchtete Porte du Non-Retour bei Nacht"},"ring":"sun"},{"text":"im Herzen Ihrer Geschichte,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Der bemalte Eingang des Temple des Pythons"},"ring":"abyss"},{"text":"von der Route des Esclaves"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Der Strand von Ouidah bei Sonnenuntergang"},"ring":"sun"},{"text":"bis zum Ozean."}],"columns":[{"title":"Erinnerung und Kultur","text":"Als Agentur für Erinnerungs- und Kulturtourismus begleiten wir Sie zu Fuß auf der Route des Esclaves. Ein Reiseleiter erzählt Ihnen die Geschichte jeder Station."},{"title":"Die Orte, die Sie wählen","text":"Der Temple des Pythons gegenüber der Basilika, der heilige Wald von Kpassè, der Markt von Zobè, die Lagune mit der Piroge. Wir stellen Ihren Aufenthalt mit den Orten zusammen, die Sie ansprechen."},{"title":"Vom Flughafen nach Ouidah","text":"Shuttle vom Flughafen Cotonou, Unterkunft, Verpflegung, Fahrzeug: Wir organisieren mit Ihnen alles rund um die Besichtigung, vor, während und nach der Reise."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.placesIntro','{"kicker":"Die Karte · Von der Stadt zum Ozean","title":"Ouidah an vier Orten","titleParts":{"before":"Ouidah an","number":"4","spoken":"vier","after":"Orten."},"intro":"Scrollen Sie: Auf der Karte erscheint der Weg vom portugiesischen Fort durch die Straßen der Stadt bis zur Porte du Non-Retour.","link":"Ort ansehen","walked":"km zurückgelegt","mapLabel":"Karte von Ouidah mit den vier Orten und der Fußstrecke, die sie verbindet"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Unser Engagement","title":"Sieben Verpflichtungen, vor Ort umgesetzt.","intro":"Was Sie von uns erwarten können, von der ersten Frage bis zur Rückkehr.","of":"von"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.reasons','[{"title":"Das Gebiet, aus nächster Nähe","text":"Vom portugiesischen Fort bis zum Strand führen Sie unsere Guides zu Fuß.","couleur":"sun"},{"title":"Verifizierte Fakten","text":"Die Erzählungen der Führung stützen sich auf die dokumentierte Geschichte des Sklavenhandels.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"Eingang des Geschichtsmuseums von Ouidah im portugiesischen Fort"}},{"title":"Ihre Geschichte zuerst","text":"Wir gestalten Ihre Tour anhand Ihrer Geschichte und Ihrer Fragen.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Der bemalte Eingang des Temple des Pythons"}},{"title":"Partner im Land","text":"Unterkünfte, Verpflegung, Guides und Handwerker im Land: Wir wählen mit Ihnen die Adressen des Aufenthalts aus.","couleur":"abyss"},{"title":"Für die Diaspora","text":"Unsere Tour Retour aux sources führt Menschen afrikanischer Abstammung vom Fort zur Porte du Non-Retour.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Die Porte du Non-Retour am Meer bei Tageslicht"}},{"title":"Vor, während, nach","text":"Antwort innerhalb von 24 Stunden, Empfang bei Ankunft, Begleitung bis zur Rückkehr.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"Die von Kokospalmen gesäumte Route des Pêches in Ouidah"}},{"title":"Für lokale Akteure","text":"Wir beteiligen uns an der Ausbildung lokaler Tourismusakteure und machen sie bekannt.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.tenIntro','{"title":["Was die Stadt für Sie bereithält,","von der Erinnerung bis zum Ozean."],"link":{"label":"Entdecken Sie sie","href":"/#raisons"},"place":"Ouidah","discover":"Ort entdecken","circle":"Markieren","circled":"Markiert","path":{"label":"Meinen Weg anzeigen","href":"#chemins"},"stripLabel":"Ansichten, von den Erinnerungsorten bis zum Meer","filmEdge":"OUIDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.tenReasons','[{"slug":"route-des-esclaves","title":"Die Route des Esclaves","short":"Route des Esclaves","category":"Erinnerung","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"Der Arbre du Retour, letzte Station der Route des Esclaves vor dem Strand"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"Von der Place Chacha, wo die Versteigerungen stattfanden, bis zum Strand: etwa 4 km, der Weg der Gefangenen zu den Schiffen. Er führt am Arbre de l''Oubli vorbei, um den man sie gehen ließ, damit sie Namen und Herkunft vergaßen, an den Cases Zomaï, wo man sie im Dunkeln einsperrte, am Mémorial de Zoungbodji und schließlich am Arbre du Retour, damit ihre Seele zurückkehren konnte. Man geht zu Fuß, begleitet von einem Reiseleiter, der jede Station erklärt."},{"slug":"porte-du-non-retour","title":"Die Porte du Non-Retour","short":"Porte du Non-Retour","category":"Erinnerung","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Die Porte du Non-Retour am Meer bei Tageslicht"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"Am Ende der Route des Esclaves, am Strand gegenüber dem Atlantik. Sie markiert den Ort der gewaltsamen Verschiffung von Millionen Afrikanern. Der erste, am 30. November 1995 auf Initiative der UNESCO eingeweihte Bogen wurde im Dezember 2025 durch ein höheres Tor ersetzt. Nach den Stationen der Route erreicht man ihn zu Fuß und steht dort dem Meer gegenüber."},{"slug":"temple-des-pythons","title":"Der Temple des Pythons","short":"Temple des Pythons","category":"Glaube","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Der bemalte Eingang des Temple des Pythons"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Seit dem späten 17. Jahrhundert belegtes Vodun-Heiligtum des Schlangenkults Dangbé, in dem heilige Pythons leben. Der Tempel steht der Basilique de l''Immaculée-Conception gegenüber: zwei Glaubensrichtungen, die auf beiden Seiten desselben Platzes nebeneinander leben. Bei der Besichtigung gelten die Regeln des Ortes."},{"slug":"basilique","title":"Die Basilika, gegenüber dem Tempel","short":"Basilika","category":"Glaube","image":{"src":"/ouidah/visite-basilique.jpg","alt":"Die Basilika der Unbefleckten Empfängnis von Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"Die Basilique de l''Immaculée-Conception, wichtigste katholische Kultstätte Ouidahs, wurde von 1903 bis 1909 erbaut und 1989 zur Basilica minor erhoben. Sie steht gegenüber dem Temple des Pythons: In Ouidah genügt es, einen Platz zu überqueren, um vom einen zum anderen zu gelangen."},{"slug":"musee-histoire","title":"Das Museum der portugiesischen Festung","short":"Geschichtsmuseum","category":"Geschichte","image":{"src":"/ouidah/lieu-musee.jpg","alt":"Die portugiesische Festung von Ouidah, die das Geschichtsmuseum beherbergt"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"Das 1721 erbaute portugiesische Fort São João Baptista de Ajudá beherbergt seit dem 6. September 1967 das Geschichtsmuseum der Stadt. Rund 700 Objekte erzählen vom Sklavenhandel, den Königreichen und den Beziehungen zu Brasilien und den Amerikas. Das Gelände wird für das künftige Musée international de la mémoire et de l''esclavage umgebaut. Wir informieren Sie vor Ihrer Ankunft, was geöffnet ist."},{"slug":"foret-sacree-kpasse","title":"Der heilige Wald von Kpassè","short":"Wald von Kpassè","category":"Natur","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"Unter den großen Bäumen des heiligen Waldes von Kpassè, eine Vodun‑Skulptur"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"Eine 4 Hektar große Waldinsel mitten in der Stadt, verbunden mit König Kpassè. Der Wald beherbergt Vodun‑Gottheiten und Skulpturen und dient als Rahmen für Zeremonien, insbesondere während der Vodun Days. Man betritt ihn durch ein bemaltes Tor und geht dann unter den großen Bäumen hindurch."},{"slug":"vodun-days","title":"Die Vodun Days","short":"Vodun Days","category":"Fest","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"Ein Egungun in der Arena von Ouidah während der Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"Jeden Anfang Januar empfängt Ouidah das große jährliche Treffen der Vodun‑Kulturen: Zeremonien, rituelle Tänze, Ausstellungen und Begegnungen, unter Beachtung der von den Gemeinschaften festgelegten Regeln. Die große Zeremonie und die Konzerte finden am Strand statt, weitere Momente im Wald von Kpassè. Wir organisieren nicht die Veranstaltung, sondern Ihren Aufenthalt rundherum."},{"slug":"memorial-zoungbodji","title":"Das Mémorial de Zoungbodji","short":"Zoungbodji","category":"Erinnerung","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Das Mémorial de Zoungbodji an der Route des Esclaves"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"Das Mémorial im Dorf Zoungbodji markiert den letzten Aufenthaltsort der Gefangenen vor der Verschiffung, nahe dem Massengrab, in das die Toten geworfen wurden. Es ist die bedrückendste Station der Route des Esclaves, etwa 2 km vom Strand und der Porte du Non-Retour entfernt. Hier hält man kurz inne, bevor man zum Meer weitergeht."},{"slug":"marches","title":"Handwerker, Märkte, Küche","short":"Märkte","category":"Aromen","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Verkäuferinnen, die ihre Waren in einer Straße von Ouidah tragen"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"Der Markt von Zobè, in der Nähe des portugiesischen Forts, und der im Viertel Kpassè prägen das Leben der Stadt. Unsere Guides führen Sie dorthin, zu den Handwerkern und zu den guten Restaurants von Ouidah, von den Maquis bis zu den Restaurants. Es ist die Stadt von heute, die zwischen zwei Besichtigungen lebt."},{"slug":"plage-et-lagune","title":"Strand und Lagune","short":"Strand und Lagune","category":"Ozean","image":{"src":"/hero/hero-4-plage.jpg","alt":"Der Strand von Ouidah aus der Luft, Atlantikwellen und Kokospalmen"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"Am Ende der Route des Esclaves liegt ein langer, wenig erschlossener Strand, an dem die große Zeremonie und die Konzerte der Vodun Days stattfinden. Dahinter trennt die Lagune die Stadt vom Meer. Dieses bedeutende Küstenökosystem Benins lässt sich von der kleinen Anlegestelle aus mit einer Piroge erkunden. Dazwischen verläuft die von Kokospalmen gesäumte Route des Pêches. Bei starkem Wind wird vom Baden abgeraten."}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.toursIntro','{"label":"Unsere Touren","all":{"label":"Alle Touren","href":"/#chemins"},"onRequest":"Preis auf Anfrage","durationPending":"Dauer noch zu bestätigen","filtersLabel":"Touren filtern"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.cheminsIntro','{"origin":[2.0901,6.3589],"timeZone":"Africa/Porto-Novo","kicker":"Unsere Touren · Ab Ouidah","title":{"lead":"Ihr Weg","accent":"nach Ouidah."},"intro":"Nehmen Sie eine bereits von unseren Guides zusammengestellte Route oder wählen Sie Ihre Orte einzeln aus: Wir machen daraus Ihre Reise.","ready":{"label":"Fertige Touren","heading":"Von unseren Reiseleitern zusammengestellte Touren.","book":"Diese Tour buchen","customize":"Anpassen"},"compose":{"label":"Meinen Weg zusammenstellen","heading":"Merken Sie sich die Orte, die Sie ansprechen.","views":{"deck":"Ein Ort nach dem anderen"},"viewsLabel":"Art, die Orte zu erkunden","skip":"Überspringen","keep":"Diesen Ort merken","kept":"Gemerkt","see":"Ansehen","noPhoto":"Foto folgt","done":"Sie haben sich alle Orte angesehen.","restart":"Orte erneut ansehen","far":"Weiter"},"filters":[{"key":"a-voir","label":"Zu sehen","ids":["a-voir"],"color":"#ac3215","group":"voir","on":true},{"key":"plage","label":"Strände","ids":["plage"],"color":"#2a7ab8","group":"voir","on":true},{"key":"nature","label":"Natur","ids":["nature"],"color":"#3f8a4e","group":"voir","on":true},{"key":"hebergement","label":"Wo übernachten","ids":["hebergement"],"color":"#0f162d","group":"dormir","on":true},{"key":"restauration","label":"Wo essen","ids":["restauration"],"color":"#c98a00","group":"manger","on":true},{"key":"artisanat","label":"Handwerk","ids":["artisanat"],"color":"#8a4fb3","group":"voir","on":true},{"key":"marche","label":"Märkte","ids":["marche"],"color":"#d9661f","group":"voir","on":true},{"key":"pratique","label":"Praktisch","ids":["sante","argent","transport","services"],"color":"#5b6478","group":"pratique","on":false},{"key":"culte","label":"Kultstätten","ids":["culte"],"color":"#8a8f9c","group":"voir","on":false}],"filtersLabel":"Auf der Karte angezeigte Orte","groups":{"voir":"Zu sehen und zu erleben","dormir":"Wo übernachten","manger":"Wo essen","pratique":"Praktisch"},"place":{"add":"Zu meiner Reise hinzufügen","remove":"Aus meiner Reise entfernen","close":"Informationen schließen","call":"Anrufen","website":"Webseite","outside":"Außerhalb von Ouidah","verification":{"osm":"Auf OpenStreetMap erfasst, zu bestätigen","web":"In öffentlichen Quellen erfasst, zu bestätigen","osm+web":"Durch mehrere Quellen bestätigt"}},"mapLocale":{"CooperativeGesturesHandler.WindowsHelpText":"Strg + Mausrad zum Vergrößern der Karte","CooperativeGesturesHandler.MacHelpText":"⌘ + Mausrad zum Vergrößern der Karte","CooperativeGesturesHandler.MobileHelpText":"Zwei Finger zum Verschieben der Karte","NavigationControl.ZoomIn":"Vergrößern","NavigationControl.ZoomOut":"Verkleinern","AttributionControl.ToggleAttribution":"Kartenquellen"},"trip":{"label":"Ihr Weg","empty":"Ort speichern: Er wird hier hinzugefügt.","note":"Reihenfolge, Dauer und Preis mit Ihnen abgestimmt.","cta":"Reise anfragen","href":"/devis","back":"Willkommen zurück: Ihre gemerkten Orte warten auf Sie.","saved":"Auf diesem Gerät gespeichert, ohne Konto."},"location":{"ask":"Woher kommen Sie?","change":"Ändern","field":"Ihre Abfahrtsstadt","placeholder":"z. B.: Montréal, Paris, Abidjan","submit":"Bestätigen","notFound":"Stadt nicht gefunden, versuchen Sie eine andere Schreibweise.","you":"Sie"},"time":{},"globe":{"label":"Die Erde gerade, ausgerichtet auf Ouidah"},"mapLabel":"Karte der Orte von Ouidah und Umgebung","mapFallback":"Die interaktive Karte kann in diesem Browser nicht angezeigt werden. Die Orte müssen einzeln ausgewählt werden.","tabs":"Wählen Sie, wie Sie Ihre Reise zusammenstellen"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.datesSection','{"title":{"lead":"Zur","accent":"richtigen Zeit kommen."},"none":"Kein besonderes Ereignis an diesen Daten: Ouidah ist das ganze Jahr über zu besichtigen.","units":{"days":"Tage","hours":"h","minutes":"min","seconds":"s"},"live":{"arrival":"Anreise","departure":"Abreise","end":"Ende"},"pass":{"oht":"OHT-Veranstaltung","date":"Datum","place":"Ort","in":"In","arrival":"Anreise","departure":"Abreise","nights":"Nächte","during":"Während Ihres Aufenthalts","after":"Kurz nach Ihrer Abreise","onRequest":"Preis auf Anfrage","extendCta":"Verlängern","bookStay":"Aufenthalt buchen","bookPlace":"Meinen Platz buchen","byOht":"Veranstaltet von Ouidah Heritage Tour · Ihre Tickets erscheinen, sobald die Zahlung bestätigt ist.","formulas":"Angebot"},"talon":{"titre":"Ihr Ticketabschnitt","ouvrir":"Meinen Platz buchen","fermer":"Buchung schließen","places":"Plätze","moins":"Ein Platz weniger","plus":"Ein Platz mehr","accompagnement":"Ihre Begleitung","accompagnementNote":"auf Anfrage, Antwort innerhalb von 24 Stunden","deja":"bereits im Concierge-Service ausgewählt","unique":{"titre":"Eine Anfrage, eine Referenznummer."},"nom":"Vor- und Nachname","email":"E-Mail","repris":"aus Ihrer Anfrage übernommen","payerAvec":"Bezahlen mit","passerelles":{"kkiapay":{"nom":"Kkiapay","moyens":"Mobile Money, Karte"},"fedapay":{"nom":"FedaPay","moyens":"Mobile Money, Karte"},"stripe":{"nom":"Stripe","moyens":"Bankkarte"},"flutterwave":{"nom":"Flutterwave","moyens":"Bankkarte"},"paystack":{"nom":"Paystack","moyens":"Karte, Mobile Money"}},"accord":"Ich stimme zu, dass Ouidah Heritage Tour diese Angaben für meine Buchung verwendet.","confidentialite":{"label":"Datenschutz","href":"/politique-de-confidentialite"},"envoi":"Zahlung wird vorbereitet…","attente":{"devis":"Ihr Wunsch nach Begleitung wurde bereits erfasst.","autre":"Anders bezahlen"},"verification":"Wir prüfen Ihre Zahlung…","nonConfirme":{"titre":"Zahlung noch nicht bestätigt","texte":"Wenn Sie bezahlt haben, trifft die Bestätigung in der Regel nach wenigen Augenblicken ein.","reessayer":"Erneut prüfen"},"paye":{"titreSans":"Ihre Buchung ist bestätigt.","entree":"Am Eingang vorzeigen","precedent":"Vorheriges Ticket","suivant":"Nächstes Ticket","telecharger":"Tickets herunterladen","reference":"Referenznummer Ihrer Reise","suivi":"Mein Ticket und meinen Beleg ansehen","recap":{"formule":"Angebot","paye":"Bezahlt","devis":"Auf Anfrage"},"tampon":"BEZAHLT"},"erreurs":{"champs":"Ihr Name, Ihre E-Mail-Adresse oder Ihre Zustimmung fehlt.","limite":"Über diese Verbindung wurden gerade mehrere Buchungen vorgenommen. Versuchen Sie es in einer Stunde erneut.","surDemande":"Der Preis dieses Angebots ist auf Anfrage erhältlich: Wir nehmen es in Ihre Reiseplanung auf.","passerelle":"Diese Zahlungsmethode ist nicht verfügbar. Wählen Sie eine andere.","indisponible":"Die Online-Zahlung reagiert derzeit nicht. Versuchen Sie es gleich noch einmal."},"surDemande":"Zu meiner Reise hinzufügen"},"scrub":{"ask":"Wann kommen Sie?","hint":"Verschieben Sie die Markierung über das Jahr","place":"Legen Sie Ihren Aufenthalt fest","today":"Heute","legendOht":"OHT-Veranstaltung","legendOther":"Großes Ereignis","lengths":[{"label":"Wochenende","nuits":2},{"label":"Woche","nuits":7},{"label":"10 Nächte","nuits":10},{"label":"2 Wochen","nuits":14}],"lengthsLabel":"Aufenthaltsdauer","reset":"Meine Reisedaten löschen"},"timeZone":"Africa/Porto-Novo","fallbackImage":{"src":"/hero/hero-4-plage.jpg","alt":"Der Strand von Ouidah aus der Luft, Atlantikwellen und Kokospalmen"}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.prepare','{"title":["Planen Sie Ihre Reise,","mit der Karte in der Hand."],"lead":"Ouidah liegt an der Küste, 41 km vom Flughafen entfernt. Ein paar Tipps vermitteln das Wichtigste.","carte":{"ouidah":[2.0851,6.3622],"aeroport":[2.3844,6.3573],"porte":[2.0896,6.3243],"ville":"Ouidah","villeSous":"Atlantikküste","ocean":"Atlantischer Ozean","pays":[{"nom":"Togo","lieu":[1.12,8.2]},{"nom":"Nigeria","lieu":[3.38,8.4]}],"cotonou":"Cotonou","aeroportNom":"internationaler Flughafen","porteNom":"Porte du Non-Retour","km":"41 km","kmSous":"auf der Straße, mit dem Shuttle","ariaBenin":"Karte von Benin: Ouidah an der Atlantikküste, 41 km vom Flughafen Cotonou entfernt","ariaCote":"Die Küste Benins: die 41 km lange Straße vom Flughafen Cotonou nach Ouidah"},"fiche":{"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Die Porte du Non-Retour am Meer in Ouidah"},"titre":"Ouidah","texte":"Eine Stadt voller Geschichte am Atlantik.","heureTexte":"Im Winter dieselbe Uhrzeit wie in Paris.","fuseau":"Africa/Porto-Novo"},"accueil":{"titre":"Wir erwarten Sie.","texte":"Auf Wunsch empfängt Sie unser Team bei Ihrer Ankunft am Flughafen."},"ongletsLabel":"Planen Sie Ihre Reise nach Themen","numeros":"Nützliche Telefonnummern","question":"Eine Frage vor der Abreise? Wir antworten innerhalb von 24 Stunden.","whatsapp":"Über WhatsApp schreiben","ecrire":{"label":"Eine Frage stellen","href":"/devis?demande=question"},"verifie":"2026-10-22"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.preparer','[{"id":"sur-place","court":"Vor Ort","objet":"accueil","vue":"benin","titre":"Ouidah lässt sich entspannt erkunden.","cle":{"valeur":"Begleitet","texte":"von unserem Team, vor, während und nach der Reise."},"mot":true,"points":["Auf Wunsch erwarten wir Sie am Flughafen: Der Shuttle bringt Sie nach Ouidah.","Unterkünfte und Restaurants: Gemeinsam wählen wir aus den erfassten Adressen in Ouidah.","Vor einem Foto einer Zeremonie oder einem Porträt genügt ein Wort: Fragen Sie, so ist es üblich.","Genießen Sie am Strand den Sand und den Sonnenuntergang. Fragen Sie vor dem Baden vor Ort nach: Die Brandung des Atlantiks ist stark."],"source":"OHT-Zusagen · France Diplomatie (15. Sept. 2026) · FCDO"},{"id":"arriver","court":"Ankommen","objet":"navette","vue":"cote","titre":"Einfach ankommen.","cle":{"valeur":"41 km","texte":"vom Flughafen Cotonou nach Ouidah. Der OHT-Shuttle bringt Sie dorthin."},"points":["Ihr E-Visum beantragen Sie online auf evisa.bj: 30 oder 90 Tage, Antwort innerhalb von 1 bis 96 Stunden.","Stellen Sie den Antrag mindestens 7 Tage vor der Ankunft und halten Sie das Visum griffbereit.","Afrikanische Staatsangehörige: bis zu 90 Tage ohne Visum.","Französische Reisende: Reisepass noch 6 Monate nach der Rückkehr gültig, Rückflugticket im Gepäck."],"source":"evisa.bj · France Diplomatie · OSRM (41 km)"},{"id":"sante","court":"Gesundheit","objet":"sante","vue":"benin","titre":"Gut vorbereitet für Ihre Gesundheit.","cle":{"valeur":"1 Besuch","texte":"bei Ihrem Arzt oder in einer reisemedizinischen Impfstelle vor der Abreise."},"points":["Aktuelle Impfungen, Hepatitis A und Typhus: Ihr Arzt bespricht dies mit Ihnen.","Gelbfieber: Impfung ab 9 Monaten empfohlen. Packen Sie Ihren Impfausweis ein.","Gegen Mücken: Insektenschutz und abends lange Ärmel. Ihr Arzt berät Sie zur Malariaprophylaxe."],"source":"Gesundheitsministerium Benins (16. Sept. 2026) · Institut Pasteur · WHO — Gelbfieber: widersprüchliche Quellen, noch zu bestätigen"},{"id":"argent","court":"Geld","objet":"type-voyage","vue":"benin","titre":"Geld, ohne Rechnen.","cle":{"valeur":"15,24 €","texte":"für 10 000 FCFA. Der Kurs bleibt das ganze Jahr über gleich."},"points":["Der CFA-Franc ist an den Euro gebunden: 1 € = 655,957 FCFA, ohne Schwankungen.","Zur Orientierung: 1 000 FCFA entsprechen etwa 1,50 €.","Nutzen Sie zum Geldabheben Automaten innerhalb von Bankfilialen."],"source":"BCEAO · France Diplomatie"},{"id":"pratique","court":"Praktisch","objet":"prise","vue":"benin","fiche":"heure","titre":"Gut zu wissen.","cle":{"valeur":"0 Std.","texte":"Zeitunterschied zu Paris im Winter, 1 Stunde im Sommer."},"points":["220 V, Steckdosen vom Typ C und E: Ladegeräte aus Frankreich und Belgien passen ohne Adapter.","Französisch ist die Amtssprache; in Ouidah wird auch Fon gesprochen.","Mit einer lokalen SIM-Karte von MTN, Moov Africa oder Celtiis bleiben Sie erreichbar.","Trockenzeit von November bis März sowie von Mitte Juli bis Mitte September."],"source":"gouv.bj · ARCEP Bénin · IEC · IANA"}]'::jsonb,1,now()) on conflict(cle) do nothing;
