insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.newsletter','{"nom":"Der Brief aus Ouidah","phraseSansHeure":"Heute Abend geht die Sonne am Strand von Ouidah unter.","maintenant":"In Ouidah","photo":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Der Strand von Ouidah mit Kokospalmen und Sandweg am späten Nachmittag"},"choisir":"Wählen Sie, worüber Ouidah Ihnen schreibt","sujets":[{"id":"departs","nom":"Unsere Abreisetermine","texte":"Die nächsten Aufenthalte und Touren mit ihren Terminen.","objet":"calendrier"},{"id":"agenda","nom":"Ouidahs Veranstaltungskalender","texte":"Vodun Days, Gedenktag, Ouidah Blue: die Veranstaltungen der Stadt.","objet":"fete"}],"langue":"Der Brief auf","field":"Ihre E-Mail-Adresse","exemple":"vous@exemple.com","submit":"Den Brief erhalten","consent":"Ich möchte den Brief von Ouidah Heritage Tour erhalten. Abmeldung mit einem Klick.","envoi":"Anmeldung läuft…","thanks":"Notiert: Der Brief kommt in Ihr Postfach.","echec":"Die Anmeldung ist fehlgeschlagen. Versuchen Sie es gleich noch einmal.","limite":"Über diese Verbindung wurden bereits mehrere Anmeldungen gesendet. Versuchen Sie es in einer Stunde erneut.","aucun":"Wählen Sie mindestens ein Thema.","error":"Geben Sie eine gültige E-Mail-Adresse ein und aktivieren Sie das Kästchen."}'::jsonb,1,now()) on conflict(cle) do nothing;
