insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.places','[{"n":"01","name":"Geschichtsmuseum von Ouidah","kicker":"Portugiesisches Fort, 1721","text":"Seit dem 6. September 1967 beherbergt das portugiesische Fort das Geschichtsmuseum der Stadt: Sklavenhandel, Königreiche und die Beziehungen zu Brasilien und den Amerikas.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"Die rote Mauer des portugiesischen Forts von Ouidah"},"next":"680 m zu Fuß bis zum Temple des Pythons"},{"n":"02","name":"Temple des Pythons","kicker":"Gegenüber der Basilika","text":"Der Tempel des Pythons Dangbé steht der von 1903 bis 1909 erbauten Basilique de l''Immaculée-Conception gegenüber: zwei Glaubensrichtungen, die Seite an Seite leben.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Der bemalte Eingang des Temple des Pythons"},"next":"2,5 km bis zum Mémorial de Zoungbodji, über die Place Chacha"},{"n":"03","name":"Die Route des Esclaves","kicker":"Etwa 4 km, sechs Stationen","text":"Von der Place Chacha zum Strand: der Weg, den die Gefangenen zu den Schiffen zurücklegten, über Arbre de l''Oubli, Cases Zomaï, Mémorial de Zoungbodji und Arbre du Retour.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Das Mémorial de Zoungbodji an der Route des Esclaves"},"next":"2 km bis zum Strand und zur Porte du Non-Retour"},{"n":"04","name":"Porte du Non-Retour","kicker":"1995 errichtet, 2025 neu aufgebaut","text":"Am Strand, dem Atlantik zugewandt, markiert sie den Ort der gewaltsamen Verschiffung von Millionen Afrikanern.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Die beleuchtete Porte du Non-Retour bei Nacht"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
