insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:histoire.histoireOuverture','{"titre":"Von Glexwé nach Ouidah","texte":"Auf Fon heißt die Stadt Glexwé, oft mit „Haus der Felder“ übersetzt. Die Europäer schrieben den Namen des Königreichs Houéda, zu dem sie gehörte, auf verschiedene Weise: Whydah auf Englisch, Juda auf Französisch, Fida auf Niederländisch, Ajudá auf Portugiesisch. Daraus entstand Ouidah. Bereits 1681 datiert ein Engländer einen Brief mit „Agriffie in Whidaw“: Glexwé im Land der Houéda.","noms":["Glexwé","Whydah","Juda","Fida","Ajudá","Ouidah"]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:histoire.histoireChapitres','[{"id":"avant","repere":"17. Jahrhundert","court":"17. Jh.","titre":"Vor den Forts","ville":false,"temps":[["Im 17. Jahrhundert ist Glexwé die Unterstadt des Königreichs Houéda nördlich einer Lagune. Der König lebt im etwa zehn Kilometer weiter nördlich gelegenen Savi. Das kleine Königreich steht lange unter der Herrschaft seines Nachbarn Allada und befreit sich davon in der zweiten Hälfte des Jahrhunderts.","Als sich die Europäer am Ende des Jahrhunderts niederlassen, werden die meisten Geschäfte in Savi nahe dem Palast abgewickelt. Bei den seit 1991 durchgeführten Ausgrabungen wurden niederländische Ziegel und chinesisches Porzellan ausschließlich innerhalb der königlichen Anlage gefunden. Das deutet darauf hin, dass der König den Handel kontrollierte."],["Der Überlieferung zufolge kamen die Houéda aus Tado, und ihr erster König Haholo gründete Savi. Für Glexwé nennt die Überlieferung einen anderen Gründer, Kpassè. Er soll nicht wie ein Mensch gestorben sein, sondern sich in einen Iroko verwandelt haben. Dieser Baum wird im heiligen Wald von Kpassè im Viertel Tové verehrt, wo man das Dorf aus der Zeit vor der Ankunft der Europäer verortet.","Ein weiterer Name taucht in den Erzählungen auf: Kpate, der die ersten Europäer empfangen haben soll. Er wird in Ouidah noch immer kultisch verehrt."]],"pieces":[{"hier":{"src":"/histoire/plan-palais-savi-1747.webp","largeur":1173,"hauteur":1313,"legende":"Der Königspalast in Savi und die europäischen Handelsniederlassungen, gestochener Plan von 1747"},"auj":null},{"hier":{"src":"/histoire/couronnement-roi-juida-1723.webp","largeur":1100,"hauteur":847,"legende":"Die Krönung des Houéda-Königs, Stich aus dem 18. Jahrhundert"},"auj":null},{"hier":null,"auj":{"src":"/histoire/raison-foret-kpasse.webp","largeur":1200,"hauteur":674,"legende":"Der heilige Wald von Kpassè im Viertel Tové"}}]},{"id":"forts","repere":"1671 – 1721","court":"1671","titre":"Die Forts","ville":true,"temps":[["1671 eröffnet die Französische Westindienkompanie eine Handelsniederlassung im Königreich Houéda. Es ist die erste dauerhafte europäische Niederlassung. Die Engländer kommen in den 1680er-Jahren. Die französische Niederlassung wird im Krieg von 1692 zerstört. 1704 entsteht sie erneut als Fort, das der Freibeuter Jean Doublet in wenigen Wochen aus Erde und Stroh errichtet.","José de Torres, ein Händler aus Bahia, gründet 1721 das portugiesische Fort São João Baptista de Ajudá."],["Im 18. Jahrhundert liegen das englische, französische und portugiesische Fort mehrere Kilometer vom Strand entfernt nebeneinander. Die Niederländer hatten nie ein Fort in Ouidah, ebenso wenig die Dänen.","Die Engländer verlassen ihr Fort 1812. Das französische Fort wird 1908 abgerissen. An seiner Stelle liegt ein Platz, auf dem während der Vodun Days die Zangbéto, die Wächter der Nacht, tanzen. Heute steht nur noch das portugiesische Fort."]],"pieces":[{"hier":{"src":"/histoire/fort-anglais-1727.webp","largeur":1226,"hauteur":410,"legende":"Das englische Fort, William''s Fort genannt, Stich von 1727"},"auj":null},{"hier":{"src":"/histoire/fort-francais-plan-1747.webp","largeur":1330,"hauteur":1400,"legende":"Plan des französischen Forts, Stich von 1747"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-gravure-1886.webp","largeur":960,"hauteur":628,"legende":"Das portugiesische Fort, Stich von 1886"},"auj":{"src":"/histoire/eng-2-musee.webp","largeur":1200,"hauteur":900,"legende":"Der Eingang zum portugiesischen Fort, heute Geschichtsmuseum"}}]},{"id":"dahomey","repere":"1727","court":"1727","titre":"Dahomey","ville":false,"temps":[["1724 erobert Agaja, König von Dahomey, Allada. Anfang März 1727 nimmt seine Armee Savi ein und zerstört die Stadt samt den dortigen europäischen Handelsniederlassungen. Hufon, der letzte König der Houéda, flieht mit einem Teil seines Volkes nach Westen, zunächst auf eine Insel nahe Grand-Popo. Andere Houéda lassen sich in Porto-Novo und Badagry nieder."],["Glexwé erhält einen neuen Herrscher und eine neue Rolle. Der Handel mit den Europäern konzentriert sich hier, und die Stadt wird zum wichtigsten Sklavenhandelsplatz Dahomeys. 1733 lässt sich ein Gouverneur nieder. Die Europäer nennen ihn Vizekönig.","Später trägt er den Fon-Titel Yovogan, „Oberhaupt der Weißen“, den bereits das Königreich Houéda verwendete. Das Amt wird stets einem Einheimischen übertragen. Die Forts unterstehen Dahomey: Im Juli 1743 greift dessen Armee das portugiesische Fort an."]],"pieces":[{"hier":{"src":"/histoire/comptoirs-savi-1747.webp","largeur":1400,"hauteur":948,"legende":"Die europäischen Handelsniederlassungen von Savi, Stich nach Aufzeichnungen von 1725, zwei Jahre vor dem Fall der Stadt"},"auj":null}]},{"id":"chacha","repere":"1800 – 1849","court":"1800","titre":"Der Chacha","ville":true,"temps":[["Francisco Félix de Souza, ein Sklavenhändler aus Brasilien, kommt Anfang der 1790er-Jahre erstmals an die Küste und lässt sich um 1800 dort nieder. Er beginnt als Schreiber und Buchhalter im portugiesischen Fort, führt es um 1806 vorübergehend und handelt anschließend auf eigene Rechnung.","Nach einem Zerwürfnis mit König Adandozan wird er in Abomey inhaftiert und flieht nach Petit-Popo. Von dort unterstützt er den Staatsstreich, der Ghézo vermutlich 1818 auf den Thron von Dahomey bringt. Der neue König macht ihn zu seinem Handelsagenten in Ouidah, wohin er um 1820 zurückkehrt."],["Man nennt ihn Chacha. Der Ursprung des Wortes ist ungeklärt. Eine Überlieferung führt es auf das portugiesische „já, já“, „sofort“, zurück, das er oft gesagt haben soll. Im Südwesten der Stadt gründet er ein Viertel, das später Brésil heißt, auf Fon Blézin. Dort leben seine Familie, seine Sklaven und seine Klienten.","Ein Roman machte ihn zum „Vizekönig von Ouidah“. Das war er nie: Das Amt des Yovogan wurde einem Mann aus Dahomey übertragen."],["Er stirbt am 8. Mai 1849 in Ouidah, hoch verschuldet: Er schuldete König Ghézo 80 000 Dollar. Der König bestimmt seinen ältesten Sohn Isidoro zum Nachfolger. Der Beiname wird damit zu einem erblichen Titel, den seitdem das Oberhaupt der Familie de Souza trägt.","Sein Grab liegt auf dem Familienanwesen Singbomey hinter der Place Chacha. Seit 1999 weist eine Tafel den Platz mit diesem Namen aus. Neuere amtliche Texte nennen ihn auch Place aux Enchères."]],"pieces":[{"hier":{"src":"/histoire/portrait-de-souza.webp","largeur":1164,"hauteur":1400,"legende":"Francisco Félix de Souza zugeschriebenes Porträt, vor 1849 gemalt"},"auj":null},{"hier":{"src":"/histoire/place-chacha-stele-2017.webp","largeur":1400,"hauteur":933,"legende":"Die Stele „Place Chacha“ im Jahr 2017"},"auj":null,"temps":2}]},{"id":"agudas","repere":"1835 – 1922","court":"1835","titre":"Die Agudas","ville":true,"temps":[["Ab 1835, nach dem Malê-Aufstand in Bahia, werden freigelassene Afrikaner aus Brasilien vertrieben oder zur Ausreise gedrängt. Viele gehören zu den Yoruba. In Ouidah lassen sie sich insbesondere im Viertel Maro westlich des Viertels Brésil nieder, unter dem Schutz von De Souza.","Gemeinsam mit portugiesischen und brasilianischen Händlerfamilien sowie mit ihnen verbundenen afrikanischen Familien bilden sie die Agudas. Im 19. Jahrhundert bezeichnet das Wort Portugiesen einschließlich der Brasilianer; es soll von Ajudá stammen. Einige Agudas, darunter die Familie de Souza, lebten vom Sklavenhandel."],["Ihre Nachfahren tragen Namen wie de Souza, da Silva, d''Almeida, Martins, Olympio oder Paraïso. In Benin feiern sie im Januar Nosso Senhor do Bonfim und tanzen Bourian, ein aus Bahia stammendes Maskenspiel."],["Entlang der gesamten Küste erinnern ihre mehrgeschossigen Häuser mit Galerien, Balustraden, Fensterläden und verzierten Giebeln an die Sobrados von Salvador. Anfang des 20. Jahrhunderts wird dieser Stil zum Zeichen des Erfolgs. Auch Honoratioren, die keine Agudas sind, übernehmen ihn.","Die Villa Ajavon ist ein Beispiel dafür. Auf ihrem Giebel steht „VILLA AJAVON 1922“. Sie wurde für Ajavon erbaut, einen wohlhabenden Händler aus dem benachbarten Togo. Seit dem 11. November 2013 beherbergt sie das Museum für zeitgenössische Kunst der Fondation Zinsou."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/maison-du-bresil.webp","largeur":1120,"hauteur":1400,"legende":"Die Maison du Brésil im Jahr 2024"},"temps":2},{"hier":null,"auj":{"src":"/histoire/villa-ajavon-1922.webp","largeur":1400,"hauteur":1050,"legende":"Die Villa Ajavon von 1922, heute Museum der Fondation Zinsou"},"temps":2}]},{"id":"mer","repere":"Ende des 17. Jahrhunderts – 1863","court":"1863","titre":"Bis zum Meer","ville":false,"temps":[["Historikern zufolge wurden von Ende des 17. Jahrhunderts bis in die 1860er-Jahre mehr als eine Million Menschen von Ouidah aus verschleppt."],["Die Stadt liegt hinter einer Lagune, etwa vier Kilometer vom Meer entfernt. Die Gefangenen wurden zu Fuß zum Strand geführt. Pirogen brachten sie durch die Brandung, die die Küste abschirmt, zu den vor der Küste ankernden Schiffen."],["Sie wurden vor allem nach Brasilien, insbesondere Bahia, und auf die Antillen verschleppt, vor allem nach Saint-Domingue, dem heutigen Haiti. Gegen Ende des Sklavenhandels gingen die Transporte nach Kuba.","In den 1840er-Jahren wächst der Palmölhandel, doch der Sklavenhandel geht weiter. Unter britischer Blockade unterzeichnet König Ghézo im Januar 1852 einen Vertrag zu dessen Abschaffung. Er bleibt ohne dauerhafte Wirkung."],["Im Mai 1860 verlässt der Schoner Clotilda Ouidah mit 110 Gefangenen an Bord. Im Juli legt er heimlich nahe Mobile in Alabama an. Es ist das letzte bekannte Sklavenschiff, das die Vereinigten Staaten erreichte.","Am 10. Oktober 1863 nimmt der Dampfer Cicerón in Godomey etwa 960 Menschen an Bord, die zu Fuß aus Ouidah hergeführt wurden, um sie nach Kuba zu bringen. Dies ist die letzte bekannte transatlantische Verschiffung mit Bezug zu Ouidah."]],"chiffre":{"valeur":"Mehr als eine Million","legende":"Menschen wurden Historikern zufolge von Ende des 17. Jahrhunderts bis in die 1860er-Jahre von Ouidah aus verschleppt"},"legende":[{"lettre":"A","nom":"Zelte der Europäer"},{"lettre":"B","nom":"Das Ufer"},{"lettre":"C","nom":"Schiffe auf Reede"}],"pieces":[{"hier":null,"auj":{"src":"/histoire/bienvenue-3-plage-cocotiers.webp","largeur":1200,"hauteur":795,"legende":"Der Strand von Ouidah"}}]},{"id":"basilique","repere":"1903 – 2011","court":"1903","titre":"Der Python und die Basilika","ville":true,"temps":[["Dangbé, der Königspython, ist die Gottheit des Königreichs Houéda. Er verkörpert sich in lebenden Schlangen, die in seinen Heiligtümern gehalten werden. Um 1700 vermerkt ein niederländischer Händler, dass Schlangen die wichtigsten Gottheiten des Königreichs sind."],["In Ouidah steht sein Tempel der Basilique de l''Immaculée-Conception gegenüber. Die Kirche steht auf dem Gelände der ehemaligen Residenz des Yovogan, das 1901 an die katholische Mission abgetreten wurde. Diese war 1861 nach Ouidah gekommen.","Am 30. August 1903 wird der Grundstein gelegt. Für den Bau tragen Menschen aus allen Stadtvierteln Sand vom Strand herbei, auch Anhänger des Vodun. Am 9. Mai 1909 wird die Kathedrale vor etwa 4 000 Menschen geweiht."],["1989 wird sie zur Basilika erhoben. Am 19. November 2011 unterzeichnet Benedikt XVI. hier Africae munus, sein apostolisches Schreiben über die Kirche in Afrika."]],"pieces":[{"hier":{"src":"/histoire/procession-serpent-1725.webp","largeur":1400,"hauteur":674,"legende":"Prozession zur großen Schlange anlässlich der Königskrönung, 1730 veröffentlichter Stich"},"auj":null},{"hier":{"src":"/histoire/temple-serpent-1930.webp","largeur":1400,"hauteur":666,"legende":"Der Schlangentempel um 1930"},"auj":{"src":"/histoire/bienvenue-2-temple-pythons.webp","largeur":1200,"hauteur":900,"legende":"Der Eingang zum Temple des Pythons"}},{"hier":{"src":"/histoire/basilique-1930.webp","largeur":1003,"hauteur":1400,"legende":"Die Kathedrale um 1930"},"auj":{"src":"/histoire/visite-basilique.webp","largeur":800,"hauteur":1200,"legende":"Die Basilique de l''Immaculée-Conception"}}]},{"id":"fort","repere":"1892 – 1990","court":"1961","titre":"Das brennende Fort","ville":true,"temps":[["1892 gerät Ouidah unter französische Besatzung. Die Franzosen bestimmen Porto-Novo zum Verwaltungssitz, und der Handel verlagert sich zum Landungssteg von Cotonou. Die Stadt verliert allmählich an Bedeutung. Das portugiesische Fort bleibt jedoch in den Händen Lissabons."],["Dahomey wird am 1. August 1960 unabhängig. Genau ein Jahr später nimmt es das Fort in Besitz, das eine portugiesische Enklave geblieben war. Vor ihrer Abreise setzen die beiden letzten portugiesischen Beamten es in Brand.","1967 zieht das Geschichtsmuseum von Ouidah in das Fort ein. 1975 erhält Dahomey den Namen Benin. Nach der Restaurierung mit Unterstützung der portugiesischen Gulbenkian-Stiftung wird das Fort im August 1990 wiedereröffnet. Der 2020 begonnene Umbau soll es zum künftigen Musée international de la mémoire et de l''esclavage machen."]],"pieces":[{"hier":{"src":"/histoire/rue-1892.webp","largeur":1216,"hauteur":665,"legende":"Eine Straße in Ouidah, Stich von 1892"},"auj":null},{"hier":{"src":"/histoire/marche-1930.webp","largeur":1400,"hauteur":1290,"legende":"Der Markt von Ouidah um 1930"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-entree-1917.webp","largeur":600,"hauteur":440,"legende":"Der Eingang zum portugiesischen Fort im Jahr 1917"},"auj":{"src":"/histoire/lieu-musee.webp","largeur":1200,"hauteur":675,"legende":"Die Mauern des portugiesischen Forts"}}]},{"id":"souvenir","repere":"1993 – 1998","court":"1993","titre":"Erinnern","ville":true,"temps":[["Vom 8. bis 18. Februar 1993 findet in der Stadt das Festival Ouidah 92 statt, das der Kunst und Kultur des Vodun gewidmet ist. Ursprünglich für 1992 geplant, behielt es diesen Namen. Präsident Nicéphore Soglo hatte es angestoßen. Priester und Besucher kommen unter anderem aus Brasilien, Haiti sowie Trinidad und Tobago.","Zu diesem Anlass werden im Wald von Kpassè Statuen von Vodun-Gottheiten aufgestellt, und er wird für nicht initiierte Besucher geöffnet."],["Die Route des Esclaves entsteht während dieses Festivals. Sechs Stationen mit überwiegend von Cyprien Tokoudagba geschaffenen Skulpturen führen auf etwa drei bis vier Kilometern von der Place Chacha zum Strand. Im September 1994 startet die UNESCO in Ouidah ihr von Haiti und afrikanischen Ländern vorgeschlagenes Programm „La Route de l''esclave“. Am 30. November 1995 wird am Strand am Ende des Weges die Porte du Non-Retour eingeweiht.","1998 entsteht auf Initiative des Soziologen Honorat Aguessy ein Bußmarsch. Am dritten Sonntag im Januar führt er von der Place Chacha zum Mémorial Zomachi, um die Nachfahren der Verschleppten um Vergebung zu bitten."]],"pieces":[{"hier":{"src":"/histoire/plaque-ouidah92.webp","largeur":933,"hauteur":1400,"legende":"Die für Ouidah 92 auf der Place aux Enchères angebrachte Tafel im Jahr 2017"},"auj":null},{"hier":{"src":"/histoire/memorial-zomachi-2017.webp","largeur":1400,"hauteur":933,"legende":"Das Mémorial Zomachi im Jahr 2017"},"auj":null}]},{"id":"fete","repere":"1996 – 2026","court":"2024","titre":"Das Fest im Januar","ville":true,"temps":[["Auf Fon bedeutet Vodun „Gottheit, Geist“. Daraus entstand in Haiti das Wort Vodou. Am 10. Januar 1996 erklärt die Regierung von Nicéphore Soglo diesen Tag zum bezahlten arbeitsfreien Feiertag zu Ehren des Vodun und der traditionellen Religionen. Ein Gesetz vom August 1997 macht ihn zum jährlichen Feiertag.","Jahrelang findet die offizielle Zeremonie am 10. Januar am Strand von Ouidah nahe der Porte du Non-Retour statt."],["Im Oktober 2023 führt die Regierung die Vodun Days ein, um das Fest einem Publikum aus aller Welt zu öffnen. Die erste Ausgabe findet am 9. und 10. Januar 2024 in Ouidah an fünf Orten statt: Place Maro, Vorplatz des Fort français, Platz am Temple des Pythons, ein vorübergehender Mami-Konvent und Wald von Kpassè. An den beiden großen Abendveranstaltungen nehmen fast 100 000 Menschen teil.","Seit dem Gesetz vom 2. September 2024 fällt das Fest auf den zweiten Freitag im Januar. Die Ausgaben 2025 und 2026 dauern drei Tage."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-vodun-days-2024.webp","largeur":1200,"hauteur":675,"legende":"Tänzerinnen vor dem Publikum der Vodun Days 2024 in Ouidah"},"temps":1},{"hier":null,"auj":{"src":"/histoire/collage-zangbeto-meko.webp","largeur":1200,"hauteur":801,"legende":"Zangbéto bei den Vodun Days 2026 im Dorf Mèkô, Gemeinde Ouidah"},"temps":1}]},{"id":"route","repere":"1993 – 2025","court":"2025","titre":"Die Route, Station für Station","ville":true,"temps":[["Die an den Stationen erzählten Geschichten entstammen der Überlieferung. Der Weg der Gefangenen zum Meer ist hingegen historisch belegt.","Die Route beginnt auf der Place Chacha, auch Place aux Enchères genannt. Eine 1993 angebrachte Tafel besagt, dass hier unter einem großen Baum Gefangene versteigert wurden. Zeitgenössische Zeugnisse beschreiben etwas anderes: Der König legte die Preise für die Gefangenen fest. Verkäufe liefen über seine Agenten und die Handelshäuser, etwa das der Familie de Souza am Rand des Platzes. Nach einer jüngeren Neugestaltung ist der Platz heute gepflastert."],["Es folgt der Arbre de l''oubli. Nach der den Besuchern erzählten Überlieferung mussten Männer ihn neunmal, Frauen siebenmal umrunden, um ihre Heimat zu vergessen. Vor den 1990er-Jahren findet sich diese Erzählung in keiner Schrift. Ältere Texte nennen den Ort Arbre des capitaines: Hier empfingen die Oberhäupter Ouidahs die Europäer und umrundeten den Baum dreimal. Der ursprüngliche Baum ist verschwunden."],["Die Case Zomaï trägt einen Namen, der „wo Feuer oder Licht nicht eindringt“ bedeuten soll. Der Überlieferung zufolge wurden hier Gefangene im Dunkeln eingesperrt. Ältere Schriften verbinden den Namen mit den Pulverlagern von De Souza."],["In Zoungbodji steht eine Gedenkstätte. Der Überlieferung zufolge wurden hier die Gefangenen begraben, die vor der Abreise starben."],["Weiter folgt der Arbre du retour. Der Überlieferung zufolge umrundeten die Gefangenen ihn dreimal, damit ihre Seele nach dem Tod nach Afrika zurückkehren konnte. Keine zeitgenössische Quelle erwähnt dieses Ritual. Seine Statue stammt von Cyprien Tokoudagba."],["Der Weg endet am Strand an der Porte du Non-Retour. Sie ist ein Denkmal: Die Gefangenen wurden nicht von einem genau festgelegten Punkt aus verschifft, sondern vom Strand aus in Pirogen. Der Bogen von 1995 wurde ersetzt. Die im Dezember 2025 enthüllte neue Porte ist über sechzehn Meter hoch und trägt mehr als zweihundert Skulpturen.","Seit 2021 stehen der Platz, das portugiesische Fort, die Stätten von Zoungbodji und der Strand an der Porte auf der beninischen UNESCO-Vorschlagsliste, einer Voraussetzung für eine mögliche Aufnahme ins Welterbe."]],"etapes":["Place Chacha","Arbre de l''oubli","Case Zomaï","Zoungbodji","Arbre du retour","Porte du Non-Retour"],"pieces":[{"hier":{"src":"/histoire/place-chacha-2017.webp","largeur":1400,"hauteur":933,"legende":"Der Platz 2017 mit seinem großen Baum und der Stele „Place Chacha“"},"auj":{"src":"/histoire/place-chacha-2025.webp","largeur":1400,"hauteur":787,"legende":"Der neu gestaltete Platz im Januar 2025"}},{"hier":{"src":"/histoire/arbre-oubli-2015.webp","largeur":768,"hauteur":1024,"legende":"Die für Ouidah 92 aufgestellte Skulptur des Arbre de l''oubli im Jahr 2015"},"auj":null},{"hier":null,"auj":{"src":"/histoire/case-zomai-2019.webp","largeur":809,"hauteur":1400,"legende":"Die im Februar 1993 eingeweihte Stele der Case Zomaï (Foto von 2019)"}},{"hier":null,"auj":{"src":"/histoire/visite-zoungbodji.webp","largeur":1200,"hauteur":1200,"legende":"Das Mémorial de Zoungbodji"}},{"hier":null,"auj":{"src":"/histoire/raison-arbre-du-retour.webp","largeur":800,"hauteur":1200,"legende":"Der Arbre du retour mit seiner Statue (Foto von 2017)"}},{"hier":{"src":"/histoire/porte-1995.webp","largeur":1280,"hauteur":866,"legende":"Der Bogen von 1995, fotografiert im Jahr 2019"},"auj":{"src":"/histoire/eng-5-porte-jour.webp","largeur":675,"hauteur":1200,"legende":"Die neue Porte du Non-Retour, im Dezember 2025 enthüllt"}}]},{"id":"aujourdhui","repere":"Heute","court":"2027","titre":"Zurückkehren","ville":true,"temps":[["Seit dem Gesetz vom 2. September 2024 können Menschen afrikanischer Abstammung, deren Vorfahren im Zuge des Sklavenhandels verschleppt wurden, die beninische Staatsangehörigkeit beantragen. Als Nachweis können Personenstandsurkunden, amtliche Dokumente, Zeugenaussagen oder ein nicht verpflichtender DNA-Test dienen. Die Staatsangehörigkeit wird unter bestimmten Voraussetzungen per Dekret verliehen und an die Nachkommen weitergegeben."],["2027 finden die Vodun Days vom 2. bis 9. Januar statt. Das Fest der traditionellen Religionen fällt auf Freitag, den 8."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-egungun-vodun-days.webp","largeur":800,"hauteur":1200,"legende":"Ein Egungun während der Vodun Days"},"temps":1},{"hier":null,"auj":{"src":"/histoire/visite-cite-historique.webp","largeur":1200,"hauteur":675,"legende":"Der Eingang zur historischen Stadt Ouidah"},"temps":0}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:histoire.histoireFinale','{"titre":"Die Route des Esclaves führt zu Fuß von der Place Chacha zum Strand.","texte":"Sechs Stationen auf etwa drei bis vier Kilometern."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:histoire.histoirePage','{"metaTitre":"Die Geschichte von Ouidah — Ouidah Heritage Tour","metaDescription":"Von Glexwé nach Ouidah: die Forts, Dahomey, der Chacha und die Agudas, der Sklavenhandel bis zum Meer, die Basilika, die Route des Esclaves Station für Station, die neue Porte du Non-Retour und die Vodun Days.","defiler":"Scrollen","hier":"Gestern","avant":"Davor","aujourdhui":"Heute","chapitres":"Kapitel","cartes":{"royaume":{"src":"/histoire/carte-lune.webp","largeur":3146,"hauteur":2421},"ville":{"src":"/histoire/ville-1926-lune.webp","largeur":2400,"hauteur":2118}},"photoFin":"/histoire/fin-porte-nuit.webp","son":{"sources":["/son/histoire-bohicon.webm","/son/histoire-bohicon.m4a"],"volume":0.3,"fondu":4},"carteRoyaume":"Karte des Königreichs Whidah, Stich aus dem 18. Jahrhundert","carteVille":"Stadtplan von Ouidah aus dem Jahr 1926","appel":{"principal":{"label":"Der Route des Esclaves zu Fuß folgen","href":"/devis?circuit=route-des-esclaves"},"secondaire":{"label":"Meine Reise zusammenstellen","href":"/devis"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
