insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:credits-photos.creditsPhotos','[{"fichier":"/hero/hero-2-porte.jpg","oeuvre":"Neue Porte du Non-Retour, Seitenansicht","auteur":"MIA20102","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Nouvelle_Porte_du_Non-Retour_de_Ouidah_-_Vue_lat%C3%A9rale.jpg","modifiee":true},{"fichier":"/ouidah/aeroport-facade.jpg","oeuvre":"Fassade des Flughafens Cotonou","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Fa%C3%A7ade_principale_de_l%27a%C3%A9roport_international_de_Cotonou.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-2-temple-pythons.jpg","oeuvre":"Eingang zum Temple des Pythons","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_Temple_des_Pythons_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-3-plage-cocotiers.jpg","oeuvre":"Strand von Ouidah (Benin, 2013)","auteur":"jbdodane","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Ouidah_(Benin,_2013).jpg","modifiee":true},{"fichier":"/ouidah/collage-danse-atchinan-kpasse.jpg","oeuvre":"Vodoun Atchinan, heiliger Wald von Kpassè (15)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._15.jpg","modifiee":true},{"fichier":"/ouidah/collage-danseur-kpasse.jpg","oeuvre":"Vodoun Atchinan, heiliger Wald von Kpassè (01)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.w