thing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:legal','{"_note":"Pages légales (mentions, confidentialité et cookies, CGV), en français, éditables depuis l''admin (à venir) : chaque information de la société a une valeur et un interrupteur « visible » ; une information masquée ou vide disparaît de toutes les pages (ligne de fiche, phrase qui la cite). Sources : RCCM, carte professionnelle APIEx, annonce légale (11-12/06/2026) ; Code du numérique du Bénin (loi 2017-20), art. 328 : capital social et adresse du siège sont des mentions obligatoires ; décret 2023-493 art. 38 : référence de la licence obligatoire. Références : Assets OHT/Pages-legales/recherches/REFERENCES.md. Blocs : p (texte, liens [texte](adresse), {clé} de la société), liste, fiche, tableau, composant.","miseAJour":"6. November 2026","societe":{"denomination":{"libelle":"Bezeichnung","valeur":"OUIDAH HERITAGE TOUR","visible":true},"forme":{"libelle":"Rechtsform","valeur":"Vereinfachte Aktiengesellschaft französischen Rechts (SAS)","visible":true},"capital":{"libelle":"Stammkapital","valeur":"1 000 000 FCFA","visible":true},"siege":{"libelle":"Geschäftssitz","valeur":"Îlot 1158, parcelle F, maison Sikiratou Moustapha Lawani, quartier Haie Vive-Cocotiers, 12e arrondissement, Cotonou (Littoral), Bénin","visible":true},"quartier":{"libelle":"Stadtviertel des Geschäftssitzes (öffentlich)","valeur":"Haie Vive-Cocotiers","visible":true},"ville":{"libelle":"Stadt des Geschäftssitzes (öffentlich)","valeur":"Cotonou","visible":true},"agence":{"libelle":"Agentur in Ouidah","valeur":null,"visible":true},"rccm":{"libelle":"RCCM","valeur":"RB/COT/26 B 43278 vom 11. Juni 2026, Handelsgericht Cotonou","visible":true},"ifu":{"libelle":"IFU","valeur":"3202629321372","visible":true},"carte":{"libelle":"Gewerbeausweis","valeur":"Gewerbeausweis für Händler Nr. 1310CPC26, ausgestellt von APIEx, gültig bis zum 12. Juni 2028","visible":true},"licence":{"libelle":"Reisebürolizenz","valeur":null,"visible":true},"activite":{"libelle":"Tätigkeit","valeur":"Tourismus und Veranstaltungen, künstlerische und kulturelle Aktivitäten","visible":true},"presidente":{"libelle":"Verantwortlich für die Veröffentlichung","valeur":"Frau Nathalie Rosine RIFFERT, Präsidentin","visible":true},"telephones":{"libelle":"Telefon","valeur":["+229 01 98 87 36 36","+229 01 94 35 50 50"],"visible":true},"email":{"libelle":"E-Mail","valeur":"contact@ouidahheritagetour.bj","visible":true}},"pages":{"/mentions-legales":{"titre":"Impressum","metaTitre":"Impressum — Ouidah Heritage Tour","metaDescription":"Herausgeber, Hosting, Eigentum an Inhalten, Bildnachweise und Barrierefreiheit der Website von Ouidah Heritage Tour.","intro":"Wer diese Website herausgibt, wer sie hostet und an wen Sie sich wenden können.","sections":[{"id":"editeur","titre":"Herausgeber","blocs":[{"fiche":["denomination","forme","capital","siege","agence","rccm","ifu","carte","licence","activite","telephones","email"]}]},{"id":"publication","titre":"Verantwortlich für die Veröffentlichung","blocs":[{"p":"{presidente}."}]},{"id":"hebergement","titre":"Unterkunft","blocs":[{"fiche":[["Website","Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, Vereinigte Staaten · [vercel.com](https://vercel.com)"],["Datenbank","Supabase Pte. Ltd., 65 Chulia Street #38-02/03, OCBC Centre, Singapur 049513 · [supabase.com](https://supabase.com)"]]}]},{"id":"propriete","titre":"Texte, Fotos und Logo","blocs":[{"p":"Das Logo, die Texte, die Illustrationen und das Layout dieser Website gehören OUIDAH HERITAGE TOUR oder ihren jeweiligen Urhebern. Für eine vollständige oder teilweise Weiterverwendung bitten Sie uns vorab unter {email} um eine schriftliche Genehmigung."},{"p":"Fotos unter freien Lizenzen werden gemäß deren Bedingungen verwendet. Ihre Urheber sind in den folgenden Bildnachweisen aufgeführt. Die Kartengrundlagen sind © OpenStreetMap-Mitwirkende, unter ODbL-Lizenz."}]},{"id":"credits","titre":"Bildnachweise","blocs":[{"composant":"credits"}]},{"id":"accessibilite","titre":"Barrierefreiheit","blocs":[{"p":"Wir möchten, dass alle diese Website lesen und ihre Reise vorbereiten können. Sie lässt sich mit der Tastatur bedienen, Bilder haben Beschreibungen, Texte sind kontrastreich und Animationen werden reduziert, wenn Ihr Gerät weniger Bewegung anfordert."},{"p":"Ist ein Abschnitt schwer zu lesen oder reagiert eine Schaltfläche nicht? Schreiben Sie uns unter {email} und nennen Sie die Seite. Wir antworten Ihnen und beheben das Problem."}]},{"id":"liens","titre":"Links zu anderen Websites","blocs":[{"p":"Die Website verweist gelegentlich auf offizielle Websites oder Partner, etwa für ein Visum oder eine Veranstaltung. Für deren Inhalte sind die jeweiligen Herausgeber verantwortlich."}]},{"id":"droit","titre":"Anwendbares Recht","blocs":[{"p":"Diese Website unterliegt beninischem Recht. Bei einer Buchung oder Bestellung erläutern die [Allgemeinen Geschäftsbedingungen](/conditions-generales-de-vente#litiges), wie Meinungsverschiedenheiten geklärt werden können."}]}]},"/politique-de-confidentialite":{"titre":"Datenschutz und Cookies","metaTitre":"Datenschutz und Cookies — Ouidah Heritage Tour","metaDescription":"Welche Daten Ouidah Heritage Tour erhebt, warum und wie lange, was die Website in Ihrem Browser speichert und wie Sie Ihre Rechte ausüben können.","intro":"Welche Daten wir erfassen, warum, wie lange und wie Sie Ihre Rechte ausüben. Wir verkaufen keine Daten und zeigen keine Werbung. Besuche werden nur mit Ihrer Zustimmung gezählt.","sections":[{"id":"responsable","titre":"Wer für Ihre Daten verantwortlich ist","blocs":[{"p":"{denomination}, {forme}, mit Geschäftssitz in {siege}."},{"p":"Bei Fragen zu Ihren Daten schreiben Sie an {email} mit dem Betreff „Personenbezogene Daten“ oder per Post an den Geschäftssitz."}]},{"id":"donnees","titre":"Welche Daten wir erheben und warum","blocs":[{"p":"Nur Angaben, die Sie uns in einem Formular anvertrauen, und nur für den angegebenen Zweck."},{"tableau":{"colonnes":["Wann","Daten","Warum","Wie lange"],"lignes":[["Sie fordern ein Angebot an („Meine Reise planen“)","Name, E-Mail-Adresse, gegebenenfalls WhatsApp, Land, Sprache der Führung, Ihre Reise (Termine, Orte, gewählte Leistungen), Ihre Nachricht","Ihre Anfrage beantworten und auf Ihren Wunsch ein Angebot erstellen","3 Jahre nach unserem letzten Austausch, sofern keine Buchung folgt"],["Sie speichern Ihre Anfrage, um sie später fortzusetzen","Ihre Reise und Ihre Antworten, ohne Ihre Kontaktdaten","Ihnen den Link zum Fortsetzen senden und Ihre Anfrage wiederherstellen","Der Link ist 30 Tage gültig; ein nie abgesendeter Entwurf wird 90 Tage nach seiner Erstellung gelöscht"],["Sie buchen ein Ticket oder einen Aufenthalt","Name, E-Mail-Adresse, Telefon, Land, Sprache, Angebot, Anzahl der Plätze, Betrag, Zahlungsmethode und Transaktionsreferenz","Ihre Buchung, Ihr Ticket und Ihre Rechnung erstellen","10 Jahre, die Aufbewahrungsfrist für Buchungsbelege"],["Sie bestellen im Shop","Vorname, Nachname, E-Mail-Adresse, Telefon, Land, gegebenenfalls Lieferadresse, Artikel und Optionen, Ihre Nachricht","Ihre Bestellung bestätigen, vorbereiten und liefern","10 Jahre, die Aufbewahrungsfrist für Buchungsbelege"],["Sie abonnieren den Brief aus Ouidah","E-Mail-Adresse, Sprache, gewählte Themen, Datum Ihrer Zustimmung","Ihnen mit Ihrer Zustimmung den Brief senden","Bis zu Ihrer Abmeldung, jederzeit über jeden Brief oder per E-Mail möglich"],["Sie senden ein Formular","Ein kryptografischer Fingerabdruck Ihrer IP-Adresse, niemals die Adresse selbst","Automatisierte Einsendungen begrenzen und den Dienst schützen","Ebenso lange wie die zugehörige Anfrage"]]}},{"p":"Die Formulare für Termine und Partnerbewerbungen erfassen Ihre Kontaktdaten und Angaben, damit unser Team den Termin organisieren oder Ihre Bewerbung prüfen kann. Eingehende E-Mails können Ihrer Anfrage zugeordnet werden, um die Bearbeitung zu verfolgen."}]},{"id":"paiement","titre":"Zahlung","blocs":[{"p":"Sie bezahlen beim Zahlungsanbieter Ihrer Wahl aus den angebotenen Optionen: Kkiapay, FedaPay, Stripe, Flutterwave oder Paystack. Wir sehen und speichern weder Ihre Kartennummern noch Ihre Mobile-Money-Codes. Wir erhalten den Betrag, den Zahlungsstatus und die Referenznummer."}]},{"id":"destinataires","titre":"Wer Ihre Daten erhält","blocs":[{"liste":["Das Team von Ouidah Heritage Tour, das Ihre Reise oder Bestellung vorbereitet.","Unsere technischen Dienstleister ausschließlich für den jeweiligen Dienst: Vercel (Hosting der Website und, mit Ihrer Zustimmung, Besuchermessung, Vereinigte Staaten), Supabase (Datenbank), unser von AfriRegister gehostetes Postfach {email} (Versand von Bestätigungen, Angeboten und Tickets), der von Ihnen gewählte Zahlungsanbieter und Groq, Inc. (KI-Assistent der Website, Vereinigte Staaten).","Die Partner Ihres Aufenthalts (Unterkunft, Transport, Führung) erhalten nur, was sie benötigen: Ihren Namen, Ihre Reisedaten und die Anzahl der Reisenden."]},{"p":"Wir verkaufen oder vermieten Ihre Daten nicht und verwenden sie nicht für Werbung."}]},{"id":"transferts","titre":"Daten außerhalb Benins","blocs":[{"p":"Einige unserer Dienstleister sind außerhalb Benins ansässig, insbesondere in den Vereinigten Staaten und Singapur. Wir übermitteln ihnen ausschließlich die für die jeweilige Leistung erforderlichen Daten im Rahmen ihrer vertraglichen Datenschutzverpflichtungen."}]},{"id":"navigateur","titre":"Was die Website in Ihrem Browser speichert","blocs":[{"p":"Damit beim Wechsel zwischen Seiten nichts verloren geht, speichert die Website einige Angaben in Ihrem Browser. Sie bleiben auf Ihrem Gerät und erreichen uns erst, wenn Sie ein Formular absenden. Sie sind für den Betrieb der Website erforderlich."},{"liste":["Ihre Reiseplanung: ausgewählte Orte, Tour, Termine, Leistungen und Tickets.","Ihre laufende Angebotsanfrage einschließlich bereits eingegebenem Namen und E-Mail-Adresse, damit Sie diese nicht erneut eingeben müssen.","Die gewählte Währung und der Warenkorb des Shops.","Die Rückkehrinformation einer laufenden Zahlung, die beim Schließen des Tabs gelöscht wird.","Die Information, dass Sie die Eröffnungsanimation bereits gesehen haben, gelöscht beim Schließen des Tabs.","Ihre Einstellungen zu den folgenden optionalen Diensten."]},{"p":"Die Website setzt keine Werbe- oder Analyse-Cookies. Um alles zu löschen, entfernen Sie die Daten dieser Website in Ihren Browsereinstellungen."}]},{"id":"assistant","titre":"Website-Assistent und Gespräch mit dem Team","blocs":[{"p":"Der KI-Assistent von OHT beantwortet Ihre Fragen ausschließlich anhand der auf dieser Website veröffentlichten Inhalte. Für jede Antwort werden Ihre Nachricht und die letzten Gesprächsbeiträge an unseren Auftragsverarbeiter Groq, Inc. in den Vereinigten Staaten gesendet; für keinen anderen Zweck übermitteln wir sie. Das Gespräch wird beim Verlassen der Seite oder nach 30 Minuten ohne Aktivität gelöscht. Wenn Sie dem Assistenten Informationen mitteilen, auf die unser Team reagieren muss (Reisevorhaben, Angebotsanfrage, Kontaktdaten, Beschwerde, unbeantwortete Frage), übermittelt er dem Team eine Zusammenfassung. Nur diese wird 90 Tage gespeichert. Wenn Sie sich entscheiden, einer Person unseres Teams zu schreiben, bewahren wir das Gespräch und die zur Kontaktaufnahme angegebene E-Mail-Adresse oder WhatsApp-Nummer 90 Tage auf und löschen sie anschließend. Wird ein Gespräch in eine Anfrage umgewandelt, gilt die Aufbewahrungsfrist für Anfragen. Fragen, die der Assistent nicht beantworten konnte, werden ohne Ihre IP-Adresse oder andere Kennung gespeichert, nachdem enthaltene E-Mail-Adressen, Nummern und Namen entfernt wurden. So kann unser Team sie beantworten und das Wissen des Assistenten ergänzen. Ihre IP-Adresse wird nur als Fingerabdruck zur Begrenzung der Nutzung (Nachrichtenanzahl) gespeichert. Zugang, Berichtigung oder Löschung Ihrer Daten können Sie unter {email} beantragen."}]},{"id":"cookies","titre":"Optionale Dienste nach Ihrer Wahl","blocs":[{"p":"Drei Dienste übermitteln Daten an Dritte oder zählen Ihre Besuche. Sie starten nur mit Ihrer Zustimmung. Eine Ablehnung schränkt den Zugang zu keiner Seite ein."},{"fiche":[["Interaktive Karten","Die Kartengrundlagen stammen von OpenFreeMap, das Ihre IP-Adresse erhält. Bei Ablehnung wird die Karte als Bild angezeigt."],["Ungefährer Standort","Ihr ungefährer Wohnort wird von unserem Hoster Vercel aus Ihrer IP-Adresse ermittelt, ersatzweise von Open-Meteo aus Ihrer Zeitzone. Er dient dazu, Ouidah im Verhältnis zu Ihrem Wohnort darzustellen, und bleibt in Ihrem Browser. Bei Ablehnung geben Sie ihn selbst ein."],["Besuchermessung","OHT und Vercel Web Analytics (Vereinigte Staaten) zählen Seitenaufrufe ohne Cookies oder Kennungen, damit wir wissen, was unsere Besucher interessiert. Bei Ablehnung wird nichts gezählt."]]},{"p":"Sie können Ihre Entscheidung jederzeit hier oder über den Link „Cookies“ am Ende jeder Seite ändern."},{"composant":"choixCookies"}]},{"id":"securite","titre":"Sicherheit","blocs":[{"p":"Die Website wird über HTTPS bereitgestellt. Auf unsere Datenbanken können nur Personen zugreifen, die dies benötigen. Links zum Fortsetzen einer Anfrage und Tickets sind signiert. Wir speichern von einem Link nur seinen Fingerabdruck, niemals den Link selbst."}]},{"id":"droits","titre":"Ihre Rechte","blocs":[{"p":"Sie können jederzeit auf Ihre Daten zugreifen, sie berichtigen oder löschen lassen, ihrer Verwendung widersprechen, eine Kopie in einem lesbaren Format anfordern und Ihre Zustimmung zum Brief oder zu optionalen Diensten widerrufen."},{"p":"Schreiben Sie an {email} mit dem Betreff „Personenbezogene Daten“. Wir können Sie bitten, Ihre Identität zu bestätigen, und antworten anschließend innerhalb von 30 Tagen."},{"p":"Wenn Sie mit unserer Antwort nicht zufrieden sind, können Sie sich an die Autorité de Protection des Données à caractère Personnel (APDP) wenden: Rue 6.076, Aïdjèdo, immeuble El Marzouk Joël, 01 BP 04837 Cotonou, Bénin · +229 21 32 57 88 · contact@apdp.bj · [apdp.bj](https://apdp.bj)."},{"p":"Unter [Meine Daten](/mes-donnees) können Sie einen persönlichen Link an Ihre E-Mail-Adresse anfordern. Damit können Sie Ihre Daten herunterladen oder dem Team einen Löschantrag senden. Für die Zahlungsverfolgung und Buchhaltung erforderliche Belege werden aufbewahrt."}]},{"id":"mineurs","titre":"Minderjährige","blocs":[{"p":"Unsere Buchungen richten sich an Erwachsene. Minderjährige unter 16 Jahren dürfen uns nur mit Zustimmung eines Elternteils Daten übermitteln."}]},{"id":"modifications","titre":"Aktualisierungen","blocs":[{"p":"Das Datum der letzten Aktualisierung steht oben auf dieser Seite. Wenn eine Änderung eine laufende Buchung betrifft, schreiben wir Ihnen."}]}]},"/conditions-generales-de-vente":{"titre":"Allgemeine Geschäftsbedingungen","metaTitre":"Allgemeine Geschäftsbedingungen — Ouidah Heritage Tour","metaDescription":"Veranstaltungstickets, Aufenthalte auf Anfrage und der Shop von Ouidah Heritage Tour: Preise, Zahlung, Widerruf, Stornierung, Lieferung, Rückgabe und Streitigkeiten.","intro":"Die Regeln für die Buchung eines Tickets oder Aufenthalts und für Bestellungen im Shop. Ist etwas unklar? Schreiben Sie uns vor der Buchung.","sections":[{"id":"champ","titre":"Wofür diese Bedingungen gelten","blocs":[{"p":"Sie gelten für die Verkäufe von {denomination}, {forme} (siehe [Impressum](/mentions-legales)):"},{"liste":["Tickets für die von uns organisierten Veranstaltungen;","Aufenthalte, Touren und Begleitungen nach Angebot, auch im Zusammenhang mit Veranstaltungen anderer Organisatoren;","Artikel aus dem Shop."]},{"p":"Sie akzeptieren diese Bedingungen mit der Bestätigung Ihrer Buchung oder Bestellung. Die an diesem Tag geltende Fassung bleibt für Sie maßgeblich."}]},{"id":"prix","titre":"Preise und Zahlung","blocs":[{"liste":["Die Preise verstehen sich einschließlich aller Steuern in CFA-Franc (XOF). Die Anzeige in Euro folgt dem festen Kurs 1 € = 655,957 FCFA.","Im Shop kommen Lieferkosten zum Artikelpreis hinzu. Sie werden Ihnen vor jeder Zahlung mitgeteilt.","Sie bezahlen den Gesamtbetrag ohne Anzahlung über einen der zum Zahlungszeitpunkt angebotenen Anbieter. Wir erhalten niemals Ihre Kartendaten."]}]},{"id":"retractation","titre":"Ihr Widerrufsrecht","blocs":[{"p":"Sie haben 15 Werktage Zeit, Ihre Entscheidung ohne Begründung zu ändern: ab der Zahlung bei einem Ticket oder Aufenthalt, ab dem Erhalt bei einem Artikel. Schreiben Sie an {email}. Wir erstatten Ihnen den vollständigen Betrag innerhalb von 14 Tagen über das verwendete Zahlungsmittel."},{"p":"Dieses Recht gilt nicht mehr für ein bereits vollständig genutztes Ticket oder einen vollständig durchgeführten Aufenthalt sowie für auf Ihren Wunsch maßgefertigte oder personalisierte Artikel."}]},{"id":"billets","titre":"Veranstaltungstickets","blocs":[{"liste":["Sie buchen im Veranstaltungskalender der Website: Angebot, Anzahl der Plätze und Kontaktdaten, anschließend die Zahlung.","Ihr auf Ihren Namen ausgestelltes Ticket mit QR-Code wird Ihnen per E-Mail zugesandt, sobald der Zahlungsanbieter die Zahlung bestätigt. Zeigen Sie es auf Ihrem Telefon oder ausgedruckt vor. Jeder QR-Code gewährt einmalig Einlass.","Sie können nicht kommen? Nach Ablauf der Widerrufsfrist erstatten wir bis 30 Tage vor der Veranstaltung den gesamten Betrag, zwischen 30 und 8 Tagen vorher die Hälfte. Danach können Sie Ihren Platz verschenken: Bis 48 Stunden vorher stellen wir das Ticket kostenlos auf eine Person Ihrer Wahl aus.","Wenn wir die Veranstaltung absagen oder verschieben, wählen Sie zwischen der vollständigen Erstattung und Ihrem Platz zum neuen Termin."]}]},{"id":"sejours","titre":"Aufenthalte und Begleitungen nach Angebot","blocs":[{"liste":["Ihre Angebotsanfrage ist kostenlos und unverbindlich. Das Angebot enthält die Leistungen, die Termine, die enthaltenen Bestandteile und den Gesamtpreis. Es ist 15 Tage gültig.","Ihre Buchung wird verbindlich, wenn Sie das Angebot annehmen und den vollständigen Betrag bezahlen. Anschließend senden wir Ihnen die schriftliche Bestätigung Ihrer Reise.","Bei einem Aufenthalt rund um eine von anderen organisierte Veranstaltung wie die Vodun Days verkaufen wir den Aufenthalt, nicht die Veranstaltung. Das Programm hängt von den Veranstaltern ab. Bei Änderungen passen wir Ihren Aufenthalt gemeinsam mit Ihnen an.","Möchten Sie Ihre Termine oder Leistungen ändern? Teilen Sie es uns mit. Wir passen sie nach Verfügbarkeit an; eine Preisdifferenz wird zusätzlich berechnet oder erstattet.","Wenn Sie nach Ablauf der Widerrufsfrist stornieren, erstatten wir bis 45 Tage vor der Ankunft den gesamten Betrag abzüglich bereits angefallener, nicht erstattbarer Partnerkosten, die wir Ihnen nachweisen. Zwischen 45 und 15 Tagen vorher erstatten wir die Hälfte. Weniger als 15 Tage vorher bieten wir Ihnen an, Ihren Aufenthalt nach Verfügbarkeit zu verschieben.","Wenn wir absagen müssen, erstatten wir Ihnen den vollständigen Betrag oder bieten Ihnen nach Ihrer Wahl einen anderen Aufenthalt an.","Für Reisepass, Visum und Gelbfieber-Impfbescheinigung sind Sie selbst verantwortlich. Der Abschnitt „Planen Sie Ihre Reise“ hilft Ihnen dabei. Eine Reiseversicherung einschließlich Rücktransport wird dringend empfohlen.","Wir sind für die ordnungsgemäße Erbringung der von uns verkauften Leistungen verantwortlich. Selbst gebuchte Flüge fallen nicht in unseren Zuständigkeitsbereich."]}]},{"id":"boutique","titre":"Shop","blocs":[{"liste":["Ihre Bestellung ist zunächst eine Anfrage. Innerhalb von 2 Werktagen bestätigen wir Ihnen per E-Mail die Verfügbarkeit, die Übergabeart und den Gesamtbetrag einschließlich Gebühren.","Sie bezahlen nach dieser Bestätigung den vollständigen Betrag. Der Kaufvertrag kommt mit Eingang der Zahlung zustande.","Maßgefertigte oder personalisierte Artikel werden nach der Zahlung innerhalb der in der Bestätigung genannten Frist hergestellt."]}]},{"id":"livraison","titre":"Lieferung und Rückgabe","blocs":[{"liste":["Kostenlose Abholung in Ouidah: Ort und Zeiten stehen in der Bestätigung.","Lieferung in Benin und in die bei der Bestellung angebotenen Länder. Die Kosten hängen von Land und Paket ab und werden Ihnen vor der Zahlung mitgeteilt.","Ungefähre Lieferzeiten ab Versand: 2 bis 5 Werktage in Benin, 5 bis 10 in Westafrika und 7 bis 21 in andere Länder. Wir übermitteln Ihnen die Sendungsverfolgung.","Außerhalb Benins trägt der Empfänger gegebenenfalls anfallende Einfuhrzölle und Steuern.","Rückgabe eines Artikels: innerhalb von 15 Werktagen nach Erhalt, im ursprünglichen Zustand. Wir erstatten Ihnen den Artikelpreis und die ursprünglichen Lieferkosten innerhalb von 14 Tagen nach Eingang der Rücksendung. Die Rücksendekosten tragen Sie. Ein Umtausch der Größe oder Farbe ist innerhalb derselben Frist nach Verfügbarkeit möglich.","Beschädigter oder falsch gelieferter Artikel: Melden Sie dies innerhalb von 7 Tagen nach Erhalt mit Fotos. Wir tauschen den Artikel aus, reparieren ihn oder erstatten den Preis auf unsere Kosten.","Maßgefertigte oder personalisierte Artikel werden nur bei Mängeln zurückgenommen oder umgetauscht."]}]},{"id":"donnees","titre":"Ihre Daten","blocs":[{"p":"Wie wir Ihre Kontaktdaten verwenden, steht auf der Seite [Datenschutz und Cookies](/politique-de-confidentialite)."}]},{"id":"litiges","titre":"Beschwerden und Streitigkeiten","blocs":[{"p":"Bei Beschwerden kontaktieren Sie uns unter {telephones} · {email}. Wir antworten innerhalb von 7 Werktagen und suchen zunächst gemeinsam mit Ihnen eine einvernehmliche Lösung."},{"p":"Sie können sich auch mit einer Beschwerde an die für Tourismus zuständige beninische Behörde wenden."},{"p":"Diese Bedingungen unterliegen beninischem Recht. Kommt keine Einigung zustande, ist das Handelsgericht Cotonou zuständig. Wenn Sie außerhalb Benins wohnen, behalten Sie die Schutzrechte, die Ihnen das Recht Ihres Landes gewährt, einschließlich des Rechts, ein Gericht an Ihrem Wohnsitz anzurufen, sofern dies vorgesehen ist."}]}]}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:legal-ui.legalUi','{"miseAJour":"Aktualisiert am:","sommaire":"Inhalt","revoirChoix":"Meine Einstellungen prüfen"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.consentement','{"titre":"Ihre Einstellungen auf dieser Website","court":"Interaktive Karten und ungefährer Standort: Sie entscheiden.","accepter":"Alle akzeptieren","refuser":"Alle ablehnen","choisir":"Auswählen","enregistrer":"Meine Einstellungen speichern","fermer":"Schließen","toujours":"Immer aktiv","politique":{"label":"Datenschutz und Cookies","href":"/politique-de-confidentialite"},"categories":[{"id":"necessaires","nom":"Erforderlich","texte":"Ihre Reiseplanung, Währung, Warenkorb und Zahlungsrückkehr, gespeichert in Ihrem Browser."},{"id":"cartes","nom":"Interaktive Karten","texte":"Die Kartengrundlagen stammen von OpenFreeMap, das Ihre IP-Adresse erhält. Bei Ablehnung wird die Karte als Bild angezeigt."},{"id":"ville","nom":"Ungefährer Standort","texte":"Ihr Ort wird von unserem Hoster aus Ihrer IP-Adresse ermittelt, um Ouidah im Verhältnis zu Ihrem Wohnort darzustellen. Er bleibt in Ihrem Browser. Bei Ablehnung geben Sie ihn selbst ein."},{"id":"mesure","nom":"Besuchermessung","texte":"OHT und Vercel Web Analytics (Vereinigte Staaten) zählen Seitenaufrufe ohne Cookies oder Kennungen, damit wir wissen, was unsere Besucher interessiert. Bei Ablehnung wird nichts gezählt."}],"lienPied":"Cookies","afficherCarte":"Interaktive Karte anzeigen"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.nav','{"primary":[{"label":"Ouidah","href":"#ouidah","sous":[{"label":"Sehenswerte Orte","href":"/#lieux"},{"label":"10 Gründe für einen Besuch","href":"/#raisons"},{"label":"Geschichte","href":"/ouidah/histoire"}]},{"label":"Touren","href":"/#chemins"},{"label":"Veranstaltungen","href":"/#agenda"},{"label":"Concierge-Service","href":"/#conciergerie"},{"label":"Shop","href":"/boutique","boutique":true},{"label":"Blog","href":"/blog","blog":true},{"label":"Die Agentur","href":"#agence","sous":[{"label":"Wer wir sind","href":"/#bienvenue"},{"label":"Unsere Zusagen","href":"/#engagements"},{"label":"Schreiben Sie uns","href":"/devis?demande=question"}]}],"book":{"label":"Meine Reise planen","href":"/devis"},"contact":{"label":"Schreiben Sie uns","href":"/devis?demande=question"},"logo":{"src":"/brand/oht-logo.png","alt":"Ouidah Heritage Tour"},"embleme":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"wordmark":["Ouidah","Heritage Tour"],"home":"Ouidah Heritage Tour, zurück zur Startseite","currencies":[{"code":"EUR","short":"EUR €","long":"EUR (€)"},{"code":"FCFA","short":"FCFA","long":"FCFA (XOF)"},{"code":"USD","short":"USD $","long":"USD ($)"}],"currencyLabel":"Anzeigewährung:","drawerLabel":"Navigation","drawerNote":"Ouidah Heritage Tour — Agentur für Erinnerungs- und Kulturtourismus in Ouidah, Benin","open":"Menü öffnen","close":"Menü schließen","whatsapp":{"label":"WhatsApp","number":null,"message":"Hallo Ouidah Heritage Tour, ich plane eine Reise nach Ouidah und würde gerne mit Ihnen darüber sprechen."},"languages":[{"code":"FR","label":"Français","active":true},{"code":"EN","label":"English"},{"code":"ES","label":"Español"},{"code":"DE","label":"Deutsch"},{"code":"PT","label":"Português"},{"code":"HT","label":"Kreyòl ayisyen"},{"code":"GCF","label":"Kréyòl"}],"languageLabel":"Sprache ändern","brand":"Ouidah Heritage Tour","skip":"Zum Inhalt"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('DE:fr.footer','{"tagline":"Agentur für Erinnerungs- und Kulturtourismus in Ouidah, Benin.","photos":[{"src":"/ouidah/raison-foret-kpasse.jpg","legende":"Heiliger Wald von Kpassè, Ouidah","position":"50% 55%","nuit":false},{"src":"/hero/hero-2-porte.jpg","legende":"Porte du Non-Retour bei Nacht","position":"50% 30%","nuit":true},{"src":"/ouidah/visite-cite-historique.jpg","legende":"Historische Stadt Ouidah","position":"50% 40%","nuit":false}],"vif":["Es ist","in Ouidah."],"columns":[{"title":"Entdecken","links":[{"label":"Sehenswerte Orte","href":"/#lieux"},{"label":"10 Gründe für einen Besuch","href":"/#raisons"},{"label":"Geschichte","href":"/ouidah/histoire"},{"label":"Blog","href":"/blog","blog":true}]},{"title":"Reisen","links":[{"label":"Touren","href":"/#chemins"},{"label":"Veranstaltungen","href":"/#agenda"},{"label":"Concierge-Service","href":"/#conciergerie"},{"label":"Meine Reise vorbereiten","href":"/#preparer"},{"label":"Meine Reise planen","href":"/devis"},{"label":"Gruppen und Geschäftsreisende","href":"/devis?demande=groupe"},{"label":"Einen Termin vereinbaren","href":"/rendez-vous"}]},{"title":"Einkaufen","boutique":true,"links":[{"label":"Shop","href":"/boutique"},{"label":"Lieferung und Rückgabe","href":"/conditions-generales-de-vente#livraison"}]},{"title":"Die Agentur","links":[{"label":"Wer wir sind","href":"/#bienvenue"},{"label":"Unsere Zusagen","href":"/#engagements"},{"label":"Schreiben Sie uns","href":"/devis?demande=question"}]}],"planLabel":"Seitenübersicht","joindre":{"avant":"Weitere Kontaktmöglichkeiten:","whatsapp":"über WhatsApp schreiben","apres":"."},"legal":[{"label":"Impressum","href":"/mentions-legales"},{"label":"Datenschutz und Cookies","href":"/politique-de-confidentialite"},{"label":"AGB","href":"/conditions-generales-de-vente"},{"label":"Bildnachweise","href":"/mentions-legales#credits"},{"label":"Barrierefreiheit","href":"/mentions-legales#accessibilite"}],"legalLabel":"Rechtliche Informationen","pays":"Benin","langue":"Sprache","devise":"Währung","bientot":"demnächst","reglages":"Sprache und Währung","haut":"Nach oben"}'::jsonb,1,now()) on conflict(cle) do nothing;
