insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:site.seo','{"titre":"Ouidah Heritage Tour · Viagens a Ouidah, Benim","description":"Descubra Ouidah, o seu património e os seus lugares de memória com a Ouidah Heritage Tour. Circuitos, eventos e viagens preparados com a equipa local.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.hero','{"kicker":["Agência de turismo de memória e cultura","Ouidah, Benim"],"title":{"lead":"Ouidah,","accent":"cidade do Vodun e da memória"},"sub":"Percorra a pé a Route des Esclaves, da place Chacha até à Porte du Non-Retour, diante do Atlântico.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Vista aérea da praia de Ouidah: ondas do Atlântico, areia dourada e coqueiros"},{"src":"/hero/hero-2-porte.jpg","alt":"A nova Porte du Non-Retour de Ouidah, vista de lado"}],"search":{"action":"/#chemins","label":"Pesquisar um circuito","submit":"Pesquisar","fields":[{"name":"lieu","label":"Destino","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Tipo de viagem","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Duração","objet":"calendrier","options":[{"value":"","label":"Todas as durações"},{"value":"demi-journee","label":"Meio dia"},{"value":"journee","label":"Um dia"},{"value":"plusieurs-jours","label":"Vários dias"}]}]},"primary":{"label":"Ver os nossos circuitos","href":"/#chemins"},"secondary":{"label":"Criar a minha viagem à medida","href":"/devis"},"facts":[{"value":"1721","label":"Forte português, hoje museu de história"},{"value":"4 km","label":"Da place Chacha à praia, pela Route des Esclaves"},{"value":"2025","label":"Nova Porte du Non-Retour"},{"value":"23 de agosto","label":"Dia de memória do tráfico de escravos"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.welcome','{"label":"Quem somos","title":["Bem-vindo a casa,","no coração da sua História."],"paragraphs":["A Ouidah Héritage Tour é mais do que uma agência: é um compromisso com um turismo responsável e profundamente humano.","Convidamo-lo a viver Ouidah perto da sua essência, num destino onde a história, a espiritualidade, a cultura, a arte e a natureza se encontram para lhe proporcionar uma experiência autêntica.","Cada viagem é única: a nossa equipa cuida dos seus interesses, expectativas e necessidades. Estamos consigo antes, durante e depois da viagem."],"link":{"label":"A história de Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Uma jovem arruma tecidos wax coloridos no mercado"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Quem somos","segments":[{"text":"Bem-vindo a casa,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"A Porte du Non-Retour iluminada à noite"},"ring":"sun"},{"text":"no coração da sua História,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"A entrada pintada do Temple des Pythons"},"ring":"abyss"},{"text":"da Route des Esclaves"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"A praia de Ouidah ao pôr do sol"},"ring":"sun"},{"text":"até ao oceano."}],"columns":[{"title":"Memória e cultura","text":"Como agência de turismo de memória e cultura, levamo-lo a pé pela Route des Esclaves, com um guia que conta a história de cada etapa."},{"title":"Os lugares que escolher","text":"O Temple des Pythons diante da basílica, a floresta sagrada de Kpassè, o mercado de Zobè, a lagoa de piroga. Compomos a sua estadia com os lugares que lhe dizem algo."},{"title":"Do aeroporto a Ouidah","text":"Transporte desde o aeroporto de Cotonou, alojamento, refeições e veículo: organizamos consigo tudo o que acompanha a visita, antes, durante e depois da viagem."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.placesIntro','{"kicker":"O mapa · Da cidade ao oceano","title":"Ouidah em quatro lugares","titleParts":{"before":"Ouidah em","number":"4","spoken":"quatro","after":"lugares."},"intro":"Desloque a página: o percurso desenha-se no mapa, do forte português à Porte du Non-Retour, pelas ruas da cidade.","link":"Ver o lugar","walked":"km percorridos","mapLabel":"Mapa de Ouidah com os quatro lugares e o percurso a pé que os liga"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Os nossos compromissos","title":"Sete compromissos, cumpridos no terreno.","intro":"O que pode esperar de nós, da primeira pergunta ao regresso.","of":"de"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.reasons','[{"title":"Um território que conhecemos de perto","text":"Do forte português à praia, os nossos guias acompanham-no a pé.","couleur":"sun"},{"title":"Factos verificados","text":"Os relatos da visita apoiam-se na história documentada do tráfico de escravos.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"A entrada do museu de história de Ouidah, no forte português"}},{"title":"A sua história em primeiro lugar","text":"O seu circuito constrói-se em torno da sua história e das suas perguntas.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"A entrada pintada do Temple des Pythons"}},{"title":"Parceiros do país","text":"Alojamentos, restaurantes, guias e artesãos do país: escolhemos consigo os locais da estadia.","couleur":"abyss"},{"title":"Para a diáspora","text":"O nosso circuito Retour aux sources leva os afrodescendentes do forte à Porte du Non-Retour.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"A Porte du Non-Retour diante do oceano, durante o dia"}},{"title":"Antes, durante e depois","text":"Resposta em 24 horas, acolhimento à chegada e acompanhamento até ao regresso.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"A route des Pêches, ladeada de coqueiros, em Ouidah"}},{"title":"Para os profissionais locais","text":"Participamos na formação dos profissionais do turismo local e damos a conhecer o seu trabalho.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.tenIntro','{"title":["O que a cidade lhe reserva,","da memória ao oceano."],"link":{"label":"Descobrir","href":"/#raisons"},"place":"Ouidah","discover":"Descobrir o lugar","circle":"Assinalar","circled":"Assinalada","path":{"label":"Ver o meu percurso","href":"#chemins"},"stripLabel":"As paisagens, da memória ao oceano","filmEdge":"OUIDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.tenReasons','[{"slug":"route-des-esclaves","title":"A Route des Esclaves","short":"Route des Esclaves","category":"Memória","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"L''Arbre du Retour, última etapa da Route des Esclaves antes da praia"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"Da place Chacha, onde se realizavam os leilões, até à praia: cerca de 4 km, o caminho que os cativos percorriam até aos navios. Passamos por L''Arbre de l''Oubli, à volta do qual os obrigavam a andar para apagar o seu nome e a sua origem, pelas Cases Zomaï, onde os encerravam na escuridão, pelo memorial de Zoungbodji e por L''Arbre du Retour, para que a sua alma regressasse. Fazemos o percurso a pé, com um guia que conta a história de cada etapa."},{"slug":"porte-du-non-retour","title":"A Porte du Non-Retour","short":"Porte du Non-Retour","category":"Memória","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"A Porte du Non-Retour diante do oceano, durante o dia"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"No fim da Route des Esclaves, na praia, diante do Atlântico. Assinala o lugar do embarque forçado de milhões de africanos. O primeiro arco, inaugurado a 30 de novembro de 1995 por iniciativa da UNESCO, deu lugar a uma porta mais alta em dezembro de 2025. Chega-se a pé, depois das etapas da rota, e permanece-se ali, diante do mar."},{"slug":"temple-des-pythons","title":"O Temple des Pythons","short":"Temple des Pythons","category":"Fé","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"A entrada pintada do Temple des Pythons"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Santuário vodun do culto da serpente Dangbé, documentado desde o final do século XVII, onde vivem pitões sagradas. O templo fica diante da basílica da Imaculada Conceição: duas religiões que convivem lado a lado, em extremos da mesma praça. A visita respeita as regras do lugar."},{"slug":"basilique","title":"A basílica, diante do templo","short":"Basílica","category":"Fé","image":{"src":"/ouidah/visite-basilique.jpg","alt":"A basílica da Imaculada Conceição de Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"Principal lugar de culto católico de Ouidah, a basílica da Imaculada Conceição foi construída entre 1903 e 1909 e elevada a basílica menor em 1989. Ergue-se diante do Temple des Pythons: em Ouidah, passa-se de um ao outro atravessando uma praça."},{"slug":"musee-histoire","title":"O museu do forte português","short":"Museu de história","category":"História","image":{"src":"/ouidah/lieu-musee.jpg","alt":"O forte português de Ouidah, que acolhe o museu de história"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"O forte português São João Baptista de Ajudá, construído em 1721, acolhe desde 6 de setembro de 1967 o museu de história da cidade: o tráfico de escravos, os reinos, as ligações ao Brasil e às Américas, através de cerca de 700 peças. O local está em obras para acolher o futuro Museu Internacional da Memória e da Escravatura: informamo-lo antes da visita sobre o que está aberto."},{"slug":"foret-sacree-kpasse","title":"A floresta sagrada de Kpassè","short":"Floresta de Kpassè","category":"Natureza","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"Sob as grandes árvores da floresta sagrada de Kpassè, uma escultura vodun"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"Uma área florestal de 4 hectares no centro da cidade, ligada ao rei Kpassè. A floresta abriga divindades vodun e esculturas e recebe cerimónias, sobretudo durante os Vodun Days. Entramos por um portão pintado e caminhamos sob as grandes árvores."},{"slug":"vodun-days","title":"Os Vodun Days","short":"Vodun Days","category":"Festa","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"Um Egungun na arena de Ouidah durante os Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"No início de cada janeiro, Ouidah recebe o grande encontro anual das culturas vodun: cerimónias, danças rituais, exposições e encontros, respeitando as regras das comunidades. A grande cerimónia e os concertos decorrem na praia, e outros momentos na floresta de Kpassè. Não organizamos o evento: organizamos a sua estadia em torno dele."},{"slug":"memorial-zoungbodji","title":"O memorial de Zoungbodji","short":"Zoungbodji","category":"Memória","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"O memorial de Zoungbodji, na Route des Esclaves"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"O memorial da aldeia de Zoungbodji assinala o último local onde os cativos permaneciam antes do embarque, perto da vala comum onde eram lançados os mortos. É a etapa mais dolorosa da Route des Esclaves, a cerca de 2 km da praia e da Porte du Non-Retour. Paramos ali um momento antes de chegar ao mar."},{"slug":"marches","title":"Artesãos, mercados e gastronomia","short":"Mercados","category":"Sabores","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Vendedoras transportam os seus produtos numa rua de Ouidah"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"O mercado de Zobè, perto do forte português, e o do bairro de Kpassè marcam o ritmo da cidade. Os nossos guias levam-no até lá, bem como aos artesãos e aos bons locais para comer em Ouidah, dos pequenos maquis aos restaurantes. É a cidade de hoje, que vive entre duas visitas."},{"slug":"plage-et-lagune","title":"A praia e a lagoa","short":"Praia e lagoa","category":"Oceano","image":{"src":"/hero/hero-4-plage.jpg","alt":"A praia de Ouidah vista do céu, ondas do Atlântico e coqueiros"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"No fim da Route des Esclaves, uma longa praia pouco urbanizada recebe a grande cerimónia e os concertos dos Vodun Days. Atrás, a lagoa separa a cidade do oceano: um dos ecossistemas costeiros mais importantes do Benim, que se descobre de piroga a partir do pequeno embarcadouro. A route des Pêches, ladeada de coqueiros, passa entre ambos. Não se recomenda nadar com vento forte."}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.toursIntro','{"label":"Os nossos circuitos","all":{"label":"Todos os circuitos","href":"/#chemins"},"onRequest":"Preço sob consulta","durationPending":"Duração a confirmar","filtersLabel":"Filtrar circuitos"}'::jsonb,1,now()) on conflict(cle) do nothing;
