insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.collage','{"label":"Ouidah em imagens","title":["Uma cidade","para viver."],"images":[{"src":"/ouidah/collage-danse-atchinan-kpasse.jpg","alt":"Uma dançarina com colares de contas, numa cerimónia vodun na floresta sagrada de Kpassè","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-egungun-vodun-days.jpg","alt":"Um Egungun com traje bordado, entre o público dos Vodun Days em Ouidah","credit":"Romario Coffi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-marche-zobe.jpg","alt":"A entrada do mercado de Zobè, à sombra das grandes árvores","credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-danseur-kpasse.jpg","alt":"Um dançarino com pano azul, no chão, numa cerimónia vodun na floresta sagrada de Kpassè","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-fete-vodoun-2023.jpg","alt":"Dançarinos com trajes de festa e adereços vermelhos na cabeça, na festa do vodun de 10 de janeiro em Ouidah","credit":"Dieu229, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-zangbeto-meko.jpg","alt":"Dois Zangbéto com franjas coloridas durante os Vodun Days, na aldeia de Mèkô, município de Ouidah","credit":"Gildas Lissassi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-vodun-days-2024.jpg","alt":"Dançarinas com panos coloridos diante do público dos Vodun Days 2024 em Ouidah","credit":"Fermi12, Wikimedia Commons, CC BY-SA 4.0"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
