insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fiche-lieu.ficheLieu','{"retour":{"label":"Os lugares de Ouidah","href":"/#lieux"},"ajouter":"Adicionar à minha viagem","ajoute":"Adicionado à sua viagem","creer":{"label":"Criar a minha viagem","href":"/devis"},"voirCircuits":"Ver os circuitos","scene":{"paire":"Ontem e hoje","carte":"O lugar e os seus arredores"},"hier":"Ontem","aujourdhui":"Hoje","curseur":"Arraste para passar de ontem a hoje","enPratique":"Na prática","lignes":{"aller":"Como chegar","horaires":"Horários","tarif":"Preço","usages":"No local hoje","telephone":"Telefone","site":"Site"},"yAller":"Ir até lá","lireChapitre":"Ler o capítulo completo","toutHistoire":"Toda a história de Ouidah","histoire":"/ouidah/histoire","circuits":"Os circuitos que passam por aqui","autour":"Perto deste lugar","note":"Distâncias em linha reta; tempo a pé estimado a 4,5 km/h.","familles":{"voir":"A visitar","table":"Comer","dormir":"Dormir","culte":"Lugares de culto","nature":"Natureza e praias","marche":"Mercados e artesanato"},"nord":"N"}'::jsonb,1,now()) on conflict(cle) do nothing;
