insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.places','[{"n":"01","name":"Museu de história de Ouidah","kicker":"Forte português, 1721","text":"O forte português acolhe desde 6 de setembro de 1967 o museu de história da cidade: o tráfico de escravos, os reinos, as ligações ao Brasil e às Américas.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"O muro vermelho do forte português de Ouidah"},"next":"680 m a pé até ao Temple des Pythons"},{"n":"02","name":"Temple des Pythons","kicker":"Diante da basílica","text":"O templo da pitão Dangbé fica diante da basílica da Imaculada Conceição, construída entre 1903 e 1909: duas religiões que convivem lado a lado.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"A entrada pintada do Temple des Pythons"},"next":"2,5 km até ao memorial de Zoungbodji, pela place Chacha"},{"n":"03","name":"A Route des Esclaves","kicker":"Cerca de 4 km, seis etapas","text":"Da place Chacha à praia, o caminho que os cativos percorriam até aos navios: L''Arbre de l''Oubli, as Cases Zomaï, o Mémorial de Zoungbodji e L''Arbre du Retour.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"O memorial de Zoungbodji, na Route des Esclaves"},"next":"2 km até à praia e à Porte du Non-Retour"},{"n":"04","name":"Porte du Non-Retour","kicker":"Erguida em 1995, reconstruída em 2025","text":"Na praia, diante do Atlântico, assinala o lugar do embarque forçado de milhões de africanos.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"A Porte du Non-Retour iluminada à noite"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
