insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.conciergerie','[{"id":"navette","court":"Transporte","nom":"Transporte.","question":"Só ida ou ida e volta?","moment":"Ao aterrar","lead":"Desde o aeroporto internacional Cardinal Bernardin Gantin: cerca de 41 km por estrada.","leadReleve":null,"objet":"navette","photo":{"src":"/ouidah/aeroport-fresque.jpg","alt":"O mural « Bienvenue au Bénin » no aeroporto de Cotonou"},"credit":"Houss 2020, Wikimedia Commons, CC0","options":[{"label":"Ida","detail":"Aeroporto → Ouidah","releve":null,"phrase":"o transporte à chegada"},{"label":"Ida e volta","detail":"E no dia da partida","releve":null,"phrase":"o transporte de ida e volta"},{"label":"Não preciso","detail":null,"releve":null,"passe":true}]},{"id":"accueil","court":"Acolhimento","nom":"Acolhimento.","question":"Onde quer que o esperemos?","moment":"À sua chegada","lead":null,"leadReleve":null,"objet":"accueil","photo":{"src":"/ouidah/aeroport-facade.jpg","alt":"A fachada do aeroporto internacional de Cotonou"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"No aeroporto","detail":"Logo à saída","releve":null,"phrase":"o acolhimento no aeroporto"},{"label":"Em Ouidah","detail":"Na sua morada","releve":null,"phrase":"o acolhimento em Ouidah"},{"label":"Não preciso","detail":null,"releve":null,"passe":true}]},{"id":"telephone","court":"Telefone","nom":"Telefone.","question":"Um cartão SIM à chegada?","moment":"No primeiro dia","lead":null,"leadReleve":null,"objet":"telephone","photo":{"src":"/ouidah/eng-1-rue-basilique.jpg","alt":"Uma rua de Ouidah, em direção à basílica"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Cartão SIM","detail":"Telefonar, escrever","releve":null,"phrase":"um cartão SIM"},{"label":"Cartão SIM + dados","detail":"E internet móvel","releve":null,"phrase":"um cartão SIM com internet"},{"label":"Não preciso","detail":null,"releve":null,"passe":true}]},{"id":"hebergement","court":"Alojamento","nom":"Alojamento.","question":"Que tipo de alojamento procura?","moment":"Na primeira noite","lead":"{n} alojamentos identificados em Ouidah. Escolhemos consigo o que melhor se adequa a si.","leadReleve":"hebergement","objet":"hebergement","photo":{"src":"/ouidah/eng-3-case-plage.jpg","alt":"Uma casa redonda com telhado de palha, diante da praia"},"cadre":"50% 85%","credit":null,"options":[{"label":"Hotel","detail":null,"releve":"hebergement/Hôtel","phrase":"um hotel"},{"label":"Pousada","detail":null,"releve":"hebergement/Auberge","phrase":"uma pousada"},{"label":"Casa de hóspedes","detail":null,"releve":"hebergement/Maison d''hôtes","phrase":"uma casa de hóspedes"},{"label":"Acampamento","detail":null,"releve":"hebergement/Campement","phrase":"um acampamento"},{"label":"Já tenho reserva","detail":null,"releve":null,"passe":true}]},{"id":"tables","court":"Refeições","nom":"Refeições.","question":"Onde gosta de comer?","moment":"À mesa","lead":"{n} locais para comer identificados em Ouidah. Pode escolher várias opções.","leadReleve":"restauration","multi":true,"objet":"tables","photo":{"src":"/ouidah/eng-4-paillote.jpg","alt":"Uma cabana de colmo junto à praia de Ouidah"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Restaurantes","detail":null,"releve":"restauration/Restaurant","phrase":"restaurantes"},{"label":"Bares","detail":null,"releve":"restauration/Bar","phrase":"bares"},{"label":"Cafés","detail":null,"releve":"restauration/Café","phrase":"cafés"},{"label":"Não preciso","detail":null,"releve":null,"passe":true}]},{"id":"vehicule","court":"Veículo","nom":"Veículo.","question":"Com ou sem motorista?","moment":"Nos dias seguintes","lead":"Para chegar à praia pela route des Pêches, a Ganvié ou a Abomey, ao seu ritmo.","leadReleve":null,"objet":"vehicule","photo":{"src":"/ouidah/route-des-peches.jpg","alt":"A route des Pêches, ladeada de candeeiros, entre a lagoa e o oceano"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Com motorista","detail":null,"releve":null,"phrase":"um veículo com motorista"},{"label":"Sem motorista","detail":null,"releve":null,"phrase":"um veículo sem motorista"},{"label":"Não preciso","detail":null,"releve":null,"passe":true}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:histoire.histoireOuverture','{"titre":"De Glexwé a Ouidah","texte":"Em fon, a cidade chama-se Glexwé, frequentemente traduzido como « a casa dos campos ». Os europeus registaram de várias formas o nome do reino houéda de que dependia: Whydah em inglês, Juda em francês, Fida em neerlandês e Ajudá em português. Daí vem Ouidah. Já em 1681, um inglês datava uma carta « Agriffie in Whidaw »: Glexwé, no país houéda.","noms":["Glexwé","Whydah","Juda","Fida","Ajudá","Ouidah"]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:histoire.histoireChapitres','[{"id":"avant","repere":"Século XVII","court":"XVII","titre":"Antes dos fortes","ville":false,"temps":[["No século XVII, Glexwé é a cidade baixa do reino houéda, a norte de uma lagoa. O rei vive em Savi, cerca de dez quilómetros mais a norte. Durante muito tempo dominado pelo vizinho Allada, o pequeno reino liberta-se dessa influência na segunda metade do século.","Quando os europeus se instalam, no final do século, a maior parte dos negócios é tratada em Savi, perto do palácio. As escavações realizadas no local desde 1991 só encontraram tijolos holandeses e porcelana chinesa no recinto real, sinal de que o rei controlava o comércio."],["Segundo a tradição, os Houéda teriam vindo de Tado e o seu primeiro rei, Haholo, teria fundado Savi. A tradição atribui a Glexwé outro fundador, Kpassè. Conta que não teria morrido como um homem: teria transformado-se num iroko. Esta árvore é venerada na floresta sagrada de Kpassè, no bairro de Tové, onde se situa a aldeia anterior à chegada dos europeus.","Outro nome aparece nos relatos: Kpate, que teria recebido os primeiros europeus. Continua a ser objeto de culto em Ouidah."]],"pieces":[{"hier":{"src":"/histoire/plan-palais-savi-1747.webp","largeur":1173,"hauteur":1313,"legende":"O palácio do rei em Savi e as feitorias europeias, planta gravada em 1747"},"auj":null},{"hier":{"src":"/histoire/couronnement-roi-juida-1723.webp","largeur":1100,"hauteur":847,"legende":"A coroação do rei houéda, gravura do século XVIII"},"auj":null},{"hier":null,"auj":{"src":"/histoire/raison-foret-kpasse.webp","largeur":1200,"hauteur":674,"legende":"A floresta sagrada de Kpassè, no bairro de Tové"}}]},{"id":"forts","repere":"1671 – 1721","court":"1671","titre":"Os fortes","ville":true,"temps":[["Em 1671, a Companhia Francesa das Índias Ocidentais abre uma feitoria no reino houéda. É o primeiro estabelecimento europeu permanente. Os ingleses chegam na década de 1680. A feitoria francesa é destruída durante a guerra de 1692. Regressa em 1704 sob a forma de um forte, que o corsário Jean Doublet constrói em poucas semanas, com terra e colmo.","José de Torres, negociante vindo da Bahia, funda em 1721 o forte português São João Baptista de Ajudá."],["No século XVIII, os fortes inglês, francês e português ficam próximos uns dos outros, a vários quilómetros da praia. Os holandeses nunca tiveram um forte em Ouidah, nem os dinamarqueses.","Os ingleses abandonam o seu forte em 1812. O forte francês é demolido em 1908. No seu lugar estende-se uma esplanada onde, durante os Vodun Days, dançam os Zangbéto, guardiões da noite. Hoje, apenas o forte português continua de pé."]],"pieces":[{"hier":{"src":"/histoire/fort-anglais-1727.webp","largeur":1226,"hauteur":410,"legende":"O forte inglês, conhecido como William''s Fort, gravado em 1727"},"auj":null},{"hier":{"src":"/histoire/fort-francais-plan-1747.webp","largeur":1330,"hauteur":1400,"legende":"Planta do forte francês, gravada em 1747"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-gravure-1886.webp","largeur":960,"hauteur":628,"legende":"O forte português, gravura de 1886"},"auj":{"src":"/histoire/eng-2-musee.webp","largeur":1200,"hauteur":900,"legende":"A entrada do forte português, hoje museu de história"}}]},{"id":"dahomey","repere":"1727","court":"1727","titre":"O Daomé","ville":false,"temps":[["Em 1724, Agaja, rei do Daomé, conquista Allada. No início de março de 1727, o seu exército toma Savi e destrói-a, incluindo as feitorias europeias aí instaladas. Hufon, último rei houéda, foge para oeste com parte do seu povo, primeiro para uma ilha perto de Grand-Popo. Outros Houéda estabelecem-se em Porto-Novo e Badagry."],["Glexwé muda de senhor e de função. O comércio com os europeus concentra-se ali e a cidade torna-se o principal centro do tráfico de escravos do Daomé. Um governador instala-se em 1733. Os europeus chamam-lhe vice-rei.","Mais tarde, terá o título fon de yovogan, « chefe dos Brancos », já usado pelo reino houéda. O cargo é sempre ocupado por um homem do país. Os fortes passam para a autoridade do Daomé: em julho de 1743, o seu exército ataca o forte português."]],"pieces":[{"hier":{"src":"/histoire/comptoirs-savi-1747.webp","largeur":1400,"hauteur":948,"legende":"As feitorias europeias de Savi, gravadas a partir de levantamentos de 1725, dois anos antes da queda da cidade"},"auj":null}]},{"id":"chacha","repere":"1800 – 1849","court":"1800","titre":"O Chacha","ville":true,"temps":[["Francisco Félix de Souza, traficante de escravos vindo do Brasil, chega pela primeira vez à costa no início da década de 1790 e estabelece-se ali por volta de 1800. Começa como escrivão-contabilista no forte português, assume interinamente o comando por volta de 1806 e depois passa a negociar por conta própria.","Em conflito com o rei Adandozan, é preso em Abomey e foge para Petit-Popo. A partir daí, apoia o golpe de Estado que leva Ghézo ao trono do Daomé, provavelmente em 1818. O novo rei nomeia-o seu agente comercial em Ouidah, para onde regressa por volta de 1820."],["Recebe a alcunha de Chacha. A origem da palavra continua desconhecida: uma tradição associa-a à expressão portuguesa « já, já », « imediatamente », que usaria com frequência. Funda no sudoeste da cidade um bairro que mais tarde se chamará Brasil, Blézin em fon. Ali vivem a sua família, os seus escravos e os seus clientes.","Um romance chamou-lhe « vice-rei de Ouidah ». Nunca o foi: o cargo de yovogan pertencia a um homem do Daomé."],["Morre em Ouidah a 8 de maio de 1849, muito endividado: devia 80 000 dólares ao rei Ghézo. O rei escolhe o seu filho mais velho, Isidoro, para lhe suceder. A alcunha torna-se então um título hereditário, usado desde então pelo chefe da família de Souza.","O seu túmulo fica na propriedade familiar de Singbomey, atrás da place Chacha. Desde 1999, uma placa atribui este nome à praça. Os textos oficiais recentes também lhe chamam place aux Enchères."]],"pieces":[{"hier":{"src":"/histoire/portrait-de-souza.webp","largeur":1164,"hauteur":1400,"legende":"Retrato atribuído a Francisco Félix de Souza, pintado antes de 1849"},"auj":null},{"hier":{"src":"/histoire/place-chacha-stele-2017.webp","largeur":1400,"hauteur":933,"legende":"A estela « Place Chacha », em 2017"},"auj":null,"temps":2}]},{"id":"agudas","repere":"1835 – 1922","court":"1835","titre":"Os Agudas","ville":true,"temps":[["A partir de 1835, depois da revolta dos Malês na Bahia, africanos libertos são expulsos do Brasil ou pressionados a partir. Muitos são iorubás. Em Ouidah, instalam-se sobretudo no bairro Maro, a oeste do bairro Brasil, sob a proteção de De Souza.","Com as famílias de negociantes portugueses e brasileiros e as famílias africanas a elas ligadas, formam os Agudas. No século XIX, a palavra designa os portugueses, incluindo os brasileiros; poderá derivar de Ajudá. Alguns Agudas, como a família de Souza, viviam do tráfico de escravos."],["Os seus descendentes têm apelidos como de Souza, da Silva, d''Almeida, Martins, Olympio ou Paraïso. No Benim, celebram Nosso Senhor do Bonfim em janeiro e dançam a bourian, uma mascarada vinda da Bahia."],["Ao longo de toda a costa, as suas casas de vários pisos, com galerias, balaustradas, persianas e frontões ornamentados, recordam os sobrados de Salvador. No início do século XX, este estilo torna-se sinal de sucesso. Personalidades locais que não são agudas também o adotam.","A villa Ajavon é um exemplo. No frontão lê-se « VILLA AJAVON 1922 ». Foi construída para Ajavon, um rico negociante vindo do vizinho Togo. Desde 11 de novembro de 2013, acolhe o museu de arte contemporânea da Fondation Zinsou."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/maison-du-bresil.webp","largeur":1120,"hauteur":1400,"legende":"A Maison du Brésil, em 2024"},"temps":2},{"hier":null,"auj":{"src":"/histoire/villa-ajavon-1922.webp","largeur":1400,"hauteur":1050,"legende":"A villa Ajavon, de 1922, hoje museu da Fondation Zinsou"},"temps":2}]},{"id":"mer","repere":"Final do século XVII – 1863","court":"1863","titre":"Até ao mar","ville":false,"temps":[["Segundo as estimativas dos historiadores, mais de um milhão de pessoas foram deportadas de Ouidah entre o final do século XVII e a década de 1860."],["A cidade fica a cerca de quatro quilómetros do mar, atrás de uma lagoa. Os cativos eram conduzidos a pé até à praia. Pirogas levavam-nos através da rebentação que fecha a costa, até aos navios ancorados ao largo."],["Partiam sobretudo para o Brasil, em particular a Bahia, e para as Antilhas, especialmente Saint-Domingue, o atual Haiti. No final do tráfico, partiam para Cuba.","Na década de 1840, o comércio de óleo de palma cresce, mas o tráfico de escravos continua. Em janeiro de 1852, sob bloqueio britânico, o rei Ghézo assina um tratado que o abole. Não terá efeitos duradouros."],["Em maio de 1860, a escuna Clotilda parte de Ouidah com 110 cativos a bordo. Em julho, chega em segredo perto de Mobile, no Alabama. É o último navio negreiro conhecido a ter chegado aos Estados Unidos.","A 10 de outubro de 1863, em Godomey, o vapor Cicerón embarca cerca de 960 pessoas para Cuba, conduzidas a pé desde Ouidah. É o último embarque transatlântico conhecido ligado a Ouidah."]],"chiffre":{"valeur":"Mais de um milhão","legende":"de pessoas deportadas de Ouidah entre o final do século XVII e a década de 1860, segundo as estimativas dos historiadores"},"legende":[{"lettre":"A","nom":"Tendas dos europeus"},{"lettre":"B","nom":"A costa"},{"lettre":"C","nom":"Navios ao largo"}],"pieces":[{"hier":null,"auj":{"src":"/histoire/bienvenue-3-plage-cocotiers.webp","largeur":1200,"hauteur":795,"legende":"A praia de Ouidah"}}]},{"id":"basilique","repere":"1903 – 2011","court":"1903","titre":"A pitão e a basílica","ville":true,"temps":[["Dangbé, a pitão real, é a divindade do reino houéda. Manifesta-se em serpentes vivas, guardadas nos seus santuários. Por volta de 1700, um comerciante holandês regista que as serpentes são as principais divindades do reino."],["Em Ouidah, o seu templo fica diante da basílica da Imaculada Conceição. A igreja ocupa o terreno da antiga residência do yovogan, cedido em 1901 à missão católica, que chegara a Ouidah em 1861.","A primeira pedra é lançada a 30 de agosto de 1903. Para a construir, todos os bairros da cidade transportam areia da praia, incluindo os adeptos do vodun. A catedral é consagrada a 9 de maio de 1909, perante cerca de 4 000 pessoas."],["Torna-se basílica em 1989. A 19 de novembro de 2011, Bento XVI assina ali Africae munus, a sua exortação sobre a Igreja em África."]],"pieces":[{"hier":{"src":"/histoire/procession-serpent-1725.webp","largeur":1400,"hauteur":674,"legende":"Procissão à grande serpente para a coroação do rei, gravura publicada em 1730"},"auj":null},{"hier":{"src":"/histoire/temple-serpent-1930.webp","largeur":1400,"hauteur":666,"legende":"O templo da serpente, por volta de 1930"},"auj":{"src":"/histoire/bienvenue-2-temple-pythons.webp","largeur":1200,"hauteur":900,"legende":"A entrada do Temple des Pythons"}},{"hier":{"src":"/histoire/basilique-1930.webp","largeur":1003,"hauteur":1400,"legende":"A catedral, por volta de 1930"},"auj":{"src":"/histoire/visite-basilique.webp","largeur":800,"hauteur":1200,"legende":"A basílica da Imaculada Conceição"}}]},{"id":"fort","repere":"1892 – 1990","court":"1961","titre":"O forte que arde","ville":true,"temps":[["Em 1892, Ouidah passa para a ocupação francesa. Os franceses fixam a capital em Porto-Novo e o comércio desloca-se para o cais de Cotonou. A cidade declina gradualmente. O forte português, porém, continua nas mãos de Lisboa."],["O Daomé torna-se independente a 1 de agosto de 1960. Exatamente um ano depois, toma posse do forte, que permanecera um enclave português. Antes de partir, os dois últimos funcionários portugueses incendeiam-no.","Em 1967, o forte acolhe o Museu de História de Ouidah. Em 1975, o Daomé passa a chamar-se Benim. Restaurado com o apoio da fundação portuguesa Gulbenkian, o forte reabre em agosto de 1990. A sua reabilitação, iniciada em 2020, deverá transformá-lo no futuro Museu Internacional da Memória e da Escravatura."]],"pieces":[{"hier":{"src":"/histoire/rue-1892.webp","largeur":1216,"hauteur":665,"legende":"Uma rua de Ouidah, gravura de 1892"},"auj":null},{"hier":{"src":"/histoire/marche-1930.webp","largeur":1400,"hauteur":1290,"legende":"O mercado de Ouidah, por volta de 1930"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-entree-1917.webp","largeur":600,"hauteur":440,"legende":"A entrada do forte português, em 1917"},"auj":{"src":"/histoire/lieu-musee.webp","largeur":1200,"hauteur":675,"legende":"Os muros do forte português"}}]},{"id":"souvenir","repere":"1993 – 1998","court":"1993","titre":"Recordar","ville":true,"temps":[["De 8 a 18 de fevereiro de 1993, a cidade recebe o festival Ouidah 92, dedicado às artes e culturas vodun. Previsto para 1992, manteve esse nome. Foi uma iniciativa do presidente Nicéphore Soglo. Sacerdotes e visitantes chegam, entre outros países, do Brasil, Haiti e Trindade e Tobago.","Para a ocasião, a floresta de Kpassè recebe estátuas de divindades vodun e abre-se a visitantes não iniciados."],["O percurso da Route des Esclaves nasce durante este festival. Seis etapas, marcadas por esculturas na sua maioria de Cyprien Tokoudagba, levam da place Chacha à praia, ao longo de cerca de três a quatro quilómetros. Em setembro de 1994, a UNESCO lança em Ouidah o programa « La Route de l''esclave », proposto pelo Haiti e por países africanos. A 30 de novembro de 1995, a Porte du Non-Retour é inaugurada na praia, no fim do caminho.","Em 1998 nasce uma caminhada do arrependimento, por iniciativa do sociólogo Honorat Aguessy. No terceiro domingo de janeiro, segue da place Chacha ao memorial Zomachi, para pedir perdão aos descendentes dos deportados."]],"pieces":[{"hier":{"src":"/histoire/plaque-ouidah92.webp","largeur":933,"hauteur":1400,"legende":"A placa colocada para Ouidah 92 na place des Enchères, em 2017"},"auj":null},{"hier":{"src":"/histoire/memorial-zomachi-2017.webp","largeur":1400,"hauteur":933,"legende":"O memorial Zomachi, em 2017"},"auj":null}]},{"id":"fete","repere":"1996 – 2026","court":"2024","titre":"A festa de janeiro","ville":true,"temps":[["Em fon, vodun significa « divindade, espírito ». A palavra deu origem a vodou, no Haiti. A 10 de janeiro de 1996, o governo de Nicéphore Soglo torna este dia um feriado remunerado, em homenagem ao vodun e às religiões tradicionais. Uma lei de agosto de 1997 transforma-o numa festa anual.","Durante anos, a cerimónia oficial de 10 de janeiro realiza-se na praia de Ouidah, perto da Porte du Non-Retour."],["Em outubro de 2023, o governo cria os Vodun Days, para abrir a festa a um público de todo o mundo. A primeira edição realiza-se em Ouidah a 9 e 10 de janeiro de 2024, em cinco locais: place Maro, esplanada do Fort français, praça do Temple des Pythons, um convento temporário de Mami e floresta de Kpassè. As duas grandes noites reúnem perto de 100 000 pessoas.","Desde a lei de 2 de setembro de 2024, a festa realiza-se na segunda sexta-feira de janeiro. As edições de 2025 e 2026 duram três dias."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-vodun-days-2024.webp","largeur":1200,"hauteur":675,"legende":"Dançarinas diante do público dos Vodun Days 2024, em Ouidah"},"temps":1},{"hier":null,"auj":{"src":"/histoire/collage-zangbeto-meko.webp","largeur":1200,"hauteur":801,"legende":"Zangbéto nos Vodun Days 2026, na aldeia de Mèkô, município de Ouidah"},"temps":1}]},{"id":"route","repere":"1993 – 2025","court":"2025","titre":"A Rota, etapa a etapa","ville":true,"temps":[["Os relatos contados em cada etapa pertencem à tradição. O percurso dos cativos até ao mar, por sua vez, é um facto estabelecido.","A Rota parte da place Chacha, também chamada place aux Enchères. Uma placa colocada em 1993 afirma que os cativos eram ali vendidos em leilão, sob uma grande árvore. Os testemunhos da época descrevem outra realidade: o preço dos cativos era fixado pelo rei, e as vendas passavam pelos seus agentes e pelas casas dos negociantes, como a dos de Souza, junto à praça. Requalificada recentemente, a praça é hoje uma esplanada pavimentada."],["Segue-se L''Arbre de l''Oubli. Segundo a tradição contada aos visitantes, os homens deviam dar nove voltas à árvore e as mulheres sete, para esquecerem o seu país. Este relato não aparece em nenhum texto anterior à década de 1990. Os textos antigos chamam ao lugar Arbre des capitaines: os chefes de Ouidah recebiam ali os europeus e davam três voltas à árvore. A árvore original desapareceu."],["A case Zomaï tem um nome que significaria « onde o fogo, ou a luz, não entra ». A tradição situa ali cativos encerrados na escuridão. Textos mais antigos associam este nome às reservas de pólvora de De Souza."],["Em Zoungbodji ergue-se um memorial. Segundo a tradição, os cativos que morriam antes da partida teriam sido enterrados neste local."],["Mais adiante, L''Arbre du Retour. A tradição conta que os cativos davam três voltas à árvore para que a sua alma regressasse a África depois da morte. Nenhuma fonte da época menciona este rito. A estátua é de Cyprien Tokoudagba."],["O caminho termina na praia, na Porte du Non-Retour. É um monumento: os cativos não partiam de um ponto preciso, mas da praia, em pirogas. O arco de 1995 foi substituído. Apresentada em dezembro de 2025, a nova Porta tem mais de dezasseis metros de altura e mais de duzentas esculturas.","Desde 2021, a praça, o forte português, os locais de Zoungbodji e a praia da Porta figuram na lista indicativa do Benim junto da UNESCO, etapa prévia a uma possível inscrição no património mundial."]],"etapes":["Place Chacha","Arbre de l''oubli","Case Zomaï","Zoungbodji","Arbre du retour","Porte du Non-Retour"],"pieces":[{"hier":{"src":"/histoire/place-chacha-2017.webp","largeur":1400,"hauteur":933,"legende":"A praça em 2017, com a sua grande árvore e a estela « Place Chacha »"},"auj":{"src":"/histoire/place-chacha-2025.webp","largeur":1400,"hauteur":787,"legende":"A praça requalificada, em janeiro de 2025"}},{"hier":{"src":"/histoire/arbre-oubli-2015.webp","largeur":768,"hauteur":1024,"legende":"A escultura de L''Arbre de l''Oubli, instalada para Ouidah 92, em 2015"},"auj":null},{"hier":null,"auj":{"src":"/histoire/case-zomai-2019.webp","largeur":809,"hauteur":1400,"legende":"A estela da case Zomaï, inaugurada em fevereiro de 1993 (fotografia de 2019)"}},{"hier":null,"auj":{"src":"/histoire/visite-zoungbodji.webp","largeur":1200,"hauteur":1200,"legende":"O memorial de Zoungbodji"}},{"hier":null,"auj":{"src":"/histoire/raison-arbre-du-retour.webp","largeur":800,"hauteur":1200,"legende":"L''Arbre du Retour e a sua estátua (fotografia de 2017)"}},{"hier":{"src":"/histoire/porte-1995.webp","largeur":1280,"hauteur":866,"legende":"O arco de 1995, fotografado em 2019"},"auj":{"src":"/histoire/eng-5-porte-jour.webp","largeur":675,"hauteur":1200,"legende":"A nova Porte du Non-Retour, apresentada em dezembro de 2025"}}]},{"id":"aujourdhui","repere":"Hoje","court":"2027","titre":"Regressar","ville":true,"temps":[["Desde a lei de 2 de setembro de 2024, um afrodescendente com um antepassado deportado durante o tráfico de escravos pode pedir a nacionalidade beninense. A prova pode ser feita através do registo civil, documentos oficiais, testemunhos ou um teste de ADN, que não é obrigatório. A nacionalidade é concedida por decreto, mediante condições, e transmite-se aos descendentes."],["Em 2027, os Vodun Days realizam-se de 2 a 9 de janeiro. A festa das religiões tradicionais é na sexta-feira, dia 8."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-egungun-vodun-days.webp","largeur":800,"hauteur":1200,"legende":"Um Egungun durante os Vodun Days"},"temps":1},{"hier":null,"auj":{"src":"/histoire/visite-cite-historique.webp","largeur":1200,"hauteur":675,"legende":"A entrada da cidade histórica de Ouidah"},"temps":0}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:histoire.histoireFinale','{"titre":"A Route des Esclaves percorre-se a pé, da place Chacha até à praia.","texte":"Seis etapas, ao longo de cerca de três a quatro quilómetros."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:histoire.histoirePage','{"metaTitre":"A história de Ouidah — Ouidah Heritage Tour","metaDescription":"De Glexwé a Ouidah: os fortes, o Daomé, o Chacha e os Agudas, o tráfico até ao mar, a basílica, a Route des Esclaves etapa a etapa, a nova Porte du Non-Retour e os Vodun Days.","defiler":"Desloque a página","hier":"Ontem","avant":"Antes","aujourdhui":"Hoje","chapitres":"Capítulos","cartes":{"royaume":{"src":"/histoire/carte-lune.webp","largeur":3146,"hauteur":2421},"ville":{"src":"/histoire/ville-1926-lune.webp","largeur":2400,"hauteur":2118}},"photoFin":"/histoire/fin-porte-nuit.webp","son":{"sources":["/son/histoire-bohicon.webm","/son/histoire-bohicon.m4a"],"volume":0.3,"fondu":4},"carteRoyaume":"Mapa do reino de Whidah, gravado no século XVIII","carteVille":"Planta de Ouidah em 1926","appel":{"principal":{"label":"Percorrer a Route des Esclaves a pé","href":"/devis?circuit=route-des-esclaves"},"secondaire":{"label":"Compor a minha viagem","href":"/devis"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.creditsPage','{"intro":"Algumas fotografias do site e o som de fundo da página História são publicados sob licença livre. Agradecemos aos seus autores.","modifiee":"adaptada","carteSource":"© colaboradores do OpenStreetMap"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:credits-photos.creditsPhotos','[{"fichier":"/hero/hero-2-porte.jpg","oeuvre":"Nova Porte du Non-Retour, vista lateral","auteur":"MIA20102","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Nouvelle_Porte_du_Non-Retour_de_Ouidah_-_Vue_lat%C3%A9rale.jpg","modifiee":true},{"fichier":"/ouidah/aeroport-facade.jpg","oeuvre":"Fachada do aeroporto de Cotonou","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Fa%C3%A7ade_principale_de_l%27a%C3%A9roport_international_de_Cotonou.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-2-temple-pythons.jpg","oeuvre":"Entrada do Temple des Pythons","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_Temple_des_Pythons_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-3-plage-cocotiers.jpg","oeuvre":"Praia de Ouidah (Benim, 2013)","auteur":"jbdodane","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Ouidah_(Benin,_2013).jpg","modifiee":true},{"fichier":"/ouidah/collage-danse-atchinan-kpasse.jpg","oeuvre":"Vodoun Atchinan, floresta sagrada de Kpassè (15)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._15.jpg","modifiee":true},{"fichier":"/ouidah/collage-danseur-kpasse.jpg","oeuvre":"Vodoun Atchinan, floresta sagrada de Kpassè (01)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._01.jpg","modifiee":true},{"fichier":"/ouidah/collage-egungun-vodun-days.jpg","oeuvre":"Egungun, Vodun Days","auteur":"Romario Coffi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Egungun_Allada_au_B%C3%A9nin_06.png","modifiee":true},{"fichier":"/ouidah/collage-fete-vodoun-2023.jpg","oeuvre":"Festa do vodoun, 10 de janeiro de 2023","auteur":"Dieu229","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:10_Janvier_2023,_F%C3%AAte_de_vodoun_%C3%A0_Ouidah_33.jpg","modifiee":true},{"fichier":"/ouidah/collage-marche-zobe.jpg","oeuvre":"Mercado de Zobè","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-March%C3%A9_Zob%C3%A9.jpg","modifiee":true},{"fichier":"/ouidah/collage-vodun-days-2024.jpg","oeuvre":"Vodun Days 2024 em Ouidah","auteur":"Fermi12","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_Edition_2024_%C3%A0_Ouidah_au_B%C3%A9nin_18.jpg","modifiee":true},{"fichier":"/ouidah/collage-zangbeto-meko.jpg","oeuvre":"Zangbéto, Vodun Days 2026, Mèkô","auteur":"Gildas Lissassi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:VODUN_DAYS_2026_au_village_M%C3%A8k%C3%B4,_arrondissement_de_Dj%C3%AAgbadji_et_Commune_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-1-rue-basilique.jpg","oeuvre":"Praça do vodun e basílica","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_Vodun_place_and_Cathedral.jpg","modifiee":true},{"fichier":"/ouidah/eng-2-musee.jpg","oeuvre":"Museu de história de Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_mus%C3%A9e_d%E2%80%99histoire_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-4-paillote.jpg","oeuvre":"Habitação na praia de Ouidah","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Habitation_sur_la_plage_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-7-vendeuses.jpg","oeuvre":"Vendedoras, praia de Ouidah","auteur":"GARNI RAFIK","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vendeuses-_plage_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/raison-arbre-du-retour.jpg","oeuvre":"Arbre du Retour","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Arbre_du_Retour_(1).jpg","modifiee":true},{"fichier":"/ouidah/raison-foret-kpasse.jpg","oeuvre":"Floresta sagrada de Kpassè","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Sacred_Forest_Ouidah_Benin_Jan_2018.jpg","modifiee":true},{"fichier":"/ouidah/raison-vodun-days.jpg","oeuvre":"Vodun Days, arena de Ouidah","auteur":"Eureka9090","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_-_Ar%C3%A8ne_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/route-des-peches.jpg","oeuvre":"Route des Pêches","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Route_des_p%C3%AAches_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/ouidah/visite-basilique.jpg","oeuvre":"Basílica da Imaculada Conceição","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Basilique_de_l%27Immacul%C3%A9e_Conception.jpg","modifiee":true},{"fichier":"/ouidah/visite-zoungbodji.jpg","oeuvre":"Mémorial de Zoungbodji","auteur":"Gbehlon","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_m%C3%A9morial_de_Zungboji.jpg","modifiee":true},{"fichier":"/histoire/place-chacha-stele-2017.webp","oeuvre":"Place Chacha, estela e portão (8)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(8).jpg","modifiee":true},{"fichier":"/histoire/maison-du-bresil.webp","oeuvre":"Maison du Brésil, Ouidah (Ouidah 05)","auteur":"Satovgrad","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_05.jpg","modifiee":true},{"fichier":"/histoire/villa-ajavon-1922.webp","oeuvre":"Villa Ajavon","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_Villa_Ajavon_%C3%A0_Ouidah_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/histoire/plaque-ouidah92.webp","oeuvre":"Place Chacha, placa Ouidah 92 (5)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(5).jpg","modifiee":true},{"fichier":"/histoire/memorial-zomachi-2017.webp","oeuvre":"Memorial Zomachi (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Memorial_Zomachi_(1).jpg","modifiee":true},{"fichier":"/histoire/place-chacha-2017.webp","oeuvre":"Place Chacha, figueira e estátua (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(1).jpg","modifiee":true},{"fichier":"/histoire/arbre-oubli-2015.webp","oeuvre":"Árvore do Esquecimento","auteur":"David Stanley","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Tree_of_Forgetting_(21136368019).jpg","modifiee":false},{"fichier":"/histoire/case-zomai-2019.webp","oeuvre":"A cela de Zomaï, Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_cage_de_Zoma%C3%AF_Ouidah.jpg","modifiee":true},{"fichier":"/histoire/porte-1995.webp","oeuvre":"Porta do Não Retorno","auteur":"Francisco Anzola","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Door_of_no_return.jpg","modifiee":true},{"fichier":"/son/histoire-bohicon.webm","oeuvre":"Canto, casa subterrânea de Agongointo, Bohicon (som de fundo da página História)","auteur":"algoryn, radio aporee ::: maps","licence":"Domínio público (PDM 1.0)","licenceUrl":"https://creativecommons.org/publicdomain/mark/1.0/","source":"https://archive.org/details/aporee_34624_39796","modifiee":true},{"fichier":"cartes","oeuvre":"Mapas de base","auteur":"© les contributeurs d''OpenStreetMap, OpenMapTiles, OpenFreeMap","licence":"ODbL","licenceUrl":"https://opendatacommons.org/licenses/odbl/","source":"https://www.openstreetmap.org/copyright","modifiee":false}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:legal','{"_note":"Pages légales (mentions, confidentialité et cookies, CGV), en français, éditables depuis l''admin (à venir) : chaque information de la société a une valeur et un interrupteur « visible » ; une information masquée ou vide disparaît de toutes les pages (ligne de fiche, phrase qui la cite). Sources : RCCM, carte professionnelle APIEx, annonce légale (11-12/06/2026) ; Code du numérique du Bénin (loi 2017-20), art. 328 : capital social et adresse du siège sont des mentions obligatoires ; décret 2023-493 art. 38 : référence de la licence obligatoire. Références : Assets OHT/Pages-legales/recherches/REFERENCES.md. Blocs : p (texte, liens [texte](adresse), {clé} de la société), liste, fiche, tableau, composant.","miseAJour":"6 de novembro de 2026","societe":{"denomination":{"libelle":"Denominação","valeur":"OUIDAH HERITAGE TOUR","visible":true},"forme":{"libelle":"Forma jurídica","valeur":"Sociedade por ações simplificada (SAS)","visible":true},"capital":{"libelle":"Capital social","valeur":"1 000 000 FCFA","visible":true},"siege":{"libelle":"Sede social","valeur":"Îlot 1158, parcelle F, maison Sikiratou Moustapha Lawani, quartier Haie Vive-Cocotiers, 12e arrondissement, Cotonou (Littoral), Bénin","visible":true},"quartier":{"libelle":"Bairro da sede (público)","valeur":"Haie Vive-Cocotiers","visible":true},"ville":{"libelle":"Cidade da sede (público)","valeur":"Cotonou","visible":true},"agence":{"libelle":"Agência em Ouidah","valeur":null,"visible":true},"rccm":{"libelle":"RCCM","valeur":"RB/COT/26 B 43278 de 11 de junho de 2026, Tribunal de Comércio de Cotonou","visible":true},"ifu":{"libelle":"IFU","valeur":"3202629321372","visible":true},"carte":{"libelle":"Carteira profissional","valeur":"Carteira profissional de comerciante n.º 1310CPC26, emitida pela APIEx, válida até 12 de junho de 2028","visible":true},"licence":{"libelle":"Licença de agência de viagens","valeur":null,"visible":true},"activite":{"libelle":"Atividade","valeur":"Turismo e eventos, atividades artísticas e culturais","visible":true},"presidente":{"libelle":"Direção da publicação","valeur":"Sra. Nathalie Rosine RIFFERT, Presidente","visible":true},"telephones":{"libelle":"Telefone","valeur":["+229 01 98 87 36 36","+229 01 94 35 50 50"],"visible":true},"email":{"libelle":"E-mail","valeur":"contact@ouidahheritagetour.bj","visible":true}},"pages":{"/mentions-legales":{"titre":"Avisos legais","metaTitre":"Avisos legais — Ouidah Heritage Tour","metaDescription":"Editor, alojamento, propriedade dos conteúdos, créditos fotográficos e acessibilidade do site Ouidah Heritage Tour.","intro":"Quem edita este site, quem o aloja e a quem escrever.","sections":[{"id":"editeur","titre":"O editor","blocs":[{"fiche":["denomination","forme","capital","siege","agence","rccm","ifu","carte","licence","activite","telephones","email"]}]},{"id":"publication","titre":"Direção da publicação","blocs":[{"p":"{presidente}."}]},{"id":"hebergement","titre":"Alojamento","blocs":[{"fiche":[["Site","Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, Estados Unidos · [vercel.com](https://vercel.com)"],["Base de dados","Supabase Pte. Ltd., 65 Chulia Street #38-02/03, OCBC Centre, Singapura 049513 · [supabase.com](https://supabase.com)"]]}]},{"id":"propriete","titre":"Textos, fotografias e logótipo","blocs":[{"p":"O logótipo, os textos, as ilustrações e a paginação deste site pertencem à OUIDAH HERITAGE TOUR ou aos seus autores. Para os reproduzir, mesmo parcialmente, peça-nos primeiro autorização escrita através de {email}."},{"p":"As fotografias publicadas sob licença livre são utilizadas segundo as respetivas condições e os autores são identificados nos créditos abaixo. Os mapas de base são © colaboradores do OpenStreetMap, sob licença ODbL."}]},{"id":"credits","titre":"Créditos fotográficos","blocs":[{"composant":"credits"}]},{"id":"accessibilite","titre":"Acessibilidade","blocs":[{"p":"Queremos que todos possam ler este site e preparar a sua viagem. Pode navegar com o teclado, as imagens têm descrições, os textos têm contraste e as animações são reduzidas quando o seu dispositivo pede menos movimento."},{"p":"Encontrou um texto difícil de ler ou um botão que não responde? Escreva para {email}, indicando a página: responderemos e corrigiremos o problema."}]},{"id":"liens","titre":"Links para outros sites","blocs":[{"p":"O site remete por vezes para sites oficiais ou de parceiros, por exemplo para o visto ou um evento. O respetivo conteúdo é da responsabilidade dos seus editores."}]},{"id":"droit","titre":"Direito aplicável","blocs":[{"p":"Este site está sujeito à legislação do Benim. Para uma reserva ou encomenda, as [condições gerais de venda](/conditions-generales-de-vente#litiges) explicam como resolver um desacordo."}]}]},"/politique-de-confidentialite":{"titre":"Privacidade e cookies","metaTitre":"Privacidade e cookies — Ouidah Heritage Tour","metaDescription":"Os dados recolhidos pela Ouidah Heritage Tour, porquê, durante quanto tempo, o que o site guarda no seu navegador e como exercer os seus direitos.","intro":"O que recolhemos, porquê, durante quanto tempo e como exercer os seus direitos. Não vendemos dados e o site não apresenta publicidade. As visitas só são contadas com o seu consentimento.","sections":[{"id":"responsable","titre":"Quem é responsável pelos seus dados","blocs":[{"p":"{denomination}, {forme}, com sede social em {siege}."},{"p":"Para qualquer questão sobre os seus dados, escreva para {email} com o assunto « Dados pessoais », ou por correio para a sede."}]},{"id":"donnees","titre":"O que recolhemos e porquê","blocs":[{"p":"Apenas o que nos confia num formulário e apenas para a finalidade indicada."},{"tableau":{"colonnes":["Quando","Dados","Porquê","Durante quanto tempo"],"lignes":[["Pede um orçamento (« Criar a minha viagem »)","Nome, e-mail, WhatsApp se o indicar, país, língua do guia, a sua viagem (datas, lugares, serviços escolhidos) e a sua mensagem","Responder ao seu pedido e preparar o orçamento que solicitou","3 anos após o nosso último contacto, se não houver uma reserva"],["Guarda o seu pedido para o retomar mais tarde","A sua viagem e as suas respostas, sem os seus contactos","Enviar-lhe o link para retomar o pedido e recuperar as suas informações","O link é válido por 30 dias; um rascunho nunca enviado é apagado 90 dias após a sua criação"],["Reserva um bilhete ou uma estadia","Nome, e-mail, telefone, país, língua, modalidade, número de lugares, valor, meio de pagamento e referência da transação","Emitir a sua reserva, bilhete e fatura","10 anos, prazo de conservação dos documentos contabilísticos"],["Faz uma encomenda na loja","Nome próprio, apelido, e-mail, telefone, país, morada de entrega se escolher entrega, artigos e opções, a sua mensagem","Confirmar, preparar e entregar a sua encomenda","10 anos, prazo de conservação dos documentos contabilísticos"],["Subscreve a newsletter de Ouidah","E-mail, língua, temas escolhidos e data do seu consentimento","Enviar-lhe a newsletter, com o seu consentimento","Até cancelar a subscrição, o que pode fazer a qualquer momento em cada newsletter ou por e-mail"],["Envia um formulário","Uma impressão criptográfica do seu endereço IP, nunca o endereço em si","Limitar envios automatizados e proteger o serviço","O mesmo prazo do pedido a que está associada"]]}},{"p":"Os formulários de marcação e de candidatura de parceiros recolhem os seus contactos e as informações que introduz para que a nossa equipa organize a marcação ou analise a candidatura. Os e-mails recebidos podem ser associados ao seu pedido para acompanhar o seu tratamento."}]},{"id":"paiement","titre":"Pagamento","blocs":[{"p":"Paga através do serviço de pagamento que escolher entre os disponíveis: Kkiapay, FedaPay, Stripe, Flutterwave ou Paystack. Não vemos nem guardamos os números do seu cartão ou códigos Mobile Money: recebemos o valor, o estado do pagamento e a sua referência."}]},{"id":"destinataires","titre":"Quem recebe os seus dados","blocs":[{"liste":["A equipa da Ouidah Heritage Tour que prepara a sua viagem ou encomenda.","Os nossos prestadores técnicos, apenas para este serviço: Vercel (alojamento do site e, se aceitar, medição de audiência, Estados Unidos), Supabase (base de dados), o nosso serviço de correio {email}, alojado pela AfriRegister (envio de e-mails de confirmação, orçamentos e bilhetes), o serviço de pagamento que escolher e Groq, Inc. (assistente de IA do site, Estados Unidos).","Os parceiros da sua estadia (alojamento, transporte, guia), apenas na medida do necessário: o seu nome, as suas datas e o número de viajantes."]},{"p":"Não vendemos nem alugamos os seus dados e não os utilizamos para publicidade."}]},{"id":"transferts","titre":"Dados fora do Benim","blocs":[{"p":"Alguns dos nossos prestadores estão estabelecidos fora do Benim, nomeadamente nos Estados Unidos e em Singapura. Confiamos-lhes apenas o necessário para o serviço prestado, ao abrigo dos seus compromissos contratuais de proteção de dados."}]},{"id":"navigateur","titre":"O que o site guarda no seu navegador","blocs":[{"p":"Para que não perca nada ao mudar de página, o site guarda algumas informações no seu navegador. Permanecem no seu dispositivo e só chegam até nós se enviar um formulário. São necessárias ao funcionamento do site."},{"liste":["O seu dossier de viagem: lugares, circuito, datas, serviços e bilhetes escolhidos.","O pedido de orçamento em curso, incluindo o nome e o e-mail que já introduziu, para não ter de os escrever novamente.","A moeda escolhida e o carrinho da loja.","O regresso de um pagamento em curso, apagado ao fechar o separador.","A abertura do site já vista, apagada ao fechar o separador.","As suas escolhas sobre os serviços opcionais abaixo."]},{"p":"O site não coloca cookies publicitários nem de medição de audiência. Para apagar tudo, elimine os dados deste site nas definições do seu navegador."}]},{"id":"assistant","titre":"Assistente do site e conversa com a equipa","blocs":[{"p":"O assistente de IA da OHT responde às suas perguntas apenas com base no conteúdo publicado neste site. Para produzir cada resposta, a sua mensagem e as últimas trocas da conversa são enviadas ao nosso subcontratante Groq, Inc., nos Estados Unidos; não as enviamos para qualquer outra finalidade. A conversa é apagada quando sai da página ou após 30 minutos de inatividade. Se fornecer ao assistente informações que exijam uma ação da nossa equipa (projeto de viagem, pedido de orçamento, contactos, reclamação ou pergunta sem resposta), este transmite um resumo à equipa: apenas esse resumo é conservado, durante 90 dias. Se escolher escrever a uma pessoa da equipa, a conversa e o e-mail ou número de WhatsApp deixados para contacto são conservados durante 90 dias e depois apagados; uma conversa convertida em pedido segue o prazo dos pedidos. As perguntas a que o assistente não soube responder são guardadas sem o seu endereço IP ou qualquer identificador, depois de removidos os e-mails, números e nomes nelas presentes, para que a equipa lhes responda e complete os conhecimentos do assistente. O seu endereço IP é guardado apenas sob a forma de impressão criptográfica, para aplicar os limites de utilização (número de mensagens). Pode pedir acesso, retificação ou apagamento dos seus dados através de {email}."}]},{"id":"cookies","titre":"Serviços opcionais, à sua escolha","blocs":[{"p":"Três serviços transmitem dados a terceiros ou contam as suas visitas. Só começam com o seu consentimento, e recusá-los não impede o acesso a nenhuma página."},{"fiche":[["Mapas interativos","Os mapas de base vêm do OpenFreeMap, que recebe o seu endereço IP. Se recusar, o mapa é apresentado como imagem."],["Cidade aproximada","A sua cidade é deduzida do endereço IP pelo nosso alojador, Vercel; na falta dessa informação, é deduzida do fuso horário pelo serviço Open-Meteo. Serve para situar Ouidah em relação ao seu local e permanece no seu navegador. Se recusar, introduz a cidade manualmente."],["Medição de audiência","As páginas vistas são contadas sem cookies nem identificadores pelo contador da OHT e pelo Vercel Web Analytics (Estados Unidos), para sabermos o que interessa aos visitantes. Se recusar, nada é contado."]]},{"p":"Pode mudar de ideias a qualquer momento aqui ou através do link « Cookies » no rodapé de cada página."},{"composant":"choixCookies"}]},{"id":"securite","titre":"Segurança","blocs":[{"p":"O site é disponibilizado em HTTPS. As nossas bases só estão acessíveis a quem precisa delas. Os links para retomar pedidos e os bilhetes são assinados; de cada link, guardamos apenas a impressão criptográfica, nunca o próprio link."}]},{"id":"droits","titre":"Os seus direitos","blocs":[{"p":"Pode, a qualquer momento, aceder aos seus dados, pedir a sua correção ou apagamento, opor-se à sua utilização, pedir uma cópia num formato legível e retirar o consentimento para a newsletter ou os serviços opcionais."},{"p":"Escreva para {email} com o assunto « Dados pessoais ». Poderemos pedir-lhe que confirme a sua identidade e responderemos no prazo de 30 dias."},{"p":"Se a nossa resposta não o satisfizer, pode contactar a Autorité de Protection des Données à caractère Personnel (APDP): Rue 6.076, Aïdjèdo, immeuble El Marzouk Joël, 01 BP 04837 Cotonou, Bénin · +229 21 32 57 88 · contact@apdp.bj · [apdp.bj](https://apdp.bj)."},{"p":"Também pode utilizar [Os meus dados](/mes-donnees) para receber um link pessoal no seu endereço de e-mail. O link permite descarregar os seus dados ou enviar um pedido de eliminação à equipa. Os comprovativos necessários para acompanhar os pagamentos e para a contabilidade são conservados."}]},{"id":"mineurs","titre":"Menores","blocs":[{"p":"As nossas reservas destinam-se a adultos. Um menor de 16 anos só nos transmite os seus dados com o consentimento de um dos pais."}]},{"id":"modifications","titre":"Atualizações","blocs":[{"p":"A data da última atualização aparece no topo desta página. Se uma alteração afetar uma reserva em curso, escrever-lhe-emos."}]}]},"/conditions-generales-de-vente":{"titre":"Condições gerais de venda","metaTitre":"Condições gerais de venda — Ouidah Heritage Tour","metaDescription":"Bilhetes de eventos, estadias mediante orçamento e loja da Ouidah Heritage Tour: preços, pagamento, livre resolução, cancelamento, entrega, devoluções e litígios.","intro":"As regras aplicáveis quando reserva um bilhete, uma estadia ou faz uma encomenda na loja. Algum ponto não está claro? Escreva-nos antes de reservar.","sections":[{"id":"champ","titre":"A que se aplicam estas condições","blocs":[{"p":"Aplicam-se às vendas de {denomination}, {forme} (consulte os [avisos legais](/mentions-legales)):"},{"liste":["os bilhetes dos eventos que organizamos;","as estadias, os circuitos e os serviços de acompanhamento definidos por orçamento, incluindo em torno de eventos organizados por terceiros;","os artigos da loja."]},{"p":"Aceita estas condições ao confirmar a sua reserva ou encomenda. A versão em vigor nessa data continua a aplicar-se à sua compra."}]},{"id":"prix","titre":"Preços e pagamento","blocs":[{"liste":["Os preços incluem todos os impostos e são indicados em francos CFA (XOF). A apresentação em euros segue a taxa fixa de 1 € = 655,957 FCFA.","Na loja, os portes de entrega acrescem ao preço dos artigos e são indicados antes de qualquer pagamento.","Paga o valor total de uma só vez, sem sinal, através de um dos serviços disponíveis no momento do pagamento. Nunca recebemos os dados do seu cartão."]}]},{"id":"retractation","titre":"O seu direito de livre resolução","blocs":[{"p":"Dispõe de 15 dias úteis para mudar de ideias sem ter de apresentar justificação: a partir do pagamento, para um bilhete ou uma estadia, ou da receção, para um artigo. Escreva para {email}; reembolsamos o valor total no prazo de 14 dias, pelo meio de pagamento utilizado."},{"p":"Este direito deixa de se aplicar a um bilhete ou estadia já inteiramente usufruídos, assim como aos artigos feitos por medida ou personalizados a seu pedido."}]},{"id":"billets","titre":"Bilhetes de eventos","blocs":[{"liste":["Reserva na agenda do site: modalidade, número de lugares e contactos, seguidos do pagamento.","O bilhete, emitido em seu nome e com código QR, é enviado por e-mail assim que o serviço de pagamento nos confirmar a transação. Apresente-o no telefone ou impresso; cada código QR permite uma única entrada.","Não pode comparecer? Após o prazo de livre resolução, reembolsamos o valor total até 30 dias antes do evento e metade entre 30 e 8 dias antes. Mais tarde, ofereça o seu lugar: alteramos gratuitamente o bilhete para o nome de quem escolher, até 48 horas antes.","Se cancelarmos ou adiarmos o evento, pode escolher entre o reembolso integral e o seu lugar na nova data."]}]},{"id":"sejours","titre":"Estadias e acompanhamento mediante orçamento","blocs":[{"liste":["O pedido de orçamento é gratuito e não implica qualquer compromisso. O orçamento discrimina os serviços, as datas, o que está incluído e o preço total. É válido por 15 dias.","A sua reserva torna-se definitiva quando aceita o orçamento e paga o valor total de uma só vez. Enviamos-lhe então a confirmação escrita da viagem.","Numa estadia em torno de um evento organizado por terceiros, como os Vodun Days, vendemos a estadia, não o evento. O programa depende dos organizadores; se mudar, adaptamos consigo a sua estadia.","Quer alterar as datas ou os serviços? Diga-nos: ajustamos consoante a disponibilidade, e a diferença de preço é acrescentada ou reembolsada.","Após o prazo de livre resolução, se cancelar, reembolsamos o valor total até 45 dias antes da chegada, descontando os custos não reembolsáveis já assumidos com os nossos parceiros, que lhe justificaremos; metade entre 45 e 15 dias antes; a menos de 15 dias, propomos adiar a estadia consoante a disponibilidade.","Se tivermos de cancelar, reembolsamos o valor total ou propomos outra estadia, à sua escolha.","O passaporte, o visto e o certificado de vacinação contra a febre amarela são da sua responsabilidade: a secção « Preparar a sua viagem » orienta-o. Recomendamos vivamente um seguro de viagem, incluindo repatriamento.","Somos responsáveis pela boa execução dos serviços que vendemos. Os voos que reservar por conta própria ficam fora do nosso âmbito."]}]},{"id":"boutique","titre":"Loja","blocs":[{"liste":["A sua encomenda começa por ser um pedido. No prazo de 2 dias úteis, confirmamos por e-mail a disponibilidade, a modalidade de entrega e o valor total, incluindo custos.","Paga o valor total de uma só vez após esta confirmação; a venda fica concluída quando recebemos o pagamento.","Os artigos por medida ou personalizados são produzidos após o pagamento, no prazo indicado na confirmação."]}]},{"id":"livraison","titre":"Entrega e devoluções","blocs":[{"liste":["Levantamento em Ouidah, sem custos: o local e os horários constam da confirmação.","Entrega no Benim e nos países disponíveis ao encomendar. Os portes dependem do país e da encomenda e são indicados antes do pagamento.","Prazos indicativos após expedição: 2 a 5 dias úteis no Benim, 5 a 10 na África Ocidental e 7 a 21 nos restantes destinos. Enviamos-lhe o acompanhamento da encomenda.","Fora do Benim, eventuais direitos aduaneiros e impostos de importação são da responsabilidade do destinatário.","Devolução de um artigo: nos 15 dias úteis após a receção, no estado original. Reembolsamos o artigo e os portes da entrega original no prazo de 14 dias após o recebermos; os portes da devolução ficam a seu cargo. Pode trocar o tamanho ou a cor no mesmo prazo, consoante o stock.","Artigo danificado ou diferente do encomendado: informe-nos nos 7 dias após a receção, juntando fotografias. Trocamos, reparamos ou reembolsamos o artigo, assumindo os custos.","Os artigos por medida ou personalizados não podem ser devolvidos nem trocados, salvo defeito."]}]},{"id":"donnees","titre":"Os seus dados","blocs":[{"p":"A forma como utilizamos os seus contactos está descrita na página [Privacidade e cookies](/politique-de-confidentialite)."}]},{"id":"litiges","titre":"Reclamações e litígios","blocs":[{"p":"Para qualquer reclamação, contacte-nos: {telephones} · {email}. Respondemos no prazo de 7 dias úteis e procuramos primeiro uma solução amigável consigo."},{"p":"Também pode apresentar uma reclamação à administração beninense responsável pelo turismo."},{"p":"Estas condições estão sujeitas à legislação do Benim; na falta de acordo, é competente o Tribunal de Comércio de Cotonou. Se residir fora do Benim, mantém as proteções concedidas pela lei do seu país, incluindo o direito de recorrer ao tribunal do seu domicílio quando previsto."}]}]}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:legal-ui.legalUi','{"miseAJour":"Atualização:","sommaire":"Índice","revoirChoix":"Rever as minhas escolhas"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('PT:fr.consentement','{"titre":"As suas escolhas neste site","court":"Mapas interativos e cidade aproximada: a escolha é sua.","accepter":"Aceitar tudo","refuser":"Recusar tudo","choisir":"Escolher","enregistrer":"Guardar as minhas escolhas","fermer":"Fechar","toujours":"Sempre ativo","politique":{"label":"Privacidade e cookies","href":"/politique-de-confidentialite"},"categories":[{"id":"necessaires","nom":"Necessários","texte":"O seu dossier de viagem, a moeda, o carrinho e o regresso do pagamento, guardados no navegador."},{"id":"cartes","nom":"Mapas interativos","texte":"Os mapas de base vêm do OpenFreeMap, que recebe o seu endereço IP. Se recusar, o mapa é apresentado como imagem."},{"id":"ville","nom":"Cidade aproximada","texte":"A sua cidade, deduzida do endereço IP pelo nosso alojador, para situar Ouidah em relação ao seu local. Permanece no navegador. Se recusar, introduz a cidade manualmente."},{"id":"mesure","nom":"Medição de audiência","texte":"As páginas vistas são contadas sem cookies nem identificadores pelo contador da OHT e pelo Vercel Web Analytics (Estados Unidos), para sabermos o que interessa aos visitantes. Se recusar, nada é contado."}],"lienPied":"Cookies","afficherCarte":"Mostrar o mapa interativo"}'::jsonb,1,now()) on conflict(cle) do nothing;
