insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:site.seo','{"titre":"Ouidah Heritage Tour · Vwayaj nan Ouidah, Bénin","description":"Dekouvri Ouidah, patrimwàn li ak kote ki pote memwa li yo avèk Ouidah Heritage Tour. Ekip lokal la prepare sikwi, evènman ak vwayaj pou ou.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.hero','{"kicker":["Ajans touris kiltirèl ak touris memwa","Ouidah, Bénin"],"title":{"lead":"Ouidah,","accent":"vil Vodun ak memwa"},"sub":"Mache sou Route des Esclaves, depi place Chacha rive Porte du Non-Retour, anfas Atlantik la.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Plaj Ouidah depi anlè : vag Atlantik la, sab dore ak pye kokoye"},{"src":"/hero/hero-2-porte.jpg","alt":"Nouvo Porte du Non-Retour nan Ouidah, sou kote"}],"search":{"action":"/#chemins","label":"Chèche yon sikwi","submit":"Chèche","fields":[{"name":"lieu","label":"Destinasyon","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Kalite vwayaj","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Dire","objet":"calendrier","options":[{"value":"","label":"Tout dire yo"},{"value":"demi-journee","label":"Mwatye jounen"},{"value":"journee","label":"Yon jounen"},{"value":"plusieurs-jours","label":"Plizyè jou"}]}]},"primary":{"label":"Gade sikwi nou yo","href":"/#chemins"},"secondary":{"label":"Prepare vwayaj mwen selon sa mwen vle","href":"/devis"},"facts":[{"value":"1721","label":"Fò pòtigè a, ki vin mize istwa"},{"value":"4 km","label":"Soti place Chacha rive sou plaj la, pase sou Route des Esclaves"},{"value":"2025","label":"Nouvo Porte du Non-Retour"},{"value":"23 out","label":"Jounen souvni komès esklav la"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.welcome','{"label":"Kiyès nou ye","title":["Byenveni lakay ou,","nan kè Istwa ou."],"paragraphs":["Ouidah Héritage Tour se plis pase yon ajans : se yon angajman pou yon touris ki responsab, ki mete moun nan sant li.","Nou envite ou viv Ouidah toupre nanm li. Se yon destinasyon kote istwa, espirityalite, kilti, atizay ak lanati rankontre pou fè ou viv yon eksperyans otantik.","Chak vwayaj diferan : ekip nou an pran enterè ou, sa ou espere ak bezwen ou yo an konsiderasyon. Nou akonpaye ou anvan, pandan ak apre vwayaj la."],"link":{"label":"Istwa Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"Yon jèn fi ap ranje twal wax ki gen plizyè koulè nan mache a"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Kiyès nou ye","segments":[{"text":"Byenveni lakay ou,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Porte du Non-Retour limen lannuit"},"ring":"sun"},{"text":"nan kè Istwa ou,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Antre Temple des Pythons la ki pentire"},"ring":"abyss"},{"text":"depi Route des Esclaves"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Plaj Ouidah lè solèy ap kouche"},"ring":"sun"},{"text":"rive jouk nan oseyan an."}],"columns":[{"title":"Memwa ak kilti","text":"Kòm ajans touris kiltirèl ak touris memwa, nou mennen ou mache sou Route des Esclaves, avèk yon gid k ap rakonte chak etap."},{"title":"Kote ou chwazi yo","text":"Temple des Pythons anfas bazilik la, forè sakre Kpassè, mache Zobè, lagin nan an pirog. Nou prepare sejou ou avèk kote ki enterese ou yo."},{"title":"Soti ayewopò a rive Ouidah","text":"Transpò depi ayewopò Cotonou, lojman, kote pou manje, machin : nou òganize tout sa ki antoure vizit la avèk ou, anvan, pandan ak apre vwayaj la."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.placesIntro','{"kicker":"Kat la · Soti nan vil la rive nan oseyan an","title":"Ouidah nan kat kote","titleParts":{"before":"Ouidah nan","number":"4","spoken":"kat","after":"kote."},"intro":"Desann paj la : wout la trase sou kat la, depi fò pòtigè a rive Porte du Non-Retour, atravè lari vil la.","link":"Gade kote a","walked":"km ou fè","mapLabel":"Kat Ouidah ak kat kote yo ansanm ak wout pou mache ki konekte yo"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Angajman nou yo","title":"Sèt angajman nou respekte sou teren an.","intro":"Men sa ou ka atann de nou, depi premye kesyon an jouk ou retounen.","of":"sou"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.reasons','[{"title":"Nou konnen zòn nan byen","text":"Depi fò pòtigè a rive sou plaj la, gid nou yo mennen ou apye.","couleur":"sun"},{"title":"Enfòmasyon verifye","text":"Istwa nou rakonte pandan vizit la baze sou dokiman istorik sou komès esklav la.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"Antre mize istwa Ouidah la, nan fò pòtigè a"}},{"title":"Istwa ou an premye","text":"Nou bati sikwi ou a selon istwa ou ak kesyon ou yo.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Antre Temple des Pythons la ki pentire"}},{"title":"Patnè nan peyi a","text":"Lojman, kote pou manje, gid ak atizan peyi a : nou chwazi adrès pou sejou a avèk ou.","couleur":"abyss"},{"title":"Pou dyaspora a","text":"Sikwi Retour aux sources nou an mennen desandan Afriken yo depi fò a rive Porte du Non-Retour.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour anfas oseyan an, lajounen"}},{"title":"Anvan, pandan, apre","text":"Repons nan 24 èdtan, akèy lè ou rive, akonpayman jouk ou retounen.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"Route des Pêches la, ak pye kokoye sou bò li, nan Ouidah"}},{"title":"Pou moun k ap travay nan zòn nan","text":"Nou patisipe nan fòmasyon moun k ap travay nan touris lokal la epi nou fè moun konnen yo.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.tenIntro','{"title":["Sa vil la sere pou ou,","depi memwa a rive nan oseyan an."],"link":{"label":"Dekouvri yo","href":"/#raisons"},"place":"Ouidah","discover":"Dekouvri kote a","circle":"Antoure","circled":"Antoure","path":{"label":"Gade wout mwen","href":"#chemins"},"stripLabel":"Peyizaj yo, depi memwa a rive nan oseyan an","filmEdge":"OUIDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.tenReasons','[{"slug":"route-des-esclaves","title":"Route des Esclaves la","short":"Route des Esclaves","category":"Memwa","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"Arbre du Retour, dènye estasyon Route des Esclaves anvan plaj la"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"Depi place Chacha, kote yo te vann moun nan vant ozanchè, rive sou plaj la : anviwon 4 km, sou wout kaptif yo te fè pou rive nan bato yo. Nou pase bò Arbre de l''Oubli, kote yo te fè yo vire pou efase non yo ak kote yo soti, Cases Zomaï yo, kote yo te fèmen yo nan fènwa, memoryal Zoungbodji a, epi Arbre du Retour, pou nanm yo te ka retounen. Nou mache sou wout la avèk yon gid k ap rakonte chak etap."},{"slug":"porte-du-non-retour","title":"Porte du Non-Retour la","short":"Porte du Non-Retour","category":"Memwa","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour anfas oseyan an, lajounen"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"Nan bout Route des Esclaves, sou plaj la, anfas Atlantik la. Li make kote yo te fòse plizyè milyon Afriken monte nan bato. Premye pòt la, yo te inogire 30 novanm 1995 sou inisyativ UNESCO, kite plas li pou yon pòt ki pi wo an desanm 2025. Nou rive la apye, apre estasyon wout la, epi nou kanpe anfas lanmè a."},{"slug":"temple-des-pythons","title":"Temple des Pythons la","short":"Temple des Pythons","category":"Lafwa","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Antre Temple des Pythons la ki pentire"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Yon sanktyè vodun pou sèvis koulèv Dangbé, ki gen tras li depi fen XVIIᵉ syèk la, kote piton sakre yo viv. Tanp lan anfas bazilik Immaculée-Conception an : de lafwa k ap viv kòtakòt, chak sou yon bò menm plas la. Vizit la fèt avèk respè pou règ kote a."},{"slug":"basilique","title":"Bazilik la, anfas tanp lan","short":"Bazilik","category":"Lafwa","image":{"src":"/ouidah/visite-basilique.jpg","alt":"Bazilik Immaculée-Conception nan Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"Prensipal kote katolik yo pratike relijyon yo nan Ouidah, bazilik Immaculée-Conception te bati ant 1903 ak 1909. Li vin yon bazilik minè an 1989. Li anfas Temple des Pythons : nan Ouidah, ou sèlman travèse yon plas pou pase soti youn ale nan lòt la."},{"slug":"musee-histoire","title":"Mize fò pòtigè a","short":"Mize istwa","category":"Istwa","image":{"src":"/ouidah/lieu-musee.jpg","alt":"Fò pòtigè Ouidah la, kote mize istwa a ye"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"Fò pòtigè São João Baptista de Ajudá, ki te bati an 1721, resevwa mize istwa vil la depi 6 septanm 1967 : komès esklav la, wayòm yo, lyen ak Brésil ansanm ak Amerik yo, atravè anviwon 700 pyès. Travay ap fèt sou sit la pou resevwa Musée international de la mémoire et de l''esclavage la : n ap di ou sa ki louvri anvan ou vini."},{"slug":"foret-sacree-kpasse","title":"Forè sakre Kpassè a","short":"Forè Kpassè","category":"Lanati","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"Yon eskilti vodun anba gwo pyebwa forè sakre Kpassè a"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"Yon ti forè 4 ekta nan mitan vil la, ki gen rapò ak wa Kpassè. Forè a gen divinite vodun ak eskilti, epi yo fè seremoni ladan li, sitou pandan Vodun Days. Nou antre nan yon pòtay pentire, apre sa nou mache anba gwo pyebwa yo."},{"slug":"vodun-days","title":"Vodun Days yo","short":"Vodun Days","category":"Fèt","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"Yon Egungun nan arèn Ouidah pandan Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"Chak kòmansman janvye, Ouidah resevwa gwo randevou anyèl kilti vodun yo : seremoni, dans seremoni, ekspozisyon ak rankont, avèk respè pou règ kominote yo fikse. Gwo seremoni an ak konsè yo fèt sou plaj la, lòt aktivite yo nan forè Kpassè. Se pa nou ki òganize evènman an : nou òganize sejou ou alantou li."},{"slug":"memorial-zoungbodji","title":"Memoryal Zoungbodji a","short":"Zoungbodji","category":"Memwa","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Memoryal Zoungbodji a, sou Route des Esclaves"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"Memoryal vilaj Zoungbodji a make dènye kote kaptif yo te rete anvan yo te monte nan bato, toupre twou kote yo te jete mò yo ansanm. Se etap ki pi lou sou Route des Esclaves, anviwon 2 km ak plaj la ansanm ak Porte du Non-Retour. Nou kanpe yon ti moman la anvan nou rive bò lanmè a."},{"slug":"marches","title":"Atizan, mache, manje","short":"Mache","category":"Gou","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Machann fi k ap pote machandiz yo nan yon lari Ouidah"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"Mache Zobè a, toupre fò pòtigè a, ansanm ak mache katye Kpassè a, bay vil la ritm li. Gid nou yo mennen ou la, lakay atizan yo ak nan bon kote pou manje nan Ouidah, soti nan ti maquis yo rive nan restoran yo. Se vil jodi a, k ap viv ant de vizit."},{"slug":"plage-et-lagune","title":"Plaj la ak lagin nan","short":"Plaj ak lagin","category":"Oseyan","image":{"src":"/hero/hero-4-plage.jpg","alt":"Plaj Ouidah depi anlè, vag Atlantik la ak pye kokoye"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"Nan bout Route des Esclaves, gen yon plaj ki long, ki pa gen anpil amenajman, kote gwo seremoni ak konsè Vodun Days yo fèt. Dèyè li, lagin nan separe vil la ak oseyan an : se youn nan ekosistèm bò lanmè ki pi enpòtan nan Bénin. Nou dekouvri li an pirog depi ti waf la. Route des Pêches, ak pye kokoye sou bò li yo, pase ant de yo. Nou pa konseye benyen lè van an fò."}]'::jsonb,1,now()) on conflict(cle) do nothing;
