insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.cheminsIntro','{"origin":[2.0901,6.3589],"timeZone":"Africa/Porto-Novo","kicker":"Sikwi nou yo · Soti Ouidah","title":{"lead":"Wout ou","accent":"pou rive Ouidah."},"intro":"Chwazi yon sikwi gid nou yo deja prepare, oswa chwazi kote ou yo youn pa youn : nou fè yo tounen vwayaj ou.","ready":{"label":"Sikwi ki deja pare","heading":"Sikwi gid nou yo prepare.","book":"Rezève sikwi sa a","customize":"Adapte li selon sa mwen vle"},"compose":{"label":"Prepare wout mwen","heading":"Kenbe kote ki enterese ou yo.","views":{"deck":"Yon kote alafwa"},"viewsLabel":"Fason pou dekouvri kote yo","skip":"Pase","keep":"Kenbe kote sa a","kept":"Kenbe","see":"Gade","noPhoto":"Foto ap vini","done":"Ou fin gade tout kote yo.","restart":"Gade kote yo ankò","far":"Pi lwen"},"filters":[{"key":"a-voir","label":"Pou wè","ids":["a-voir"],"color":"#ac3215","group":"voir","on":true},{"key":"plage","label":"Plaj","ids":["plage"],"color":"#2a7ab8","group":"voir","on":true},{"key":"nature","label":"Lanati","ids":["nature"],"color":"#3f8a4e","group":"voir","on":true},{"key":"hebergement","label":"Kote pou dòmi","ids":["hebergement"],"color":"#0f162d","group":"dormir","on":true},{"key":"restauration","label":"Kote pou manje","ids":["restauration"],"color":"#c98a00","group":"manger","on":true},{"key":"artisanat","label":"Atizana","ids":["artisanat"],"color":"#8a4fb3","group":"voir","on":true},{"key":"marche","label":"Mache","ids":["marche"],"color":"#d9661f","group":"voir","on":true},{"key":"pratique","label":"Enfòmasyon itil","ids":["sante","argent","transport","services"],"color":"#5b6478","group":"pratique","on":false},{"key":"culte","label":"Kote pou pratike relijyon","ids":["culte"],"color":"#8a8f9c","group":"voir","on":false}],"filtersLabel":"Kote ki parèt sou kat la","groups":{"voir":"Pou wè ak pou viv","dormir":"Kote pou dòmi","manger":"Kote pou manje","pratique":"Enfòmasyon itil"},"place":{"add":"Ajoute nan vwayaj mwe