insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.datesSection','{"title":{"lead":"Vini nan","accent":"bon moman an."},"none":"Pa gen gwo randevou nan dat sa yo : ou ka vizite Ouidah tout ane a.","units":{"days":"jou","hours":"h","minutes":"min","seconds":"s"},"live":{"arrival":"Arive","departure":"Depa","end":"Fen"},"pass":{"oht":"Evènman OHT","date":"Dat","place":"Kote","in":"Nan","arrival":"Arive","departure":"Depa","nights":"Nwit","during":"Pandan sejou ou","after":"Tousuit apre depa ou","onRequest":"Mande pri a","extendCta":"Pwolonje","bookStay":"Rezève sejou a","bookPlace":"Rezève plas mwen","byOht":"Ouidah Heritage Tour òganize li · tikè ou yo parèt depi peman an konfime.","formulas":"Fòmil"},"talon":{"titre":"Souch tikè ou","ouvrir":"Rezève plas mwen","fermer":"Fèmen rezèvasyon an","places":"Plas","moins":"Yon plas an mwens","plus":"Yon plas an plis","accompagnement":"Akonpayman ou","accompagnementNote":"sou devis, repons nan 24 h","deja":"deja chwazi nan sèvis konsyèj la","unique":{"titre":"Yon sèl demann, yon sèl referans."},"nom":"Prenon ak non","email":"Imèl","repris":"reprann nan demann ou an","payerAvec":"Peye avèk","passerelles":{"kkiapay":{"nom":"Kkiapay","moyens":"Mobile Money, kat"},"fedapay":{"nom":"FedaPay","moyens":"Mobile Money, kat"},"stripe":{"nom":"Stripe","moyens":"Kat labank"},"flutterwave":{"nom":"Flutterwave","moyens":"Kat labank"},"paystack":{"nom":"Paystack","moyens":"Kat, Mobile Money"}},"accord":"Mwen dakò pou Ouidah Heritage Tour sèvi ak enfòmasyon sa yo pou rezèvasyon mwen.","confidentialite":{"label":"Konfidansyalite","href":"/politique-de-confidentialite"},"envoi":"N ap prepare peman an…","attente":{"devis":"Nou deja note demann akonpayman ou an.","autre":"Peye yon lòt jan"},"verification":"N ap verifye peman ou an…","nonConfirme":{"titre":"Peman an poko konfime","texte":"Si ou peye, konfimasyon an rive anjeneral nan kèk moman.","reessayer":"Verifye ankò"},"paye":{"titreSans":"Li rezève.","entree":"Pou prezante nan antre a","precedent":"Tikè anvan an","suivant":"Tikè apre a","telecharger":"Telechaje tikè yo","reference":"Referans vwayaj ou","suivi":"Gade tikè mwen ak resi mwen","recap":{"formule":"Fòmil","paye":"Peye","devis":"Sou devis"},"tampon":"PEYE"},"erreurs":{"champs":"Non ou, imèl ou oswa konsantman ou manke.","limite":"Plizyè rezèvasyon fèk fèt sou koneksyon sa a. Eseye ankò nan yon èdtan.","surDemande":"Pri fòmil sa a disponib sou demann : n ap ajoute li nan vwayaj ou.","passerelle":"Mwayen peman sa a pa disponib. Chwazi yon lòt.","indisponible":"Sèvis peman sou entènèt la pa reponn kounye a. Eseye ankò nan yon ti moman."},"surDemande":"Ajoute nan vwayaj mwen"},"scrub":{"ask":"Kilè w ap vini ?","hint":"Glise ti makè a sou ane a","place":"Mete dat sejou ou","today":"Jodi a","legendOht":"Evènman OHT","legendOther":"Gwo randevou","lengths":[{"label":"Wikenn","nuits":2},{"label":"Semèn","nuits":7},{"label":"10 nwit","nuits":10},{"label":"2 semèn","nuits":14}],"lengthsLabel":"Dire sejou a","reset":"Efase dat mwen yo"},"timeZone":"Africa/Porto-Novo","fallbackImage":{"src":"/hero/hero-4-plage.jpg","alt":"Plaj Ouidah depi anlè, vag Atlantik la ak pye kokoye"}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.prepare','{"title":["Prepare vwayaj ou,","ak kat la nan men ou."],"lead":"Ouidah sou kòt la, 41 km ak ayewopò a. Men kèk konsèy esansyèl.","carte":{"ouidah":[2.0851,6.3622],"aeroport":[2.3844,6.3573],"porte":[2.0896,6.3243],"ville":"Ouidah","villeSous":"Kòt Atlantik","ocean":"Oseyan Atlantik","pays":[{"nom":"Togo","lieu":[1.12,8.2]},{"nom":"Nigeria","lieu":[3.38,8.4]}],"cotonou":"Cotonou","aeroportNom":"ayewopò entènasyonal","porteNom":"Porte du Non-Retour","km":"41 km","kmSous":"pa wout, nan navèt","ariaBenin":"Kat Bénin : Ouidah, sou kòt Atlantik la, 41 km ak ayewopò Cotonou","ariaCote":"Kòt Bénin : wout depi ayewopò Cotonou rive Ouidah, 41 km"},"fiche":{"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour anfas oseyan an, nan Ouidah"},"titre":"Ouidah","texte":"Yon vil ki chaje istwa, anfas Atlantik la.","heureTexte":"Menm lè ak Paris pandan sezon ivè.","fuseau":"Africa/Porto-Novo"},"accueil":{"titre":"N ap tann ou.","texte":"Lè ou rive, ekip la resevwa ou nan ayewopò a si ou vle."},"ongletsLabel":"Prepare vwayaj ou, pa sijè","numeros":"Nimewo itil","question":"Ou gen yon kesyon anvan ou pati ? Nou reponn nan 24 èdtan.","whatsapp":"Ekri sou WhatsApp","ecrire":{"label":"Poze yon kesyon","href":"/devis?demande=question"},"verifie":"2026-10-22"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.preparer','[{"id":"sur-place","court":"Sou plas","objet":"accueil","vue":"benin","titre":"Vizite Ouidah ak lespri poze.","cle":{"valeur":"Avèk akonpayman","texte":"ekip nou an, anvan, pandan ak apre vwayaj la."},"mot":true,"points":["N ap tann ou nan ayewopò a si ou vle : navèt la mennen ou rive Ouidah.","Lojman ak kote pou manje : nou chwazi avèk ou pami adrès nou jwenn nan Ouidah yo.","Anvan ou pran foto yon seremoni oswa yon moun, mande pèmisyon : se koutim nan.","Sou plaj la, pwofite sab la ak solèy k ap kouche a. Pou benyen, mande konsèy sou plas, paske vag Atlantik la fò."],"source":"Angajman OHT · France Diplomatie (15 sept. 2026) · FCDO"},{"id":"arriver","court":"Rive","objet":"navette","vue":"cote","titre":"Rive, san tèt chaje.","cle":{"valeur":"41 km","texte":"depi ayewopò Cotonou rive Ouidah. Navèt OHT la mennen ou la."},"points":["Ou mande e-Visa ou sou entènèt, sou evisa.bj : pou 30 oswa 90 jou, avèk repons nan 1 a 96 èdtan.","Fè demann lan omwen 7 jou anvan ou rive, epi kenbe li toupre ou.","Sitwayen peyi afriken yo : pa bezwen viza pou jiska 90 jou.","Vwayajè fransè yo : paspò a dwe valab 6 mwa apre retou a, epi mete tikè retou a nan sak ou."],"source":"evisa.bj · France Diplomatie · OSRM (41 km)"},{"id":"sante","court":"Sante","objet":"sante","vue":"benin","titre":"Prepare sante ou.","cle":{"valeur":"1 vizit","texte":"kay doktè ou oswa nan yon sant vaksinasyon entènasyonal, anvan ou pati."},"points":["Vaksen ajou, epatit A ak tifoyid : doktè ou verifye sa ou bezwen avèk ou.","Lafyèv jòn : yo rekòmande vaksen an depi 9 mwa. Mete kanè vaksen ou nan sak ou.","Kont moustik : pwodui pou chase moustik ak rad manch long nan aswè. Doktè ou ap di ou si ou bezwen tretman kont malarya."],"source":"Ministère de la Santé du Bénin (16 sept. 2026) · Institut Pasteur · OMS — lafyèv jòn : sous yo pa dakò, pou konfime"},{"id":"argent","court":"Lajan","objet":"type-voyage","vue":"benin","titre":"Lajan, san kalkil.","cle":{"valeur":"15,24 €","texte":"pou 10 000 FCFA. To a fiks pandan tout ane a."},"points":["Franc CFA a mare ak ewo a : 1 € = 655,957 FCFA, san chanjman.","Yon repè rapid : 1 000 FCFA vo anviwon 1,50 €.","Pou retire lajan, chwazi distribitè ki andedan ajans bank yo."],"source":"BCEAO · France Diplomatie"},{"id":"pratique","court":"Enfòmasyon itil","objet":"prise","vue":"benin","fiche":"heure","titre":"Sa pou konnen.","cle":{"valeur":"0 h","texte":"diferans ak Paris pandan sezon ivè, 1 h pandan sezon ete."},"points":["220 V, priz C ak E : chajè ki soti France ak Belgique yo konekte san adaptè.","Fransè se lang ofisyèl la ; nan Ouidah, yo pale fon tou.","Yon kat SIM lokal MTN, Moov Africa oswa Celtiis ap pèmèt moun jwenn ou.","Sezon sèk la soti novanm rive mas, epi soti mitan jiyè rive mitan septanm."],"source":"gouv.bj · ARCEP Bénin · IEC · IANA"}]'::jsonb,1,now()) on conflict(cle) do nothing;
