insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.newsletter','{"nom":"Lèt Ouidah la","phraseSansHeure":"Aswè a, solèy la kouche sou plaj Ouidah la.","maintenant":"Nan Ouidah","photo":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Plaj Ouidah la, pye kokoye li yo ak chemen sab la nan fen jounen an"},"choisir":"Chwazi sa w vle resevwa sou Ouidah","sujets":[{"id":"departs","nom":"Dat depa nou yo","texte":"Pwochen sejou ak sikwi yo, ansanm ak dat yo.","objet":"calendrier"},{"id":"agenda","nom":"Kalandriye Ouidah la","texte":"Vodun Days, Journée du souvenir, Ouidah Blue : gwo randevou vil la.","objet":"fete"}],"langue":"Lèt la an","field":"Adrès imèl ou","exemple":"vous@exemple.com","submit":"Resevwa lèt la","consent":"Mwen dakò resevwa lèt Ouidah Heritage Tour la. Mwen ka dezabòne ak yon sèl klik.","envoi":"Enskripsyon an ap fèt…","thanks":"Nou pran nòt : w ap resevwa lèt la nan bwat imèl ou.","echec":"Enskripsyon an pa rive fèt. Eseye ankò nan yon ti moman.","limite":"Gen plizyè enskripsyon ki deja soti nan koneksyon sa a. Eseye ankò nan inèdtan.","aucun":"Chwazi omwen yon sijè.","error":"Antre yon adrès imèl ki valab epi tcheke kare a."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.collage','{"label":"Ouidah an imaj","title":["Yon vil","pou w viv."],"images":[{"src":"/ouidah/collage-danse-atchinan-kpasse.jpg","alt":"Yon dansèz ak kolye pèl sou li, pandan yon seremoni vodun nan forè sakre Kpassè a","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-egungun-vodun-days.jpg","alt":"Yon Egungun ak yon kostim bwode, nan mitan piblik Vodun Days yo nan Ouidah","credit":"Romario Coffi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-marche-zobe.jpg","alt":"Antre mache Zobè a, nan lonbraj gwo pyebwa yo","credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-danseur-kpasse.jpg","alt":"Yon dansè ak yon twal ble, atè, pandan yon seremoni vodun nan forè sakre Kpassè a","credit":"Maelan123, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-fete-vodoun-2023.jpg","alt":"Dansè ak rad fèt ak chapo wouj, nan fèt vodun 10 janvye a nan Ouidah","credit":"Dieu229, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-zangbeto-meko.jpg","alt":"De Zangbéto ak franj koulè pandan Vodun Days yo, nan vilaj Mèkô (komin Ouidah)","credit":"Gildas Lissassi, Wikimedia Commons, CC BY-SA 4.0"},{"src":"/ouidah/collage-vodun-days-2024.jpg","alt":"Dansèz ak twal koulè devan piblik Vodun Days 2024 yo nan Ouidah","credit":"Fermi12, Wikimedia Commons, CC BY-SA 4.0"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
