insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.devisPage','{"metaTitre":"Kreye vwayaj mwen — Ouidah Heritage Tour","metaDescription":"Tikè w pou Ouidah : vwayaj ou prepare sou sit la, sa ki rete pou ranpli, epi yon konseye k ap reponn ou nan 24 èdtan.","titre":{"voyage":"Tikè w pou Ouidah.","groupe":"Tikè gwoup ou a pou Ouidah.","question":"Ekri nou."},"intro":{"compose":"Tout sa ou te prepare sou paj dakèy la deja la. Ranpli kare jòn yo, apre sa pati anba a.","vide":"Ranpli kare jòn yo, apre sa pati anba a : yon konseye ap reponn ou nan 24 èdtan.","groupe":"Asosyasyon, lekòl, antrepriz, gwo fanmi : di nou kiyès k ap vini, n ap prepare sejou a.","question":"Ou gen yon kesyon anvan w pati, yon lide vwayaj ? N ap reponn ou nan 24 èdtan."},"reference":{"lib":"Referans","note":"yo bay lè w voye l","lib2":"Referans demann ou an"},"trajet":{"depart":"Depa","arrivee":"Arive","destination":"Destinasyon","vol":"vòl ou","detectee":"nou pwopoze dapre koneksyon ou","choisie":"vil ou","villeTrou":"vil ou","villeNote":"pa obligatwa","villeTitre":"Ki kote w ap soti ?","villeAide":"Egz. : Paris, Montréal, Abidjan","villeOk":"Kenbe vil sa a","villeIntrouvable":"Nou pa jwenn vil la. Eseye ekri non an yon lòt jan.","aeroport":{"code":"COO","nom":"Ayewopò Cotonou","km":41},"ouidah":"OUIDAH","pays":"Bénin"},"dates":{"aller":"Ale","retour":"Retounen","sejour":"Sejou","trou":"nan ki dat ?","conseil":"Ban m konsèy","conseillees":"Dat pou nou rekòmande","choisir":"M ap chwazi dat mwen yo","arrivee":"Arive","depart":"Depa","garder":"Kenbe dat sa yo","invalides":"Depa a dwe vini apre arive a, pi ta twa ane apre jodi a.","modifier":{"label":"Chanje dat yo","href":"/#agenda"},"pendant":"pandan"},"lieux":{"titreVide":"Kote ou yo","trou":"ki kote ?","conseil":"Ban m konsèy","conseilles":"Kote pou nou rekòmande","choisir":{"label":"Chwazi kote mwen yo","href":"/#chemins"},"modifier":{"label":"Chanje kote yo","href":"/#chemins"}},"services":{"titreVide":"Sèvis ou yo","modifier":{"label":"Chanje sèvis yo","href":"/#conciergerie"},"aucun":"Navèt, lojman, machin :","aucunLien":{"label":"sèvis konsyèj la ap okipe sa","href":"/#conciergerie"}},"billets":{"modifier":{"label":"Chanje tikè yo","href":"/#agenda"},"surDevis":"Sou devis","unSeul":"Ou ka peye yon sèl evènman sou entènèt pou chak demann ou voye : tikè ou yo ap ale kòm demann devis."},"qui":{"lib":"Pasaje","titre":"Kiyès k ap vwayaje ?","trou":"ak kiyès ?","options":[{"id":"Seul(e)","phrase":"poukont mwen","adultes":1},{"id":"En couple","phrase":"an koup","adultes":2},{"id":"En famille","phrase":"an fanmi","adultes":2},{"id":"Entre amis","phrase":"ak zanmi","adultes":2},{"id":"En groupe","phrase":"an gwoup","adultes":2},{"id":"Professionnel","phrase":"pou travay","adultes":1}],"adultes":"Granmoun","enfants":"Timoun, mwens pase 18 an","valider":"Valide"},"pays":{"lib":"Peyi depa","titre":"Nan ki peyi w ap soti ?","trou":"peyi ou","recherche":"Chèche yon peyi","propose":"nou pwopoze dapre koneksyon ou","aucun":"Eseye non peyi a an franse."},"occasion":{"lib":"Okazyon","titre":"Yon okazyon espesyal ?","trou":"yon okazyon ?","note":"pa obligatwa","options":[{"id":"Retour aux sources","phrase":"yon retou nan rasin mwen"},{"id":"Voyage de noces","phrase":"yon lin de myèl"},{"id":"Anniversaire","phrase":"yon anivèsè"},{"id":"Voyage scolaire","phrase":"yon vwayaj lekòl"}],"aucune":"Pa presize"},"langue":{"lib":"Lang pou repons lan","titre":"Nan ki lang pou nou ekri ou ?","note":"lang sit la","aide":"Pou echanj nou yo, devis la epi, lè sa posib, vizit la."},"langues":{"FR":"franse","EN":"anglè","ES":"panyòl","DE":"alman","PT":"pòtigè","HT":"kreyòl ayisyen","GCF":"kreyòl"},"fermer":"Fèmen","talon":{"titre":"Kiyès pou nou reponn ?","titreQuestion":"Mesaj ou","logo":"Ouidah Heritage Tour","noms":{"dates":"dat ou yo","lieux":"kote ou yo","qui":"ak kiyès","pays":"peyi ou","nom":"non ou","email":"imèl ou","message":"mesaj ou","consent":"akò ou"},"champs":{"nom":"Prenon ak non","email":"Imèl","whatsapp":"WhatsApp","facultatif":"pa obligatwa","whatsappAide":"Kòd peyi ak nimewo","message":"Gen yon bagay pou ajoute ?","messageQuestion":"Mesaj ou","messageAide":"Yon ritm, yon anvi, yon kontrent sante, yon seremoni ou ta renmen…"},"emailInvalide":"Adrès sa a sanble pa konplè : verifye pati ki apre @ a.","consent":"Mwen dakò pou Ouidah Heritage Tour itilize enfòmasyon sa yo pou prepare devis mwen. Pou sa sèlman.","consentQuestion":"Mwen dakò pou Ouidah Heritage Tour itilize enfòmasyon sa yo pou reponn mwen. Pou sa sèlman.","confidentialite":{"label":"Konfidansyalite","href":"/politique-de-confidentialite"},"bouton":"Voye demann mwen","payerAvec":"Peye avèk","envoi":"N ap voye l…","reessayer":"Eseye voye l ankò","promesse":"N ap reponn ou nan 24 èdtan.","echec":"Nou pa rive voye l. Anyen pa pèdi : repons ou yo rete sou aparèy sa a. Eseye ankò nan yon ti moman.","limite":"Gen plizyè demann ki deja soti nan koneksyon sa a. Eseye ankò nan inèdtan.","reprise":{"bouton":"Reprann sou yon lòt aparèy","creation":"N ap kreye lyen an…","lien":"Lyen ou an, ki valab pandan 30 jou :","copier":"Kopye lyen an","copie":"Lyen an kopye","note":"Kenbe l pou ou sèlman : li ouvri demann ou an.","erreur":"Nou pa rive kreye lyen an. Eseye ankò nan yon ti moman."}},"merci":{"copie":"Nou fèk voye yon kopi demann ou an nan bwat imèl ou.","retour":{"label":"Retounen nan paj dakèy la","href":"/"},"suivre":"Swiv demann mwen (dosye ak devis)"},"reprendre":{"metaTitre":"Reprann vwayaj mwen — Ouidah Heritage Tour","chargement":"Vwayaj ou ap retounen…","invalide":"Lyen sa a pa valab ankò : li ka ekspire. Prepare vwayaj ou ankò, oswa ekri nou.","accueil":{"label":"Prepare vwayaj mwen","href":"/"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
