insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.places','[{"n":"01","name":"Mize istwa Ouidah la","kicker":"Fò pòtigè a, 1721","text":"Depi 6 septanm 1967, fò pòtigè a loje mize istwa vil la : trafik esklav, wayòm yo, lyen ak Brezil ak Amerik yo.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"Mi wouj fò pòtigè Ouidah la"},"next":"680 m apye pou rive nan Temple des Pythons"},{"n":"02","name":"Temple des Pythons","kicker":"Anfas bazilik la","text":"Tanp piton Dangbé a anfas bazilik Immaculée-Conception an, ki te konstwi ant 1903 ak 1909 : de lafwa k ap viv youn bò kote lòt.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Antre Temple des Pythons la ki pentire"},"next":"2,5 km pou rive nan memoryal Zoungbodji a, atravè plas Chacha"},{"n":"03","name":"Route des Esclaves la","kicker":"Anviwon 4 km, sis estasyon","text":"Soti plas Chacha rive nan plaj la, chemen prizonye yo te pran pou rive sou bato yo : Arbre de l''Oubli, Cases Zomaï, Mémorial de Zoungbodji, Arbre du Retour.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Memoryal Zoungbodji a, sou Route des Esclaves"},"next":"2 km pou rive nan plaj la ak Porte du Non-Retour"},{"n":"04","name":"Porte du Non-Retour","kicker":"Bati an 1995, rebati an 2025","text":"Sou plaj la, anfas Atlantik la, li make kote yo te fòse plizyè milyon Afriken monte sou bato.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Porte du Non-Retour limen lannuit"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
