insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.conciergerie','[{"id":"navette","court":"Navèt","nom":"Navèt.","question":"Yon trajè, oswa ale-retou ?","moment":"Lè avyon an ateri","lead":"Depi ayewopò entènasyonal Cardinal Bernardin Gantin : anviwon 41 km sou wout.","leadReleve":null,"objet":"navette","photo":{"src":"/ouidah/aeroport-fresque.jpg","alt":"Fresk « Bienvenue au Bénin » nan ayewopò Cotonou a"},"credit":"Houss 2020, Wikimedia Commons, CC0","options":[{"label":"Ale","detail":"Ayewopò → Ouidah","releve":null,"phrase":"navèt lè w rive a"},{"label":"Ale-retou","detail":"Epi jou depa a","releve":null,"phrase":"navèt ale-retou a"},{"label":"Mwen pa bezwen","detail":null,"releve":null,"passe":true}]},{"id":"accueil","court":"Akèy","nom":"Akèy.","question":"Ki kote ou vle nou tann ou ?","moment":"Lè w rive","lead":null,"leadReleve":null,"objet":"accueil","photo":{"src":"/ouidah/aeroport-facade.jpg","alt":"Fasad ayewopò entènasyonal Cotonou a"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Nan ayewopò a","detail":"Depi nan sòti a","releve":null,"phrase":"akèy nan ayewopò a"},{"label":"Nan Ouidah","detail":"Nan adrès ou","releve":null,"phrase":"akèy nan Ouidah la"},{"label":"Mwen pa bezwen","detail":null,"releve":null,"passe":true}]},{"id":"telephone","court":"Telefòn","nom":"Telefòn.","question":"Yon kat SIM lè w rive ?","moment":"Premye jou a","lead":null,"leadReleve":null,"objet":"telephone","photo":{"src":"/ouidah/eng-1-rue-basilique.jpg","alt":"Yon lari nan Ouidah, bò bazilik la"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Kat SIM","detail":"Rele, ekri","releve":null,"phrase":"yon kat SIM"},{"label":"Kat SIM + done","detail":"Ak entènèt mobil","releve":null,"phrase":"yon kat SIM ak entènèt"},{"label":"Mwen pa bezwen","detail":null,"releve":null,"passe":true}]},{"id":"hebergement","court":"Lojman","nom":"Lojman.","question":"Ki kalite kote ?","moment":"Premye swa a","lead":"{n} adrès nou note nan Ouidah. N ap chwazi sa ki mache ak ou a ansanm avè w.","leadReleve":"hebergement","objet":"hebergement","photo":{"src":"/ouidah/eng-3-case-plage.jpg","alt":"Yon kay won ak twati pay, anfas plaj la"},"cadre":"50% 85%","credit":null,"options":[{"label":"Otèl","detail":null,"releve":"hebergement/Hôtel","phrase":"yon otèl"},{"label":"Obèj","detail":null,"releve":"hebergement/Auberge","phrase":"yon obèj"},{"label":"Kay dakèy","detail":null,"releve":"hebergement/Maison d''hôtes","phrase":"yon kay dakèy"},{"label":"Kanman","detail":null,"releve":"hebergement/Campement","phrase":"yon kanman"},{"label":"Mwen deja rezève","detail":null,"releve":null,"passe":true}]},{"id":"tables","court":"Kote pou manje","nom":"Kote pou manje.","question":"Ki kote ou renmen manje ?","moment":"Sou tab","lead":"{n} kote pou manje nou note nan Ouidah. Ou ka chwazi plizyè.","leadReleve":"restauration","multi":true,"objet":"tables","photo":{"src":"/ouidah/eng-4-paillote.jpg","alt":"Yon abri ak twati pay bò plaj Ouidah la"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Restoran","detail":null,"releve":"restauration/Restaurant","phrase":"restoran"},{"label":"Ba","detail":null,"releve":"restauration/Bar","phrase":"ba"},{"label":"Kafe","detail":null,"releve":"restauration/Café","phrase":"kafe"},{"label":"Mwen pa bezwen","detail":null,"releve":null,"passe":true}]},{"id":"vehicule","court":"Machin","nom":"Machin.","question":"Ak chofè oswa san chofè ?","moment":"Jou ki vin apre yo","lead":"Pou ale nan plaj la pa Route des Pêches, nan Ganvié oswa Abomey nan ritm ou.","leadReleve":null,"objet":"vehicule","photo":{"src":"/ouidah/route-des-peches.jpg","alt":"Route des Pêches la, ak poto limyè sou kote l, ant lagin ak oseyan"},"credit":"Fawaz.tairou, Wikimedia Commons, CC BY-SA 4.0","options":[{"label":"Ak chofè","detail":null,"releve":null,"phrase":"yon machin ak chofè"},{"label":"San chofè","detail":null,"releve":null,"phrase":"yon machin san chofè"},{"label":"Mwen pa bezwen","detail":null,"releve":null,"passe":true}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:histoire.histoireOuverture','{"titre":"Soti Glexwé rive Ouidah","texte":"An fon, vil la rele Glexwé, yo souvan tradui non sa a kòm « kay jaden yo ». Ewopeyen yo te ekri non wayòm houéda vil la te fè pati a plizyè fason : Whydah an anglè, Juda an franse, Fida an olandè, Ajudá an pòtigè. Se la Ouidah soti. Depi 1681, yon Anglè te deja make sou yon lèt « Agriffie in Whidaw » : Glexwé, nan peyi houéda.","noms":["Glexwé","Whydah","Juda","Fida","Ajudá","Ouidah"]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:histoire.histoireChapitres','[{"id":"avant","repere":"XVIIe syèk","court":"XVIIe","titre":"Anvan fò yo","ville":false,"temps":[["Nan XVIIe syèk la, Glexwé se vil ki pi ba nan wayòm houéda a, nan nò yon lagin. Wa a rete Savi, anviwon dis kilomèt pi nan nò. Apre vwazen li Allada te domine l pandan lontan, ti wayòm nan libere tèt li nan dezyèm mwatye syèk la.","Lè Ewopeyen yo vin enstale nan fen syèk la, pifò biznis fèt nan Savi, toupre palè a. Fouy ki fèt sou sit la depi 1991 jwenn brik olandè ak pòslèn chinwa sèlman anndan lakou wa a, yon siy se wa a ki te kontwole komès la."],["Dapre tradisyon an, Houéda yo ta soti Tado, epi premye wa yo a, Haholo, ta fonde Savi. Tradisyon an bay Glexwé yon lòt fondatè, Kpassè. Li rakonte li pa ta mouri tankou yon moun : li ta tounen yon pye iwoko. Yo venere pyebwa sa a nan forè sakre Kpassè a, nan katye Tové, kote yo mete vilaj ki te la anvan Ewopeyen yo.","Yon lòt non parèt nan istwa yo : Kpate, ki ta akeyi premye Ewopeyen yo. Yo toujou fè sèvis pou li nan Ouidah."]],"pieces":[{"hier":{"src":"/histoire/plan-palais-savi-1747.webp","largeur":1173,"hauteur":1313,"legende":"Palè wa a nan Savi ak kontwa komès Ewopeyen yo, plan grave an 1747"},"auj":null},{"hier":{"src":"/histoire/couronnement-roi-juida-1723.webp","largeur":1100,"hauteur":847,"legende":"Kouwònman wa houéda a, gravir XVIIIe syèk la"},"auj":null},{"hier":null,"auj":{"src":"/histoire/raison-foret-kpasse.webp","largeur":1200,"hauteur":674,"legende":"Forè sakre Kpassè a, nan katye Tové"}}]},{"id":"forts","repere":"1671 – 1721","court":"1671","titre":"Fò yo","ville":true,"temps":[["An 1671, Compagnie française des Indes occidentales ouvri yon kontwa komès nan wayòm houéda a. Se premye etablisman ewopeyen pèmanan an. Anglè yo rive nan ane 1680 yo. Kontwa franse a detwi pandan lagè 1692 a. Li retounen an 1704 sou fòm yon fò, korsè Jean Doublet bati li nan kèk semèn, ak tè ak pay.","José de Torres, yon komèsan ki soti Bahia, fonde fò pòtigè São João Baptista de Ajudá a an 1721."],["Nan XVIIIe syèk la, fò anglè, franse ak pòtigè yo youn toupre lòt, plizyè kilomèt ak plaj la. Olandè yo pa janm te gen fò nan Ouidah, Danwa yo nonplis.","Anglè yo abandone pa yo a an 1812. Yo demoli fò franse a an 1908. Nan plas li, gen yon esplanad kote Zangbéto yo, gadyen lannuit yo, danse pandan Vodun Days yo. Jodi a, se sèlman fò pòtigè a ki toujou kanpe."]],"pieces":[{"hier":{"src":"/histoire/fort-anglais-1727.webp","largeur":1226,"hauteur":410,"legende":"Fò anglè a, yo rele William''s Fort, gravir 1727"},"auj":null},{"hier":{"src":"/histoire/fort-francais-plan-1747.webp","largeur":1330,"hauteur":1400,"legende":"Plan fò franse a, gravir 1747"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-gravure-1886.webp","largeur":960,"hauteur":628,"legende":"Fò pòtigè a, gravir 1886"},"auj":{"src":"/histoire/eng-2-musee.webp","largeur":1200,"hauteur":900,"legende":"Antre fò pòtigè a, ki tounen mize istwa"}}]},{"id":"dahomey","repere":"1727","court":"1727","titre":"Dahomey","ville":false,"temps":[["An 1724, Agaja, wa Dahomey, pran Allada. Nan kòmansman mas 1727, lame li pran Savi epi detwi l, ansanm ak kontwa komès Ewopeyen ki la yo. Hufon, dènye wa houéda a, kouri al nan lwès ak yon pati nan pèp li a, dabò sou yon zile toupre Grand-Popo. Lòt Houéda al enstale nan Porto-Novo ak Badagry."],["Glexwé chanje mèt ak wòl. Komès ak Ewopeyen yo vin konsantre la, epi vil la tounen prensipal sant trafik esklav Dahomey. Yon gouvènè enstale la an 1733. Ewopeyen yo rele l vis-wa.","Pi ta, li pote tit fon yovogan an, « chèf Blan yo », wayòm houéda a te deja itilize. Se toujou yon moun nan peyi a ki okipe pòs sa a. Fò yo pase anba otorite Dahomey : an jiyè 1743, lame li atake fò pòtigè a."]],"pieces":[{"hier":{"src":"/histoire/comptoirs-savi-1747.webp","largeur":1400,"hauteur":948,"legende":"Kontwa komès Ewopeyen Savi yo, gravir ki fèt dapre desen 1725, de ane anvan vil la tonbe"},"auj":null}]},{"id":"chacha","repere":"1800 – 1849","court":"1800","titre":"Chacha a","ville":true,"temps":[["Francisco Félix de Souza, yon trafikan esklav ki soti Brezil, vini premye fwa sou kòt la nan kòmansman ane 1790 yo epi enstale la bò 1800. Li kòmanse kòm sekretè-kontab nan fò pòtigè a, li dirije l pwovizwaman bò 1806, apre sa li fè komès pou tèt li.","Apre yon konfli ak wa Adandozan, yo mete l nan prizon Abomey, epi li sove pou ale Petit-Popo. Depi la, li soutni koudeta ki mete Ghézo sou twòn Dahomey a, pwobableman an 1818. Nouvo wa a fè l tounen ajan komès li nan Ouidah, kote li retounen bò 1820."],["Yo ba l ti non Chacha. Orijin mo a poko konnen : yon tradisyon mare l ak pòtigè « já, já », « touswit », li ta konn di souvan. Li fonde yon katye nan sidwès vil la ki pran non Brésil pi ta, Blézin an fon. Fanmi li, esklav li ak kliyan li yo rete la.","Yon woman fè l tounen « vis-wa Ouidah ». Li pa janm te sa : se yon moun Dahomey ki te okipe pòs yovogan an."],["Li mouri nan Ouidah 8 me 1849, ak gwo dèt : li te dwe wa Ghézo 80 000 dola. Wa a chwazi premye pitit gason li a, Isidoro, pou ranplase l. Lè sa a, ti non an tounen yon tit ereditè chèf fanmi de Souza a toujou pote depi lè sa a.","Tonm li nan lakou fanmi an nan Singbomey, dèyè plas Chacha. Depi 1999, yon plak bay plas la non sa a. Tèks ofisyèl resan yo rele l tou place aux Enchères."]],"pieces":[{"hier":{"src":"/histoire/portrait-de-souza.webp","largeur":1164,"hauteur":1400,"legende":"Pòtrè yo atribye ak Francisco Félix de Souza, pentire anvan 1849"},"auj":null},{"hier":{"src":"/histoire/place-chacha-stele-2017.webp","largeur":1400,"hauteur":933,"legende":"Stèl « Place Chacha » a, an 2017"},"auj":null,"temps":2}]},{"id":"agudas","repere":"1835 – 1922","court":"1835","titre":"Aguda yo","ville":true,"temps":[["Apati 1835, apre revòlt Malês yo nan Bahia, yo mete Afriken ki te libere yo deyò Brezil oswa pouse yo pati. Anpil ladan yo se Yoruba. Nan Ouidah, yo enstale sitou nan katye Maro, nan lwès katye Brésil la, anba pwoteksyon De Souza.","Ansanm ak fanmi komèsan pòtigè ak brezilyen yo, ak fanmi afriken ki gen lyen ak yo, yo fòme Aguda yo. Nan XIXe syèk la, mo a deziyen Pòtigè yo, Brezilyen yo ladan l tou ; li ta soti nan Ajudá. Gen Aguda, tankou fanmi de Souza a, ki te viv de trafik esklav."],["Desandan yo pote non tankou de Souza, da Silva, d''Almeida, Martins, Olympio oswa Paraïso. Nan Bénin, yo fete Nosso Senhor do Bonfim an janvye epi yo danse bourian, yon maskarad ki soti Bahia."],["Sou tout kòt la, kay etaj yo ak galri, balistrad, jalouzi ak fronton dekore yo fè sonje sobrado Salvador yo. Nan kòmansman XXe syèk la, estil sa a tounen yon siy reyisit. Moun enpòtan ki pa Aguda adopte l tou.","Vila Ajavon an se yon egzanp. Sou fronton li, gen enskripsyon « VILLA AJAVON 1922 ». Yo te bati l pou Ajavon, yon komèsan rich ki soti nan Togo, peyi vwazen an. Depi 11 novanm 2013, li loje mize atizay kontanporen Fondation Zinsou a."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/maison-du-bresil.webp","largeur":1120,"hauteur":1400,"legende":"Maison du Brésil la, an 2024"},"temps":2},{"hier":null,"auj":{"src":"/histoire/villa-ajavon-1922.webp","largeur":1400,"hauteur":1050,"legende":"Vila Ajavon an, ki date 1922, ki tounen mize Fondation Zinsou"},"temps":2}]},{"id":"mer","repere":"Fen XVIIe syèk la – 1863","court":"1863","titre":"Jiska lanmè a","ville":false,"temps":[["Dapre estimasyon istoryen yo, yo te depòte plis pase yon milyon moun depi Ouidah, soti nan fen XVIIe syèk la rive nan ane 1860 yo."],["Vil la anviwon kat kilomèt ak lanmè a, dèyè yon lagin. Yo te mennen prizonye yo apye rive nan plaj la. Piròg te fè yo travèse gwo vag ki fèmen kòt la pou rive nan bato ki te jete lank nan lanmè a."],["Yo te ale sitou Brezil, espesyalman Bahia, ak nan Zantiy yo, sitou Sendomeng, Ayiti jodi a. Nan fen trafik esklav la, yo te ale Kiba.","Nan ane 1840 yo, komès lwil palmis pran anplè, men trafik esklav la kontinye. An janvye 1852, anba blokis britanik, wa Ghézo siyen yon trete ki aboli l. Li pa bay rezilta ki dire."],["An me 1860, golèt Clotilda kite Ouidah ak 110 prizonye abò. An jiyè, li debake an sekrè toupre Mobile, nan Alabama. Se dènye bato trafik esklav yo konnen ki te rive Etazini.","10 oktòb 1863, nan Godomey, bato vapè Cicerón anbake anviwon 960 moun pou Kiba, apre yo te mennen yo apye depi Ouidah. Se dènye anbakman transatlantik yo konnen ki gen lyen ak Ouidah."]],"chiffre":{"valeur":"Plis pase yon milyon","legende":"moun yo te depòte depi Ouidah, soti nan fen XVIIe syèk la rive nan ane 1860 yo, dapre estimasyon istoryen yo"},"legende":[{"lettre":"A","nom":"Tant Ewopeyen yo"},{"lettre":"B","nom":"Bò lanmè a"},{"lettre":"C","nom":"Bato ki jete lank toupre kòt la"}],"pieces":[{"hier":null,"auj":{"src":"/histoire/bienvenue-3-plage-cocotiers.webp","largeur":1200,"hauteur":795,"legende":"Plaj Ouidah la"}}]},{"id":"basilique","repere":"1903 – 2011","court":"1903","titre":"Piton an ak bazilik la","ville":true,"temps":[["Dangbé, piton wa a, se divinite wayòm houéda a. Li manifeste nan koulèv vivan yo kenbe nan tanp li yo. Bò 1700, yon machann olandè note koulèv yo se premye divinite wayòm nan."],["Nan Ouidah, tanp li anfas bazilik Immaculée-Conception an. Legliz la sou teren ansyen kay yovogan an, yo te bay misyon katolik la an 1901, apre misyon an te rive Ouidah an 1861.","Yo poze premye wòch la 30 out 1903. Pou bati l, tout katye vil la pote sab depi plaj la, pratikan vodun yo ladan l tou. Yo konsakre katedral la 9 me 1909, devan anviwon 4 000 moun."],["Li tounen bazilik an 1989. 19 novanm 2011, Benoît XVI siyen Africae munus la, egzòtasyon li sou Legliz la nan Lafrik."]],"pieces":[{"hier":{"src":"/histoire/procession-serpent-1725.webp","largeur":1400,"hauteur":674,"legende":"Pwosesyon pou gwo koulèv la nan kouwònman wa a, gravir pibliye an 1730"},"auj":null},{"hier":{"src":"/histoire/temple-serpent-1930.webp","largeur":1400,"hauteur":666,"legende":"Tanp koulèv la, bò 1930"},"auj":{"src":"/histoire/bienvenue-2-temple-pythons.webp","largeur":1200,"hauteur":900,"legende":"Antre Temple des Pythons la"}},{"hier":{"src":"/histoire/basilique-1930.webp","largeur":1003,"hauteur":1400,"legende":"Katedral la, bò 1930"},"auj":{"src":"/histoire/visite-basilique.webp","largeur":800,"hauteur":1200,"legende":"Bazilik Immaculée-Conception an"}}]},{"id":"fort","repere":"1892 – 1990","court":"1961","titre":"Fò k ap boule a","ville":true,"temps":[["An 1892, Ouidah pase anba okipasyon franse. Franse yo fikse chèflye a nan Porto-Novo, epi komès la deplase pou ale nan waf Cotonou a. Vil la febli tikras pa tikras. Fò pòtigè a, li menm, rete nan men Lisbon."],["Dahomey vin endepandan 1ye out 1960. Egzakteman yon ane apre, li pran posesyon fò a, ki te rete yon anklav pòtigè. Anvan yo pati, de dènye fonksyonè pòtigè yo mete dife ladan l.","An 1967, fò a akeyi Mize istwa Ouidah la. An 1975, Dahomey pran non Bénin. Apre yo restore l ak èd fondasyon pòtigè Gulbenkian, fò a reouvri an out 1990. Travay restorasyon ki kòmanse an 2020 yo dwe fè l tounen Musée international de la mémoire et de l''esclavage nan lavni."]],"pieces":[{"hier":{"src":"/histoire/rue-1892.webp","largeur":1216,"hauteur":665,"legende":"Yon lari nan Ouidah, gravir 1892"},"auj":null},{"hier":{"src":"/histoire/marche-1930.webp","largeur":1400,"hauteur":1290,"legende":"Mache Ouidah la, bò 1930"},"auj":null},{"hier":{"src":"/histoire/fort-portugais-entree-1917.webp","largeur":600,"hauteur":440,"legende":"Antre fò pòtigè a, an 1917"},"auj":{"src":"/histoire/lieu-musee.webp","largeur":1200,"hauteur":675,"legende":"Mi fò pòtigè yo"}}]},{"id":"souvenir","repere":"1993 – 1998","court":"1993","titre":"Sonje","ville":true,"temps":[["Soti 8 rive 18 fevriye 1993, vil la akeyi festival Ouidah 92, ki konsakre ak atizay ak kilti vodun. Yo te planifye l pou 1992, e li kenbe non sa a. Se prezidan Nicéphore Soglo ki te vle l fèt. Prèt ak vizitè vini sitou soti Brezil, Ayiti ak Trinidad ak Tobago.","Pou okazyon an, forè Kpassè a resevwa estati divinite vodun epi li ouvri pou vizitè ki pa inisye yo."],["Pakou Route des Esclaves la fèt pandan festival sa a. Sis etap, ak eskilti ki fèt sitou pa Cyprien Tokoudagba, mennen soti plas Chacha rive nan plaj la, sou anviwon twa rive kat kilomèt. An septanm 1994, UNESCO lanse nan Ouidah pwogram li « La Route de l''esclave », Ayiti ak peyi afriken te pwopoze. 30 novanm 1995, yo inogire Porte du Non-Retour sou plaj la, nan bout chemen an.","An 1998, yon mach repantans kòmanse, sou inisyativ sosyològ Honorat Aguessy. Twazyèm dimanch janvye a, li soti plas Chacha pou rive nan memoryal Zomachi a, pou mande desandan moun yo te depòte yo padon."]],"pieces":[{"hier":{"src":"/histoire/plaque-ouidah92.webp","largeur":933,"hauteur":1400,"legende":"Plak yo te poze pou Ouidah 92 sou place des Enchères la, an 2017"},"auj":null},{"hier":{"src":"/histoire/memorial-zomachi-2017.webp","largeur":1400,"hauteur":933,"legende":"Memoryal Zomachi a, an 2017"},"auj":null}]},{"id":"fete","repere":"1996 – 2026","court":"2024","titre":"Fèt janvye a","ville":true,"temps":[["An fon, vodun vle di « divinite, lespri ». Se mo sa a ki bay vodou, an Ayiti. 10 janvye 1996, gouvènman Nicéphore Soglo a fè jou sa a tounen yon jou konje peye, pou onore vodun ak relijyon tradisyonèl yo. Yon lwa out 1997 fè l tounen yon fèt anyèl.","Pandan plizyè ane, seremoni ofisyèl 10 janvye a fèt sou plaj Ouidah la, toupre Porte du Non-Retour."],["An oktòb 2023, gouvènman an kreye Vodun Days yo, pou ouvri fèt la bay yon piblik ki soti toupatou nan lemonn. Premye edisyon an fèt nan Ouidah 9 ak 10 janvye 2024, sou senk sit : plas Maro, esplanad Fort français a, plas Temple des Pythons la, yon kouvan Mami tanporè ak forè Kpassè a. Gen prèske 100 000 moun pandan de gwo sware yo.","Depi lwa 2 septanm 2024 la, fèt la tonbe dezyèm vandredi janvye a. Edisyon 2025 ak 2026 yo dire twa jou."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-vodun-days-2024.webp","largeur":1200,"hauteur":675,"legende":"Dansèz devan piblik Vodun Days 2024 yo, nan Ouidah"},"temps":1},{"hier":null,"auj":{"src":"/histoire/collage-zangbeto-meko.webp","largeur":1200,"hauteur":801,"legende":"Zangbéto nan Vodun Days 2026 yo, nan vilaj Mèkô, komin Ouidah"},"temps":1}]},{"id":"route","repere":"1993 – 2025","court":"2025","titre":"Wout la, etap pa etap","ville":true,"temps":[["Istwa yo rakonte nan etap yo soti nan tradisyon. Men trajè prizonye yo jiska lanmè a se yon reyalite ki etabli.","Wout la kòmanse nan plas Chacha, yo rele l tou place aux Enchères. Yon plak yo te poze an 1993 deklare yo te vann prizonye yo la nan vant piblik, anba yon gwo pyebwa. Temwayaj nan epòk la dekri yon lòt bagay : se wa a ki te fikse pri prizonye yo, epi vant yo te pase nan men ajan li yo ak kay komèsan yo, tankou kay de Souza yo, ki bò plas la. Apre yon amenajman resan, plas la se yon esplanad pave jodi a."],["Apre sa vini Arbre de l''Oubli. Dapre tradisyon yo rakonte vizitè yo, gason yo te dwe fè nèf wonn, fanm yo sèt, pou bliye peyi yo. Istwa sa a pa parèt nan okenn dokiman ekri anvan ane 1990 yo. Ansyen tèks yo rele kote sa a Arbre des capitaines : chèf Ouidah yo te resevwa Ewopeyen yo la epi yo te fè twa wonn. Pyebwa orijinal la disparèt."],["Kay Zomaï a pote yon non ki ta vle di « kote dife, oswa limyè, pa antre ». Tradisyon an di yo te fèmen prizonye nan fènwa la. Ekri ki pi ansyen yo mare non sa a ak depo poud pou zam De Souza yo."],["Nan Zoungbodji, gen yon memoryal. Dapre tradisyon an, yo ta antere prizonye ki te mouri anvan depa a nan kote sa a."],["Pi lwen, Arbre du Retour. Tradisyon an di prizonye yo te fè twa wonn, pou nanm yo retounen Lafrik apre lanmò yo. Pa gen okenn sous nan epòk la ki mansyone rit sa a. Se Cyprien Tokoudagba ki fè estati li a."],["Chemen an fini sou plaj la, nan Porte du Non-Retour. Se yon moniman : prizonye yo pa t soti nan yon pwen presi, men depi plaj la, an piròg. Yo ranplase ach 1995 lan. Nouvo pòt la, yo te prezante an desanm 2025, monte plis pase sèz mèt epi li pote plis pase desan eskilti.","Depi 2021, plas la, fò pòtigè a, sit Zoungbodji yo ak plaj Pòt la sou lis pwovizwa Bénin nan UNESCO, yon etap anvan yon posib enskripsyon nan patrimwàn mondyal la."]],"etapes":["Place Chacha","Arbre de l''oubli","Case Zomaï","Zoungbodji","Arbre du retour","Porte du Non-Retour"],"pieces":[{"hier":{"src":"/histoire/place-chacha-2017.webp","largeur":1400,"hauteur":933,"legende":"Plas la an 2017, ak gwo pyebwa li a ak stèl « Place Chacha » a"},"auj":{"src":"/histoire/place-chacha-2025.webp","largeur":1400,"hauteur":787,"legende":"Plas la apre amenajman li, an janvye 2025"}},{"hier":{"src":"/histoire/arbre-oubli-2015.webp","largeur":768,"hauteur":1024,"legende":"Eskilti Arbre de l''oubli a, yo te poze pou Ouidah 92, an 2015"},"auj":null},{"hier":null,"auj":{"src":"/histoire/case-zomai-2019.webp","largeur":809,"hauteur":1400,"legende":"Stèl Case Zomaï a, inogire an fevriye 1993 (foto 2019)"}},{"hier":null,"auj":{"src":"/histoire/visite-zoungbodji.webp","largeur":1200,"hauteur":1200,"legende":"Memoryal Zoungbodji a"}},{"hier":null,"auj":{"src":"/histoire/raison-arbre-du-retour.webp","largeur":800,"hauteur":1200,"legende":"Arbre du retour ak estati li a (foto 2017)"}},{"hier":{"src":"/histoire/porte-1995.webp","largeur":1280,"hauteur":866,"legende":"Ach 1995 lan, foto pran an 2019"},"auj":{"src":"/histoire/eng-5-porte-jour.webp","largeur":675,"hauteur":1200,"legende":"Nouvo Porte du Non-Retour la, prezante an desanm 2025"}}]},{"id":"aujourdhui","repere":"Jodi a","court":"2027","titre":"Retounen","ville":true,"temps":[["Depi lwa 2 septanm 2024 la, yon moun ki desandan Afriken epi ki gen yon zansèt yo te depòte pandan trafik esklav la ka mande nasyonalite beninwa. Prèv la ka soti nan rejis eta sivil, dokiman ofisyèl, temwayaj oswa yon tès ADN, ki pa obligatwa. Yo bay nasyonalite a pa dekrè, sou kondisyon, epi li pase bay desandan yo."],["An 2027, Vodun Days yo fèt soti 2 rive 9 janvye. Fèt relijyon tradisyonèl yo tonbe vandredi 8 la."]],"pieces":[{"hier":null,"auj":{"src":"/histoire/collage-egungun-vodun-days.webp","largeur":800,"hauteur":1200,"legende":"Yon Egungun pandan Vodun Days yo"},"temps":1},{"hier":null,"auj":{"src":"/histoire/visite-cite-historique.webp","largeur":1200,"hauteur":675,"legende":"Antre vil istorik Ouidah la"},"temps":0}]}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:histoire.histoireFinale','{"titre":"Ou mache Route des Esclaves la apye, soti plas Chacha rive nan plaj la.","texte":"Sis etap, sou anviwon twa rive kat kilomèt."}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:histoire.histoirePage','{"metaTitre":"Istwa Ouidah — Ouidah Heritage Tour","metaDescription":"Soti Glexwé rive Ouidah : fò yo, Dahomey, Chacha ak Aguda yo, trafik esklav jiska lanmè a, bazilik la, Route des Esclaves etap pa etap, nouvo Porte du Non-Retour la ak Vodun Days yo.","defiler":"Desann paj la","hier":"Yè","avant":"Anvan","aujourdhui":"Jodi a","chapitres":"Chapit","cartes":{"royaume":{"src":"/histoire/carte-lune.webp","largeur":3146,"hauteur":2421},"ville":{"src":"/histoire/ville-1926-lune.webp","largeur":2400,"hauteur":2118}},"photoFin":"/histoire/fin-porte-nuit.webp","son":{"sources":["/son/histoire-bohicon.webm","/son/histoire-bohicon.m4a"],"volume":0.3,"fondu":4},"carteRoyaume":"Kat wayòm Whidah a, grave nan XVIIIe syèk la","carteVille":"Plan Ouidah an 1926","appel":{"principal":{"label":"Suiv Route des Esclaves la, apye","href":"/devis?circuit=route-des-esclaves"},"secondaire":{"label":"Prepare vwayaj mwen","href":"/devis"}}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.creditsPage','{"intro":"Gen foto sou sit la ak son an fon paj Istwa a ki pibliye sou lisans lib. Mèsi ak otè yo.","modifiee":"adapte","carteSource":"© kontribitè OpenStreetMap yo"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:credits-photos.creditsPhotos','[{"fichier":"/hero/hero-2-porte.jpg","oeuvre":"Nouvo Porte du Non-Retour la, gade sou kote","auteur":"MIA20102","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Nouvelle_Porte_du_Non-Retour_de_Ouidah_-_Vue_lat%C3%A9rale.jpg","modifiee":true},{"fichier":"/ouidah/aeroport-facade.jpg","oeuvre":"Fasad ayewopò Cotonou a","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Fa%C3%A7ade_principale_de_l%27a%C3%A9roport_international_de_Cotonou.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-2-temple-pythons.jpg","oeuvre":"Antre Temple des Pythons","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_Temple_des_Pythons_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/bienvenue-3-plage-cocotiers.jpg","oeuvre":"Plaj Ouidah (Benin, 2013)","auteur":"jbdodane","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Plage_de_Ouidah_(Benin,_2013).jpg","modifiee":true},{"fichier":"/ouidah/collage-danse-atchinan-kpasse.jpg","oeuvre":"Vodoun Atchinan, forè sakre Kpassè (15)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._15.jpg","modifiee":true},{"fichier":"/ouidah/collage-danseur-kpasse.jpg","oeuvre":"Vodoun Atchinan, forè sakre Kpassè (01)","auteur":"Maelan123","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Manifestation_du_vodoun_Atchinan_%C3%A0_la_for%C3%AAt_Sacr%C3%A9e_de_Kpass%C3%A8_._01.jpg","modifiee":true},{"fichier":"/ouidah/collage-egungun-vodun-days.jpg","oeuvre":"Egungun, Vodun Days","auteur":"Romario Coffi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Egungun_Allada_au_B%C3%A9nin_06.png","modifiee":true},{"fichier":"/ouidah/collage-fete-vodoun-2023.jpg","oeuvre":"Fèt vodoun, 10 janvye 2023","auteur":"Dieu229","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:10_Janvier_2023,_F%C3%AAte_de_vodoun_%C3%A0_Ouidah_33.jpg","modifiee":true},{"fichier":"/ouidah/collage-marche-zobe.jpg","oeuvre":"Mache Zobè","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-March%C3%A9_Zob%C3%A9.jpg","modifiee":true},{"fichier":"/ouidah/collage-vodun-days-2024.jpg","oeuvre":"Vodun Days 2024 nan Ouidah","auteur":"Fermi12","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_Edition_2024_%C3%A0_Ouidah_au_B%C3%A9nin_18.jpg","modifiee":true},{"fichier":"/ouidah/collage-zangbeto-meko.jpg","oeuvre":"Zangbéto, Vodun Days 2026, Mèkô","auteur":"Gildas Lissassi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:VODUN_DAYS_2026_au_village_M%C3%A8k%C3%B4,_arrondissement_de_Dj%C3%AAgbadji_et_Commune_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-1-rue-basilique.jpg","oeuvre":"Plas vodun nan ak bazilik la","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_Vodun_place_and_Cathedral.jpg","modifiee":true},{"fichier":"/ouidah/eng-2-musee.jpg","oeuvre":"Mize istwa Ouidah la","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_mus%C3%A9e_d%E2%80%99histoire_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-4-paillote.jpg","oeuvre":"Kay sou plaj Ouidah la","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Habitation_sur_la_plage_%C3%A0_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/eng-7-vendeuses.jpg","oeuvre":"Machann fanm, plaj Ouidah","auteur":"GARNI RAFIK","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vendeuses-_plage_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/raison-arbre-du-retour.jpg","oeuvre":"Arbre du Retour","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Arbre_du_Retour_(1).jpg","modifiee":true},{"fichier":"/ouidah/raison-foret-kpasse.jpg","oeuvre":"Forè sakre Kpassè a","auteur":"Kulttuurinavigaattori","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Sacred_Forest_Ouidah_Benin_Jan_2018.jpg","modifiee":true},{"fichier":"/ouidah/raison-vodun-days.jpg","oeuvre":"Vodun Days, arèn Ouidah","auteur":"Eureka9090","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Vodun_Days_-_Ar%C3%A8ne_de_Ouidah.jpg","modifiee":true},{"fichier":"/ouidah/route-des-peches.jpg","oeuvre":"Route des Pêches","auteur":"Fawaz.tairou","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Route_des_p%C3%AAches_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/ouidah/visite-basilique.jpg","oeuvre":"Bazilik Immaculée-Conception","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Basilique_de_l%27Immacul%C3%A9e_Conception.jpg","modifiee":true},{"fichier":"/ouidah/visite-zoungbodji.jpg","oeuvre":"Mémorial de Zoungbodji","auteur":"Gbehlon","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Le_m%C3%A9morial_de_Zungboji.jpg","modifiee":true},{"fichier":"/histoire/place-chacha-stele-2017.webp","oeuvre":"Place Chacha, stèl ak pòtay (8)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(8).jpg","modifiee":true},{"fichier":"/histoire/maison-du-bresil.webp","oeuvre":"Maison du Brésil, Ouidah (Ouidah 05)","auteur":"Satovgrad","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah_05.jpg","modifiee":true},{"fichier":"/histoire/villa-ajavon-1922.webp","oeuvre":"Villa Ajavon","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_Villa_Ajavon_%C3%A0_Ouidah_au_B%C3%A9nin.jpg","modifiee":true},{"fichier":"/histoire/plaque-ouidah92.webp","oeuvre":"Place Chacha, plak Ouidah 92 (5)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(5).jpg","modifiee":true},{"fichier":"/histoire/memorial-zomachi-2017.webp","oeuvre":"Memoryal Zomachi (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Memorial_Zomachi_(1).jpg","modifiee":true},{"fichier":"/histoire/place-chacha-2017.webp","oeuvre":"Place Chacha, pye fig ak estati (1)","auteur":"Ji-Elle","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:Ouidah-Place_Chacha_(1).jpg","modifiee":true},{"fichier":"/histoire/arbre-oubli-2015.webp","oeuvre":"Pyebwa Bliye a","auteur":"David Stanley","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Tree_of_Forgetting_(21136368019).jpg","modifiee":false},{"fichier":"/histoire/case-zomai-2019.webp","oeuvre":"Kaj Zomaï a, Ouidah","auteur":"Rachad sanoussi","licence":"CC BY-SA 4.0","licenceUrl":"https://creativecommons.org/licenses/by-sa/4.0/","source":"https://commons.wikimedia.org/wiki/File:La_cage_de_Zoma%C3%AF_Ouidah.jpg","modifiee":true},{"fichier":"/histoire/porte-1995.webp","oeuvre":"Pòt San Retou a","auteur":"Francisco Anzola","licence":"CC BY 2.0","licenceUrl":"https://creativecommons.org/licenses/by/2.0/","source":"https://commons.wikimedia.org/wiki/File:Door_of_no_return.jpg","modifiee":true},{"fichier":"/son/histoire-bohicon.webm","oeuvre":"Chante, kay anba tè Agongointo, Bohicon (son an fon paj Istwa a)","auteur":"algoryn, radio aporee ::: maps","licence":"Domèn piblik (PDM 1.0)","licenceUrl":"https://creativecommons.org/publicdomain/mark/1.0/","source":"https://archive.org/details/aporee_34624_39796","modifiee":true},{"fichier":"cartes","oeuvre":"Fon kat","auteur":"© les contributeurs d''OpenStreetMap, OpenMapTiles, OpenFreeMap","licence":"ODbL","licenceUrl":"https://opendatacommons.org/licenses/odbl/","source":"https://www.openstreetmap.org/copyright","modifiee":false}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:legal','{"_note":"Pages légales (mentions, confidentialité et cookies, CGV), en français, éditables depuis l''admin (à venir) : chaque information de la société a une valeur et un interrupteur « visible » ; une information masquée ou vide disparaît de toutes les pages (ligne de fiche, phrase qui la cite). Sources : RCCM, carte professionnelle APIEx, annonce légale (11-12/06/2026) ; Code du numérique du Bénin (loi 2017-20), art. 328 : capital social et adresse du siège sont des mentions obligatoires ; décret 2023-493 art. 38 : référence de la licence obligatoire. Références : Assets OHT/Pages-legales/recherches/REFERENCES.md. Blocs : p (texte, liens [texte](adresse), {clé} de la société), liste, fiche, tableau, composant.","miseAJour":"6 novanm 2026","societe":{"denomination":{"libelle":"Non legal","valeur":"OUIDAH HERITAGE TOUR","visible":true},"forme":{"libelle":"Fòm","valeur":"Sosyete pa aksyon senplifye (SAS)","visible":true},"capital":{"libelle":"Kapital sosyal","valeur":"1 000 000 FCFA","visible":true},"siege":{"libelle":"Syèj sosyal","valeur":"Îlot 1158, parcelle F, maison Sikiratou Moustapha Lawani, quartier Haie Vive-Cocotiers, 12e arrondissement, Cotonou (Littoral), Bénin","visible":true},"quartier":{"libelle":"Katye syèj la (piblik)","valeur":"Haie Vive-Cocotiers","visible":true},"ville":{"libelle":"Vil syèj la (piblik)","valeur":"Cotonou","visible":true},"agence":{"libelle":"Ajans nan Ouidah","valeur":null,"visible":true},"rccm":{"libelle":"RCCM","valeur":"RB/COT/26 B 43278, 11 jen 2026, Tribinal komès Cotonou","visible":true},"ifu":{"libelle":"IFU","valeur":"3202629321372","visible":true},"carte":{"libelle":"Kat pwofesyonèl","valeur":"Kat pwofesyonèl komèsan n° 1310CPC26, APIEx bay, valab jiska 12 jen 2028","visible":true},"licence":{"libelle":"Lisans ajans vwayaj","valeur":null,"visible":true},"activite":{"libelle":"Aktivite","valeur":"Touris ak òganizasyon evènman, aktivite atistik ak kiltirèl","visible":true},"presidente":{"libelle":"Responsab piblikasyon","valeur":"Madanm Nathalie Rosine RIFFERT, Prezidant","visible":true},"telephones":{"libelle":"Telefòn","valeur":["+229 01 98 87 36 36","+229 01 94 35 50 50"],"visible":true},"email":{"libelle":"Imèl","valeur":"contact@ouidahheritagetour.bj","visible":true}},"pages":{"/mentions-legales":{"titre":"Enfòmasyon legal","metaTitre":"Enfòmasyon legal — Ouidah Heritage Tour","metaDescription":"Piblikatè, ebèjman, pwopriyete kontni, kredi foto ak aksesibilite sit Ouidah Heritage Tour la.","intro":"Kiyès ki pibliye sit sa a, kiyès ki loje l ak kiyès pou ekri.","sections":[{"id":"editeur","titre":"Piblikatè a","blocs":[{"fiche":["denomination","forme","capital","siege","agence","rccm","ifu","carte","licence","activite","telephones","email"]}]},{"id":"publication","titre":"Responsab piblikasyon","blocs":[{"p":"{presidente}."}]},{"id":"hebergement","titre":"Lojman","blocs":[{"fiche":[["Sit","Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, Etazini · [vercel.com](https://vercel.com)"],["Baz done","Supabase Pte. Ltd., 65 Chulia Street #38-02/03, OCBC Centre, Singapore 049513 · [supabase.com](https://supabase.com)"]]}]},{"id":"propriete","titre":"Tèks, foto ak logo","blocs":[{"p":"Logo, tèks, ilistrasyon ak prezantasyon paj sit sa a se pwopriyete OUIDAH HERITAGE TOUR oswa otè yo. Pou repran yo, menm yon pati ladan yo, mande nou yon akò alekri anvan nan {email}."},{"p":"Foto ki pibliye sou lisans lib yo itilize dapre kondisyon lisans yo, epi nou site otè yo nan kredi ki anba yo. Fon kat yo se © kontribitè OpenStreetMap yo, sou lisans ODbL."}]},{"id":"credits","titre":"Kredi foto","blocs":[{"composant":"credits"}]},{"id":"accessibilite","titre":"Aksesibilite","blocs":[{"p":"Nou vle tout moun ka li sit sa a epi prepare vwayaj yo. Ou ka navige ak klavye, imaj yo gen deskripsyon, tèks yo gen bon kontras, epi animasyon yo disparèt lè aparèy ou mande mwens mouvman."},{"p":"Yon pasaj difisil pou li oswa yon bouton ki pa mache ? Ekri nou nan {email} epi presize paj la : n ap reponn ou epi korije l."}]},{"id":"liens","titre":"Lyen pou lòt sit","blocs":[{"p":"Pafwa sit la mennen sou sit ofisyèl oswa sit patnè, pa egzanp pou viza oswa yon evènman. Se piblikatè yo ki responsab kontni sit sa yo."}]},{"id":"droit","titre":"Lalwa ki aplikab","blocs":[{"p":"Sit sa a soumèt ak lalwa beninwa. Pou yon rezèvasyon oswa yon kòmann, [kondisyon jeneral lavant yo](/conditions-generales-de-vente#litiges) presize kijan pou rezoud yon dezakò."}]}]},"/politique-de-confidentialite":{"titre":"Konfidansyalite ak bonbon","metaTitre":"Konfidansyalite ak bonbon — Ouidah Heritage Tour","metaDescription":"Done Ouidah Heritage Tour ranmase yo, poukisa, pou konbyen tan, sa sit la kenbe nan navigatè ou ak kijan pou egzèse dwa ou yo.","intro":"Sa nou ranmase, poukisa, pandan konbyen tan, ak kijan pou egzèse dwa ou. Nou pa vann okenn done epi sit la pa montre piblisite. Nou konte vizit yo sèlman avèk akò ou.","sections":[{"id":"responsable","titre":"Kiyès ki responsab done ou yo","blocs":[{"p":"{denomination}, {forme}, ki gen syèj sosyal li nan {siege}."},{"p":"Pou nenpòt kesyon sou done ou yo, ekri nan {email} ak sijè « Done pèsonèl », oswa voye yon lèt nan syèj la."}]},{"id":"donnees","titre":"Sa nou ranmase ak poukisa","blocs":[{"p":"Sèlman sa ou ban nou nan yon fòm, epi sèlman pou rezon ki endike a."},{"tableau":{"colonnes":["Kilè","Done","Poukisa","Pou konbyen tan"],"lignes":[["Ou mande yon devis (« Kreye vwayaj mwen »)","Non, imèl, WhatsApp si ou bay li, peyi, lang gid la, vwayaj ou (dat, kote, sèvis ou chwazi), mesaj ou","Reponn demann ou an epi prepare devis ou, jan ou mande a","3 ane apre dènye echanj nou si pa gen rezèvasyon apre sa"],["Ou konsève demann ou an pou reprann li pita","Vwayaj ou ak repons ou yo, san enfòmasyon kontak ou","Voye lyen pou reprann lan ba ou epi jwenn demann ou an ankò","Lyen an valab 30 jou ; yon bouyon ou pa janm voye efase 90 jou apre kreyasyon li"],["Ou rezève yon tikè oswa yon sejou","Non, imèl, telefòn, peyi, lang, fòmil, kantite plas, montan, mwayen peman ak referans tranzaksyon an","Fè rezèvasyon ou, tikè ou ak fakti ou","10 ane, dire konsèvasyon dokiman kontab yo"],["Ou fè kòmann nan boutik la","Prenon, non, imèl, telefòn, peyi, adrès livrezon si ou chwazi livrezon, atik ak opsyon, mesaj ou","Konfime, prepare ak livre kòmann ou an","10 ane, dire konsèvasyon dokiman kontab yo"],["Ou abòne ak Lèt Ouidah la","Imèl, lang, sijè ou chwazi, dat akò ou","Voye lèt la ba ou, avèk akò ou","Jiskaske ou dezabòne, sa posib nenpòt lè depi chak lèt oswa pa imèl"],["Ou voye yon fòm","Yon anprent kriptografik adrès IP ou, pa janm adrès la menm","Limite mesaj otomatik epi pwoteje sèvis la","Menm dire ak demann li asosye avè l la"]]}},{"p":"Fòm randevou ak aplikasyon patnè yo ranmase kowòdone ou ak enfòmasyon ou antre yo pou ekip nou an ka òganize randevou a oswa egzamine aplikasyon ou. Imèl nou resevwa yo ka tache ak demann ou pou ekip la ka swiv li."}]},{"id":"paiement","titre":"Peman","blocs":[{"p":"Ou peye atravè pòtay peman ou chwazi pami sa nou pwopoze yo : Kkiapay, FedaPay, Stripe, Flutterwave oswa Paystack. Nou pa wè ni kenbe nimewo kat ou oswa kòd Mobile Money ou : nou resevwa montan an, estati peman an ak referans li."}]},{"id":"destinataires","titre":"Kiyès ki resevwa done ou yo","blocs":[{"liste":["Ekip Ouidah Heritage Tour la ki prepare vwayaj ou oswa kòmann ou an.","Founisè teknik nou yo, pou sèvis sa a sèlman : Vercel (ebèjman sit la epi, si ou aksepte, mezi vizit yo, Etazini), Supabase (baz done), sèvis imèl nou an {email}, AfriRegister loje (voye imèl konfimasyon, devis ak tikè), pòtay peman ou chwazi a ak Groq, Inc. (asistan IA sit la, Etazini).","Patnè sejou ou yo (lojman, transpò, gid), sèlman pou sa yo bezwen : non ou, dat ou yo ak kantite vwayajè yo."]},{"p":"Nou pa vann ni lwe done ou yo, epi nou pa itilize yo pou piblisite."}]},{"id":"transferts","titre":"Done andeyò Bénin","blocs":[{"p":"Gen founisè nou yo ki enstale andeyò Bénin, sitou Etazini ak Singapore. Nou sèlman ba yo sa ki nesesè pou sèvis yo bay la, dapre angajman kontra yo pran pou pwoteje done yo."}]},{"id":"navigateur","titre":"Sa sit la kenbe nan navigatè ou","blocs":[{"p":"Pou ou pa pèdi anyen lè w pase soti nan yon paj ale nan yon lòt, sit la kenbe kèk enfòmasyon nan navigatè ou. Yo rete sou aparèy ou epi yo rive jwenn nou sèlman si ou voye yon fòm. Yo nesesè pou sit la fonksyone."},{"liste":["Dosye vwayaj ou : kote, sikwi, dat, sèvis ak tikè ou chwazi.","Demann devis ou poko fini an, ansanm ak non ak imèl ou deja antre yo, pou ou pa bezwen tape yo ankò.","Lajan ou chwazi a ak panye boutik la.","Enfòmasyon retou yon peman k ap fèt, ki efase lè ou fèmen onglet la.","Endikasyon ou deja wè ouvèti sit la, ki efase lè ou fèmen onglet la.","Chwa ou yo pou sèvis fakiltatif ki anba yo."]},{"p":"Sit la pa depoze okenn bonbon piblisite ni bonbon pou mezire vizit. Pou efase tout, efase done sit sa a nan paramèt navigatè ou."}]},{"id":"assistant","titre":"Asistan sit la ak diskisyon ak ekip la","blocs":[{"p":"Asistan IA OHT la reponn kesyon ou yo dapre kontni ki pibliye sou sit sa a sèlman. Pou pwodui chak repons, mesaj ou ak dènye echanj nan konvèsasyon an ale jwenn soutretan nou Groq, Inc., nan Etazini ; nou pa voye yo pou okenn lòt bagay. Konvèsasyon an efase lè ou kite paj la, oswa apre 30 minit san aktivite. Si ou bay asistan an enfòmasyon ekip nou an dwe aji sou yo (pwojè vwayaj, demann devis, enfòmasyon kontak, plent, kesyon ki rete san repons), li transmèt yon rezime bay ekip la : se sèlman rezime sa a ki konsève, pandan 90 jou. Si ou chwazi ekri yon moun nan ekip la, konvèsasyon an ak imèl oswa nimewo WhatsApp ou kite pou nou rekontakte ou rete lakay nou pandan 90 jou, apre sa yo efase ; yon konvèsasyon ki tounen yon demann suiv dire konsèvasyon demann yo. Kesyon asistan an pa t ka reponn yo konsève san adrès IP ou ni okenn idantifyan, apre nou retire imèl, nimewo ak non yo gen ladan yo, pou ekip nou an reponn yo epi konplete sa asistan an konnen. Adrès IP ou konsève sèlman kòm yon anprent, pou aplike limit itilizasyon yo (kantite mesaj). Ou ka mande aksè, koreksyon oswa efasman done ou yo nan {email}."}]},{"id":"cookies","titre":"Sèvis fakiltatif, jan ou chwazi","blocs":[{"p":"Twa sèvis transmèt done bay yon twazyèm pati oswa konte vizit ou yo. Yo kòmanse sèlman avèk akò ou, epi refize pa anpeche ou jwenn okenn paj."},{"fiche":[["Kat entèaktif","Fon kat yo soti nan OpenFreeMap, ki resevwa adrès IP ou. Si ou refize : kat la parèt kòm imaj."],["Vil apwoksimatif","Founisè ebèjman nou an, Vercel, dedui vil ou dapre adrès IP ou ; si sa pa posib, sèvis Open-Meteo dedui li dapre zòn lè ou. Li sèvi pou montre kote Ouidah ye parapò ak lakay ou epi li rete nan navigatè ou. Si ou refize : ou antre l ou menm."],["Mezi vizit","Paj yo gade yo, kontè OHT ak Vercel Web Analytics (Etazini) konte yo san bonbon ni idantifyan, pou konnen sa ki enterese vizitè nou yo. Si ou refize : anyen pa konte."]]},{"p":"Ou ka chanje lide nenpòt lè isit oswa ak lyen « Bonbon » ki anba chak paj."},{"composant":"choixCookies"}]},{"id":"securite","titre":"Sekirite","blocs":[{"p":"Sit la sèvi ak HTTPS. Se sèlman moun ki bezwen baz done nou yo ki ka jwenn aksè ladan yo. Lyen pou reprann yon demann ak tikè yo siyen ; nou kenbe sèlman anprent yon lyen, pa janm lyen an menm."}]},{"id":"droits","titre":"Dwa ou yo","blocs":[{"p":"Ou ka jwenn aksè nan done ou yo nenpòt lè, fè korije oswa efase yo, opoze ak itilizasyon yo, mande yon kopi nan yon fòma ki ka li, epi retire akò ou pou Lèt la oswa sèvis fakiltatif yo."},{"p":"Ekri nan {email} ak sijè « Done pèsonèl ». Nou ka mande ou konfime idantite ou, apre sa n ap reponn ou nan 30 jou."},{"p":"Si repons nou an pa satisfè ou, ou ka kontakte Autorité de Protection des Données à caractère Personnel (APDP) : Rue 6.076, Aïdjèdo, immeuble El Marzouk Joël, 01 BP 04837 Cotonou, Bénin · +229 21 32 57 88 · contact@apdp.bj · [apdp.bj](https://apdp.bj)."},{"p":"Ou kapab itilize [Done mwen yo](/mes-donnees) tou pou resevwa yon lyen pèsonèl nan adrès imèl ou. Lyen sa a pèmèt ou telechaje done ou oswa voye yon demann pou efase yo bay ekip la. Nou konsève dokiman ki nesesè pou swiv peman yo ak pou kontablite."}]},{"id":"mineurs","titre":"Minè","blocs":[{"p":"Rezèvasyon nou yo fèt pou granmoun. Yon minè ki poko gen 16 an ka transmèt done li yo sèlman avèk akò yon paran."}]},{"id":"modifications","titre":"Mizajou","blocs":[{"p":"Dat dènye mizajou a anlè paj sa a. Si yon chanjman touche yon rezèvasyon k ap fèt, n ap ekri ou."}]}]},"/conditions-generales-de-vente":{"titre":"Kondisyon jeneral lavant","metaTitre":"Kondisyon jeneral lavant — Ouidah Heritage Tour","metaDescription":"Tikè evènman, sejou sou devis ak boutik Ouidah Heritage Tour : pri, peman, dwa chanje lide, anilasyon, livrezon, retou ak konfli.","intro":"Règ ki aplike lè ou rezève yon tikè, yon sejou oswa fè kòmann nan boutik la. Gen yon pwen ki pa klè ? Ekri nou anvan ou rezève.","sections":[{"id":"champ","titre":"Sou ki sa kondisyon sa yo aplike","blocs":[{"p":"Yo aplike sou lavant {denomination}, {forme} (gade [enfòmasyon legal yo](/mentions-legales)) :"},{"liste":["tikè evènman nou òganize yo ;","sejou, sikwi ak akonpayman ki prepare sou devis, ansanm ak sa ki fèt bò kote yon evènman lòt moun òganize ;","atik boutik la."]},{"p":"Ou aksepte yo lè ou konfime rezèvasyon ou oswa kòmann ou an. Se vèsyon ki anvigè jou sa a ki rete aplikab pou ou."}]},{"id":"prix","titre":"Pri ak peman","blocs":[{"liste":["Pri yo gen tout taks ladan yo, an fran CFA (XOF). Pri ki parèt an ewo yo suiv to fiks 1 € = 655,957 FCFA.","Pou boutik la, frè livrezon ajoute sou pri atik yo epi nou fè ou konnen yo anvan nenpòt peman.","Ou peye yon sèl kou, san avans, atravè youn nan pòtay peman yo pwopoze lè w ap peye a. Nou pa janm resevwa done kat ou."]}]},{"id":"retractation","titre":"Dwa ou pou chanje lide","blocs":[{"p":"Ou gen 15 jou ouvrab pou chanje lide, san ou pa bezwen bay rezon : depi peman ou pou yon tikè oswa yon sejou, depi resepsyon pou yon atik. Ekri nou nan {email} ; n ap remèt tout lajan ou nan 14 jou, atravè mwayen peman ou te itilize a."},{"p":"Dwa sa a pa aplike ankò pou yon tikè oswa yon sejou ki deja fin fèt, ni pou atik yo fè sou mezi oswa pèsonalize sou demann ou."}]},{"id":"billets","titre":"Tikè evènman","blocs":[{"liste":["Ou rezève nan kalandriye sit la : fòmil, kantite plas ak enfòmasyon kontak, apre sa peman.","Nou voye tikè ou pa imèl, sou non ou ak yon kòd QR, depi pòtay peman an konfime peman an ban nou. Prezante l sou telefòn ou oswa enprime ; chak kòd QR bay aksè yon sèl fwa.","Ou pa ka vini ? Apre delè pou chanje lide a, nou remèt tout lajan ou jiska 30 jou anvan evènman an ak mwatye ant 30 ak 8 jou anvan. Pi ta, bay yon lòt moun plas ou : nou mete tikè a sou non moun ou chwazi a, san frè, jiska 48 èdtan anvan.","Si nou anile oswa ranvwaye evènman an, ou chwazi ant ranbousman total ak plas ou nan nouvo dat la."]}]},{"id":"sejours","titre":"Sejou ak akonpayman sou devis","blocs":[{"liste":["Demann devis ou a gratis epi li pa angaje ou. Devis la detaye sèvis yo, dat yo, sa ki ladan l ak pri total la. Li rete valab 15 jou.","Rezèvasyon ou konfime lè ou aksepte devis la epi peye montan li yon sèl kou. Lè sa a, nou voye konfimasyon ekri vwayaj ou ba ou.","Pou yon sejou bò kote yon evènman lòt moun òganize, tankou Vodun Days yo, nou vann sejou a, pa evènman an. Pwogram li depann de òganizatè li yo ; si li chanje, n ap adapte sejou ou ansanm avè w.","Ou vle chanje dat ou yo oswa sèvis ou yo ? Di nou sa : n ap ajiste selon disponibilite yo, epi diferans pri a ajoute oswa nou remèt li ba ou.","Apre delè pou chanje lide a, si ou anile, nou remèt tout lajan ou jiska 45 jou anvan arive a, apre nou retire frè nou deja peye patnè nou yo ki pa ranbousab, ak prèv nou ba ou ; mwatye ant 45 ak 15 jou anvan ; mwens pase 15 jou anvan, nou pwopoze ou ranvwaye sejou ou selon disponibilite yo.","Si nou oblije anile, nou remèt tout lajan ou oswa nou pwopoze yon lòt sejou, jan ou chwazi.","Se ou ki responsab paspò a, viza a ak sètifika vaksen kont lafyèv jòn nan : seksyon « Prepare vwayaj ou » a gide ou. Nou konseye anpil pou ou pran asirans vwayaj, ansanm ak rapatriman.","Nou responsab pou sèvis nou vann yo fèt kòrèkteman. Vòl ou rezève ou menm yo pa antre nan responsablite nou."]}]},{"id":"boutique","titre":"Boutik","blocs":[{"liste":["Kòmann ou an se yon demann dabò. Nan 2 jou travay, nou konfime pa imèl disponibilite a, fason ou resevwa l ak montan total la, frè ladan l.","Ou peye yon sèl kou apre konfimasyon sa a ; vant lan konkli lè nou resevwa peman an.","Atik sou mezi oswa pèsonalize yo fèt apre peman an, nan delè ki endike nan konfimasyon an."]}]},{"id":"livraison","titre":"Livrezon ak retou","blocs":[{"liste":["Vin pran nan Ouidah, san frè : kote a ak orè yo nan konfimasyon an.","Livrezon nan Bénin ak nan peyi yo pwopoze lè w ap fè kòmann nan. Frè yo depann de peyi a ak pakè a ; nou fè ou konnen yo anvan peman an.","Delè estimatif depi ekspedisyon an : 2 rive 5 jou travay nan Bénin, 5 rive 10 nan Afrik Lwès, 7 rive 21 lòt kote. Nou voye enfòmasyon pou suiv pakè a ba ou.","Andeyò Bénin, se moun k ap resevwa a ki responsab dwa ak taks enpòtasyon ki ta genyen.","Retou yon atik : nan 15 jou ouvrab apre ou resevwa l, nan eta orijinal li. Nou remèt lajan atik la ak frè livrezon orijinal yo nan 14 jou apre nou resevwa l ; se ou ki peye frè retou yo. Yon echanj tay oswa koulè posib nan menm delè a, selon estòk la.","Yon atik domaje oswa diferan ak kòmann ou an : fè nou konnen sa nan 7 jou apre ou resevwa l, ak foto kòm prèv. Nou chanje l, repare l oswa remèt ou lajan an, se nou ki peye frè yo.","Nou pa repran ni chanje atik sou mezi oswa pèsonalize yo, sof si yo gen yon defo."]}]},{"id":"donnees","titre":"Done ou yo","blocs":[{"p":"Sa nou fè ak enfòmasyon kontak ou yo dekri nan paj [Konfidansyalite ak bonbon](/politique-de-confidentialite)."}]},{"id":"litiges","titre":"Plent ak konfli","blocs":[{"p":"Pou nenpòt plent, kontakte nou : {telephones} · {email}. N ap reponn ou nan 7 jou travay epi n ap chèche yon antant avè w dabò."},{"p":"Ou ka voye yon plent tou bay administrasyon beninwa ki responsab touris la."},{"p":"Kondisyon sa yo soumèt ak lalwa beninwa ; si pa gen antant, se Tribinal komès Cotonou ki gen konpetans. Si ou rete andeyò Bénin, ou kenbe pwoteksyon lalwa peyi ou ba ou, tankou dwa pote ka a devan jij kote ou rete a lè lalwa prevwa sa."}]}]}}}'::jsonb,1,now()) on conflict(cle) do nothing;
