insert into public.contenu_site(cle,valeur,version,publie_le) values('HT:fr.consentement','{"titre":"Chwa ou yo sou sit sa a","court":"Kat entèaktif ak vil apwoksimatif : se ou ki chwazi.","accepter":"Aksepte tout","refuser":"Refize tout","choisir":"Chwazi","enregistrer":"Anrejistre chwa mwen yo","fermer":"Fèmen","toujours":"Toujou aktif","politique":{"label":"Konfidansyalite ak bonbon","href":"/politique-de-confidentialite"},"categories":[{"id":"necessaires","nom":"Nesesè","texte":"Dosye vwayaj ou, lajan ou chwazi a, panye a ak retou peman an, konsève nan navigatè ou."},{"id":"cartes","nom":"Kat entèaktif","texte":"Fon kat yo soti nan OpenFreeMap, ki resevwa adrès IP ou. Si ou refize : kat la parèt kòm imaj."},{"id":"ville","nom":"Vil apwoksimatif","texte":"Founisè ebèjman nou an dedui vil ou dapre adrès IP ou, pou montre kote Ouidah ye parapò ak lakay ou. Li rete nan navigatè ou. Si ou refize : ou antre l ou menm."},{"id":"mesure","nom":"Mezi vizit","texte":"Paj yo gade yo, kontè OHT ak Vercel Web Analytics (Etazini) konte yo san bonbon ni idantifyan, pou konnen sa ki enterese vizitè nou yo. Si ou refize : anyen pa konte."}],"lienPied":"Bonbon","afficherCarte":"Montre kat entèaktif la"}'::jsonb,1,now()) on conflict(cle) do nothing;
