insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:site.seo','{"titre":"Ouidah Heritage Tour · Vwayaj Ouidah, Bénin","description":"Dékouvè Ouidah, patrimwàn li épi koté mémwa li épi Ouidah Heritage Tour. Sikwi, événman épi vwayaj préparé épi lékip ki la a.","image":{"src":"/brand/oht-embleme.webp","alt":"Ouidah Heritage Tour"},"pages":[]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.hero','{"kicker":["Ajans touris mémwa épi kilti","Ouidah, Bénin"],"title":{"lead":"Ouidah,","accent":"lavil Vodun épi mémwa"},"sub":"Maché asou Route des Esclaves, dépi laplas Chacha jik Porte du Non-Retour, douvan Latlantik.","images":[{"src":"/hero/hero-4-plage.jpg","alt":"Plaj Ouidah wè dépi anlè : lanm Latlantik, sab doré épi pyé koko"},{"src":"/hero/hero-2-porte.jpg","alt":"Nouvo Porte du Non-Retour Ouidah, wè asou koté"}],"search":{"action":"/#chemins","label":"Chèché an sikwi","submit":"Chèché","fields":[{"name":"lieu","label":"Destinasion","objet":"destination","options":[{"value":"","label":"Tout Ouidah"},{"value":"musee-histoire","label":"Musée d''histoire de Ouidah"},{"value":"temple-des-pythons","label":"Temple des Pythons"},{"value":"route-des-esclaves","label":"La Route des Esclaves"},{"value":"porte-du-non-retour","label":"Porte du Non-Retour"}]},{"name":"type","label":"Kalité vwayaj","objet":"type-voyage","options":[{"value":"","label":"Tous les types"},{"value":"memoire","label":"Mémoire"},{"value":"spiritualite","label":"Spiritualité"},{"value":"nature","label":"Nature"},{"value":"diaspora","label":"Diaspora"}]},{"name":"duree","label":"Diré","objet":"calendrier","options":[{"value":"","label":"Tout diré"},{"value":"demi-journee","label":"An dimi-jounen"},{"value":"journee","label":"An jounen"},{"value":"plusieurs-jours","label":"Pliziè jou"}]}]},"primary":{"label":"Wè sé sikwi nou an","href":"/#chemins"},"secondary":{"label":"Préparé vwayaj mwen dapré sa mwen lé","href":"/devis"},"facts":[{"value":"1721","label":"Fò pòtigé a, ki vini an mizé listwa"},{"value":"4 km","label":"Dépi laplas Chacha jik laplaj, pa Route des Esclaves"},{"value":"2025","label":"Nouvo Porte du Non-Retour"},{"value":"23 out","label":"Jounen mémwa trafik èsklav nwa"}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.welcome','{"label":"Kilès nou yé","title":["Bienvini lakay zot,","an tjè Listwa zot."],"paragraphs":["Ouidah Héritage Tour sé plis ki an ajans : sé an angajman pou an touris ki ni rèsponsabilité é ki mété moun an tjè''y.","Nou ka envité zot viv Ouidah toupré nanm li, an destinasion koté listwa, lèspiritualité, kilti, la épi lanati ka jwenn pou fè zot viv an lèkspérians vré.","Chak vwayaj ni manniè''y : lékip nou ka gadé sa ki ka entérésé zot, sa zot ka atann é sa zot bizwen. Nou ka akonpann zot avan, pandan épi apré vwayaj-la."],"link":{"label":"Listwa Ouidah","href":"/ouidah/histoire"},"portrait":{"src":"https://images.pexels.com/photos/8655018/pexels-photo-8655018.jpeg?auto=compress&cs=tinysrgb&w=1600","alt":"An jenn fanm ka ranjé twèl wax koulè an maché-a"},"caption":null}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.welcomeStatement','{"kicker":"Ouidah Heritage Tour · Kilès nou yé","segments":[{"text":"Bienvini lakay zot,"},{"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Porte du Non-Retour kléré lannuit"},"ring":"sun"},{"text":"an tjè Listwa zot,"},{"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Lantwé pentiré Temple des Pythons"},"ring":"abyss"},{"text":"dépi Route des Esclaves"},{"image":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Plaj Ouidah lè solèy ka kouché"},"ring":"sun"},{"text":"jik loséan."}],"columns":[{"title":"Mémwa épi kilti","text":"Nou sé an ajans touris mémwa épi kilti. Nou ka mennen zot a pyé asou Route des Esclaves, épi an gid ki ka rakonté chak létap."},{"title":"Sé koté-a zot ka chwazi a","text":"Temple des Pythons douvan bazilik-la, laforé sakré Kpassè, maché Zobè, lagin-lan an kannòt. Nou ka préparé séjou zot épi sé koté-a ki ka palé ba zot la."},{"title":"Dépi laéwopò-a jik Ouidah","text":"Navèt dépi laéwopò Cotonou, lojman, rèstoran, loto : nou ka òganizé épi zot tout sa ki ka antouré vizit-la, avan, pandan épi apré vwayaj-la."}]}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.placesIntro','{"kicker":"Kat-la · Dépi lavil jik loséan","title":"Ouidah an kat koté","titleParts":{"before":"Ouidah an","number":"4","spoken":"kat","after":"koté."},"intro":"Fè paj-la désann : trajé-a ka désiné asou kat-la, dépi fò pòtigé-a jik Porte du Non-Retour, an lari lavil-la.","link":"Wè koté-a","walked":"km ja fèt","mapLabel":"Kat Ouidah épi sé kat koté-a é chimen a pyé ki ka lianné yo"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.reasonsIntro','{"kicker":"Ouidah Heritage Tour · Angajman nou","title":"Sèt angajman nou ka tjenbé asou téren-an.","intro":"Sa zot pé atann di nou, dépi prèmié kèsion-an jik lè zot viré.","of":"asou"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.reasons','[{"title":"An péyi nou konnèt byen","text":"Dépi fò pòtigé-a jik laplaj, sé gid nou an ka mennen zot a pyé.","couleur":"sun"},{"title":"Dé bagay vérifié","text":"Sé rakontaj vizit-la ka apiyé asou listwa trafik èsklav ki ni dokiman pou''y.","image":{"src":"/ouidah/eng-2-musee.jpg","alt":"Lantwé mizé listwa Ouidah, an fò pòtigé-a"}},{"title":"Listwa zot an prèmié","text":"Sikwi zot ka préparé alantou listwa zot épi sé kèsion zot la.","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Lantwé pentiré Temple des Pythons"}},{"title":"Patnè péyi-a","text":"Lojman, rèstoran, gid épi atizan péyi-a : nou ka chwazi sé ladwès séjou-a épi zot.","couleur":"abyss"},{"title":"Pou ladiaspora","text":"Sikwi Retour aux sources nou an ka mennen désandan Afriken dépi fò-a jik Porte du Non-Retour.","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour douvan loséan, an plen lajounen"}},{"title":"Avan, pandan, apré","text":"Répons an 24 lè, akèy lè zot rivé, swivi jik zot viré.","image":{"src":"/ouidah/eng-6-route-peches.jpg","alt":"Route des Pêches, épi pyé koko bò''y, Ouidah"}},{"title":"Pou sé moun péyi-a","text":"Nou ka patisipé an fòmasion sé moun ki ka travay an touris péyi-a é nou ka fè moun konnèt yo.","couleur":"laterite"}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.tenIntro','{"title":["Sa lavil-la séré ba zot,","dépi mémwa jik loséan."],"link":{"label":"Dékouvè yo","href":"/#raisons"},"place":"Ouidah","discover":"Dékouvè koté-a","circle":"Fè an won alantou","circled":"Matjé épi an won","path":{"label":"Wè chimen mwen","href":"#chemins"},"stripLabel":"Sé vi-a, dépi mémwa jik loséan","filmEdge":"OUIDAH 400"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.tenReasons','[{"slug":"route-des-esclaves","title":"Route des Esclaves","short":"Route des Esclaves","category":"Mémwa","image":{"src":"/ouidah/raison-arbre-du-retour.jpg","alt":"Arbre du Retour, dènié létap Route des Esclaves avan laplaj"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/place-chacha","lieux":["place-chacha","arbre-de-l-oubli","arbre-du-retour"],"text":"Dépi laplas Chacha, koté yo té ka vann moun an lanchè, jik laplaj : apéprè 4 km, chimen sé kaptif-la té ka fè pou rivé bò bato. Nou ka pasé bò Arbre de l''Oubli, koté yo té ka fè yo tounen pou éfasé non yo épi koté yo sòti, bò sé Cases Zomaï-a, koté yo té ka fèmen yo an nwèsè, bò mémorial Zoungbodji, épi bò Arbre du Retour, pou nanm yo viré. Nou ka fè chimen-an a pyé épi an gid ki ka rakonté chak létap."},{"slug":"porte-du-non-retour","title":"Porte du Non-Retour","short":"Porte du Non-Retour","category":"Mémwa","image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour douvan loséan, an plen lajounen"},"credit":null,"href":"/ouidah/lieux/porte-du-non-retour","lieux":["porte-du-non-retour"],"text":"An bout Route des Esclaves, asou laplaj, douvan Latlantik. I ka matjé koté yo fòsé milyon Afriken monté abo bato. Prèmié lawch-la, yo té inogiré 30 novanm 1995 gras a linisiativ UNESCO, kité plas an désanm 2025 ba an pòt pli wo. Nou ka rivé la a pyé, apré sé létap chimen-an, é nou ka rété la an ti moman, douvan lanmè."},{"slug":"temple-des-pythons","title":"Temple des Pythons","short":"Temple des Pythons","category":"Lafwa","image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Lantwé pentiré Temple des Pythons"},"credit":"Rachad sanoussi, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/temple-des-pythons","lieux":["temple-des-pythons"],"text":"Sanktjè vodun pou kil sèpan Dangbé, moun ka atesté dépi lafen XVIIᵉ sièk-la, koté piton sakré ka viv. Tanp-la douvan bazilik Imakilé-Konsèpsion-an : dé lafwa ka viv yonn bò lòt, chak asou an bò menm laplas-la. Vizit-la ka fèt épi rèspé pou règ koté-a."},{"slug":"basilique","title":"Bazilik-la, douvan tanp-lan","short":"Bazilik","category":"Lafwa","image":{"src":"/ouidah/visite-basilique.jpg","alt":"Bazilik Immaculée-Conception Ouidah"},"credit":"Ji-Elle, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/basilique","lieux":["basilique"],"text":"Bazilik Immaculée-Conception, prensipal koté katolik Ouidah ka priyé, té bati dépi 1903 jik 1909, épi i vini an bazilik minè an 1989. I doubout douvan Temple des Pythons : Ouidah, pou pasé yonn a lòt, sé anni travèsé an laplas."},{"slug":"musee-histoire","title":"Mizé fò pòtigé-a","short":"Mizé listwa","category":"Listwa","image":{"src":"/ouidah/lieu-musee.jpg","alt":"Fò pòtigé Ouidah, koté mizé listwa-a yé"},"credit":null,"href":"/ouidah/lieux/musee-histoire","lieux":["musee-histoire"],"text":"Fò pòtigé São João Baptista de Ajudá, bati an 1721, ka risivwè mizé listwa lavil-la dépi 6 sèptanm 1967 : latrèt, wayòm, lyannaj épi Brézil épi Lézamérik, atravè apepré 700 pyès. Travay ka fèt asou sit-la pou risivwè Musée international de la mémoire et de l''esclavage : nou ka di zot sa ki ouvè avan zot vini."},{"slug":"foret-sacree-kpasse","title":"Laforé sakré Kpassè","short":"Laforé Kpassè","category":"Lanati","image":{"src":"/ouidah/raison-foret-kpasse.jpg","alt":"An eskilti vodun anba sé gran pyébwa laforé sakré Kpassè a"},"credit":"Kulttuurinavigaattori, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/foret-sacree-kpasse","lieux":["foret-sacree-kpasse"],"text":"An ti mòso laforé 4 èkta an mitan lavil-la, ki lyanné épi wa Kpassè. Laforé-a ni divinité vodun épi eskilti, épi sé la sérémoni ka fèt, sitou pannan Vodun Days. Nou ka antré pa an pòtay pentiré, épi nou ka maché anba sé gran pyébwa-a."},{"slug":"vodun-days","title":"Vodun Days","short":"Vodun Days","category":"Lafèt","image":{"src":"/ouidah/raison-vodun-days.jpg","alt":"An Egungun adan larèn Ouidah pannan Vodun Days"},"credit":"Eureka9090, Wikimedia Commons, CC BY-SA 4.0","href":"/#agenda","lieux":[],"text":"Chak koumansman janvyé, Ouidah ka risivwè gran randévou lanné-a pou kilti vodun : sérémoni, dans ritiyèl, lèkspozisyon épi rankont, an rèspé sé règ kominoté-a mété a. Gran sérémoni-a épi sé konsè-a ka fèt asou laplaj-la, épi lòt moman adan laforé Kpassè. Nou pa ka òganizé lévénman-an : nou ka òganizé séjou zot alantou''y."},{"slug":"memorial-zoungbodji","title":"Mémoryal Zoungbodji","short":"Zoungbodji","category":"Mémwa","image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Mémoryal Zoungbodji, asou Route des Esclaves"},"credit":"Gbehlon, Wikimedia Commons, CC BY-SA 4.0","href":"/ouidah/lieux/memorial-zoungbodji","lieux":["memorial-zoungbodji"],"text":"Mémoryal vilaj Zoungbodji ka matjé dènyé koté moun yo té kaptiré té ka rété avan yo anbarké yo, bò fòs komen koté yo té ka jété sé mò-a. Sé létap ki pi lou asou Route des Esclaves, apepré 2 km dépi laplaj-la épi Porte du Non-Retour. Nou ka fè an ti kanpé la avan nou jwenn lanmè-a."},{"slug":"marches","title":"Atizan, maché, manjé","short":"Maché","category":"Savè","image":{"src":"/ouidah/eng-7-vendeuses.jpg","alt":"Machann fanm ka pòté machandiz yo adan an lari Ouidah"},"credit":"GARNI RAFIK, Wikimedia Commons, CC BY-SA 4.0","href":null,"lieux":["r:marche-de-zobe"],"text":"Maché Zobè, bò fò pòtigé-a, épi ta katjé Kpassè ka bay lavi lavil-la ritm li. Gid nou ka mennen zot la, lakay sé atizan-an épi adan sé bon koté manjé Ouidah-la, dépi sé maki-a jik sé rèstoran-an. Sé lavil jòdi-a, tala ki ka viv ant dé vizit."},{"slug":"plage-et-lagune","title":"Laplaj-la épi lagin-la","short":"Laplaj épi lagin","category":"Loséan","image":{"src":"/hero/hero-4-plage.jpg","alt":"Laplaj Ouidah wè dépi syèl-la, lanm Latlantik épi pyé koko"},"credit":null,"href":null,"lieux":["route-des-peches","r:lagune-de-ouidah"],"text":"An bout Route des Esclaves, ni an long laplaj ki poko ni anpil aménajman, koté gran sérémoni-a épi konsè Vodun Days ka fèt. Dèyè''y, lagin-la ka séparé lavil-la épi loséan-an : sé yonn adan sé ékosistèm bò lanmè ki pi enpòtan Bénin, pou dékouvè an pirog dépi ti anbarkadè-a. Route des Pêches, épi pyé koko bò''y, ka pasé ant lé dé. Yo pa ka konséyé benyen lè van-an fò."}]'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.toursIntro','{"label":"Sikwi nou","all":{"label":"Tout sé sikwi-a","href":"/#chemins"},"onRequest":"Mandé pri-a","durationPending":"Diré-a pou konfimen","filtersLabel":"Filtré sé sikwi-a"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.cheminsIntro','{"origin":[2.0901,6.3589],"timeZone":"Africa/Porto-Novo","kicker":"Sikwi nou · Dépa dépi Ouidah","title":{"lead":"Chimen zot","accent":"pou Ouidah."},"intro":"Pran an sikwi gid nou ja préparé, oben chwazi sé koté-a yonn pa yonn : nou ka fè vwayaj zot épi yo.","ready":{"label":"Sikwi ki paré","heading":"Sikwi gid nou préparé.","book":"Rézèvé sikwi-tala","customize":"Adapté''y pou mwen"},"compose":{"label":"Konpozé chimen mwen","heading":"Gadé sé koté-a ki ka palé ba zot.","views":{"deck":"An koté alafwa"},"viewsLabel":"Fason dékouvè sé koté-a","skip":"Pasé","keep":"Gadé koté-tala","kept":"Gadé","see":"Wè","noPhoto":"Foto ka vini","done":"Zot ja gadé tout sé koté-a.","restart":"Wè sé koté-a ankò","far":"Pli lwen"},"filters":[{"key":"a-voir","label":"Pou wè","ids":["a-voir"],"color":"#ac3215","group":"voir","on":true},{"key":"plage","label":"Laplaj","ids":["plage"],"color":"#2a7ab8","group":"voir","on":true},{"key":"nature","label":"Lanati","ids":["nature"],"color":"#3f8a4e","group":"voir","on":true},{"key":"hebergement","label":"Koté pou dòmi","ids":["hebergement"],"color":"#0f162d","group":"dormir","on":true},{"key":"restauration","label":"Koté pou manjé","ids":["restauration"],"color":"#c98a00","group":"manger","on":true},{"key":"artisanat","label":"Atizana","ids":["artisanat"],"color":"#8a4fb3","group":"voir","on":true},{"key":"marche","label":"Maché","ids":["marche"],"color":"#d9661f","group":"voir","on":true},{"key":"pratique","label":"Pratik","ids":["sante","argent","transport","services"],"color":"#5b6478","group":"pratique","on":false},{"key":"culte","label":"Koté pou priyé","ids":["culte"],"color":"#8a8f9c","group":"voir","on":false}],"filtersLabel":"Koté ki afiché asou kat-la","groups":{"voir":"Pou wè épi viv","dormir":"Koté pou dòmi","manger":"Koté pou manjé","pratique":"Pratik"},"place":{"add":"Ajouté adan vwayaj mwen","remove":"Tiré adan vwayaj mwen","close":"Fèmen