insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.datesSection','{"title":{"lead":"Vini o","accent":"bon moman."},"none":"Pa ni gran randévou adan sé dat-tala : zot pé vizité Ouidah tout lanné-a.","units":{"days":"jou","hours":"h","minutes":"min","seconds":"s"},"live":{"arrival":"Rivé","departure":"Dépa","end":"Lafen"},"pass":{"oht":"Lévénman OHT","date":"Dat","place":"Koté","in":"Adan","arrival":"Rivé","departure":"Dépa","nights":"Lannuit","during":"Pannan séjou zot","after":"Jis apré dépa zot","onRequest":"Mandé tarif-la","extendCta":"Pwolonje","bookStay":"Rézèvé séjou-a","bookPlace":"Rézèvé plas mwen","byOht":"Òganizé pa Ouidah Heritage Tour · biyé zot ka afiché dépi péman-an konfimen.","formulas":"Fòmil"},"talon":{"titre":"Talon zot","ouvrir":"Rézèvé plas mwen","fermer":"Fèmen rézèvasyon-an","places":"Plas","moins":"An plas an mwens","plus":"An plas an plis","accompagnement":"Akonpayman zot","accompagnementNote":"asou devis, répons adan 24 h","deja":"ja chwézi adan sèvis konsyèj-la","unique":{"titre":"An sèl anvwa, an sèl référans."},"nom":"Prénon épi non","email":"Imèl","repris":"ripran dépi demann zot","payerAvec":"Péyé épi","passerelles":{"kkiapay":{"nom":"Kkiapay","moyens":"Mobile Money, kat"},"fedapay":{"nom":"FedaPay","moyens":"Mobile Money, kat"},"stripe":{"nom":"Stripe","moyens":"Kat labank"},"flutterwave":{"nom":"Flutterwave","moyens":"Kat labank"},"paystack":{"nom":"Paystack","moyens":"Kat, Mobile Money"}},"accord":"Mwen dakò pou Ouidah Heritage Tour sèvi sé enfòmasyon-tala pou rézèvasyon mwen.","confidentialite":{"label":"Konfidansyalité","href":"/politique-de-confidentialite"},"envoi":"Péman-an ka préparé…","attente":{"devis":"Demann akonpayman zot ja matjé.","autre":"Péyé an lòt jan"},"verification":"Nou ka vérifié péman zot…","nonConfirme":{"titre":"Péman poko konfimen","texte":"Si zot ja péyé, an jénéral konfimasyon-an ka rivé adan déotwa moman.","reessayer":"Vérifié ankò"},"paye":{"titreSans":"I rézèvé.","entree":"Pou prézanté lè zot ka antré","precedent":"Biyé avan-an","suivant":"Biyé swivan-an","telecharger":"Téléchajé sé biyé-a","reference":"Référans vwayaj zot","suivi":"Wè tiké mwen épi risi mwen","recap":{"formule":"Fòmil","paye":"Péyé","devis":"Asou devis"},"tampon":"PÉYÉ"},"erreurs":{"champs":"Non zot, imèl zot oben lakò zot ka mantjé.","limite":"Plizyè rézèvasyon sòti adan konèksyon-tala tousuit la. Éséyé ankò adan inèdtan.","surDemande":"Tarif fòmil-tala ka fèt asou demann : nou ka ajouté''y adan vwayaj zot.","passerelle":"Mwayen péman-tala pa disponib. Chwazi an lòt.","indisponible":"Péman anlign-lan pa ka réponn atjèlman. Éséyé ankò talè."},"surDemande":"Ajouté adan vwayaj mwen"},"scrub":{"ask":"Ki lè zot ka vini ?","hint":"Glisé kapsil-la asou lanné-a","place":"Pozé séjou zot","today":"Jòdi-a","legendOht":"Lévénman OHT","legendOther":"Gran randévou","lengths":[{"label":"Wikenn","nuits":2},{"label":"Simenn","nuits":7},{"label":"10 lannuit","nuits":10},{"label":"2 simenn","nuits":14}],"lengthsLabel":"Diré séjou-a","reset":"Éfasé dat mwen"},"timeZone":"Africa/Porto-Novo","fallbackImage":{"src":"/hero/hero-4-plage.jpg","alt":"Laplaj Ouidah wè dépi syèl-la, lanm Latlantik épi pyé koko"}}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.prepare','{"title":["Préparé vwayaj zot,","kat an lanmen."],"lead":"Ouidah asou lakòt-la, a 41 km ayéwopò-a. Déotwa konsèy ka ba zot lésansyèl-la.","carte":{"ouidah":[2.0851,6.3622],"aeroport":[2.3844,6.3573],"porte":[2.0896,6.3243],"ville":"Ouidah","villeSous":"Lakòt Latlantik","ocean":"Loséan Latlantik","pays":[{"nom":"Togo","lieu":[1.12,8.2]},{"nom":"Nigeria","lieu":[3.38,8.4]}],"cotonou":"Cotonou","aeroportNom":"ayéwopò entènasyonal","porteNom":"Porte du Non-Retour","km":"41 km","kmSous":"pa larout, an navèt","ariaBenin":"Kat Bénin : Ouidah, asou lakòt Latlantik, a 41 km ayéwopò Cotonou","ariaCote":"Lakòt Bénin : larout dépi ayéwopò Cotonou jik Ouidah, 41 km"},"fiche":{"image":{"src":"/ouidah/eng-5-porte-jour.jpg","alt":"Porte du Non-Retour douvan loséan-an, Ouidah"},"titre":"Ouidah","texte":"Lavil listwa, douvan Latlantik.","heureTexte":"Menm lè épi Paris an livè.","fuseau":"Africa/Porto-Novo"},"accueil":{"titre":"Nou ka atann zot.","texte":"Lè zot ka rivé, lékip-la ka risivwè zot ayéwopò-a, si zot lé."},"ongletsLabel":"Préparé vwayaj zot, pa tèm","numeros":"Niméro itil","question":"An kestyon avan zot pati ? Nou ka réponn adan 24 lè.","whatsapp":"Ékri asou WhatsApp","ecrire":{"label":"Pozé an kestyon","href":"/devis?demande=question"},"verifie":"2026-10-22"}'::jsonb,1,now()) on conflict(cle) do nothing;
insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.preparer','[{"id":"sur-place","court":"Asou plas","objet":"accueil","vue":"benin","titre":"Zot pé vizité Ouidah lespri trantjil.","cle":{"valeur":"Akonpanyé","texte":"pa lékip nou, avan, pannan épi apré vwayaj-la."},"mot":true,"points":["Ayéwopò-a, nou ka atann zot si zot lé : navèt-la ka mennen zot jik Ouidah.","Lojman épi koté manjé : nou ka chwazi épi zot adan sé adrès ki rilèvé Ouidah la.","Avan zot pran an foto sérémoni oben an pòtré, an ti pawòl sifi : mandé, sé labitid-la.","Laplaj-la, pwofité sab-la épi solèy-la lè i ka kouché ; pou benyen, mandé konsèy asou plas, ba Latlantik-la fò."],"source":"Angajman OHT · France Diplomatie (15 sèpt. 2026) · FCDO"},{"id":"arriver","court":"Rivé","objet":"navette","vue":"cote","titre":"Rivé, san konplikasyon.","cle":{"valeur":"41 km","texte":"dépi ayéwopò Cotonou jik Ouidah. Navèt OHT ka mennen zot la."},"points":["Zot ka mandé e-Visa zot anlign, asou evisa.bj : 30 oben 90 jou, répons adan 1 a 96 lè.","Fè demann-lan omwen 7 jou avan zot rivé, épi gadé''y koté zot pé pran''y fasil.","Sitwayen afriken : pa ni viza, jik 90 jou.","Vwayajè fransé : paspò valid 6 mwa apré ritou-a, biyé ritou adan sak-la."],"source":"evisa.bj · France Diplomatie · OSRM (41 km)"},{"id":"sante","court":"Lasanté","objet":"sante","vue":"benin","titre":"Lasanté zot, préparé.","cle":{"valeur":"1 vizit","texte":"lakay doktè zot oben adan an sant vaksinasyon entènasyonal, avan dépa-a."},"points":["Vaksen a jou, épatit A épi tifoyid : doktè zot ka fè an bilan épi zot.","Lafièv jòn : vaksen konséyé dépi 9 mwa. Mété kanè zot adan sak-la.","Kont moustik : pwodui pou pousé yo épi manch long lèswè. Doktè zot ké di zot si an trètman kont palidis itil."],"source":"Ministère de la Santé du Bénin (16 sèpt. 2026) · Institut Pasteur · OMS — lafièv jòn : sé sous-la pa dakò, pou konfimen"},{"id":"argent","court":"Lajan","objet":"type-voyage","vue":"benin","titre":"Lajan-an, san kalkil.","cle":{"valeur":"15,24 €","texte":"pou 10 000 FCFA. To-a fiks, tout lanné-a."},"points":["Fran CFA-a lyanné épi léwo-a : 1 € = 655,957 FCFA, san varyasyon.","An ripè rapid : 1 000 FCFA ka fè apepré 1,50 €.","Pou tiré lajan, chwazi sé distribitè-a ki andidan sé ajans-lan."],"source":"BCEAO · France Diplomatie"},{"id":"pratique","court":"Pratik","objet":"prise","vue":"benin","fiche":"heure","titre":"Bon pou sav.","cle":{"valeur":"0 h","texte":"dékala épi Paris an livè, 1 h an lété."},"points":["220 V, priz C épi E : chajè Lafrans épi Bèljik ka branché san adaptatè.","Fransé sé lang ofisyèl-la ; Ouidah, yo ka palé fon tou.","An kat SIM lokal MTN, Moov Africa oben Celtiis, épi moun pé jwenn zot.","Sézon sèk dépi novanm jik mas, épi dépi mitan jiyé jik mitan sèptanm."],"source":"gouv.bj · ARCEP Bénin · IEC · IANA"}]'::jsonb,1,now()) on conflict(cle) do nothing;
