insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.newsletter','{"nom":"Lèt Ouidah","phraseSansHeure":"Oswè-a, solèy-la ka kouché asou laplaj Ouidah.","maintenant":"Ouidah","photo":{"src":"/ouidah/bienvenue-3-plage-cocotiers.jpg","alt":"Laplaj Ouidah, pyé koko''y épi chimen sab-la an bout lajounen-an"},"choisir":"Chwazi sa Ouidah ka ékri ba zot","sujets":[{"id":"departs","nom":"Dat dépa nou","texte":"Sé séjou épi sikwi ka vini a, épi dat yo.","objet":"calendrier"},{"id":"agenda","nom":"Lajanda Ouidah","texte":"Vodun Days, Journée du souvenir, Ouidah Blue : randévou lavil-la.","objet":"fete"}],"langue":"Lèt-la an","field":"Adrès imèl zot","exemple":"vous@exemple.com","submit":"Risivwè lèt-la","consent":"Mwen dakò pou risivwè lèt Ouidah Heritage Tour. Zot pé dézabonné zot adan an klik.","envoi":"Enskripsyon ka fèt…","thanks":"I matjé : lèt-la ké rivé adan bwèt zot.","echec":"Enskripsyon-an pa fèt. Éséyé ankò talè.","limite":"Plizyè enskripsyon ja sòti adan konèksyon-tala. Éséyé ankò adan inèdtan.","aucun":"Chwazi omwen an tèm.","error":"Bay an adrès imèl valid épi koché kaz-la."}'::jsonb,1,now()) on conflict(cle) do nothing;
