insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.devisPage','{"metaTitre":"Kréyé vwayaj mwen — Ouidah Heritage Tour","metaDescription":"Biyé zot pou Ouidah : vwayaj zot konpozé asou sit-la, sa ki rété pou konplété, an konséyé ka réponn zot adan 24 lè.","titre":{"voyage":"Biyé zot pou Ouidah.","groupe":"Biyé gwoup zot pou Ouidah.","question":"Ékri nou."},"intro":{"compose":"Tout sa zot konpozé asou lakèy-la ja la. Konplété sé kaz jòn-lan, épi talon-an.","vide":"Konplété sé kaz jòn-lan, épi talon-an : an konséyé ka réponn zot adan 24 lè.","groupe":"Asosyasyon, lékòl, lantrepriz, gran fanmi : di nou ki moun ka vini, nou ka konpozé séjou-a.","question":"An kestyon avan zot pati, an lidé vwayaj ? Nou ka réponn adan 24 lè."},"reference":{"lib":"Référans","note":"bay lè zot ka voyé''y","lib2":"Référans demann zot"},"trajet":{"depart":"Dépa","arrivee":"Rivé","destination":"Destinasion","vol":"vòl zot","detectee":"pwopozé dapré konèksyon zot","choisie":"lavil zot","villeTrou":"lavil zot","villeNote":"si zot lé","villeTitre":"Dépi ki koté zot ka pati ?","villeAide":"Egz. : Paris, Montréal, Abidjan","villeOk":"Gadé lavil-tala","villeIntrouvable":"Nou pa trouvé lavil-la, éséyé ékri''y an lòt jan.","aeroport":{"code":"COO","nom":"Ayéwopò Cotonou","km":41},"ouidah":"OUIDAH","pays":"Bénin"},"dates":{"aller":"Alé","retour":"Ritou","sejour":"Séjou","trou":"ki dat ?","conseil":"Konséyé mwen","conseillees":"Dat pou konséyé","choisir":"Mwen ka chwazi dat mwen","arrivee":"Rivé","depart":"Dépa","garder":"Gadé sé dat-tala","invalides":"Dépa-a apré larivé-a, épi pa pli lwen ki twa lanné apré jòdi-a.","modifier":{"label":"Chanjé sé dat-la","href":"/#agenda"},"pendant":"pannan sé"},"lieux":{"titreVide":"Koté zot","trou":"ki koté ?","conseil":"Konséyé mwen","conseilles":"Koté pou konséyé","choisir":{"label":"Chwazi koté mwen","href":"/#chemins"},"modifier":{"label":"Chanjé sé koté-a","href":"/#chemins"}},"services":{"titreVide":"Sèvis zot","modifier":{"label":"Chan