insert into public.contenu_site(cle,valeur,version,publie_le) values('GCF:fr.places','[{"n":"01","name":"Mizé listwa Ouidah","kicker":"Fò pòtigé, 1721","text":"Fò pòtigé-a ka risivwè mizé listwa lavil-la dépi 6 sèptanm 1967 : latrèt, wayòm, lyannaj épi Brézil épi Lézamérik.","slug":"musee-histoire","href":"/ouidah/lieux/musee-histoire","coords":[6.3588947,2.0901242],"image":{"src":"/ouidah/lieu-musee.jpg","alt":"Mi wouj fò pòtigé Ouidah"},"next":"680 m a pyé jik Temple des Pythons"},{"n":"02","name":"Temple des Pythons","kicker":"Douvan bazilik-la","text":"Tanp piton Dangbé-a douvan bazilik Immaculée-Conception, bati dépi 1903 jik 1909 : dé lafwa ka viv yonn bò lòt.","slug":"temple-des-pythons","href":"/ouidah/lieux/temple-des-pythons","coords":[6.3599709,2.0850407],"image":{"src":"/ouidah/bienvenue-2-temple-pythons.jpg","alt":"Lantwé pentiré Temple des Pythons"},"next":"2,5 km jik mémoryal Zoungbodji, pa laplas Chacha"},{"n":"03","name":"Route des Esclaves","kicker":"Apepré 4 km, sis estasyon","text":"Dépi laplas Chacha jik laplaj-la, chimen moun yo té kaptiré té ka pran jik sé bato-a : Arbre de l''Oubli, Cases Zomaï, Mémorial de Zoungbodji, Arbre du Retour.","slug":"route-des-esclaves","href":null,"coords":[6.3398445,2.0893791],"image":{"src":"/ouidah/visite-zoungbodji.jpg","alt":"Mémoryal Zoungbodji, asou Route des Esclaves"},"next":"2 km jik laplaj-la épi Porte du Non-Retour"},{"n":"04","name":"Porte du Non-Retour","kicker":"Bati an 1995, ribati an 2025","text":"Asou laplaj-la, douvan Latlantik, i ka matjé koté yo fòsé milyon Afriken anbarké.","slug":"porte-du-non-retour","href":"/ouidah/lieux/porte-du-non-retour","coords":[6.3242524,2.0895803],"image":{"src":"/ouidah/bienvenue-1-porte-nuit.jpg","alt":"Porte du Non-Retour kléré lannuit"},"next":null}]'::jsonb,1,now()) on conflict(cle) do nothing;
